window.VOCABULARY_INDEX = [{"id":"cs","name":"컴퓨터과학 기초","blurb":"면접에서도, 설계에서도 계속 나온다","terms":[{"id":"cs--async-await","term":"Async/Await","reading":"비동기 문법","category":"컴퓨터과학 기초","summary":"Async/Await는 **비동기 코드를 위에서 아래로 읽히게 쓰는 문법**이다.","aliases":["async/await","비동기 문법","async-await","async","await"],"related":[{"term":"Concurrency","note":"— async/await 가 문법으로 구현하는 개념"},{"term":"Parallelism","note":"— 여러 코어로 진짜 동시에 돌리는 쪽. async/await 로는 안 된다"},{"term":"Thread","note":"— 다른 방식의 동시 실행 수단"},{"term":"Multi-thread","note":"— CPU 작업을 나눌 때 쓰는 쪽"}]},{"id":"cs--big-o","term":"Big O 표기법","reading":"Big O Notation","category":"컴퓨터과학 기초","summary":"Big O는 **데이터가 늘어날 때 시간이 얼마나 늘어나는지 적는 표기**다.","aliases":["big o 표기법","big o notation"],"related":[{"term":"Algorithm","note":"— Big O로 비교하는 대상"},{"term":"Hash","note":"— 평균 O(1) 조회를 만드는 대표적인 방법"},{"term":"Index","note":"— 전체 훑기를 O(log n)으로 바꾸는 장치"},{"term":"자료구조","note":"— 무엇을 고르느냐가 곧 Big O를 정한다"}]},{"id":"cs--binary","term":"Binary","reading":"이진법","category":"컴퓨터과학 기초","summary":"Binary는 **0과 1 두 기호만으로 값을 적는 방식**이다.","aliases":["binary","이진법"],"related":[{"term":"CPU","note":"— 0과 1의 연산을 실제로 수행하는 부품"},{"term":"Memory","note":"— 바이트 단위로 주소를 매겨 비트를 담아두는 곳"},{"term":"RAM","note":"— 그 메모리를 이루는 실제 부품"},{"term":"Hash","note":"— 아무 데이터나 정해진 길이의 비트열로 바꾸는 계산"}]},{"id":"cs--binary-search","term":"Binary Search","reading":"이진 탐색","category":"컴퓨터과학 기초","summary":"Binary Search 는 정렬된 목록의 가운데를 보고 **반을 버리는** 찾기다.","aliases":["binary search","이진 탐색"],"related":[{"term":"Sorting","note":"— 이진 탐색의 전제를 만들어 주는 일. 정렬 없이는 쓸 수 없다"},{"term":"Big O 표기법","note":"— 목록이 두 배로 늘어도 한 번만 더 보는 것이 O(log n) 이다"},{"term":"Hash","note":"— 값 하나를 정확히 집는 일이라면 이쪽이 빠르다. 대신 구간으로는 못 묻는다"},{"term":"Array","note":"— 번호로 아무 자리나 바로 짚을 수 있어야 절반씩 버릴 수 있다"}]},{"id":"cs--blocking-vs-non-blocking","term":"Blocking vs Non-blocking","reading":"블로킹과 논블로킹","category":"컴퓨터과학 기초","summary":"블로킹과 논블로킹은 부른 일이 끝날 때까지 **멈춰 서 있는지**로 갈린다.","aliases":["blocking vs non-blocking","블로킹과 논블로킹","blocking","non-blocking"],"related":[{"term":"Concurrency","note":"— 논블로킹으로 비운 기다림을 다른 작업으로 채우는 상위 개념"},{"term":"Async-Await","note":"— 논블로킹 호출을 위에서 아래로 읽히게 쓰는 문법. 이 개념 위에 얹혀 있다"},{"term":"Thread","note":"— 블로킹 호출을 그대로 두고 갈래를 늘려 처리량을 버는 다른 길"},{"term":"Socket","note":"— 블로킹·논블로킹·타임아웃 셋 중 하나를 실제로 골라 설정하는 통로"}]},{"id":"cs--cpu","term":"CPU","reading":"Central Processing Unit","category":"컴퓨터과학 기초","summary":"CPU는 **명령어를 하나씩 꺼내 실행하는 부품**이다.","aliases":["cpu","central processing unit"],"related":[{"term":"Memory","note":"— CPU가 값을 꺼내 오는 바깥 저장소"},{"term":"Cache","note":"— CPU 옆에 붙어 메모리까지 나가는 횟수를 줄인다"},{"term":"Process","note":"— CPU가 실제로 실행하는 프로그램의 단위"},{"term":"Thread","note":"— 코어 하나가 붙들 수 있는 실행 흐름"},{"term":"Parallelism","note":"— 코어 여러 개를 실제로 같이 쓰는 방식"}]},{"id":"cs--cache","term":"Cache","reading":"캐시","category":"컴퓨터과학 기초","summary":"Cache는 **한 번 구한 결과를 가까운 곳에 두고 다시 쓰는 것**이다.","aliases":["cache","캐시"],"related":[{"term":"Redis","note":"— 여러 서버가 함께 쓰는 캐시의 대표적인 구현"},{"term":"CDN","note":"— 캐시를 사용자 가까이 옮긴 것"},{"term":"TTL","note":"— 캐시를 얼마나 들고 있을지 정하는 값"},{"term":"Memory","note":"— 캐시가 놓이는 자리"}]},{"id":"cs--character-encoding","term":"Character Encoding","reading":"문자 인코딩","category":"컴퓨터과학 기초","summary":"문자 인코딩은 **글자를 바이트로 바꿔 적는 약속**이다.","aliases":["character encoding","문자 인코딩"],"related":[{"term":"Binary","note":"— 그 바이트가 결국 0과 1 로 남는 아래층"},{"term":"Memory","note":"— 바뀐 바이트가 실제로 놓이는 자리"},{"term":"HTML","note":"— 글자로 된 문서라 약속이 어긋나면 그대로 깨진다"},{"term":"JSON","note":"— 글자로 자료를 주고받는 형식이라 같은 문제를 그대로 안는다"}]},{"id":"cs--concurrency","term":"Concurrency","reading":"동시성","category":"컴퓨터과학 기초","summary":"Concurrency는 **여러 작업을 번갈아 진행시키는 방식**이다.","aliases":["concurrency","동시성"],"related":[{"term":"Parallelism","note":"— 여러 코어로 실제로 같은 시각에 돌리는 쪽"},{"term":"Async-Await","note":"— 동시성을 코드로 쓰게 해주는 문법"},{"term":"Thread","note":"— 동시성을 구현하는 또 다른 수단"},{"term":"Process","note":"— 서로 메모리를 나누지 않는 독립 실행 단위"},{"term":"Multi-thread","note":"— 스레드를 여러 개 두고 나누는 방식"}]},{"id":"cs--context-switch","term":"Context Switch","reading":"문맥 교환","category":"컴퓨터과학 기초","summary":"Context Switch는 **CPU가 일감을 바꿀 때 상태를 갈아 끼우는 일**이다.","aliases":["context switch","문맥 교환"],"related":[{"term":"Thread","note":"— 갈아 끼우는 대상. 문맥이 이 단위로 저장된다"},{"term":"CPU","note":"— 한 번에 하나만 도는 자리. 그래서 갈아 끼워야 한다"},{"term":"Process","note":"— 프로세스끼리 바꿀 때는 주소 공간을 가리키는 장부까지 함께 바뀐다"},{"term":"Multi-thread","note":"— 갈래를 늘리면 교환 횟수도 함께 늘어난다"},{"term":"Concurrency","note":"— 하나의 CPU가 여럿을 함께 하는 것처럼 보이게 만드는 결과"}]},{"id":"cs--coroutine","term":"Coroutine","reading":"코루틴","category":"컴퓨터과학 기초","summary":"코루틴은 **멈췄다가 이어서 하는** 일감이다.","aliases":["coroutine","코루틴"],"related":[{"term":"Thread","note":"— 코루틴이 올라타 도는 실행 단위. 코루틴은 이것을 붙잡지 않는다"},{"term":"Blocking vs Non-blocking","note":"— 기다릴 때 자리를 붙잡느냐 놓느냐의 구분"},{"term":"Async-Await","note":"— 멈췄다 이어 하는 일을 순서대로 읽히게 적는 문법"},{"term":"Concurrency","note":"— 여러 일을 번갈아 진행시키는 성질. 코루틴은 그것을 쓰는 한 방법이다"},{"term":"Scope","note":"— 이름이 살아 있는 범위. 코루틴도 스코프 안에서만 태어난다"}]},{"id":"cs--deadlock","term":"Deadlock","reading":"교착 상태","category":"컴퓨터과학 기초","summary":"Deadlock 은 서로가 쥔 것을 기다리다 **둘 다 멈춰 선** 상태다.","aliases":["deadlock","교착 상태"],"related":[{"term":"Transaction","note":"— 교착이 가장 자주 관찰되는 단위. 취소되는 것도 이 단위다"},{"term":"Mutex vs Semaphore","note":"— 교착을 만드는 잠금 도구 그 자체"},{"term":"Race Condition","note":"— 잠금으로 이것을 막으려다 반대쪽 함정으로 빠진 결과가 교착이다"},{"term":"Thread","note":"— 애플리케이션 안에서 서로를 기다리며 서는 주체"},{"term":"Concurrency","note":"— 여럿이 같은 것을 동시에 노리는, 교착의 전제"}]},{"id":"cs--event-loop","term":"Event Loop","reading":"이벤트 루프","category":"컴퓨터과학 기초","summary":"이벤트 루프는 **한 줄기가 끝난 일부터 골라 처리하기를 반복하는 구조**다.","aliases":["event loop","이벤트 루프"],"related":[{"term":"Blocking vs Non-blocking","note":"— 기다리며 서 있느냐 아니냐. 이 루프가 성립하는 전제다"},{"term":"Async-Await","note":"— 이 구조 위에서 돌아가는 코드를 위아래로 읽히게 쓰는 문법"},{"term":"Concurrency","note":"— 하나씩 하면서도 여러 일이 겹쳐 보이게 하는 성질. 그것을 만드는 한 방법이다"},{"term":"Thread","note":"— 이 루프가 올라타 있는 한 줄기. 그 수를 줄이려고 만든 구조다"}]},{"id":"cs--file-system","term":"File System","reading":"파일 시스템","category":"컴퓨터과학 기초","summary":"File System은 **저장 장치의 칸들을 파일과 폴더로 보이게 하는 규칙**이다.","aliases":["file system","파일 시스템"],"related":[{"term":"Kernel","note":"— 파일 시스템 구현과 VFS 가 실제로 도는 자리"},{"term":"System Call","note":"— `open`·`read`·`write` 로 파일 시스템에 부탁하는 창구"},{"term":"OS","note":"— 파일 시스템을 들고 프로그램에는 이름과 폴더만 보여주는 쪽"},{"term":"Cache","note":"— 경로 조각을 RAM 에 두어 디스크를 덜 뒤지게 하는 장치"}]},{"id":"cs--floating-point","term":"Floating Point","reading":"부동소수점","category":"컴퓨터과학 기초","summary":"부동소수점은 **소수를 2진 근삿값으로 담는 수 형식**이다.","aliases":["floating point","부동소수점"],"related":[{"term":"Binary","note":"— 10진 소수를 정확히 담을 수 없는 이유가 있는 아래층"},{"term":"Variable","note":"— 값을 어떤 형식으로 담을지 고르는 자리"},{"term":"CPU","note":"— 이 형식의 계산을 실제로 수행하는 쪽"},{"term":"Memory","note":"— 64비트가 실제로 놓이는 자리"}]},{"id":"cs--garbage-collection","term":"Garbage Collection","reading":"가비지 컬렉션","category":"컴퓨터과학 기초","summary":"Garbage Collection은 **쓰지 않게 된 메모리를 알아서 거둬 가는 일**이다.","aliases":["garbage collection","가비지 컬렉션"],"related":[{"term":"Memory","note":"— 거둬 가는 대상이 놓여 있는 자리"},{"term":"Object","note":"— 수집기가 세고 거두는 단위"},{"term":"Variable","note":"— 객체를 붙잡고 있는 이름. 이 참조가 남아 있으면 안 거둔다"},{"term":"Heap","note":"— 실행 도중에 얻어 쓰는 메모리 영역을 부르는 같은 이름. 수집기가 훑는 곳이 그쪽이다"},{"term":"Cache","note":"— 참조를 오래 붙잡아 두어 누수를 만드는 대표적인 자리"}]},{"id":"cs--graph","term":"Graph","reading":"그래프","category":"컴퓨터과학 기초","summary":"Graph 는 마디와 **이음선**으로 무엇이 무엇과 이어졌는지 적는 자료구조다.","aliases":["graph","그래프"],"related":[{"term":"자료구조","note":"— 마디와 이음선이라는 짜임 하나가 곧 이 자료구조다"},{"term":"Tree","note":"— 되돌아오는 길이 없는 그래프. 그래서 훑기가 훨씬 단순하다"},{"term":"Sorting","note":"— 위상 정렬은 값의 크기가 아니라 선후로 줄을 세우는 정렬이다"},{"term":"Algorithm","note":"— 순환 찾기·위상 정렬처럼 그래프 위에서 도는 절차들"}]},{"id":"cs--hash","term":"Hash","reading":"해시","category":"컴퓨터과학 기초","summary":"Hash는 **아무 길이의 값을 정해진 길이의 숫자로 바꾸는 계산**이다.","aliases":["hash","해시"],"related":[{"term":"Dictionary","note":"— 해시 테이블로 만들어진 자료구조"},{"term":"Big O 표기법","note":"— 해시가 왜 빠른지를 적는 방법"},{"term":"암호화","note":"— 되돌릴 수 있다는 점이 해시와 다르다"},{"term":"Index","note":"— DB에서 조회를 빠르게 하는 다른 장치"}]},{"id":"cs--hash-table","term":"Hash Table","reading":"해시 테이블","category":"컴퓨터과학 기초","summary":"Hash Table 은 **열쇠를 계산해 값의 칸을 정하는 자료구조**다.","aliases":["hash table","해시 테이블"],"related":[{"term":"Hash","note":"— 어느 칸에 앉을지 계산하는 함수. 이 그릇의 부품이다"},{"term":"Dictionary","note":"— 언어가 이 자료구조에 이름을 붙여 내놓은 것"},{"term":"Array","note":"— 칸을 한 줄로 잡아 두는 바탕. 번호로만 찾는 한계가 출발점이다"},{"term":"Tree","note":"— 순서와 범위를 함께 다뤄야 할 때 대신 고르는 모양"},{"term":"Big O 표기법","note":"— 평균 O(1) 과 무너진 뒤를 견주어 적는 표기"}]},{"id":"cs--heap","term":"Heap","reading":"힙","category":"컴퓨터과학 기초","summary":"Heap 은 **꼭대기에 항상 최댓값이나 최솟값이 오는 트리**다.","aliases":["heap","힙"],"related":[{"term":"Stack","note":"— 함수가 쓰고 반납하는 메모리 영역. 힙과 짝을 이룬다"},{"term":"Queue","note":"— 들어온 순서로 꺼내는 쪽. 힙은 우선순위로 꺼낸다"},{"term":"자료구조","note":"— 힙이 속한 갈래"},{"term":"Memory","note":"— 힙이 놓이는 자리"},{"term":"Big O 표기법","note":"— 넣고 꺼내는 비용을 재는 잣대"}]},{"id":"cs--interrupt","term":"Interrupt","reading":"인터럽트","category":"컴퓨터과학 기초","summary":"인터럽트는 **일이 생겼을 때 장치가 CPU 를 불러 세우는 신호**다.","aliases":["interrupt","인터럽트"],"related":[{"term":"CPU","note":"— 신호를 받고 하던 일을 멈추는 쪽"},{"term":"Context Switch","note":"— 멈춘 자리를 저장하고 되돌아오는 그 동작"},{"term":"Process","note":"— 인터럽트 덕에 CPU 를 번갈아 쓸 수 있게 되는 단위"},{"term":"Async-Await","note":"— 기다리지 않고 불려 가는 같은 발상을 코드에서 쓴 것"}]},{"id":"cs--kernel","term":"Kernel","reading":"커널","category":"컴퓨터과학 기초","summary":"Kernel은 **하드웨어에 직접 닿는 운영체제의 가장 안쪽 층**이다.","aliases":["kernel","커널"],"related":[{"term":"OS","note":"— 커널을 감싸 사람이 쓸 수 있게 묶어 놓은 전체"},{"term":"System Call","note":"— 사용자 모드에서 커널로 넘어가는 경계 그 자체"},{"term":"Process","note":"— 커널이 CPU 를 짧게 갈라 나눠주는 단위"},{"term":"Memory","note":"— 커널이 가상 주소로 갈라 관리하는 자원"},{"term":"Linux","note":"— 커널 이름이 그대로 운영체제 이름이 된 대표적 예"}]},{"id":"cs--linked-list","term":"Linked List","reading":"연결 리스트","category":"컴퓨터과학 기초","summary":"Linked List 는 **값마다 다음 값의 자리를 들고 있는 자료구조**다.","aliases":["linked list","연결 리스트"],"related":[{"term":"Array","note":"— 자리를 계산해 곧장 가는 반대쪽 모양"},{"term":"자료구조","note":"— 이 모양이 어느 자리에 맞는지 고르는 기준을 다루는 상위 단어"},{"term":"Queue","note":"— 앞뒤로 드나드는 대기열을 이 모양으로 만든다"},{"term":"Hash Table","note":"— 한 칸에 몰린 값들을 이 모양으로 이어 붙인다"},{"term":"Big O 표기법","note":"— 꺼내기와 끼우기의 값을 견주어 적는 표기"}]},{"id":"cs--linux","term":"Linux","reading":"리눅스","category":"컴퓨터과학 기초","summary":"Linux는 **누구나 뜯어보고 고칠 수 있는 운영체제**다.","aliases":["linux","리눅스"],"related":[{"term":"OS","note":"— 리눅스가 속한 갈래"},{"term":"Terminal","note":"— 리눅스에 명령을 넣는 창"},{"term":"CLI","note":"— 리눅스를 다루는 주된 방식"},{"term":"Windows","note":"— 개인 컴퓨터 쪽에서 자리를 잡은 다른 운영체제"},{"term":"Container","note":"— 안쪽이 대개 리눅스로 채워지는 실행 단위"}]},{"id":"cs--memory","term":"Memory","reading":"메모리","category":"컴퓨터과학 기초","summary":"메모리는 **지금 쓰는 데이터를 잠시 올려두는 자리**다.","aliases":["memory","메모리"],"related":[{"term":"CPU","note":"— 메모리에서 값을 꺼내 계산하는 쪽"},{"term":"Cache","note":"— 메모리 계층의 위쪽. 자주 쓰는 값을 붙들어 둔다"},{"term":"RAM","note":"— 실행 중인 프로그램이 올라가 있는 층"},{"term":"Process","note":"— 메모리를 나눠 받아 돌아가는 단위"}]},{"id":"cs--multi-thread","term":"Multi-thread","reading":"멀티 스레드","category":"컴퓨터과학 기초","summary":"Multi-thread는 **한 프로그램 안에서 일을 여러 갈래로 나눠 돌리는 방식**이다.","aliases":["multi-thread","멀티 스레드"],"related":[{"term":"Thread","note":"— 갈래 하나를 가리키는 말. 여럿을 함께 돌리는 것이 여기다"},{"term":"Process","note":"— 메모리를 따로 쓰는 단위. 스레드는 그 안에서 메모리를 공유한다"},{"term":"Concurrency","note":"— 여러 일을 번갈아 진행하는 개념"},{"term":"Parallelism","note":"— 코어를 여러 개 써서 실제로 동시에 돌리는 것"},{"term":"Queue","note":"— 갈래들이 작업을 주고받을 때 쓰는 안전한 통로"}]},{"id":"cs--mutex-vs-semaphore","term":"Mutex vs Semaphore","reading":"뮤텍스와 세마포어","category":"컴퓨터과학 기초","summary":"뮤텍스는 한 명만 들이고, 세마포어는 **정한 수만큼** 들인다.","aliases":["mutex vs semaphore","뮤텍스와 세마포어","mutex","semaphore"],"related":[{"term":"Deadlock","note":"— 잠금을 여러 개 쓰다 순서가 어긋날 때 빠지는 함정"},{"term":"Race Condition","note":"— 이 둘로 막으려는 바로 그 문제"},{"term":"Thread","note":"— 잠금 앞에 줄을 서는 주체"},{"term":"Concurrency","note":"— 자리 수를 정해야 하는 상황을 만드는 전제"},{"term":"Connection Pool","note":"— 세마포어로 상한을 지키는 대표적인 자원"}]},{"id":"cs--os","term":"OS","reading":"Operating System, 운영체제","category":"컴퓨터과학 기초","summary":"OS는 **프로그램과 하드웨어 사이에서 자원을 나눠주는 소프트웨어**다.","aliases":["os","operating system, 운영체제"],"related":[{"term":"Process","note":"— 운영체제가 CPU를 나눠주는 단위"},{"term":"Memory","note":"— 운영체제가 프로그램마다 갈라주는 자원"},{"term":"Linux","note":"— 서버에서 널리 쓰이는 운영체제"},{"term":"Windows","note":"— 데스크톱에서 널리 쓰이는 운영체제"}]},{"id":"cs--parallelism","term":"Parallelism","reading":"병렬성","category":"컴퓨터과학 기초","summary":"Parallelism은 **여러 코어가 같은 시간에 각자 일하는 것**이다.","aliases":["parallelism","병렬성"],"related":[{"term":"Concurrency","note":"— 번갈아 하는 쪽. 기다림이 긴 일에 쓴다"},{"term":"Process","note":"— 병렬 처리에서 코어마다 하나씩 얹는 실행 단위"},{"term":"Multi-thread","note":"— 메모리를 나눠 쓰는 방식. 파이썬에서는 GIL에 막힌다"},{"term":"CPU","note":"— 코어 개수가 병렬로 어디까지 갈 수 있는지를 정한다"}]},{"id":"cs--process","term":"Process","reading":"프로세스","category":"컴퓨터과학 기초","summary":"Process는 **실행 중인 프로그램**이다.","aliases":["process","프로세스"],"related":[{"term":"Thread","note":"— 프로세스 안에서 갈라지는 실행 흐름"},{"term":"Memory","note":"— 프로세스가 올라가 자리를 잡는 곳"},{"term":"CPU","note":"— 프로세스가 차례를 받아 도는 하드웨어"},{"term":"Stack","note":"— 함수 호출과 지역 변수가 쌓이는 영역"},{"term":"Concurrency","note":"— 여러 실행 단위를 번갈아 돌리는 방식"}]},{"id":"cs--queue","term":"Queue","reading":"큐","category":"컴퓨터과학 기초","summary":"Queue는 **먼저 넣은 것을 먼저 꺼내는 자료구조**다.","aliases":["queue","큐"],"related":[{"term":"Stack","note":"— 마지막에 넣은 것을 먼저 꺼내는 반대 구조"},{"term":"Message Queue","note":"— 같은 개념을 서버 사이에 둔 것"},{"term":"자료구조","note":"— 큐가 속한 갈래"},{"term":"Algorithm","note":"— 큐를 쓰는 대표적인 탐색 방법이 여기 있다"}]},{"id":"cs--ram","term":"RAM","reading":"Random Access Memory","category":"컴퓨터과학 기초","summary":"RAM은 **실행 중인 것만 올려두는 작업 공간**이다.","aliases":["ram","random access memory"],"related":[{"term":"Memory","note":"— RAM 을 포함한 기억 장치 전체를 가리키는 말"},{"term":"Cache","note":"— RAM 보다 위에 있는 더 빠르고 작은 층"},{"term":"CPU","note":"— RAM 에서 값을 꺼내 계산하는 쪽"},{"term":"Process","note":"— 실행되면서 RAM 을 차지하는 단위"},{"term":"Heap","note":"— 프로그램이 실행 중에 RAM 을 받아 쓰는 영역"}]},{"id":"cs--race-condition","term":"Race Condition","reading":"경쟁 상태","category":"컴퓨터과학 기초","summary":"Race Condition 은 **누가 먼저 닿는지**에 따라 결과가 달라지는 버그다.","aliases":["race condition","경쟁 상태"],"related":[{"term":"Mutex vs Semaphore","note":"— 순서를 정해주는 도구. 경쟁 상태를 막는 정공법이다"},{"term":"Deadlock","note":"— 경쟁 상태를 잠금으로 막으려다 반대쪽으로 빠지는 함정"},{"term":"Concurrency","note":"— 여럿이 번갈아 진행하는, 경쟁 상태의 전제"},{"term":"Thread","note":"— 서로 끼어드는 주체"},{"term":"Transaction","note":"— 데이터베이스가 여러 갱신을 한 덩어리로 묶어 같은 문제를 막는 단위"}]},{"id":"cs--sorting","term":"Sorting","reading":"정렬","category":"컴퓨터과학 기초","summary":"Sorting 은 값을 정해진 순서대로 **줄 세우는** 일이다.","aliases":["sorting","정렬"],"related":[{"term":"Binary Search","note":"— 정렬을 전제로만 쓸 수 있는 찾기. 정렬이 사 주는 대표적인 값이다"},{"term":"Big O 표기법","note":"— 정렬 한 번의 값이 O(n log n) 으로 적히는 그 표기다"},{"term":"Hash","note":"— 값 하나를 정확히 집는 일은 줄 세우지 않고 이쪽으로 한다"},{"term":"Heap","note":"— 전부 줄 세우지 않고 상위 몇 개만 손에 들 때 쓰는 짜임"},{"term":"Graph","note":"— 위상 정렬은 값의 크기가 아니라 선후로 줄을 세우는 정렬이다"}]},{"id":"cs--stack","term":"Stack","reading":"스택","category":"컴퓨터과학 기초","summary":"Stack은 **마지막에 넣은 것을 먼저 꺼내는 자료구조**다.","aliases":["stack","스택"],"related":[{"term":"Queue","note":"— 먼저 넣은 것을 먼저 꺼내는 반대 구조"},{"term":"Heap","note":"— 스택과 나뉘어 쓰이는 다른 메모리 영역"},{"term":"Recursion","note":"— 스택 깊이를 가장 빨리 쓰는 방식"},{"term":"Memory","note":"— 스택 영역이 놓이는 자리"}]},{"id":"cs--structured-concurrency","term":"Structured Concurrency","reading":"구조적 동시성","category":"컴퓨터과학 기초","summary":"구조적 동시성은 시작한 일이 **태어난 자리보다 오래 못 살게** 하는 원칙이다.","aliases":["structured concurrency","구조적 동시성"],"related":[{"term":"Coroutine","note":"— 이 원칙이 부모와 자식으로 묶어 다스리는 대상"},{"term":"Concurrency","note":"— 여러 일을 동시에 진행시키는 성질. 이 원칙은 그것에 수명 규칙을 씌운다"},{"term":"Async-Await","note":"— 자식 작업을 띄우고 그 결과를 기다리는 문법"},{"term":"Scope","note":"— 이름이 살아 있는 범위. 여기서는 작업이 살아 있는 범위로 쓰인다"},{"term":"Thread","note":"— 구조가 없던 시절에는 이 단위를 하나씩 손으로 붙들어야 했다"}]},{"id":"cs--system-call","term":"System Call","reading":"시스템 콜","category":"컴퓨터과학 기초","summary":"System Call은 **프로그램이 커널에 일을 시키는 유일한 창구**다.","aliases":["system call","시스템 콜"],"related":[{"term":"Kernel","note":"— 이 창구 너머에서 실제로 일을 하는 쪽"},{"term":"OS","note":"— 시스템 콜은 그 운영체제가 프로그램에 내놓은 창구 목록이다"},{"term":"Process","note":"— 시스템 콜을 부르는 주체이자, 커널이 대신 관리해 주는 단위"},{"term":"Memory","note":"— 메모리를 더 달라는 것도 이 창구로 부탁한다"},{"term":"Container","note":"— 허용할 시스템 콜만 골라 남겨 두는 대표적 자리"}]},{"id":"cs--thread","term":"Thread","reading":"스레드","category":"컴퓨터과학 기초","summary":"Thread는 **한 프로그램 안에서 따로 도는 실행 흐름**이다.","aliases":["thread","스레드"],"related":[{"term":"Process","note":"— 스레드를 담고 있는 독립된 실행 단위"},{"term":"Concurrency","note":"— 여러 일을 번갈아 진행하는 개념"},{"term":"Parallelism","note":"— 실제로 동시에 도는 것. 코어가 여럿이어야 한다"},{"term":"Multi-thread","note":"— 스레드를 여러 개 쓰는 방식"}]},{"id":"cs--tree","term":"Tree","reading":"트리","category":"컴퓨터과학 기초","summary":"Tree 는 **한 뿌리에서 아래로 갈라져 내려가는 구조**다.","aliases":["tree","트리"],"related":[{"term":"자료구조","note":"— 이 모양이 어느 자리에 맞는지 고르는 기준을 다루는 상위 단어"},{"term":"Heap","note":"— 부모와 자식 사이 크기 규칙만 지키는 트리"},{"term":"B-Tree","note":"— 한 마디를 여러 갈래로 넓혀 디스크에 맞춘 트리"},{"term":"Hash Table","note":"— 순서와 범위가 필요 없을 때 대신 고르는 모양"},{"term":"Big O 표기법","note":"— O(log n) 이 무슨 뜻인지 적는 표기"}]},{"id":"cs--virtual-memory","term":"Virtual Memory","reading":"가상 메모리","category":"컴퓨터과학 기초","summary":"Virtual Memory는 **프로그램마다 메모리를 혼자 통째로 쓰는 것처럼 보여주는 장치**다.","aliases":["virtual memory","가상 메모리"],"related":[{"term":"RAM","note":"— 가상 주소가 실제로 놓이는 자리. 여기 올라와 있는 몫이 작업 집합이다"},{"term":"Memory","note":"— 빠른 층부터 느린 층까지 겹쳐 쓰는 구조. 가상 메모리가 그 층을 감춰 준다"},{"term":"Process","note":"— 주소 범위와 장부를 하나씩 따로 받는 단위"},{"term":"OS","note":"— 장부를 관리하고 페이지를 올렸다 내리는 주체"},{"term":"Context Switch","note":"— 프로세스를 바꿀 때 이 장부까지 함께 갈아 끼운다"}]},{"id":"cs--windows","term":"Windows","reading":"윈도우","category":"컴퓨터과학 기초","summary":"Windows는 **마이크로소프트가 만든 데스크톱 운영체제**다.","aliases":["windows","윈도우"],"related":[{"term":"OS","note":"— Windows가 속한 갈래"},{"term":"Linux","note":"— 서버 쪽에서 더 많이 쓰이는 다른 운영체제"},{"term":"CLI","note":"— CMD와 PowerShell이 여기에 해당한다"},{"term":"Process","note":"— 작업 관리자에 목록으로 보이는 것"}]},{"id":"cs--term-36813d92","term":"알고리즘","reading":"Algorithm","category":"컴퓨터과학 기초","summary":"알고리즘은 **문제를 푸는 절차를 단계로 적어둔 것**이다.","aliases":["알고리즘","algorithm"],"related":[{"term":"Big O 표기법","note":"— 시간이 늘어나는 모양을 적는 표기"},{"term":"자료구조","note":"— 데이터를 어떻게 담아두느냐가 쓸 수 있는 절차를 정한다"},{"term":"Recursion","note":"— 문제를 같은 모양의 작은 문제로 쪼갤 때 쓰는 방식"},{"term":"Hash","note":"— 이미 본 값을 기록해두고 한 번에 찾을 때 쓰인다"},{"term":"CPU","note":"— 절차를 실제로 실행하는 곳. 비교 횟수가 곧 여기서 도는 시간이다"}]},{"id":"cs--term-ffa8fb5a","term":"자료구조","reading":"Data Structure","category":"컴퓨터과학 기초","summary":"자료구조는 **데이터를 어떤 모양으로 담아둘지 정해 놓은 방식**이다.","aliases":["자료구조","data structure"],"related":[{"term":"Array","note":"— 한 줄로 늘어놓는 가장 기본 모양"},{"term":"Hash","note":"— 열쇠를 계산해 자리를 정하는 방식"},{"term":"Stack","note":"— 마지막에 넣은 것을 먼저 꺼내는 줄"},{"term":"Queue","note":"— 처음 넣은 것을 먼저 꺼내는 줄"},{"term":"Big O 표기법","note":"— 어느 쪽이 빠른지 견주어 적는 표기"}]}]},{"id":"lang","name":"프로그래밍","blurb":"코드를 이루는 말들","terms":[{"id":"lang--array-list","term":"Array / List","reading":"배열 / 리스트","category":"프로그래밍","summary":"Array는 **여러 값을 번호 순서대로 담아두는 그릇**이다.","aliases":["array / list","배열 / 리스트","array","list","배열","리스트"],"related":[{"term":"Dictionary","note":"— 번호 대신 이름으로 값을 꺼내는 자료구조"},{"term":"Loop","note":"— 배열을 처음부터 끝까지 도는 데 쓴다"},{"term":"Variable","note":"— 배열도 결국 변수 하나에 담긴다"},{"term":"Big O 표기법","note":"— 번호로 꺼내기와 가운데 끼우기의 비용 차이를 재는 잣대"}]},{"id":"lang--base64","term":"Base64","reading":"베이스64","category":"프로그래밍","summary":"Base64 는 **이진 데이터를 글자 64개로 바꿔 적는 방법**이다.","aliases":["base64","베이스64"],"related":[{"term":"Character Encoding","note":"— 글자를 바이트로 바꾸는 반대 방향의 일"},{"term":"Serialization","note":"— 값을 한 줄로 펴는 일. 그 결과가 이진이면 Base64 가 뒤를 잇는다"},{"term":"JSON","note":"— 글자만 담을 수 있어서 이진을 넣으려면 Base64 를 거쳐야 하는 형식"},{"term":"JWT","note":"— 세 토막을 전부 Base64 로 적어 잇는 대표 사례"},{"term":"HTTP","note":"— 헤더처럼 글자만 지나는 자리를 가진 프로토콜"}]},{"id":"lang--build","term":"Build","reading":"빌드","category":"프로그래밍","summary":"Build는 **소스 코드를 실행할 수 있는 형태로 만드는 과정**이다.","aliases":["build","빌드"],"related":[{"term":"Compile","note":"— 소스를 실행 가능한 형태로 바꾸는 단계. 빌드의 일부다"},{"term":"CI_CD","note":"— 코드가 올라올 때마다 빌드와 배포를 자동으로 돌리는 구조"},{"term":"Docker","note":"— 빌드 환경까지 이미지에 담아 결과를 같게 만드는 도구"},{"term":"Package","note":"— 빌드가 받아 오는 외부 의존성의 단위"},{"term":"Environment Variable","note":"— 빌드 시점에 값이 달라지는 설정을 넣는 자리"}]},{"id":"lang--csv","term":"CSV","reading":"Comma-Separated Values","category":"프로그래밍","summary":"CSV는 **쉼표로 값을 나눈 표 데이터 텍스트 파일**이다.","aliases":["csv","comma-separated values"],"related":[{"term":"JSON","note":"— 중첩된 구조를 담을 수 있는 형식. CSV는 표 하나만 담는다"},{"term":"XML","note":"— 태그로 구조를 표현하는 또 다른 교환 형식"},{"term":"SQL","note":"— 조회 결과를 CSV로 내보내는 일이 잦다"},{"term":"구조화 데이터","note":"— CSV가 속한 갈래. 미리 정해진 틀에 값을 채우는 데이터"}]},{"id":"lang--class","term":"Class","reading":"클래스","category":"프로그래밍","summary":"Class는 **데이터와 기능을 한 덩어리로 묶은 설계도**다.","aliases":["class","클래스"],"related":[{"term":"Object","note":"— 클래스로 찍어낸 실체. 값은 여기에 들어 있다"},{"term":"Function","note":"— 같은 것이 클래스 안으로 들어가면 메서드가 된다"},{"term":"Variable","note":"— 같은 것이 클래스 안으로 들어가면 속성이 된다"},{"term":"Component","note":"— 화면 조각을 같은 방식으로 묶어 재사용하는 단위"}]},{"id":"lang--closure","term":"Closure","reading":"클로저","category":"프로그래밍","summary":"Closure는 **자기가 태어난 자리를 그대로 데리고 다니는 함수**다.","aliases":["closure","클로저"],"related":[{"term":"Function","note":"— 클로저는 함수에 태어난 자리를 붙여 둔 것이다"},{"term":"Variable","note":"— 함수가 붙들고 다니는 것이 바로 이 이름들이다"},{"term":"Object","note":"— 값과 그 값을 다루는 일을 함께 묶는 다른 방법"},{"term":"OOP","note":"— 데이터 감추기와 캡슐화를 짜임의 기둥으로 삼는 쪽"},{"term":"Garbage Collection","note":"— 붙들린 값이 언제까지 안 사라지는지를 정하는 자리"}]},{"id":"lang--code-coverage","term":"Code Coverage","reading":"코드 커버리지","category":"프로그래밍","summary":"코드 커버리지는 **테스트가 실제로 지나간 코드의 비율**이다.","aliases":["code coverage","코드 커버리지"],"related":[{"term":"Unit Test","note":"— 이 값을 실제로 만들어 내는 쪽. 밟는 일은 테스트가 한다"},{"term":"Integration Test","note":"— 단위 테스트가 못 닿는 자리를 대신 지나가며 값을 채운다"},{"term":"TDD","note":"— 테스트를 먼저 쓰는 방식. 커버리지는 목표가 아니라 결과로 따라온다"},{"term":"CI/CD","note":"— 변경마다 이 값을 자동으로 재고 떨어지면 세우는 자리"}]},{"id":"lang--compile","term":"Compile","reading":"컴파일","category":"프로그래밍","summary":"컴파일은 **사람이 쓴 코드를 기계어로 미리 번역하는 일**이다.","aliases":["compile","컴파일"],"related":[{"term":"Build","note":"— 컴파일과 링킹, 포장까지 묶은 더 넓은 과정"},{"term":"Compile vs Interpret","note":"— 미리 번역해두는 쪽과 그때그때 해석하는 쪽의 차이"},{"term":"Binary","note":"— 컴파일 결과로 나오는 0과 1의 형태"},{"term":"CPU","note":"— 컴파일된 기계어를 실제로 읽는 쪽"}]},{"id":"lang--compile-vs-interpret","term":"Compile vs Interpret","reading":"컴파일 vs 인터프리트","category":"프로그래밍","summary":"컴파일과 인터프리트는 **코드를 기계가 실행하게 만드는 두 방식**이다.","aliases":["compile vs interpret","컴파일 vs 인터프리트","interpret","인터프리트"],"related":[{"term":"Compile","note":"— 이 글의 한쪽. 실행 전에 한 번에 옮기는 방식"},{"term":"Build","note":"— 컴파일을 포함해 돌릴 수 있는 결과물을 만들어내는 전체 작업"},{"term":"CPU","note":"— 옮겨진 기계어를 실제로 실행하는 쪽"},{"term":"Binary","note":"— 컴파일 결과로 남는 파일의 형태"}]},{"id":"lang--component","term":"Component","reading":"컴포넌트","category":"프로그래밍","summary":"Component는 **화면의 한 조각을 떼어내 재사용하는 단위**다.","aliases":["component","컴포넌트"],"related":[{"term":"Frontend","note":"— 컴포넌트를 조립해 화면을 만드는 쪽"},{"term":"CSR","note":"— 브라우저가 컴포넌트를 조립해 화면을 그리는 방식"},{"term":"SPA","note":"— 화면 전체를 컴포넌트 트리로 두고 부분만 갈아 끼우는 구조"},{"term":"Function","note":"— 값을 돌려주는 함수와 달리 컴포넌트는 화면 조각을 돌려준다"},{"term":"Framework vs Library","note":"— 컴포넌트를 어떤 규칙으로 조립할지는 프레임워크가 정한다"}]},{"id":"lang--dependency-injection","term":"Dependency Injection","reading":"의존성 주입","category":"프로그래밍","summary":"Dependency Injection 은 **쓸 것을 스스로 만들지 않고 밖에서 받는** 방식이다.","aliases":["dependency injection","의존성 주입"],"related":[{"term":"Dependency","note":"— 주입해서 다루려는 그 기댐 자체"},{"term":"Unit Test","note":"— 진짜 대신 가짜를 끼워 넣어 돌리는 쪽"},{"term":"Class","note":"— 무엇을 받을지 적어 두는 자리"},{"term":"Framework vs Library","note":"— 부르는 쪽이 뒤집히는 같은 성질을 다루는 자리"}]},{"id":"lang--dictionary-map","term":"Dictionary / Map","reading":"딕셔너리 / 맵","category":"프로그래밍","summary":"Dictionary는 **이름표를 붙여 값을 넣어두는 자료구조**다.","aliases":["dictionary / map","딕셔너리 / 맵","dictionary","map"],"related":[{"term":"Hash","note":"— 키를 칸 번호로 바꾸는 계산. 딕셔너리가 빠른 이유다"},{"term":"Array","note":"— 순서 번호로 찾는 쪽. 딕셔너리와 대비된다"},{"term":"Object","note":"— 여기에 기능까지 함께 묶은 것"},{"term":"JSON","note":"— 딕셔너리 모양을 그대로 글자로 적는 형식"},{"term":"자료구조","note":"— 딕셔너리가 속한 큰 갈래"}]},{"id":"lang--exception","term":"Exception","reading":"예외 처리","category":"프로그래밍","summary":"Exception 은 **실행 중에 생긴 오류를 정상 흐름 밖으로 넘기는 장치**다.","aliases":["exception","예외 처리"],"related":[{"term":"Function","note":"— 예외가 밖으로 밀려 올라가는 길이 함수를 부른 순서 그대로다"},{"term":"Type System","note":"— 실행 전에 걸러지는 오류와 실행 중에 터지는 오류를 가르는 선"},{"term":"Null Safety","note":"— 값이 없는 경우를 예외로 터뜨리지 않고 미리 막으려는 쪽"},{"term":"Debugger","note":"— 예외가 난 자리와 거기까지 온 호출 자취를 들여다보는 도구"}]},{"id":"lang--framework-vs-library","term":"Framework vs Library","reading":"프레임워크와 라이브러리","category":"프로그래밍","summary":"둘의 차이는 **누가 누구를 부르느냐** 하나로 갈린다.","aliases":["framework vs library","프레임워크와 라이브러리","framework","library"],"related":[{"term":"Package","note":"— 라이브러리를 묶어 배포하고 설치하는 단위"},{"term":"SDK","note":"— 특정 서비스를 쓰라고 묶어 주는 도구 모음. 대개 라이브러리 쪽이다"},{"term":"Component","note":"— 프레임워크가 정해진 시점에 불러 쓰는 단위의 대표적인 예"},{"term":"Build","note":"— 프레임워크가 정한 구조대로 코드를 묶어 내보내는 단계"}]},{"id":"lang--function","term":"Function","reading":"함수","category":"프로그래밍","summary":"Function은 **이름을 붙여 다시 부를 수 있게 묶어둔 코드**다.","aliases":["function","함수"],"related":[{"term":"Variable","note":"— 함수가 받는 값과 돌려주는 값이 담기는 자리"},{"term":"Class","note":"— 함수가 클래스 안으로 들어가면 메서드가 된다"},{"term":"Recursion","note":"— 함수가 자기 자신을 부르는 방식"},{"term":"Loop","note":"— 반복하는 부분을 함수로 감싸 이름을 붙이는 일이 흔하다"}]},{"id":"lang--functional-programming","term":"Functional Programming","reading":"함수형 프로그래밍","category":"프로그래밍","summary":"함수형 프로그래밍은 **바깥을 건드리지 않는 함수로 프로그램을 짜는 방식**이다.","aliases":["functional programming","함수형 프로그래밍"],"related":[{"term":"Function","note":"— 이 방식이 유일한 재료로 삼는 것"},{"term":"Immutability","note":"— 값을 고치지 않는다는 짝 규칙"},{"term":"Variable","note":"— 값을 고쳐 가며 짜는 반대편 방식의 도구"},{"term":"Recursion","note":"— 값을 고치는 반복문 없이 되풀이하는 방법"}]},{"id":"lang--generic","term":"Generic","reading":"제네릭","category":"프로그래밍","summary":"Generic은 **값의 갈래를 비워 둔 채로 만들어 두는 틀**이다.","aliases":["generic","제네릭"],"related":[{"term":"Class","note":"— 갈래를 비워 두는 틀이 클래스일 때가 가장 흔하다"},{"term":"Interface","note":"— 비운 자리에 무엇이 올 수 있는지 거는 조건으로 쓰인다"},{"term":"Array","note":"— 담는 갈래만 다르고 하는 일이 같은 대표적인 통"},{"term":"Compile","note":"— 갈래가 맞는지 실행 전에 걸러지는 자리"}]},{"id":"lang--immutability","term":"Immutability","reading":"불변성","category":"프로그래밍","summary":"불변성은 **한 번 만든 값을 고치지 않는** 성질이다.","aliases":["immutability","불변성"],"related":[{"term":"Functional Programming","note":"— 값을 고치지 않는다는 이 규칙을 짜기 방식으로 삼은 갈래"},{"term":"Variable","note":"— 이름과 값을 잇는 자리. 불변성은 그중 값 쪽을 잠근다"},{"term":"Immutable Infrastructure","note":"— 같은 생각을 서버에 옮겨, 고치는 대신 새로 만들어 갈아 끼운다"},{"term":"Event Sourcing","note":"— 상태를 덮어쓰지 않고 일어난 일을 덧붙여 쌓는 저장 방식"}]},{"id":"lang--integration-test","term":"Integration Test","reading":"통합 테스트","category":"프로그래밍","summary":"Integration Test 는 **조각을 이어 붙여 함께 도는지 보는** 테스트다.","aliases":["integration test","통합 테스트"],"related":[{"term":"Unit Test","note":"— 조각 하나 안쪽을 맡는 쪽"},{"term":"TDD","note":"— 시험을 먼저 쓰는 순서. 통합에도 쓴다"},{"term":"Dependency Injection","note":"— 어디까지 진짜를 붙일지 정하는 자리"},{"term":"Transaction","note":"— 시험이 남긴 것을 되돌릴 때 쓰는 묶음"},{"term":"CI/CD","note":"— 합칠 때마다 이 시험을 돌리는 자리"}]},{"id":"lang--interface","term":"Interface","reading":"인터페이스","category":"프로그래밍","summary":"Interface는 **할 일의 목록만 적고 방법은 안 적은 약속**이다.","aliases":["interface","인터페이스"],"related":[{"term":"Class","note":"— 약속을 실제로 지키는 쪽에 가장 흔히 쓰는 틀"},{"term":"OOP","note":"— 대상이 밖으로 열어 두는 면을 짜임의 중심에 두는 방식"},{"term":"API","note":"— 프로그램끼리 맞닿는 면을 같은 뜻으로 부르는 이름"},{"term":"Generic","note":"— 비워 둔 갈래 자리에 무엇이 올 수 있는지 거는 조건으로 쓰인다"}]},{"id":"lang--iterator","term":"Iterator","reading":"반복자","category":"프로그래밍","summary":"반복자는 **속을 안 열고 원소를 하나씩 내주는** 물건이다.","aliases":["iterator","반복자"],"related":[{"term":"Loop","note":"— 반복문. 반복자를 안 보이게 감싸서 도는 문법이다"},{"term":"Array","note":"— 번호로 바로 집는 모음. 반복자는 번호 없이도 도는 길을 준다"},{"term":"Interface","note":"— \"다음이 있나 / 하나 줘\" 만 약속으로 내주는 자리"},{"term":"Generic","note":"— 원소 타입이 무엇이든 같은 반복자로 다루게 하는 장치"}]},{"id":"lang--json","term":"JSON","reading":"JavaScript Object Notation","category":"프로그래밍","summary":"JSON 은 **프로그램끼리 데이터를 주고받으려고 적어두는 텍스트 형식**이다.","aliases":["json","javascript object notation"],"related":[{"term":"API","note":"— JSON 이 가장 많이 오가는 자리"},{"term":"YAML","note":"— 사람이 쓰기 편한 쪽으로 기운 형식"},{"term":"XML","note":"— JSON 이전에 같은 자리를 맡던 형식"},{"term":"CSV","note":"— 표 모양 데이터를 주고받는 더 단순한 형식"}]},{"id":"lang--json-schema","term":"JSON Schema","reading":"JSON 스키마","category":"프로그래밍","summary":"JSON Schema는 **JSON 이 어떤 모양이어야 하는지 적어둔 JSON**이다.","aliases":["json schema","json 스키마"],"related":[{"term":"JSON","note":"— 스키마도 검사받는 쪽도 이 형식으로 쓴다"},{"term":"OpenAPI","note":"— API 명세가 요청·응답의 모양을 적을 때 기대는 자리"},{"term":"구조화 데이터","note":"— 모양을 미리 정해둔다는 같은 생각이 데이터베이스 쪽에 선 모습"},{"term":"YAML","note":"— 같은 규칙을 사람이 쓰기 편한 표기로 적을 때 쓰는 이웃 형식"}]},{"id":"lang--loop","term":"Loop","reading":"반복문","category":"프로그래밍","summary":"Loop 는 **같은 코드를 조건이 끝날 때까지 다시 실행하는 구조**다.","aliases":["loop","반복문"],"related":[{"term":"Array","note":"— 반복문이 가장 많이 도는 대상"},{"term":"Recursion","note":"— 같은 일을 함수 호출로 되풀이하는 다른 방법"},{"term":"Big O 표기법","note":"— 반복이 겹칠수록 커지는 비용을 재는 잣대"},{"term":"Function","note":"— 되풀이할 일을 이름 붙여 떼어내는 쪽"}]},{"id":"lang--null-safety","term":"Null Safety","reading":"널 안전성","category":"프로그래밍","summary":"Null Safety 는 **값이 없을 수 있는 자리를 타입에 표시해 두는 장치**다.","aliases":["null safety","널 안전성"],"related":[{"term":"Type System","note":"— 없을 수 있음을 타입 쪽으로 옮겨 놓은 것이라 그 규칙 위에서만 성립한다"},{"term":"Exception","note":"— 표시가 없을 때 빈 값이 결국 예외로 터져 나오는 자리"},{"term":"Variable","note":"— 비어도 되는지 아닌지가 붙는 자리"},{"term":"Function","note":"— 못 찾았음을 돌려줄 수 있다는 사실이 반환 타입에 적히는 곳"}]},{"id":"lang--oop","term":"OOP","reading":"Object-Oriented Programming","category":"프로그래밍","summary":"OOP는 **값과 기능을 묶은 객체들로 프로그램을 짜는 방식**이다.","aliases":["oop","object-oriented programming"],"related":[{"term":"Object","note":"— 이 방식이 중심에 두는 그 대상"},{"term":"Class","note":"— 그 대상을 찍어내는 틀"},{"term":"Interface","note":"— 대상이 밖으로 열어 두는 면만 뽑아 약속으로 적은 것"},{"term":"Function","note":"— 대상 안으로 들어가면 메서드라 불린다"},{"term":"Closure","note":"— 값과 그 값을 다루는 일을 묶는 다른 방법"}]},{"id":"lang--object","term":"Object","reading":"객체","category":"프로그래밍","summary":"Object는 **데이터와 그 데이터를 다루는 기능을 한 덩어리로 묶은 것**이다.","aliases":["object","객체"],"related":[{"term":"Class","note":"— 객체를 만들어내는 설계도"},{"term":"Variable","note":"— 객체가 있는 자리를 가리키는 이름"},{"term":"Function","note":"— 객체 안에 들어가면 메서드가 된다"},{"term":"Dictionary","note":"— 값만 묶는 쪽. 객체는 여기에 기능까지 넣는다"},{"term":"Memory","note":"— 객체가 실제로 자리를 잡는 곳"}]},{"id":"lang--package-module","term":"Package / Module","reading":"패키지 / 모듈","category":"프로그래밍","summary":"Module은 코드 파일 하나고, **Package는 그 파일들을 묶은 폴더**다.","aliases":["package / module","패키지 / 모듈","package","module","패키지","모듈"],"related":[{"term":"Function","note":"— 모듈 안에 담기는 것"},{"term":"Class","note":"— 모듈 안에 담기는 또 하나"},{"term":"Framework vs Library","note":"— 남이 만든 패키지를 쓰는 두 방식"},{"term":"Build","note":"— 흩어진 모듈을 하나로 묶어 내보내는 단계"}]},{"id":"lang--protocol-buffers","term":"Protocol Buffers","reading":"프로토콜 버퍼","category":"프로그래밍","summary":"Protocol Buffers 는 **주고받을 모양을 먼저 적어두고 값을 이진으로 펴는 방식**이다.","aliases":["protocol buffers","프로토콜 버퍼"],"related":[{"term":"gRPC","note":"— 이 방식을 창구 정의와 메시지 형식으로 함께 쓰는 대표 자리"},{"term":"JSON","note":"— 같은 일을 사람이 읽는 글자로 하는 형식. 공식 문서가 견주는 상대다"},{"term":"Serialization","note":"— 값을 한 줄로 펴는 일. 이 방식은 그 일을 이진으로 한다"},{"term":"JSON Schema","note":"— 모양을 미리 못 박는다는 점이 닮은, 글자 쪽의 방법"},{"term":"Compile","note":"— `.proto` 에서 언어별 코드가 나오는 그 단계"}]},{"id":"lang--recursion","term":"Recursion","reading":"재귀","category":"프로그래밍","summary":"Recursion은 **함수가 자기 자신을 부르는 방식**이다.","aliases":["recursion","재귀"],"related":[{"term":"Function","note":"— 재귀가 딛고 서는 단위"},{"term":"Stack","note":"— 아직 답을 못 받은 호출이 쌓이는 곳"},{"term":"Loop","note":"— 같은 일을 하는 다른 방법. 비용 계산이 반대다"},{"term":"Algorithm","note":"— 분할 정복처럼 재귀를 전제로 짜인 것들이 있다"},{"term":"자료구조","note":"— 트리처럼 자기 안에 자기를 품은 구조와 잘 맞는다"}]},{"id":"lang--reflection","term":"Reflection","reading":"리플렉션","category":"프로그래밍","summary":"리플렉션은 **제 구조를 실행 중에 들여다보는** 기능이다.","aliases":["reflection","리플렉션"],"related":[{"term":"Type System","note":"— 타입을 언제 판정하나. 리플렉션은 그 판정을 실행 중으로 미룬다"},{"term":"Serialization","note":"— 값을 저장·전송 형태로 바꾸는 일. 필드 이름을 여기서 읽어 온다"},{"term":"Generic","note":"— 타입을 미리 안 정하고 짜는 다른 길. 이쪽은 컴파일할 때 정해진다"},{"term":"Class","note":"— 실행 중에 물어보는 대상. 이름·필드·함수가 여기 담겨 있다"}]},{"id":"lang--scope","term":"Scope","reading":"스코프","category":"프로그래밍","summary":"Scope 는 **이름 하나가 그대로 통하는 글의 구역**이다.","aliases":["scope","스코프"],"related":[{"term":"Variable","note":"— 구역이 붙는 대상. 이름이 어디까지 통하는지가 곧 그 변수를 쓸 수 있는 범위다"},{"term":"Function","note":"— 대부분의 언어에서 새 구역이 열리는 대표적인 자리"},{"term":"Class","note":"— 이름을 자기 안에 묶어 두는 또 다른 구역"},{"term":"Package / Module","note":"— 파일 하나 바깥으로 이름이 새 나갈지를 정하는 더 큰 구역"}]},{"id":"lang--serialization","term":"Serialization","reading":"직렬화","category":"프로그래밍","summary":"직렬화는 **메모리 속 값을 한 줄로 펴서 저장하거나 보내는 일**이다.","aliases":["serialization","직렬화"],"related":[{"term":"JSON","note":"— 편 결과를 적는 가장 흔한 형식"},{"term":"Base64","note":"— 편 결과가 이진일 때 그것을 다시 글자로 옮기는 자리"},{"term":"Protocol Buffers","note":"— 모양을 먼저 정해 두고 이진으로 펴는 방식"},{"term":"Character Encoding","note":"— 글자를 바이트로 바꾸는 한 층 아래의 일"},{"term":"Object","note":"— 펴기 전에 메모리에 놓여 있던 그 값의 이름"}]},{"id":"lang--tdd","term":"TDD","reading":"Test-Driven Development","category":"프로그래밍","summary":"TDD 는 **코드보다 테스트를 먼저 쓰는** 개발 방식이다.","aliases":["tdd","test-driven development"],"related":[{"term":"Unit Test","note":"— 먼저 쓰는 그 테스트가 대개 이것이다"},{"term":"Integration Test","note":"— 조각을 붙인 뒤에도 같은 순서를 쓸 수 있다"},{"term":"Dependency Injection","note":"— 먼저 쓴 테스트가 돌아가게 자리를 내주는 장치"},{"term":"Agile","note":"— 짧게 돌면서 고쳐 가는 같은 결의 방식"},{"term":"CI/CD","note":"— 남긴 테스트를 합칠 때마다 자동으로 돌리는 자리"}]},{"id":"lang--type-system","term":"Type System","reading":"타입 시스템","category":"프로그래밍","summary":"Type System 은 **값의 종류를 정하고 그 종류에 안 맞는 연산을 막는 규칙**이다.","aliases":["type system","타입 시스템"],"related":[{"term":"Variable","note":"— 종류가 붙는 자리. 이 이름이 어떤 값을 담을 수 있는지가 여기서 정해진다"},{"term":"Function","note":"— 무엇을 받아 무엇을 돌려주는지가 타입으로 적히는 대표적인 자리"},{"term":"Null Safety","note":"— \"값이 없음\" 까지 하나의 종류로 만들어 미리 막는 쪽"},{"term":"Compile","note":"— 정적 검사가 실행 전에 끼어드는 지점"}]},{"id":"lang--typescript","term":"TypeScript","reading":"타입스크립트","category":"프로그래밍","summary":"TypeScript는 **JavaScript 에 값의 종류를 적어 두는 언어**다.","aliases":["typescript","타입스크립트"],"related":[{"term":"JavaScript","note":"— 표기를 지우고 나면 남는 것"},{"term":"Type System","note":"— 적어 두는 그 종류들을 다루는 규칙 전체"},{"term":"Compile","note":"— 적어 둔 것을 돌아가는 형태로 바꾸는 단계"},{"term":"Null Safety","note":"— 종류를 적어 두어 막는 대표적인 사고"}]},{"id":"lang--unit-test","term":"Unit Test","reading":"단위 테스트","category":"프로그래밍","summary":"Unit Test 는 **작은 조각 하나를 따로 떼어 확인하는** 테스트다.","aliases":["unit test","단위 테스트"],"related":[{"term":"Integration Test","note":"— 조각을 이어 붙여야 드러나는 것을 맡는 쪽"},{"term":"TDD","note":"— 이 시험을 코드보다 먼저 쓰는 순서"},{"term":"Dependency Injection","note":"— 진짜 대신 가짜를 끼울 수 있게 만드는 장치"},{"term":"Function","note":"— 대개 한 조각이라고 부르는 그 대상"},{"term":"CI/CD","note":"— 올릴 때마다 이 시험을 자동으로 돌리는 자리"}]},{"id":"lang--variable","term":"Variable","reading":"변수","category":"프로그래밍","summary":"Variable은 **값에 이름을 붙여두는 자리**다.","aliases":["variable","변수"],"related":[{"term":"Memory","note":"— 변수가 실제로 자리를 잡는 곳"},{"term":"Function","note":"— 지역 변수의 범위를 정하는 단위"},{"term":"Class","note":"— 변수를 속성으로 묶어 두는 틀"},{"term":"Object","note":"— 이름이 값이 아니라 가리키는 표시를 담는 대표적인 예"},{"term":"Loop","note":"— 변수에 값을 누적하며 도는 구조"}]},{"id":"lang--xml","term":"XML","reading":"eXtensible Markup Language","category":"프로그래밍","summary":"XML은 **여는 태그와 닫는 태그로 데이터의 구조를 적는 형식**이다.","aliases":["xml","extensible markup language"],"related":[{"term":"JSON","note":"— 같은 일을 더 짧게 적는 형식. 웹 API 에서 주로 쓰인다"},{"term":"YAML","note":"— 사람이 쓰기 쉬운 쪽으로 만든 설정 형식"},{"term":"CSV","note":"— 값만 나열하는 형식. 계층을 담지 못한다"},{"term":"API","note":"— XML 이 요청과 응답의 본문으로 쓰이는 자리"}]},{"id":"lang--yaml","term":"YAML","reading":"YAML Ain't Markup Language","category":"프로그래밍","summary":"YAML은 **들여쓰기로 구조를 나타내는 설정 파일 형식**이다.","aliases":["yaml","yaml ain't markup language"],"related":[{"term":"JSON","note":"— 같은 데이터를 괄호로 표현하는 형식. 프로그램끼리 주고받을 때 쓴다"},{"term":"Docker","note":"— 컨테이너 구성을 YAML 파일로 적는다"},{"term":"Kubernetes","note":"— 원하는 상태를 YAML로 적어 넘긴다"},{"term":"Environment Variable","note":"— 비밀번호처럼 파일에 적으면 안 되는 값을 대신 넣는 자리"}]},{"id":"lang--term-ac6828de","term":"정규표현식","reading":"Regex / Regular Expression","category":"프로그래밍","summary":"정규표현식은 **글자의 모양을 규칙으로 적어 찾아내는 문법**이다.","aliases":["정규표현식","regex / regular expression","regex","regular expression"],"related":[{"term":"PII","note":"— 주민번호나 전화번호 모양을 정규식으로 찾아 가린다"},{"term":"Guardrail","note":"— 정규식으로 만든 검사 규칙을 모아둔 장치"},{"term":"SQL Injection","note":"— 정규식 검증만 믿으면 막지 못하는 공격"},{"term":"Compile","note":"— 패턴도 쓰기 전에 한 번 내부 형태로 바꾼다"}]}]},{"id":"net","name":"네트워크","blurb":"요청이 오가는 길","terms":[{"id":"net--alpn","term":"ALPN","reading":"응용 계층 프로토콜 협상","category":"네트워크","summary":"ALPN은 **TLS 인사 안에서 그다음에 쓸 규약(프로토콜)을 골라 두는 확장**이다.","aliases":["alpn","응용 계층 프로토콜 협상"],"related":[{"term":"SSL/TLS","note":"— 이 협상이 실려 가는 인사 그 자체"},{"term":"HTTP/2","note":"— TLS 위에서 이 칸 없이는 못 켜지는 대표 규약"},{"term":"HTTP/3","note":"— `h3` 라는 등록된 이름으로 같은 자리에서 골라진다"},{"term":"Server Name Indication","note":"— 같은 `ClientHello` 에 나란히 실리는 옆 칸"},{"term":"TLS Termination","note":"— 고른 이름을 보고 뒷단으로 어떻게 넘길지 정하는 자리"}]},{"id":"net--arp","term":"ARP","reading":"Address Resolution Protocol","category":"네트워크","summary":"ARP는 **IP 주소로 그 장비의 MAC 주소를 알아내는 규칙**이다.","aliases":["arp","address resolution protocol"],"related":[{"term":"MAC Address","note":"— ARP 가 알아내려는 바로 그 번호"},{"term":"IP Address","note":"— 이미 알고 있는 쪽. 이것을 들고 묻는다"},{"term":"Router vs Switch","note":"— 망 밖으로 나갈 때 ARP 가 대신 물어보는 상대"},{"term":"Subnet","note":"— 같은 망인지 밖인지를 가르는 기준"},{"term":"OSI 7계층","note":"— 3계층 주소와 2계층 주소가 만나는 자리"}]},{"id":"net--anycast","term":"Anycast","reading":"애니캐스트","category":"네트워크","summary":"애니캐스트는 **한 주소를 여러 곳이 함께 알리는 방식**이다.","aliases":["anycast","애니캐스트"],"related":[{"term":"BGP","note":"— 같은 주소를 여러 곳에서 알릴 때 쓰는 그 알림"},{"term":"DNS","note":"— 지역별로 다른 주소를 주는 다른 방법. 캐시 시간이 발목을 잡는다"},{"term":"CDN","note":"— 애니캐스트로 사용자를 가까운 엣지에 붙이는 대표적 쓰임"},{"term":"Load Balancer","note":"— 한 지점 안에서 다시 나누는 층"},{"term":"IPv6","note":"— 애니캐스트를 주소 종류 셋 중 하나로 아예 규격에 넣은 판"}]},{"id":"net--autonomous-system","term":"Autonomous System","reading":"자율 시스템","category":"네트워크","summary":"Autonomous System은 **하나의 길 정책으로 묶인 망 덩어리**다.","aliases":["autonomous system","자율 시스템"],"related":[{"term":"BGP","note":"— 이 번호들 사이에 길을 주고받는 약속"},{"term":"OSPF","note":"— 한 번호 안쪽에서 길을 정하는 쪽"},{"term":"CIDR","note":"— 번호가 \"내 것\" 이라고 알리는 주소 묶음의 표기"},{"term":"IP Address","note":"— 그 묶음을 채우는 낱개 주소"},{"term":"Routing Table","note":"— 조직 번호로 고른 결과가 실제로 앉는 표"}]},{"id":"net--bgp","term":"BGP","reading":"경계 경로 프로토콜","category":"네트워크","summary":"BGP는 **인터넷의 조직들이 서로에게 길을 알려주는 약속**이다.","aliases":["bgp","경계 경로 프로토콜"],"related":[{"term":"Autonomous System","note":"— BGP 가 잇는 단위. 조직 하나에 번호 하나다"},{"term":"OSPF","note":"— 조직 안쪽 길을 정하는 다른 갈래. 지도를 나눠 갖는 방식이다"},{"term":"Routing Table","note":"— 주고받은 길이 결국 앉는 자리"},{"term":"CIDR","note":"— 주고받는 주소 덩어리를 적는 표기. 잘게 쪼갠 쪽이 이긴다"},{"term":"TCP","note":"— BGP 가 179 번 문으로 세션을 맺을 때 쓰는 연결"}]},{"id":"net--bandwidth","term":"Bandwidth","reading":"대역폭","category":"네트워크","summary":"Bandwidth 는 **일정 시간에 회선을 지날 수 있는 정보량**이다.","aliases":["bandwidth","대역폭"],"related":[{"term":"Latency","note":"— 같은 \"느리다\"를 굵기가 아니라 길이 쪽에서 재는 짝 개념"},{"term":"CDN","note":"— 굵기 대신 거리를 줄여 왕복 시간을 깎는 장치"},{"term":"Caching","note":"— 회선을 지나갈 양 자체를 없애서 굵기를 덜 쓰게 하는 방법"},{"term":"Core Web Vitals","note":"— 굵기도 길이도 아닌, 사용자가 본 결과로 속도를 재는 지표"}]},{"id":"net--cdn","term":"CDN","reading":"Content Delivery Network","category":"네트워크","summary":"CDN은 **파일을 사용자 가까운 곳에 미리 복사해두는 서버망**이다.","aliases":["cdn","content delivery network"],"related":[{"term":"DNS","note":"— 어느 거점으로 보낼지 고르는 데 쓰인다"},{"term":"Cache","note":"— CDN이 하는 일의 본질. 위치만 사용자 쪽으로 옮긴 것"},{"term":"TTL","note":"— 거점이 복사본을 얼마나 오래 들고 있을지 정하는 값"},{"term":"Load Balancer","note":"— 같은 곳에서 서버를 나누는 것. CDN은 지역을 나눈다"}]},{"id":"net--cidr","term":"CIDR","reading":"Classless Inter-Domain Routing","category":"네트워크","summary":"CIDR 는 IP 주소 묶음을 **앞 몇 비트가 같은지**로 자르는 방식이다.","aliases":["cidr","classless inter-domain routing"],"related":[{"term":"IP Address","note":"— CIDR 가 묶어서 다루는 바로 그 값"},{"term":"Subnet","note":"— 큰 CIDR 묶음을 더 작은 CIDR 로 쪼갠 것"},{"term":"VPC","note":"— 만들 때 CIDR 을 먼저 정해야 하는 클라우드 네트워크"},{"term":"Public IP vs Private IP","note":"— 사설 대역도 `10.0.0.0/8` 처럼 CIDR 로 적는다"},{"term":"방화벽 규칙","note":"— 허용 대상을 주소 하나가 아니라 CIDR 묶음으로 적는 자리"}]},{"id":"net--dhcp","term":"DHCP","reading":"Dynamic Host Configuration Protocol","category":"네트워크","summary":"DHCP 는 네트워크에 들어온 기기에 IP 주소를 **빌려주는** 규약이다.","aliases":["dhcp","dynamic host configuration protocol"],"related":[{"term":"IP Address","note":"— DHCP 가 기한을 걸어 빌려주는 바로 그 값"},{"term":"Subnet","note":"— 어느 대역에서 주소를 꺼내 줄지 정하는 범위"},{"term":"DNS","note":"— 주소와 함께 내려주는 이름 해석 서버"},{"term":"Gateway","note":"— 함께 내려주는 \"밖으로 나가는 문\" 의 주소"}]},{"id":"net--dkim","term":"DKIM","reading":"도메인키 식별 메일","category":"네트워크","summary":"DKIM은 **보낸 도메인이 메일에 서명을 붙여 두는 방식**이다.","aliases":["dkim","도메인키 식별 메일"],"related":[{"term":"SMTP","note":"— 이 서명이 얹혀 다니는 편지의 전달 약속"},{"term":"DNS","note":"— 공개 열쇠를 꺼내 오는 자리. 여기 없으면 검사 자체가 안 된다"},{"term":"Certificate","note":"— 같은 문제를 기관 보증으로 푸는 다른 방식"},{"term":"Encryption","note":"— 서명과 자주 헷갈리는 이웃. 이쪽은 감추는 일이다"},{"term":"Phishing","note":"— 이 서명이 겨누는 공격"}]},{"id":"net--dns","term":"DNS","reading":"Domain Name System","category":"네트워크","summary":"DNS는 **도메인 이름을 IP 주소로 바꿔주는 시스템**이다.","aliases":["dns","domain name system"],"related":[{"term":"TCP","note":"— DNS 조회가 끝난 뒤 실제 연결을 맺는 계층"},{"term":"HTTP","note":"— 받은 IP 로 주고받는 내용"},{"term":"CDN","note":"— DNS 응답을 지역별로 다르게 주는 대표적 활용"},{"term":"Load Balancer","note":"— 하나의 이름 뒤에 여러 서버를 두는 다른 방법"}]},{"id":"net--dns-routing-policy","term":"DNS Routing Policy","reading":"이름 조회 응답 정책","category":"네트워크","summary":"DNS Routing Policy는 **같은 이름을 물어도 묻는 쪽에 따라 다른 주소를 주는 규칙**이다.","aliases":["dns routing policy","이름 조회 응답 정책"],"related":[{"term":"DNS","note":"— 이 규칙이 얹히는 이름 조회 그 자체"},{"term":"TTL","note":"— 바꾼 규칙이 바로 안 듣는 이유"},{"term":"CDN","note":"— 지역별로 다른 답을 주는 가장 흔한 쓰임"},{"term":"Health Check","note":"— 죽은 주소를 답에서 빼는 판단 근거"},{"term":"Multi-Region","note":"— 이 규칙이 있어야 값을 하는 배치"}]},{"id":"net--dns-over-https","term":"DNS over HTTPS","reading":"암호화된 이름 조회","category":"네트워크","summary":"DNS over HTTPS는 **이름 조회를 HTTPS 요청 한 통으로 감싼 것**이다.","aliases":["dns over https","암호화된 이름 조회"],"related":[{"term":"DNS","note":"— 감싸는 대상. 안에 든 질의는 이쪽 형식 그대로다"},{"term":"HTTPS","note":"— 조회를 실어 나르는 통로 그 자체"},{"term":"DNSSEC","note":"— 통로가 아니라 답 자체의 진위를 보는 쪽"},{"term":"Server Name Indication","note":"— 조회를 가려도 그다음 인사에서 이름이 또 새는 자리"},{"term":"HTTP/2","note":"— 규격이 최소로 권고한 판. 한 연결에 조회 여러 개를 겹쳐 보낸다"}]},{"id":"net--dnssec","term":"DNSSEC","reading":"디엔에스 보안 확장","category":"네트워크","summary":"DNSSEC는 **DNS 응답에 서명을 붙여 위조를 잡아내는 확장**이다.","aliases":["dnssec","디엔에스 보안 확장"],"related":[{"term":"DNS","note":"— 서명이 붙는 대상. 이 위에 얹힌 확장이다"},{"term":"DNS over HTTPS","note":"— 같은 조회의 다른 절반. 이쪽은 가리고 저쪽은 증명한다"},{"term":"Certificate","note":"— 사슬을 타고 내려와 믿는다는 같은 구조를 웹 연결 쪽에서 쓰는 것"},{"term":"Hash","note":"— 상위 구역에 올리는 DS 레코드의 열쇠 지문이 해시다"},{"term":"Encryption","note":"— 자주 뒤섞이는 옆 개념. 가리는 일과 증명하는 일은 다르다"}]},{"id":"net--dedicated-cloud-interconnect","term":"Dedicated Cloud Interconnect","reading":"전용 회선 연결","category":"네트워크","summary":"Dedicated Cloud Interconnect는 **회사 망과 클라우드를 전용 회선으로 잇는 것**이다.","aliases":["dedicated cloud interconnect","전용 회선 연결"],"related":[{"term":"VPN","note":"— 인터넷 위에 잠긴 길을 내는 값싼 대안"},{"term":"BGP","note":"— 두 망이 서로의 길 목록을 주고받는 약속"},{"term":"On-Premises","note":"— 이 회선이 이어야 할 반대쪽"},{"term":"Bandwidth","note":"— 회선을 사는 단위가 되는 굵기"},{"term":"Egress Cost","note":"— 나가는 값이 어디로 나가느냐에 따라 달라지는 자리"}]},{"id":"net--domain","term":"Domain","reading":"도메인","category":"네트워크","summary":"Domain은 **숫자 IP 주소에 붙인 사람이 읽는 이름**이다.","aliases":["domain","도메인"],"related":[{"term":"DNS","note":"— 도메인을 IP 주소로 바꿔주는 시스템"},{"term":"IP Address","note":"— 도메인이 실제로 가리키는 숫자 주소"},{"term":"URL","note":"— 프로토콜과 경로까지 붙인 전체 주소. 도메인은 그중 한 부분이다"},{"term":"TTL","note":"— 바꾼 DNS 레코드가 언제부터 모두에게 보일지 정하는 값"},{"term":"SSL_TLS","note":"— 그 도메인이 진짜임을 증명하는 인증서가 붙는 자리"}]},{"id":"net--firewall","term":"Firewall","reading":"방화벽","category":"네트워크","summary":"Firewall은 **정해둔 규칙에 따라 통신을 통과시키거나 막는 장치**다.","aliases":["firewall","방화벽"],"related":[{"term":"방화벽 규칙","note":"— 무엇을 허용하고 무엇을 막을지 적어둔 목록"},{"term":"인바운드 아웃바운드","note":"— 들어오는 통신과 나가는 통신의 구분"},{"term":"Port","note":"— 방화벽이 열고 닫는 단위"},{"term":"Reverse Proxy","note":"— 서버 앞에서 요청을 받아 넘기는 쪽. 방화벽과 함께 쓴다"},{"term":"VPN","note":"— 방화벽 안쪽으로 들어오는 암호화된 통로"}]},{"id":"net--gateway","term":"Gateway","reading":"게이트웨이","category":"네트워크","summary":"Gateway는 **서로 다른 네트워크가 만나는 지점에 서는 중개자**다.","aliases":["gateway","게이트웨이"],"related":[{"term":"API Gateway","note":"— 서비스 앞에 두는 게이트웨이. 지금 가장 흔한 형태"},{"term":"Reverse Proxy","note":"— 뒤의 서버를 가리고 대신 받는 자리. 게이트웨이와 겹친다"},{"term":"Load Balancer","note":"— 같은 서비스의 여러 대로 요청을 나누는 쪽"},{"term":"Rate Limiting","note":"— 게이트웨이가 거는 대표적인 제한"},{"term":"NAT","note":"— 나가는 경계에서 주소를 바꾸는 일. 네트워크 게이트웨이가 맡는다"}]},{"id":"net--http","term":"HTTP","reading":"HyperText Transfer Protocol","category":"네트워크","summary":"HTTP는 **웹에서 요청과 응답을 주고받는 규칙**이다.","aliases":["http","hypertext transfer protocol"],"related":[{"term":"HTTPS","note":"— HTTP를 TLS로 감싸 내용을 가린 것"},{"term":"TCP","note":"— HTTP 요청이 실제로 타고 가는 연결"},{"term":"DNS","note":"— 요청을 어디로 보낼지 IP를 먼저 찾아주는 단계"},{"term":"REST","note":"— HTTP 메서드를 규칙으로 삼아 API를 설계하는 방식"}]},{"id":"net--http-keep-alive","term":"HTTP Keep-Alive","reading":"연결 유지","category":"네트워크","summary":"Keep-Alive 는 **한 번 맺은 연결을 끊지 않고 다음 요청에 다시 쓰는 것**이다.","aliases":["http keep-alive","연결 유지"],"related":[{"term":"HTTP","note":"— 이 유지 규칙이 사는 그 프로토콜"},{"term":"TCP Three-Way Handshake","note":"— 살려 두면 두 번째부터 건너뛰는 그 절차"},{"term":"HTTP 2","note":"— 연결 하나에 흐름을 여럿 태워 같은 문제를 다르게 푼 쪽"},{"term":"Head-of-Line Blocking","note":"— 연결 하나를 돌려 쓰기로 한 데서 따라오는 대가"},{"term":"Nginx","note":"— keepalive_timeout 같은 값이 실제로 놓이는 자리"}]},{"id":"net--http-2","term":"HTTP/2","reading":"","category":"네트워크","summary":"HTTP/2 는 **한 연결에 여러 요청을 겹쳐 보내는 HTTP**다.","aliases":["http/2","http 2"],"related":[{"term":"HTTP","note":"— HTTP/2 가 모양만 바꿔 실어 보내는 그 규칙"},{"term":"HTTP/3","note":"— HTTP/2 가 못 푼 TCP 층 줄서기를 QUIC 로 푼 다음 판"},{"term":"TCP","note":"— HTTP/2 가 올라타는 바탕. 여기서 오는 한계가 그대로 남는다"},{"term":"Packet","note":"— 하나 잃으면 그 연결의 스트림이 다 멈춘다고 할 때의 그 조각"}]},{"id":"net--http-3","term":"HTTP/3","reading":"","category":"네트워크","summary":"HTTP/3 은 **TCP 를 버리고 QUIC 위로 옮긴 HTTP**다.","aliases":["http/3","http 3"],"related":[{"term":"HTTP/2","note":"— 설계를 물려주고 못 푼 문제까지 넘긴 앞 판"},{"term":"UDP","note":"— QUIC 이 올라탄 바탕. 순서도 재전송도 없는 쪽"},{"term":"TCP","note":"— HTTP/3 이 비운 자리. 여기서 오던 줄서기가 문제였다"},{"term":"QUIC","note":"— HTTP/3 이 올라탄 전송 프로토콜. TLS 1.3 을 품고 스트림을 따로 나른다"},{"term":"Packet","note":"— 하나 잃었을 때 무엇까지 멈추느냐가 이 단어의 요점"}]},{"id":"net--https","term":"HTTPS","reading":"HTTP Secure","category":"네트워크","summary":"HTTPS는 **HTTP를 TLS로 감싸서 내용을 가린 것**이다.","aliases":["https","http secure"],"related":[{"term":"HTTP","note":"— HTTPS가 감싸고 있는 원래 프로토콜"},{"term":"SSL_TLS","note":"— 실제로 암호화를 담당하는 계층"},{"term":"인증서","note":"— 이 서버가 그 도메인의 주인임을 증명하는 문서"},{"term":"CA","note":"— 인증서를 발급하고 보증하는 기관"}]},{"id":"net--head-of-line-blocking","term":"Head-of-Line Blocking","reading":"선두 차단","category":"네트워크","summary":"선두 차단은 **줄 맨 앞 하나가 막혀 뒤가 통째로 서 버리는 일**이다.","aliases":["head-of-line blocking","선두 차단"],"related":[{"term":"HTTP 2","note":"— 응용 켜의 막힘을 없앤 쪽"},{"term":"HTTP 3","note":"— 전송 켜의 막힘까지 없앤 쪽"},{"term":"QUIC","note":"— 그 전송 켜를 통째로 갈아치운 프로토콜"},{"term":"TCP","note":"— 순서를 지키느라 뒤를 붙드는 그 약속"},{"term":"HTTP Keep-Alive","note":"— 연결 하나를 돌려 쓰기로 한 데서 이 문제가 시작된다"}]},{"id":"net--hub-and-spoke-topology","term":"Hub-and-Spoke Topology","reading":"바퀴통과 바퀴살 구조","category":"네트워크","summary":"Hub-and-Spoke Topology는 **가운데 한 곳에 공용 장비를 모으는 망 구조**다.","aliases":["hub-and-spoke topology","바퀴통과 바퀴살 구조"],"related":[{"term":"VPC","note":"— 통과 살이 되는 낱낱의 가상 망"},{"term":"VPC Peering","note":"— 통과 살을 짝짓는 방법이자 이어 타지 않는 그 관계"},{"term":"Firewall","note":"— 통 한가운데 두는 대표적 공용 장비"},{"term":"Routing Table","note":"— 살에서 나간 것을 통으로 보내려고 적는 길"},{"term":"Shared Virtual Network","note":"— 망을 쪼개지 않고 하나로 같이 쓰는 다른 답"}]},{"id":"net--icmp","term":"ICMP","reading":"Internet Control Message Protocol","category":"네트워크","summary":"ICMP는 **데이터를 나르지 않고 문제가 생겼다고 알리는 프로토콜**이다.","aliases":["icmp","internet control message protocol"],"related":[{"term":"IP Address","note":"— ICMP 신고가 얹혀 가고, 되돌아갈 곳을 정하는 주소 체계"},{"term":"TCP","note":"— 실패를 알리는 데서 끝나는 ICMP 와 달리 재전송까지 직접 하는 프로토콜"},{"term":"TTL","note":"— 같은 이름이지만 IP 에서는 시간이 아니라 지날 수 있는 라우터 수를 센다"},{"term":"Firewall","note":"— ICMP 를 막아 ping 이 실패하게 만드는 가장 흔한 원인"},{"term":"Latency","note":"— ping 이 찍어주는 왕복 시간이 재고 있는 값"}]},{"id":"net--ip-address","term":"IP Address","reading":"IP 주소","category":"네트워크","summary":"IP 주소는 **네트워크에서 어디로 보낼지 가리키는 번호**다.","aliases":["ip address","ip 주소"],"related":[{"term":"DNS","note":"— 사람이 외운 이름을 이 번호로 바꿔주는 쪽"},{"term":"NAT","note":"— 사설 주소를 공인 주소로 바꿔 내보내는 일"},{"term":"Public IP vs Private IP","note":"— 바깥에서 쓰는 주소와 안에서만 쓰는 주소의 구분"},{"term":"Subnet","note":"— 주소의 어디까지가 망을 가리키는지 정하는 것"},{"term":"Port","note":"— 같은 주소 안에서 어느 프로그램으로 갈지 가리는 번호"}]},{"id":"net--ipfix","term":"IPFIX","reading":"아이피 흐름 정보 수출","category":"네트워크","summary":"IPFIX는 **오간 흐름을 세어 요약만 수집기로 내보내는 약속**이다.","aliases":["ipfix","아이피 흐름 정보 수출"],"related":[{"term":"Packet Capture","note":"— 같은 구간을 셈이 아니라 통째로 뜨는 쪽"},{"term":"SNMP","note":"— 같은 장비에서 흐름 대신 눈금을 읽어 가는 쪽"},{"term":"Bandwidth","note":"— 이 기록이 결국 답하려는 물음"},{"term":"NAT","note":"— 주소가 갈리는 지점이라 어느 쪽에서 세느냐로 답이 달라진다"},{"term":"UDP","note":"— 현장에서 가장 많이 쓰는 바닥이자 템플릿을 잃는 이유"}]},{"id":"net--ipv6","term":"IPv6","reading":"아이피 버전 6","category":"네트워크","summary":"IPv6는 **주소를 128비트로 늘린 새 인터넷 주소 규격**이다.","aliases":["ipv6","아이피 버전 6"],"related":[{"term":"IP Address","note":"— 이 규격이 바꾸려는 그 주소 자체"},{"term":"NAT","note":"— 주소가 모자라 끼웠던 변환 장치. IPv6 가 걷어내려는 대상"},{"term":"Multicast","note":"— 브로드캐스트가 빠진 자리를 대신 맡은 방식"},{"term":"ARP","note":"— 이웃 찾기를 하던 옛 방식. IPv6 에서는 멀티캐스트로 옮겨 갔다"},{"term":"Anycast","note":"— IPv6 가 주소 종류 셋 중 하나로 규격에 넣은 것"}]},{"id":"net--intranet","term":"Intranet","reading":"인트라넷","category":"네트워크","summary":"Intranet은 **조직 안에서만 닿는 사설 네트워크**다.","aliases":["intranet","인트라넷"],"related":[{"term":"VPN","note":"— 밖에서 인트라넷 안으로 들어오는 통로"},{"term":"Firewall","note":"— 안과 밖의 경계에서 오가는 것을 거르는 장치"},{"term":"DMZ","note":"— 밖에도 열어야 하는 서버를 두는 완충 구역"},{"term":"Public IP vs Private IP","note":"— 인트라넷이 어느 쪽 주소를 쓰는지 가르는 구분"}]},{"id":"net--layer-4-vs-layer-7-load-balancing","term":"Layer 4 vs Layer 7 Load Balancing","reading":"4계층과 7계층 부하 분산","category":"네트워크","summary":"4계층은 주소와 포트만 보고 나누고, 7계층은 **내용까지 열어 보고 나눈다**.","aliases":["layer 4 vs layer 7 load balancing","4계층과 7계층 부하 분산","layer 4","layer 7 load balancing"],"related":[{"term":"Load Balancer","note":"— 이 둘을 아우르는 상위 개념"},{"term":"OSI 7계층","note":"— 4 와 7 이라는 번호가 나온 자리"},{"term":"Reverse Proxy","note":"— 7계층 분산기가 하는 일의 다른 이름"},{"term":"TLS Termination","note":"— 앞에서 잠금을 푸는 대표적 7계층 일"},{"term":"Session Affinity","note":"— 열어 본 김에 같은 손님을 같은 곳으로 붙이는 기능"}]},{"id":"net--load-balancer","term":"Load Balancer","reading":"부하 분산기","category":"네트워크","summary":"Load Balancer는 **들어오는 요청을 여러 서버에 나눠 보내는 장치**다.","aliases":["load balancer","부하 분산기"],"related":[{"term":"Reverse Proxy","note":"— 앞에 서서 요청을 대신 받는다는 점이 같다. 분산이 목적이면 분산기다"},{"term":"DNS","note":"— 이름 하나 뒤에 여러 IP를 두는 다른 방법"},{"term":"Auto Scaling","note":"— 새로 띄운 서버를 분산 대상에 넣어주는 쪽"},{"term":"Session","note":"— 서버를 여러 대로 늘리면 어디에 둘지 다시 정해야 하는 것"}]},{"id":"net--localhost","term":"Localhost","reading":"로컬호스트","category":"네트워크","summary":"Localhost는 **자기 컴퓨터 자신을 가리키는 이름**이다.","aliases":["localhost","로컬호스트"],"related":[{"term":"IP Address","note":"— localhost가 가리키는 127.0.0.1이 그중 하나다"},{"term":"Port","note":"— 같은 localhost 안에서 서비스를 구별하는 번호"},{"term":"DNS","note":"— 이름을 주소로 바꾸는 일반적인 방법. localhost는 hosts 파일이 대신한다"},{"term":"Port Forwarding","note":"— 밖에서 안쪽 포트로 들여보내는 방법"},{"term":"Public IP vs Private IP","note":"— 밖에서 닿는 주소와 안에서만 쓰는 주소의 구분"}]},{"id":"net--long-polling","term":"Long Polling","reading":"롱 폴링","category":"네트워크","summary":"Long Polling 은 **서버가 답할 것이 생길 때까지 요청을 붙잡아 두는** 방식이다.","aliases":["long polling","롱 폴링"],"related":[{"term":"HTTP","note":"— 요청이 없으면 답할 수 없다는 규칙. 롱 폴링이 비켜 가려는 대상이다"},{"term":"SSE","note":"— 응답을 끝내지 않고 계속 내려보내는 쪽. 롱 폴링의 다음 세대다"},{"term":"WebSocket","note":"— 갈아타서 양쪽이 오가게 만든 쪽. 역시 다음 세대다"},{"term":"TCP","note":"— 요청을 붙잡아 둔다는 것이 실제로 붙잡고 있는 연결"},{"term":"Reverse Proxy","note":"— 붙잡아 둔 요청 때문에 앞단 연결이 굶는 자리"}]},{"id":"net--mac-address","term":"MAC Address","reading":"MAC 주소","category":"네트워크","summary":"MAC 주소는 **네트워크 카드마다 하나씩 붙는 48비트 번호**다.","aliases":["mac address","mac 주소"],"related":[{"term":"ARP","note":"— IP 만 알 때 이 번호를 알아내는 규칙"},{"term":"IP Address","note":"— 자리에 붙는 번호. 이 번호와 짝을 이룬다"},{"term":"Router vs Switch","note":"— 이 번호로 넘기는 장비와 IP 로 길을 고르는 장비"},{"term":"OSI 7계층","note":"— 이 번호가 쓰이는 2계층의 자리"}]},{"id":"net--mcp","term":"MCP","reading":"Model Context Protocol","category":"네트워크","summary":"MCP는 **AI 가 바깥 도구를 부르는 방법을 통일한 규약(프로토콜)**이다.","aliases":["mcp","model context protocol"],"related":[{"term":"JSON","note":"— MCP 메시지가 담기는 형식"},{"term":"SSE","note":"— 원격 서버에 붙을 때 쓰는 전송 방식"},{"term":"AI Agent","note":"— 도구를 골라 부르는 쪽. MCP 는 그 부르는 방법을 통일한 것"},{"term":"API Gateway","note":"— 여러 뒷단을 창구 하나로 모은다는 점이 닮았다"}]},{"id":"net--mtu","term":"MTU","reading":"최대 전송 단위","category":"네트워크","summary":"MTU 는 **한 번에 실어 보낼 수 있는 조각의 최대 크기**다.","aliases":["mtu","최대 전송 단위"],"related":[{"term":"Packet","note":"— MTU 가 정하는 것이 이 조각 하나의 최대 크기다"},{"term":"TCP","note":"— MSS 는 MTU 에서 헤더 40바이트를 뺀 값이다"},{"term":"ICMP","note":"— 경로 MTU 를 알려주는 그 메시지를 나르는 프로토콜"},{"term":"VPN","note":"— 터널 헤더 때문에 MTU 를 가장 자주 건드리게 되는 자리"},{"term":"TCP Congestion Control","note":"— 버려진 조각을 손실로 읽어 속도를 접는다"}]},{"id":"net--multi-tenancy","term":"Multi-tenancy","reading":"멀티 테넌시","category":"네트워크","summary":"Multi-tenancy는 **한 시스템을 여러 고객이 나눠 쓰는 구조**다.","aliases":["multi-tenancy","멀티 테넌시"],"related":[{"term":"Tenant","note":"— 이 구조에서 갈라지는 단위 하나"},{"term":"IaaS_PaaS_SaaS","note":"— 멀티 테넌시가 주로 쓰이는 서비스 형태"},{"term":"DB","note":"— 데이터를 어느 층에서 가를지 정하는 자리"},{"term":"Rate Limiting","note":"— 한 고객이 자원을 독차지하지 못하게 막는 장치"},{"term":"Sharding","note":"— 데이터를 나눠 담는다는 점은 같지만 목적은 성능이다"}]},{"id":"net--multicast","term":"Multicast","reading":"멀티캐스트","category":"네트워크","summary":"멀티캐스트는 **한 번 보낸 것을 손 든 여럿이 받는 방식**이다.","aliases":["multicast","멀티캐스트"],"related":[{"term":"UDP","note":"— 멀티캐스트가 실려 가는 그릇. 재전송이 없어 빠지면 그냥 빠진다"},{"term":"MAC Address","note":"— 무리 주소가 이더넷에서 옮겨 적히는 자리. 32개가 겹친다"},{"term":"Anycast","note":"— 같은 주소 하나에 여럿이 답하되 그중 하나만 받는 쪽"},{"term":"IPv6","note":"— 브로드캐스트를 없애고 그 일까지 멀티캐스트에 맡긴 판"},{"term":"CDN","note":"— 인터넷 생중계에서 이 방식 대신 실제로 쓰이는 것"}]},{"id":"net--nat","term":"NAT","reading":"Network Address Translation","category":"네트워크","summary":"NAT는 **사설 IP를 공인 IP로 바꿔주는 기술**이다.","aliases":["nat","network address translation"],"related":[{"term":"IP Address","note":"— NAT가 바꾸는 대상. 공인과 사설로 나뉜다"},{"term":"Public IP vs Private IP","note":"— NAT가 그 사이를 오가게 만드는 두 종류"},{"term":"Port Forwarding","note":"— 밖에서 안으로 들어올 길을 미리 뚫어두는 DNAT"},{"term":"Firewall","note":"— NAT가 곁다리로 하던 가림을 규칙으로 하는 장치"}]},{"id":"net--nginx","term":"Nginx","reading":"엔진엑스","category":"네트워크","summary":"Nginx 는 **요청을 먼저 받아 파일을 주거나 뒤 서버로 넘기는 프로그램**이다.","aliases":["nginx","엔진엑스"],"related":[{"term":"Reverse Proxy","note":"— Nginx 가 앞에서 맡는 역할의 이름"},{"term":"Load Balancer","note":"— 뒤에 붙은 서버들에 요청을 나누는 기능"},{"term":"HTTPS","note":"— 인증서를 여기서 처리하고 뒤로는 평문으로 넘긴다"},{"term":"Rate Limiting","note":"— 앞단에서 호출 횟수를 제한하는 설정"},{"term":"Cache","note":"— 뒤에서 받은 응답을 앞에 잠시 두는 기능"}]},{"id":"net--osi-7","term":"OSI 7계층","reading":"OSI 7-Layer Model","category":"네트워크","summary":"OSI 7계층은 **네트워크 통신을 일곱 단계로 나눈 참조 모델**이다.","aliases":["osi 7계층","osi 7-layer model"],"related":[{"term":"TCP","note":"— 4계층에서 빠짐없는 전달을 맡는 쪽"},{"term":"UDP","note":"— 같은 4계층에서 확인 없이 보내는 쪽"},{"term":"IP Address","note":"— 3계층이 길을 정할 때 보는 주소"},{"term":"HTTP","note":"— 7계층에서 오가는 대표적인 프로토콜"},{"term":"SSL_TLS","note":"— 6계층에 해당하는 암호화가 붙는 자리"}]},{"id":"net--ospf","term":"OSPF","reading":"최단 경로 우선","category":"네트워크","summary":"OSPF는 **조직 안에서 최단 경로를 각자 계산하는 길 찾기**다.","aliases":["ospf","최단 경로 우선"],"related":[{"term":"BGP","note":"— 조직 밖으로 나가는 길을 맡는 쪽. OSPF 는 그것을 받아 안쪽에 뿌린다"},{"term":"Autonomous System","note":"— OSPF 가 도는 범위. 그 안이 한 덩어리다"},{"term":"Routing Table","note":"— 계산 결과가 실제로 앉는 표"},{"term":"Router vs Switch","note":"— 이 계산을 실제로 돌리는 장비가 어느 쪽인지"},{"term":"Bandwidth","note":"— 회선 비용을 매길 때 기준이 되는 값"}]},{"id":"net--packet","term":"Packet","reading":"패킷","category":"네트워크","summary":"패킷은 **보낼 데이터를 잘라 주소를 붙인 한 조각**이다.","aliases":["packet","패킷"],"related":[{"term":"IP Address","note":"— 조각의 머리표에 적히는 보낸 곳·받을 곳 주소"},{"term":"TCP","note":"— 뒤바뀌고 사라지는 조각을 순서대로 세워 주는 위층"},{"term":"UDP","note":"— 그 보정을 포기하고 조각을 그대로 넘기는 위층"},{"term":"OSI 7계층","note":"— 이 조각이 층마다 어떤 이름으로 불리는지 정리한 지도"},{"term":"TTL","note":"— 조각이 살아 있을 시간을 미리 정해두는 것도 같은 발상이다"}]},{"id":"net--packet-capture","term":"Packet Capture","reading":"패킷 캡처","category":"네트워크","summary":"패킷 캡처는 **선을 지나는 것을 통째로 떠서 파일로 남기는 일**이다.","aliases":["packet capture","패킷 캡처"],"related":[{"term":"Packet","note":"— 여기서 한 건씩 떠서 파일에 쌓이는 그 덩이"},{"term":"eBPF","note":"— 무엇을 뜰지 커널에서 고르던 거르개가 자라서 된 기술"},{"term":"TCP","note":"— 뜬 파일에서 가장 많이 읽게 되는 층. 재전송과 RST 가 여기 있다"},{"term":"Observability","note":"— 아프기 전에 미리 심어 두는 관측 수단 중 가장 낮은 자리"}]},{"id":"net--port","term":"Port","reading":"포트","category":"네트워크","summary":"Port는 **한 컴퓨터 안에서 어느 프로그램으로 갈지 가리키는 번호**다.","aliases":["port","포트"],"related":[{"term":"IP Address","note":"— 어느 컴퓨터인지까지 데려다주는 주소"},{"term":"Socket","note":"— IP 와 포트를 묶어 프로그램이 잡는 통신 창구"},{"term":"TCP","note":"— 포트 번호를 실어 나르는 대표적인 규약"},{"term":"Firewall","note":"— 어느 포트를 열고 막을지 정하는 자리"},{"term":"Port Forwarding","note":"— 바깥 포트를 안쪽 다른 포트로 돌려주는 설정"}]},{"id":"net--port-forwarding","term":"Port Forwarding","reading":"포트 포워딩","category":"네트워크","summary":"Port Forwarding은 **바깥 포트로 온 요청을 안쪽 기기로 넘기는 규칙**이다.","aliases":["port forwarding","포트 포워딩"],"related":[{"term":"NAT","note":"— 사설 주소와 공인 주소를 바꿔주는 기술. 포워딩이 올라타는 바탕이다"},{"term":"Public IP vs Private IP","note":"— 밖에서 닿는 주소와 안에서만 쓰는 주소의 구분"},{"term":"Port","note":"— 포워딩이 갈라 쓰는 번호"},{"term":"Reverse Proxy","note":"— 같은 일을 서버 쪽에서 경로와 도메인 단위로 하는 방법"},{"term":"방화벽 규칙","note":"— 포워딩과 별개로 허용 규칙을 따로 넣어야 하는 자리"}]},{"id":"net--private-dns-zone","term":"Private DNS Zone","reading":"사설 이름 영역","category":"네트워크","summary":"Private DNS Zone은 **그 가상 망 안에서만 통하는 이름 장부**다.","aliases":["private dns zone","사설 이름 영역"],"related":[{"term":"DNS","note":"— 이 장부가 그대로 따르는 이름 조회 방식"},{"term":"VPC","note":"— 장부를 묶는 단위가 되는 가상 망"},{"term":"Domain","note":"— 한 영역이 맡는 이름의 범위"},{"term":"Service Discovery","note":"— 안쪽 이름으로 서로를 찾는 더 큰 이야기"},{"term":"Shared Virtual Network","note":"— 장부 하나를 여러 살림이 함께 쓰게 되는 자리"}]},{"id":"net--proxy","term":"Proxy","reading":"Forward Proxy","category":"네트워크","summary":"Proxy는 **클라이언트를 대신해 밖으로 요청을 보내는 서버**다.","aliases":["proxy","forward proxy"],"related":[{"term":"Reverse Proxy","note":"— 같은 중개인데 서버 앞에 서서 서버를 가린다"},{"term":"VPN","note":"— 연결 자체를 암호화한다는 점이 프록시와 다르다"},{"term":"Cache","note":"— 프록시가 응답을 저장해뒀다 다시 쓰는 방식"},{"term":"Firewall","note":"— 규칙으로 막는 쪽. 프록시는 대신 나가주는 쪽이다"},{"term":"Gateway","note":"— 네트워크 진입점. 프록시가 그 자리에 놓이기도 한다"}]},{"id":"net--public-ip-vs-private-ip","term":"Public IP vs Private IP","reading":"공인 IP vs 사설 IP","category":"네트워크","summary":"공인 IP는 **인터넷 전체에서 유일한 주소**이고 사설 IP는 그 안쪽에서만 통하는 주소다.","aliases":["public ip vs private ip","공인 ip vs 사설 ip","public ip","private ip","공인 ip","사설 ip"],"related":[{"term":"NAT","note":"— 사설 IP와 공인 IP 사이를 바꿔주는 장치"},{"term":"IP Address","note":"— 공인과 사설로 나뉘기 전의 주소 개념"},{"term":"Port Forwarding","note":"— 밖에서 내부 사설 IP로 들어오는 통로를 여는 방법"},{"term":"VPN","note":"— 내부망에 들어와 사설 IP를 그대로 쓰게 해주는 다른 방법"},{"term":"Subnet","note":"— 사설 대역을 다시 잘게 나눠 쓰는 단위"}]},{"id":"net--quic","term":"QUIC","reading":"","category":"네트워크","summary":"QUIC 는 UDP 위에서 **신뢰성과 암호화를 직접 챙기는** 전송 규약이다.","aliases":["quic"],"related":[{"term":"UDP","note":"— QUIC 이 밑바탕 통로로 쓰는 전송"},{"term":"TCP","note":"— QUIC 이 그 자리를 대신하려는 기존 전송"},{"term":"SSL_TLS","note":"— QUIC 이 자기 악수 안으로 끌어들인 암호 규약"},{"term":"HTTP","note":"— QUIC 위에서 도는 HTTP/3 의 앞 세대"}]},{"id":"net--reverse-proxy","term":"Reverse Proxy","reading":"리버스 프록시","category":"네트워크","summary":"Reverse Proxy는 **서버 앞에 서서 요청을 대신 받는 중개 서버**다.","aliases":["reverse proxy","리버스 프록시"],"related":[{"term":"Proxy","note":"— 클라이언트 앞에 서는 반대쪽. 감추는 대상이 다르다"},{"term":"Load Balancer","note":"— 요청을 나눠 주는 일만 따로 맡는 장치"},{"term":"Nginx","note":"— 리버스 프록시로 가장 많이 쓰이는 소프트웨어"},{"term":"SSL_TLS","note":"— 앞단에서 끊어내는 그 암호화"},{"term":"CDN","note":"— 같은 원리를 지역마다 흩어 놓은 것"}]},{"id":"net--router-vs-switch","term":"Router vs Switch","reading":"라우터와 스위치","category":"네트워크","summary":"스위치는 MAC 으로 같은 망 안에 넘기고, 라우터는 **IP 로 망을 건너보낸다**.","aliases":["router vs switch","라우터와 스위치","router","switch"],"related":[{"term":"MAC Address","note":"— 스위치가 보고 넘기는 주소"},{"term":"IP Address","note":"— 라우터가 보고 길을 고르는 주소"},{"term":"ARP","note":"— 라우터로 내보낼 때 그 라우터의 MAC 을 알아내는 규칙"},{"term":"Gateway","note":"— 망의 경계에 서는 자리를 넓게 부르는 말. 공유기의 라우터 노릇이 여기다"},{"term":"Subnet","note":"— 어디까지가 한 망인지 정하는 값"}]},{"id":"net--routing-table","term":"Routing Table","reading":"라우팅 테이블","category":"네트워크","summary":"라우팅 테이블은 **목적지마다 다음에 넘길 곳을 적어 둔 표**다.","aliases":["routing table","라우팅 테이블"],"related":[{"term":"CIDR","note":"— 표의 목적지 칸에 적히는 표기. 앞자리 길이가 승패를 가른다"},{"term":"BGP","note":"— 조직 밖에서 배워 온 줄을 이 표에 넣어 주는 쪽"},{"term":"OSPF","note":"— 조직 안에서 계산한 줄을 이 표에 넣어 주는 쪽"},{"term":"Gateway","note":"— 갈 곳을 모를 때 넘기는 그 다음 한 곳"},{"term":"Packet","note":"— 이 표를 한 줄씩 밟으며 옮겨 다니는 알맹이"}]},{"id":"net--smtp","term":"SMTP","reading":"단순 메일 전송 프로토콜","category":"네트워크","summary":"SMTP는 **메일을 다음 서버로 넘길 때 주고받는 명령 약속**이다.","aliases":["smtp","단순 메일 전송 프로토콜"],"related":[{"term":"DKIM","note":"— 봉투와 편지지가 달라도 되는 그 틈을 서명으로 덮는 쪽"},{"term":"DNS","note":"— 어느 서버로 넘길지 MX 로 물어보는 자리"},{"term":"TCP","note":"— 이 명령과 대답이 실려 가는 연결"},{"term":"Port","note":"— 넘기는 25번과 부치는 587번이 갈리는 이유"},{"term":"SSL/TLS","note":"— 명령과 본문이 평문으로 흐르지 않게 덮는 층"}]},{"id":"net--snmp","term":"SNMP","reading":"단순 망 관리 프로토콜","category":"네트워크","summary":"SNMP는 **장비의 값마다 번호를 매겨 두고 그 번호로 묻는 약속**이다.","aliases":["snmp","단순 망 관리 프로토콜"],"related":[{"term":"UDP","note":"— 물음과 답과 알림이 실려 가는 바닥. 잃어버려도 다시 안 보낸다"},{"term":"Metric","note":"— 같은 일을 장비 눈금이 아니라 앱 안쪽에서 하는 요즘 방식"},{"term":"IPFIX","note":"— 같은 장비에서 눈금 대신 오간 흐름을 내보내는 쪽"},{"term":"Prometheus","note":"— 주기적으로 긁어 가는 방식을 그대로 물려받은 도구"},{"term":"Alerting","note":"— 트랩이 결국 닿으려 하는 자리"}]},{"id":"net--sse","term":"SSE","reading":"Server-Sent Events","category":"네트워크","summary":"SSE는 **서버가 클라이언트로 계속 밀어 보내는 단방향 연결**이다.","aliases":["sse","server-sent events"],"related":[{"term":"WebSocket","note":"— 양쪽이 주고받아야 할 때 쓰는 쪽"},{"term":"HTTP","note":"— SSE가 그대로 올라타는 바탕 프로토콜"},{"term":"Webhook","note":"— 서버끼리 밀어 보내는 방식. 브라우저 쪽이 아니다"},{"term":"Socket","note":"— 연결을 잡아둔다는 것이 실제로 무엇을 잡는지 설명하는 개념"}]},{"id":"net--stun","term":"STUN","reading":"NAT 통과 도구","category":"네트워크","summary":"STUN은 **밖에서 보이는 내 주소를 남에게 물어보는 방법**이다.","aliases":["stun","nat 통과 도구"],"related":[{"term":"NAT","note":"— 주소를 갈아 끼워서 이 물음이 필요해진 원인"},{"term":"WebRTC","note":"— 이 도구를 실제로 부르는 대표 쓰임"},{"term":"UDP","note":"— 물음과 답, 그리고 그 뒤의 통화가 실려 가는 바닥"},{"term":"Public IP vs Private IP","note":"— 여기서 갈리는 두 주소"},{"term":"Port Forwarding","note":"— 같은 문제를 손으로 미리 뚫어 두는 옛 방법"}]},{"id":"net--server-name-indication","term":"Server Name Indication","reading":"서버 이름 표시","category":"네트워크","summary":"SNI는 **TLS 인사 첫 마디에 접속할 이름을 적어 보내는 칸**이다.","aliases":["server name indication","서버 이름 표시"],"related":[{"term":"SSL/TLS","note":"— 이 칸이 실려 나가는 인사 그 자체"},{"term":"Certificate","note":"— 이 이름을 단서로 골라 드는 것"},{"term":"Nginx","note":"— `server_name` 으로 이 이름을 받아 블록을 고르는 대표 구현"},{"term":"TLS Termination","note":"— 이 이름을 읽고 어느 뒷단으로 넘길지 정하는 자리"},{"term":"DNS over HTTPS","note":"— 조회를 가려도 이 칸 때문에 접속 대상이 또 드러난다"}]},{"id":"net--session-affinity","term":"Session Affinity","reading":"같은 손님 같은 대","category":"네트워크","summary":"Session Affinity는 **같은 손님을 늘 같은 뒷단으로 보내는 설정**이다.","aliases":["session affinity","같은 손님 같은 대"],"related":[{"term":"Load Balancer","note":"— 붙임을 켜고 끄는 자리"},{"term":"Session","note":"— 붙여 두려는 그 \"한 판\" 자체"},{"term":"Cookie","note":"— 손님이 들고 다니는 쪽지의 정체"},{"term":"Layer 4 vs Layer 7 Load Balancing","note":"— 쪽지를 읽으려면 어느 층까지 열어야 하나"},{"term":"Redis","note":"— 손님 것을 뒷단 밖에 두는 가장 흔한 자리"}]},{"id":"net--shared-virtual-network","term":"Shared Virtual Network","reading":"공유 가상 망","category":"네트워크","summary":"Shared Virtual Network는 **여러 살림이 망 하나를 같이 쓰는 방식**이다.","aliases":["shared virtual network","공유 가상 망"],"related":[{"term":"VPC","note":"— 같이 쓰는 그 망 자체"},{"term":"VPC Peering","note":"— 망을 안 합치고 쌍쌍이 잇는 다른 길"},{"term":"Hub-and-Spoke Topology","note":"— 망을 쪼갠 채 가운데로 모으는 다른 짜임"},{"term":"Subnet","note":"— 살림에게 빌려주는 단위가 되는 칸"},{"term":"IAM","note":"— 누가 어느 칸을 쓸지 가르는 자리"}]},{"id":"net--socket","term":"Socket","reading":"소켓","category":"네트워크","summary":"Socket은 **프로그램이 네트워크에 데이터를 넣고 빼는 창구**다.","aliases":["socket","소켓"],"related":[{"term":"TCP","note":"— 소켓을 만들 때 고를 수 있는 규칙 하나"},{"term":"UDP","note":"— 연결을 안 맺는 쪽. 같은 자리에서 고른다"},{"term":"Port","note":"— 한 컴퓨터 안에서 어느 프로그램인지 가리키는 번호"},{"term":"IP Address","note":"— 어느 컴퓨터인지 가리키는 주소"},{"term":"WebSocket","note":"— 웹에서 양쪽이 계속 주고받게 만든 것"}]},{"id":"net--tcp","term":"TCP","reading":"Transmission Control Protocol","category":"네트워크","summary":"TCP는 **데이터를 빠짐없이 순서대로 배달하는 규칙**이다.","aliases":["tcp","transmission control protocol"],"related":[{"term":"UDP","note":"— 확인 없이 그냥 보내는 쪽. 빠른 대신 안 챙긴다"},{"term":"HTTP","note":"— TCP 위에서 오가는 대표적인 응용"},{"term":"IP Address","note":"— TCP가 연결을 맺을 상대를 가리키는 주소"},{"term":"Socket","note":"— 프로그램이 TCP 연결을 잡는 창구"}]},{"id":"net--tcp-congestion-control","term":"TCP Congestion Control","reading":"티시피 혼잡 제어","category":"네트워크","summary":"혼잡 제어는 **길이 막히는지 보아 가며 보내는 양을 스스로 줄이는 규칙**이다.","aliases":["tcp congestion control","티시피 혼잡 제어"],"related":[{"term":"TCP","note":"— 이 규칙이 얹혀 있는 그 프로토콜"},{"term":"TCP Three-Way Handshake","note":"— 창을 키우기 시작하는 출발점"},{"term":"Bandwidth","note":"— 회선의 폭. 창과 왕복 시간이 그 폭을 다 못 쓰게 만든다"},{"term":"Packet","note":"— 잃어버린 한 조각이 창을 절반으로 접는다"},{"term":"QUIC","note":"— 같은 일을 TCP 밖에서, 흐름마다 따로 하는 쪽"}]},{"id":"net--tcp-three-way-handshake","term":"TCP Three-Way Handshake","reading":"티시피 3방향 악수","category":"네트워크","summary":"3방향 악수는 **보내기 전에 서로의 시작 번호를 맞추는 세 번의 인사**다.","aliases":["tcp three-way handshake","티시피 3방향 악수"],"related":[{"term":"TCP","note":"— 이 악수로 문을 여는 그 프로토콜"},{"term":"Socket","note":"— 악수가 끝나면 양쪽에 하나씩 생기는 연결의 손잡이"},{"term":"Port","note":"— 악수를 어느 문에 걸지 정하는 번호"},{"term":"HTTPS","note":"— TCP 악수가 끝난 다음에 한 번 더 하는 악수(TLS)"},{"term":"Packet","note":"— SYN 과 ACK 가 실려 가는 그 조각"}]},{"id":"net--tls-termination","term":"TLS Termination","reading":"티엘에스 종료","category":"네트워크","summary":"TLS Termination은 **앞단에서 자물쇠를 풀고 뒤로는 평문으로 넘기는 것**이다.","aliases":["tls termination","티엘에스 종료"],"related":[{"term":"Reverse Proxy","note":"— 이 자리를 맡는 가장 흔한 장비. 그쪽은 밖에서 보이는 문을 줄이는 이야기고, 여기는 그 문에서 자물쇠가 끝난다는 이야기다"},{"term":"SSL/TLS","note":"— 여기서 끝나는 그 잠금"},{"term":"Server Name Indication","note":"— 앞단이 어느 인증서를 꺼낼지 정하는 단서"},{"term":"mTLS","note":"— 앞단 안쪽 구간까지 서로 증명하게 만드는 쪽"},{"term":"Ingress","note":"— 쿠버네티스에서 이 자리를 선언으로 잡는 것"}]},{"id":"net--tunnel","term":"Tunnel","reading":"터널링","category":"네트워크","summary":"Tunnel은 **다른 통신을 통째로 감싸서 실어 나르는 통로**다.","aliases":["tunnel","터널링"],"related":[{"term":"SSH","note":"— 터널을 만드는 데 가장 흔히 쓰는 통로"},{"term":"Port Forwarding","note":"— 어느 포트를 어디로 이을지 정하는 부분"},{"term":"VPN","note":"— 터널 위에 사설망 전체를 얹은 것"},{"term":"Firewall","note":"— 터널이 지나가야 하는 관문"}]},{"id":"net--udp","term":"UDP","reading":"User Datagram Protocol","category":"네트워크","summary":"UDP는 **확인하지 않고 그냥 보내는 전송 규칙**이다.","aliases":["udp","user datagram protocol"],"related":[{"term":"TCP","note":"— 빠짐과 순서를 챙기는 쪽. 그 대가로 기다림이 생긴다"},{"term":"DNS","note":"— UDP로 묻고 답하는 대표적인 프로토콜"},{"term":"Port","note":"— UDP가 어느 프로그램에 넘길지 가리는 번호"},{"term":"IP Address","note":"— UDP 조각이 실려 가는 아래층의 주소"},{"term":"OSI 7계층","note":"— UDP가 서 있는 자리는 전송 계층이다"}]},{"id":"net--url","term":"URL","reading":"Uniform Resource Locator","category":"네트워크","summary":"URL은 **인터넷에서 무엇을 어디서 어떻게 가져올지 적은 주소**다.","aliases":["url","uniform resource locator"],"related":[{"term":"DNS","note":"— URL 의 호스트 이름을 IP 주소로 바꾼다"},{"term":"Domain","note":"— URL 에서 어느 서버인지 가리키는 부분"},{"term":"Port","note":"— URL 에 적히거나 프로토콜에 따라 기본값이 붙는 번호"},{"term":"HTTP","note":"— URL 로 요청하고 응답받을 때 쓰는 프로토콜"},{"term":"REST","note":"— URL 의 경로를 자원 이름으로 쓰는 설계 방식"}]},{"id":"net--vlan","term":"VLAN","reading":"가상 랜","category":"네트워크","summary":"VLAN 은 **같은 선을 쓰면서도 서로 닿지 못하게 갈라 둔 망**이다.","aliases":["vlan","가상 랜"],"related":[{"term":"Router vs Switch","note":"— 번호표를 붙이고 떼는 쪽과, 칸 사이를 이어 주는 쪽"},{"term":"MAC Address","note":"— 번호표가 끼워지는 그 프레임의 주소 자리"},{"term":"MTU","note":"— 태그 4바이트가 프레임 크기를 1522 로 밀어 올린다"},{"term":"Firewall","note":"— 갈라진 칸 사이의 통로에서 실제로 막아 주는 것"},{"term":"Intranet","note":"— 사내망을 조직별로 가르는 가장 흔한 수단이 이것이다"}]},{"id":"net--vpn","term":"VPN","reading":"Virtual Private Network","category":"네트워크","summary":"VPN은 **공용 인터넷 위에 암호화된 전용 통로를 내는 기술**이다.","aliases":["vpn","virtual private network"],"related":[{"term":"Tunnel","note":"— VPN이 통신을 감싸 보낼 때 쓰는 방식"},{"term":"암호화","note":"— 터널 안을 못 읽게 만드는 부분"},{"term":"Proxy","note":"— 중개는 하지만 암호화를 보장하지 않는 쪽"},{"term":"IPSec VPN","note":"— VPN을 세우는 대표적인 규약 묶음"}]},{"id":"net--webrtc","term":"WebRTC","reading":"웹 실시간 통신","category":"네트워크","summary":"WebRTC는 **브라우저끼리 직접 소리와 화면을 흘리는 규격**이다.","aliases":["webrtc","웹 실시간 통신"],"related":[{"term":"STUN","note":"— 밖에서 보이는 주소를 알아내는 도구"},{"term":"NAT","note":"— 두 쪽이 서로를 못 찾게 만드는 원인"},{"term":"UDP","note":"— 소리와 화면이 실려 가는 바닥"},{"term":"WebSocket","note":"— 규격이 비워 둔 신호 통로로 가장 많이 쓰이는 이웃"},{"term":"Bandwidth","note":"— 중계로 넘어갔을 때 그대로 비용이 되는 것"}]},{"id":"net--websocket","term":"WebSocket","reading":"웹소켓","category":"네트워크","summary":"WebSocket은 **한 번 연결하면 양쪽이 계속 주고받는 통로**다.","aliases":["websocket","웹소켓"],"related":[{"term":"HTTP","note":"— 연결을 시작할 때 쓰는 것. 도중에 갈아탄다"},{"term":"SSE","note":"— 서버에서 내려보내기만 하는 더 간단한 쪽"},{"term":"TCP","note":"— WebSocket 프레임이 실려 가는 아래층"},{"term":"Socket","note":"— 이름은 닮았지만 이쪽은 운영체제가 주는 통신 창구"},{"term":"Reverse Proxy","note":"— 앞단이 갈아타기를 통과시켜 줘야 연결이 열린다"}]},{"id":"net--curl","term":"curl","reading":"Client URL","category":"네트워크","summary":"curl은 **터미널에서 URL 로 요청을 보내고 응답을 받는 명령어**다.","aliases":["curl","client url"],"related":[{"term":"HTTP","note":"— curl 이 만들어 보내는 요청의 규칙"},{"term":"Terminal","note":"— curl 을 치는 자리"},{"term":"CLI","note":"— 글자로 명령을 주는 방식. curl 이 그 예다"},{"term":"Token 인증","note":"— `-H \"Authorization: Bearer ...\"` 로 붙이는 것"},{"term":"SSL_TLS","note":"— `-k` 가 검사를 꺼버리는 대상"}]},{"id":"net--ebpf","term":"eBPF","reading":"확장 버클리 패킷 필터","category":"네트워크","summary":"eBPF는 **검사를 통과한 작은 조각을 커널 안에 붙이는 기술**이다.","aliases":["ebpf","확장 버클리 패킷 필터"],"related":[{"term":"Packet Capture","note":"— 무엇을 뜰지 고르던 거르개가 이 기술의 뿌리다"},{"term":"Observability","note":"— 앱을 안 고치고 관측 수단을 심는 요즘 방법"},{"term":"Kubernetes","note":"— 파드 사이 통신 판정을 커널로 내리는 대표 자리"},{"term":"Firewall","note":"— 같은 일을 훨씬 위쪽에서 하는 쪽"},{"term":"Pod","note":"— 이 판정이 실제로 걸리는 단위"}]},{"id":"net--mtls","term":"mTLS","reading":"Mutual TLS","category":"네트워크","summary":"mTLS 는 **양쪽이 서로 인증서를 내보이는 TLS**다.","aliases":["mtls","mutual tls"],"related":[{"term":"SSL_TLS","note":"— 서버 쪽만 증명하는 기본형. mTLS 는 그 선택 항목을 켠 것이다"},{"term":"인증서","note":"— 양쪽이 서로 내보이는 그 문서"},{"term":"CA","note":"— 그 인증서에 서명해 신뢰 사슬의 뿌리가 되는 기관"},{"term":"Zero Trust","note":"— 망 안이라고 믿지 않는다는 원칙. mTLS 가 그것을 실행하는 수단"}]}]},{"id":"web","name":"웹 개발","blurb":"브라우저와 서버 사이에서 벌어지는 일","terms":[{"id":"web--api-versioning","term":"API Versioning","reading":"API 버저닝","category":"웹 개발","summary":"API Versioning 은 **API 를 고치면서 옛 클라이언트를 살려 두는 장치**다.","aliases":["api versioning","api 버저닝"],"related":[{"term":"API","note":"— 버전을 나누는 대상. 남이 기대고 있는 그 규격이다"},{"term":"REST","note":"— 주소와 메서드로 규격을 정하는 방식. 주소에 버전을 싣는 관행이 여기서 나온다"},{"term":"HTTP","note":"— 버전을 헤더나 `Accept` 로 실어 보내는 통로"},{"term":"API Gateway","note":"— 들어온 요청의 버전을 보고 뒤쪽 서버로 갈라 보내는 자리"},{"term":"Package Manager","note":"— 라이브러리 버전을 범위로 적어 고르는, 같은 호환 문제의 패키지 쪽 답"}]},{"id":"web--accessibility","term":"Accessibility","reading":"웹 접근성","category":"웹 개발","summary":"Accessibility 는 **능력이 어떻든 쓸 수 있게** 만드는 웹 설계다.","aliases":["accessibility","웹 접근성"],"related":[{"term":"HTML","note":"— 알맞은 요소를 제 용도로 쓰는 것이 접근성의 첫 단계다"},{"term":"CSS","note":"— 명암비와 글자 크기 같은 조문이 실제로 걸리는 자리"},{"term":"Responsive Design","note":"— 작은 화면이라는 상황적 제약을 함께 다룬다"},{"term":"DOM","note":"— 보조기술이 읽어 가는 문서 구조 그 자체"}]},{"id":"web--backend","term":"Backend","reading":"백엔드","category":"웹 개발","summary":"Backend는 **화면 뒤 서버에서 데이터와 규칙을 다루는 쪽**이다.","aliases":["backend","백엔드"],"related":[{"term":"Frontend","note":"— 사용자가 직접 보는 쪽. 백엔드에 요청을 보낸다"},{"term":"API","note":"— 프론트엔드와 백엔드가 주고받는 창구"},{"term":"REST","note":"— 그 창구를 설계하는 흔한 규칙"},{"term":"DB","note":"— 백엔드가 데이터를 실제로 넣고 꺼내는 곳"},{"term":"Session","note":"— 백엔드가 요청한 사람이 누구인지 기억하는 방법"}]},{"id":"web--browser-rendering","term":"Browser Rendering","reading":"브라우저 렌더링","category":"웹 개발","summary":"브라우저 렌더링은 **글자로 온 문서를 화면 픽셀로 바꾸는 과정**이다.","aliases":["browser rendering","브라우저 렌더링"],"related":[{"term":"DOM","note":"— 파싱이 만들어 내는 트리. 이 과정의 첫 산물이다"},{"term":"HTML","note":"— 렌더링에 들어가는 원고"},{"term":"CSS","note":"— 렌더 트리의 나머지 절반. 다 받기 전에는 화면이 안 나온다"},{"term":"JavaScript","note":"— 단계 사이에 끼어들어 트리를 고치고 다시 그리게 만드는 쪽"},{"term":"Latency","note":"— 첫 화면이 뜨기까지 걸리는 시간을 재는 말"}]},{"id":"web--cors","term":"CORS","reading":"Cross-Origin Resource Sharing","category":"웹 개발","summary":"CORS는 **다른 출처의 응답을 읽어도 되는지 정하는 규칙**이다.","aliases":["cors","cross-origin resource sharing"],"related":[{"term":"HTTP","note":"— CORS 는 전부 HTTP 헤더로만 이뤄진다"},{"term":"Cookie","note":"— 함께 보낼 때 설정이 하나씩 더 필요해지는 대상"},{"term":"API","note":"— 다른 도메인의 API 를 부를 때 늘 마주치는 문제"},{"term":"Proxy","note":"— 같은 출처로 보이게 만들어 이 문제를 피하는 방법"}]},{"id":"web--csr","term":"CSR","reading":"Client Side Rendering","category":"웹 개발","summary":"CSR은 **브라우저가 자바스크립트로 화면을 그리는 방식**이다.","aliases":["csr","client side rendering"],"related":[{"term":"SSR","note":"— 반대로 서버가 화면을 다 그려서 보내는 방식"},{"term":"SPA","note":"— CSR로 화면 전체를 한 벌만 띄우고 부분만 갈아 끼우는 구조"},{"term":"Component","note":"— 브라우저가 조립하는 화면 조각의 단위"},{"term":"Frontend","note":"— CSR에서 일이 몰리는 쪽"}]},{"id":"web--css","term":"CSS","reading":"Cascading Style Sheets","category":"웹 개발","summary":"CSS는 **겹쳐 쌓인 규칙**으로 문서의 생김새를 정하는 스타일 언어다.","aliases":["css","cascading style sheets"],"related":[{"term":"HTML","note":"— CSS 가 생김새를 얹는 대상, 곧 뜻과 구조를 표시한 문서"},{"term":"DOM","note":"— 규칙이 실제로 적용되는 트리. 마디마다 이긴 값이 매겨진다"},{"term":"Component","note":"— 규칙이 겹치는 범위를 조각 안으로 좁히는 요즘 방식"},{"term":"Frontend","note":"— CSS 를 쓰는 일이 놓인 자리"}]},{"id":"web--code-splitting","term":"Code Splitting","reading":"코드 분할","category":"웹 개발","summary":"Code Splitting은 **자바스크립트를 나눠 두고 필요할 때 받게 하는 일**이다.","aliases":["code splitting","코드 분할"],"related":[{"term":"Build","note":"— 코드를 덩어리로 나누는 일이 실제로 일어나는 시점"},{"term":"CSR","note":"— 첫 화면까지 자바스크립트를 기다리는 쪽. 분할 효과가 가장 크다"},{"term":"SPA","note":"— 화면 전부를 한 벌로 받는 구조. 경로별로 쪼개는 대상이 된다"},{"term":"Component","note":"— 덩어리 경계로 흔히 쓰는 단위"}]},{"id":"web--core-web-vitals","term":"Core Web Vitals","reading":"코어 웹 바이탈","category":"웹 개발","summary":"Core Web Vitals 는 **웹 경험을 셋으로 나눠 재는 성능 지표**다.","aliases":["core web vitals","코어 웹 바이탈"],"related":[{"term":"Latency","note":"— LCP 와 INP 가 재는 기다림 자체를 가리키는 상위 개념"},{"term":"CDN","note":"— 파일을 사용자 가까이 둬서 LCP 를 줄이는 대표적 수단"},{"term":"HTTP Caching","note":"— 두 번째 방문에서 다시 받지 않게 해 로딩 지표를 낮추는 규약"},{"term":"DOM","note":"— CLS 가 재는 배치 밀림이 실제로 일어나는 대상"}]},{"id":"web--dom","term":"DOM","reading":"Document Object Model","category":"웹 개발","summary":"DOM은 문서를 프로그램이 고칠 수 있게 만든 **객체 트리**다.","aliases":["dom","document object model"],"related":[{"term":"HTML","note":"— 이 트리를 세우는 재료가 되는 원문"},{"term":"CSS","note":"— 트리의 마디마다 생김새를 매기는 규칙"},{"term":"Object","note":"— 트리의 마디 하나하나가 바로 이것"},{"term":"SPA","note":"— 페이지를 새로 받지 않고 이 트리만 고쳐 화면을 바꾸는 방식"}]},{"id":"web--frontend","term":"Frontend","reading":"프론트엔드","category":"웹 개발","summary":"Frontend 는 **사용자 기기에서 실행되는 화면 쪽 코드**다.","aliases":["frontend","프론트엔드"],"related":[{"term":"Backend","note":"— 데이터와 규칙을 맡는 반대쪽"},{"term":"API","note":"— 두 쪽이 데이터를 주고받는 창구"},{"term":"SPA","note":"— 페이지를 다시 받지 않고 화면만 바꾸는 방식"},{"term":"CDN","note":"— 화면 파일을 사용자 가까운 곳에 두는 층"}]},{"id":"web--full-stack","term":"Full Stack","reading":"풀스택","category":"웹 개발","summary":"Full Stack은 **화면부터 서버까지 전부 다루는 것**이다.","aliases":["full stack","풀스택"],"related":[{"term":"Frontend","note":"— 사용자가 직접 보는 층"},{"term":"Backend","note":"— 요청을 받아 처리하는 층"},{"term":"DB","note":"— 값을 담아두는 곳. 스택의 맨 아래"},{"term":"API","note":"— 화면과 서버가 주고받는 약속"},{"term":"DevOps","note":"— 만든 것을 띄우고 유지하는 일"}]},{"id":"web--graphql","term":"GraphQL","reading":"","category":"웹 개발","summary":"GraphQL은 **필요한 필드를 골라서 요청하는 API 방식**이다.","aliases":["graphql"],"related":[{"term":"REST","note":"— 주소마다 응답이 정해진 방식. GraphQL 과 대비된다"},{"term":"API","note":"— GraphQL 이 속한 큰 갈래"},{"term":"HTTP","note":"— GraphQL 요청도 대개 이 위로 오간다"},{"term":"gRPC","note":"— 성능을 앞세운 또 다른 통신 방식"},{"term":"API Gateway","note":"— 여러 API 앞에 두는 진입점. GraphQL 을 그 자리에 놓기도 한다"}]},{"id":"web--html","term":"HTML","reading":"HyperText Markup Language","category":"웹 개발","summary":"HTML은 웹 내용의 **뜻과 구조**를 표시하는 마크업 언어다.","aliases":["html","hypertext markup language"],"related":[{"term":"CSS","note":"— HTML 이 표시해 둔 것 위에 생김새를 얹는 언어"},{"term":"DOM","note":"— 브라우저가 HTML 원문을 읽어 세우는 객체 트리"},{"term":"Frontend","note":"— HTML·CSS·JavaScript 로 화면 쪽을 만드는 일 전체"},{"term":"URL","note":"— 하이퍼텍스트 링크가 가리키는 주소"}]},{"id":"web--http-caching","term":"HTTP Caching","reading":"HTTP 캐싱","category":"웹 개발","summary":"HTTP Caching 은 **응답을 얼마나 들고 있어도 되는지 헤더로 정하는 규약**이다.","aliases":["http caching","http 캐싱"],"related":[{"term":"Caching","note":"— 이 규약이 HTTP 위에서 조문으로 만든 개념 쪽"},{"term":"TTL","note":"— `max-age` 가 HTTP 에서 맡는 바로 그 역할"},{"term":"CDN","note":"— 이 헤더를 읽고 사본을 들고 있는 대표적인 공용 캐시"},{"term":"HTTP","note":"— 이 규칙들이 헤더로 실려 가는 규약"},{"term":"HTTP Status Code","note":"— 재확인이 `304` 로 끝난다는 것을 정하는 표"}]},{"id":"web--http-status-code","term":"HTTP Status Code","reading":"HTTP 상태 코드","category":"웹 개발","summary":"HTTP 상태 코드는 **서버가 요청 결과를 알리는 세 자리 숫자**다.","aliases":["http status code","http 상태 코드"],"related":[{"term":"HTTP","note":"— 이 숫자가 실려 오는 프로토콜"},{"term":"REST","note":"— 메서드와 이 숫자를 규칙대로 쓰는 API 설계 방식"},{"term":"Rate Limiting","note":"— 429 로 알리는 그 제한"},{"term":"Reverse Proxy","note":"— 502 처럼 게이트웨이 계열 오류가 나는 자리"}]},{"id":"web--hydration","term":"Hydration","reading":"하이드레이션","category":"웹 개발","summary":"Hydration은 **서버가 보낸 HTML에 동작을 붙여 살리는 일**이다.","aliases":["hydration","하이드레이션"],"related":[{"term":"SSR","note":"— 하이드레이션이 살려낼 HTML을 요청마다 만들어 보내는 쪽"},{"term":"SSG","note":"— 빌드 때 미리 만들어 둔 HTML도 같은 방식으로 살린다"},{"term":"CSR","note":"— 붙일 HTML 없이 브라우저가 처음부터 그리는 쪽"},{"term":"DOM","note":"— 하이드레이션이 손대는 대상. 이미 만들어진 요소에 동작을 건다"},{"term":"Component","note":"— 동작을 붙일 단위. 서버와 브라우저가 같은 것을 그려야 맞춰진다"}]},{"id":"web--idempotency-key","term":"Idempotency Key","reading":"멱등 키","category":"웹 개발","summary":"Idempotency Key 는 **같은 요청을 한 번만 처리하게 만드는 열쇠**다.","aliases":["idempotency key","멱등 키"],"related":[{"term":"HTTP","note":"— 어떤 메서드가 멱등인지 정해 둔 규칙. `POST` 가 빠진 이유가 여기 있다"},{"term":"HTTP Status Code","note":"— 열쇠가 겹쳤을 때 돌려주는 `409`·`422` 가 있는 표"},{"term":"Message Queue","note":"— 같은 메시지가 두 번 오는 자리. 처리한 id 를 적어 두고 걸러낸다"},{"term":"Transaction","note":"— 처리와 기록이 함께 되거나 함께 안 되게 묶어 주는 아래층 장치"}]},{"id":"web--javascript","term":"JavaScript","reading":"자바스크립트","category":"웹 개발","summary":"JavaScript는 **브라우저에서 페이지의 동작을 맡는 프로그래밍 언어**다.","aliases":["javascript","자바스크립트"],"related":[{"term":"HTML","note":"— 같은 페이지에서 뜻과 뼈대를 맡는 층"},{"term":"CSS","note":"— 같은 페이지에서 생김새를 맡는 층"},{"term":"DOM","note":"— 스크립트가 화면을 만질 때 붙잡는 손잡이"},{"term":"Compile vs Interpret","note":"— 이 언어를 인터프리터 쪽으로 부르는 까닭이 여기 있다"},{"term":"Service Worker","note":"— 브라우저가 준 실행 자리 가운데 화면 밖에서 도는 것"}]},{"id":"web--local-storage-session-storage","term":"Local Storage & Session Storage","reading":"브라우저 저장소","category":"웹 개발","summary":"Local Storage 와 Session Storage 는 **브라우저에 값을 남기는 두 저장소**다.","aliases":["local storage & session storage","브라우저 저장소","local storage","session storage"],"related":[{"term":"Cookie","note":"— 같은 브라우저 저장이지만 요청마다 서버로 딸려 가는 쪽"},{"term":"Session","note":"— 이름만 겹치는 서버 쪽 상태. sessionStorage 와 다른 것"},{"term":"Same-Origin Policy","note":"— 이 통을 출처마다 따로 갈라 두는 규칙"},{"term":"XSS","note":"— 이 통의 값을 스크립트로 읽어가는 공격"}]},{"id":"web--middleware","term":"Middleware","reading":"미들웨어","category":"웹 개발","summary":"Middleware는 **요청이 처리기에 닿기 전에 거쳐 가는 중간 함수**다.","aliases":["middleware","미들웨어"],"related":[{"term":"CORS","note":"— 미들웨어로 처리하는 대표적인 규칙"},{"term":"API Gateway","note":"— 같은 일을 서비스 바깥 경계에서 하는 자리"},{"term":"JWT","note":"— 인증 미들웨어가 확인하는 토큰의 한 형태"},{"term":"Logging","note":"— 미들웨어가 남기는 요청 기록"}]},{"id":"web--openapi","term":"OpenAPI","reading":"오픈API","category":"웹 개발","summary":"OpenAPI 는 **HTTP API 의 사용법을 기계도 읽게 적는** 표준 형식이다.","aliases":["openapi","오픈api"],"related":[{"term":"API","note":"— OpenAPI 가 적어 두는 대상 그 자체"},{"term":"REST","note":"— HTTP 메서드로 API 를 설계하는 방식. OpenAPI 가 주로 적는 모양이다"},{"term":"JSON","note":"— 명세 파일의 본래 형태. 문서 자체가 하나의 JSON 객체다"},{"term":"YAML","note":"— 같은 명세를 사람이 쓰기 좋게 적는 표기"},{"term":"SDK","note":"— 명세 파일에서 뽑아내는 결과물 중 하나"}]},{"id":"web--pwa","term":"PWA","reading":"Progressive Web App","category":"웹 개발","summary":"PWA는 **웹 기술로 만들어 기기에 설치되는 앱**이다.","aliases":["pwa","progressive web app"],"related":[{"term":"Service Worker","note":"— 오프라인을 맡는 다리. PWA 의 절반이 이것이다"},{"term":"HTTPS","note":"— 설치의 전제 조건. 개발용 주소 말고는 예외가 없다"},{"term":"Cache","note":"— 워커가 오프라인에 쓸 응답을 담아두는 곳"},{"term":"SPA","note":"— PWA 가 흔히 올라타는 화면 구성 방식. 서로 다른 층의 말이다"},{"term":"JavaScript","note":"— 서비스 워커를 비롯해 PWA 의 동작을 이 언어로 쓴다"}]},{"id":"web--pagination","term":"Pagination","reading":"페이지네이션","category":"웹 개발","summary":"Pagination 은 **목록을 여러 쪽으로 잘라 주는 방식**이다.","aliases":["pagination","페이지네이션"],"related":[{"term":"REST","note":"— 쪽 나누기를 쿼리 문자열과 응답 헤더로 주고받는 방식"},{"term":"GraphQL","note":"— 커서와 쪽 정보를 규격으로 못 박아 둔 쪽"},{"term":"Index","note":"— cursor 방식이 깊은 쪽에서도 빠른 이유. 정렬 기준에 걸려 있어야 한다"},{"term":"Rate Limiting","note":"— 한 번에 가져갈 양을 묶어 서버를 지키는 같은 목적의 다른 장치"}]},{"id":"web--rest","term":"REST","reading":"Representational State Transfer","category":"웹 개발","summary":"REST는 **HTTP 를 자원 중심으로 쓰기로 한 약속**이다.","aliases":["rest","representational state transfer"],"related":[{"term":"HTTP","note":"— REST 가 그대로 빌려 쓰는 바탕"},{"term":"HTTP Status Code","note":"— 결과를 알리는 데 쓰는 숫자"},{"term":"JSON","note":"— 본문을 싣는 데 가장 많이 쓰이는 형식"},{"term":"GraphQL","note":"— 주소 하나로 필요한 것만 골라 받는 다른 방식"}]},{"id":"web--responsive-design","term":"Responsive Design","reading":"반응형 디자인","category":"웹 개발","summary":"Responsive Design 은 **화면 크기에 따라 배치가 스스로 바뀌는** 웹 설계 방식이다.","aliases":["responsive design","반응형 디자인"],"related":[{"term":"CSS","note":"— 미디어 쿼리와 유연한 단위가 사는 곳"},{"term":"HTML","note":"— `viewport` 메타 태그를 놓는 자리"},{"term":"Accessibility","note":"— 작은 화면이라는 상황적 제약을 함께 다룬다"},{"term":"Frontend","note":"— 화면이 어느 폭에서도 서게 만드는 책임이 여기에 있다"}]},{"id":"web--soap","term":"SOAP","reading":"Simple Object Access Protocol","category":"웹 개발","summary":"SOAP은 **XML 봉투로 감싸 메시지를 주고받는 규격**이다.","aliases":["soap","simple object access protocol"],"related":[{"term":"REST","note":"— 같은 자리를 HTTP 로 푼 다음 세대. SOAP 을 밀어낸 방식"},{"term":"XML","note":"— 봉투와 본문을 적는 형식. SOAP 이 직렬화 형태로 못 박은 것"},{"term":"HTTP","note":"— 봉투를 실어 나르는 여러 전송 중 가장 흔한 하나"},{"term":"API","note":"— SOAP 봉투가 창구 역할을 맡던 자리"},{"term":"gRPC","note":"— 봉투 대신 이진 형식과 규격화된 계약으로 같은 문제를 푸는 요즘 방식"}]},{"id":"web--spa","term":"SPA","reading":"Single Page Application","category":"웹 개발","summary":"SPA는 **HTML 한 장으로 시작해 화면만 갈아 끼우는 웹 앱**이다.","aliases":["spa","single page application"],"related":[{"term":"CSR","note":"— SPA가 화면을 브라우저에서 그리는 방식"},{"term":"SSR","note":"— 서버가 미리 그려 보내는 쪽. 첫 화면과 검색 문제를 푸는 대안"},{"term":"Frontend","note":"— SPA가 놓이는 자리"},{"term":"REST","note":"— SPA가 데이터를 받아올 때 흔히 쓰는 API 형식"}]},{"id":"web--ssg","term":"SSG","reading":"Static Site Generation","category":"웹 개발","summary":"SSG는 **요청이 오기 전에 HTML을 미리 만들어 두는 방식**이다.","aliases":["ssg","static site generation"],"related":[{"term":"SSR","note":"— 같은 HTML을 요청이 올 때 만드는 쪽"},{"term":"CSR","note":"— 화면을 브라우저가 그리는 쪽. SSG로 만든 첫 화면과 섞어 쓴다"},{"term":"Hydration","note":"— 미리 만든 HTML에 동작을 붙이는 다음 단계"},{"term":"CDN","note":"— 미리 만든 파일을 여러 지역에 복사해 두는 곳"},{"term":"Build","note":"— SSG가 HTML을 만드는 시점"}]},{"id":"web--ssr","term":"SSR","reading":"Server Side Rendering","category":"웹 개발","summary":"SSR은 **서버가 완성된 HTML을 만들어 보내는 방식**이다.","aliases":["ssr","server side rendering"],"related":[{"term":"CSR","note":"— 같은 화면을 브라우저가 조립하는 반대쪽 방식"},{"term":"SPA","note":"— 페이지 이동을 브라우저 안에서 처리하는 구조. 주로 CSR과 함께 쓴다"},{"term":"Cache","note":"— 같은 HTML을 다시 조립하지 않으려고 함께 쓴다"},{"term":"Backend","note":"— HTML 조립이 일어나는 자리"}]},{"id":"web--same-origin-policy","term":"Same-Origin Policy","reading":"동일 출처 정책","category":"웹 개발","summary":"Same-Origin Policy는 **다른 출처의 응답을 못 읽게 막는 브라우저 규칙**이다.","aliases":["same-origin policy","동일 출처 정책"],"related":[{"term":"CORS","note":"— 이 정책이 막은 자리에 서버가 문을 내는 방법"},{"term":"URL","note":"— 출처를 이루는 스킴·호스트·포트가 적혀 있는 곳"},{"term":"HTTPS","note":"— 스킴이 달라지면 출처도 달라지므로 http 판과 남남이 된다"},{"term":"CSRF","note":"— 이 정책이 쓰기 요청을 안 막기 때문에 남는 공격"},{"term":"XSS","note":"— 담 안으로 코드를 밀어 넣어 이 정책을 없는 것으로 만드는 공격"}]},{"id":"web--service-worker","term":"Service Worker","reading":"서비스 워커","category":"웹 개발","summary":"Service Worker는 **웹앱과 네트워크 사이에서 요청을 가로채는 프록시**다.","aliases":["service worker","서비스 워커"],"related":[{"term":"Proxy","note":"— 서비스 워커가 브라우저 안에서 맡는 역할과 같은 것"},{"term":"Cache","note":"— 오프라인에 쓸 응답을 워커가 담아두는 곳"},{"term":"HTTPS","note":"— 서비스 워커를 등록하려면 먼저 갖춰야 하는 조건"},{"term":"Same-Origin Policy","note":"— 워커 파일을 같은 출처에만 둘 수 있게 하는 규칙"},{"term":"Thread","note":"— 워커가 화면과 따로 도는 실행 자리"}]},{"id":"web--webassembly","term":"WebAssembly","reading":"웹어셈블리","category":"웹 개발","summary":"WebAssembly는 **여러 언어를 컴파일해 담는 안전한 저수준 코드 형식**이다.","aliases":["webassembly","웹어셈블리"],"related":[{"term":"JavaScript","note":"— 브라우저에서 오래 혼자 돌던 언어. 웹어셈블리는 그 옆에 다른 언어들을 데려온다"},{"term":"Compile","note":"— 여러 언어가 하나의 이진 형식으로 모이는 그 단계"},{"term":"Browser Rendering","note":"— 화면을 그리는 쪽. 웹어셈블리 모듈은 그 화면을 직접 만지지 못하고 호스트를 거친다"},{"term":"Source Map","note":"— 이 형식으로 컴파일한 코드도 원본 자리로 되짚을 수 있게 하는 표"}]},{"id":"web--webhook","term":"Webhook","reading":"웹훅","category":"웹 개발","summary":"Webhook은 **일이 생겼을 때 서버가 먼저 알려주는 방식**이다.","aliases":["webhook","웹훅"],"related":[{"term":"WebSocket","note":"— 연결을 열어둔 채 양쪽이 주고받는 방식"},{"term":"SSE","note":"— 서버가 한쪽으로만 계속 흘려보내는 방식"},{"term":"Event-Driven Architecture","note":"— 웹훅이 놓여 있는 큰 그림"},{"term":"CI_CD","note":"— 저장소 웹훅으로 시작되는 대표적인 흐름"}]},{"id":"web--grpc","term":"gRPC","reading":"","category":"웹 개발","summary":"gRPC는 **먼 서버의 함수를 내 함수처럼 부르게 해주는 방식**이다.","aliases":["grpc"],"related":[{"term":"REST","note":"— 바깥에 여는 API에서 여전히 기본이 되는 방식"},{"term":"HTTP","note":"— gRPC가 올라타는 HTTP/2의 앞 버전"},{"term":"GraphQL","note":"— 같은 자리를 놓고 겨루는 또 다른 방식"},{"term":"Monolith vs Microservices","note":"— gRPC가 주로 쓰이는 구조"}]}]},{"id":"db","name":"데이터베이스","blurb":"데이터를 어디에 어떻게 두나","terms":[{"id":"db--acid","term":"ACID","reading":"","category":"데이터베이스","summary":"ACID는 **트랜잭션이 보장하는 네 가지 성질**이다.","aliases":["acid"],"related":[{"term":"Transaction","note":"— 이 네 가지를 지켜주는 묶음 그 자체"},{"term":"Isolation Level","note":"— 네 글자 중 I 를 몇 단계로 지킬지 고르는 자리"},{"term":"CAP Theorem","note":"— 한 대를 넘어 여러 대로 흩어지면 이 보장이 어디까지 가능한가"},{"term":"NoSQL","note":"— 보장을 일부 내주고 확장을 택한 쪽"},{"term":"DB","note":"— 이 보장을 파는 쪽"}]},{"id":"db--apache-airflow","term":"Apache Airflow","reading":"에어플로","category":"데이터베이스","summary":"Airflow 는 **일의 순서와 시각을 코드로 적어 두고 대신 돌려주는 판**이다.","aliases":["apache airflow","에어플로"],"related":[{"term":"Pipeline","note":"— Airflow 가 그 위에서 순서를 지켜 돌리는 틀"},{"term":"ETL","note":"— 이 판이 밤마다 부르는 가장 흔한 일감"},{"term":"Idempotency","note":"— 재시도와 구간 채우기가 기본이기에 반드시 딸려 오는 성질"},{"term":"Apache Spark","note":"— Airflow 가 부르고 결과만 기다리는 무거운 계산 쪽"},{"term":"Batch vs Stream Processing","note":"— Airflow 가 잘 맞는 박자와 안 맞는 박자의 갈림"}]},{"id":"db--apache-iceberg","term":"Apache Iceberg","reading":"아이스버그","category":"데이터베이스","summary":"Iceberg는 **파일 더미를 표 하나로 다루게 하는 규격**이다.","aliases":["apache iceberg","아이스버그"],"related":[{"term":"Apache Parquet","note":"— 이 표 안에 실제 값이 담기는 파일 형식"},{"term":"Data Lake","note":"— 파일이 쌓여 있던 자리. 거기에 표의 규칙을 씌운 것이 이 규격이다"},{"term":"Transaction","note":"— 커밋 한 번이 통째로 되거나 아예 안 되게 하는 그 성질"},{"term":"Schema Evolution","note":"— 파일을 안 건드리고 모양을 바꿀 수 있게 하는 규칙"},{"term":"Partitioning","note":"— 어느 조각만 읽을지 가르는 기준. 이 규격은 그 기준도 나중에 바꾼다"}]},{"id":"db--apache-kafka","term":"Apache Kafka","reading":"카프카","category":"데이터베이스","summary":"Kafka 는 **사건을 순서대로 적어 두고 여러 곳이 따로 읽어 가는 기록장**이다.","aliases":["apache kafka","카프카"],"related":[{"term":"Message Queue","note":"— 읽으면 사라지는 쪽. 다시 읽을 일이 없을 때의 더 가벼운 선택"},{"term":"Idempotency","note":"— 같은 것이 두 번 와도 결과가 같게 만드는 받는 쪽의 방어"},{"term":"Change Data Capture","note":"— 데이터베이스에서 바뀐 줄을 이 기록장으로 흘려보내는 대표적인 앞자리"},{"term":"Batch vs Stream Processing","note":"— 이 기록장을 어떤 박자로 읽어 갈지의 갈림"},{"term":"Replication","note":"— 기록을 여러 기계에 사본으로 두는 그 방식"}]},{"id":"db--apache-parquet","term":"Apache Parquet","reading":"파케이","category":"데이터베이스","summary":"Parquet는 **칸끼리 모아 담고 목차를 붙인 파일 형식**이다.","aliases":["apache parquet","파케이"],"related":[{"term":"Columnar Storage","note":"— 이 파일이 따르는 저장 방식 그 자체"},{"term":"Apache Iceberg","note":"— 이 파일 여럿을 표 하나로 묶어 다루는 층"},{"term":"Data Lake","note":"— 이 파일이 실제로 쌓이는 자리"},{"term":"Serialization","note":"— 값을 파일에 적는 일반적인 일. 이 형식은 그중 분석용 한 갈래"},{"term":"Schema Evolution","note":"— 파일마다 모양이 달라졌을 때 맞춰 읽는 규칙"}]},{"id":"db--apache-spark","term":"Apache Spark","reading":"스파크","category":"데이터베이스","summary":"Spark 는 **큰 표를 조각으로 쪼개 여러 대가 나눠 계산하는 엔진**이다.","aliases":["apache spark","스파크"],"related":[{"term":"Partitioning","note":"— 표를 조각으로 나누는 그 발상. Spark 는 이것을 계산 단위로 쓴다"},{"term":"Apache Airflow","note":"— Spark 에게 언제 무엇을 시킬지 들고 있는 순서표 쪽"},{"term":"Batch vs Stream Processing","note":"— 같은 엔진이 받는 두 박자의 갈림"},{"term":"Data Lake","note":"— Spark 가 조각으로 읽어 들이는 가장 흔한 입력 자리"},{"term":"ETL","note":"— Spark 가 실제로 맡는 일감의 이름"}]},{"id":"db--b-tree","term":"B-Tree","reading":"B 트리","category":"데이터베이스","summary":"B-Tree 는 **정렬된 값을 여러 갈래로 갈라 담은 균형 트리**다.","aliases":["b-tree","b 트리"],"related":[{"term":"Index","note":"— B-Tree 가 인덱스의 기본 모양이다"},{"term":"Query Plan","note":"— 이 인덱스를 탈지 훑을지 고르는 자리"},{"term":"자료구조","note":"— 이 트리가 속한 갈래"},{"term":"Big O 표기법","note":"— 층 수로 정해지는 탐색 비용을 적는 방식"},{"term":"DB","note":"— 쪽 단위로 읽고 쓰는 저장 구조"}]},{"id":"db--batch-vs-stream-processing","term":"Batch vs Stream Processing","reading":"일괄 처리와 흐름 처리","category":"데이터베이스","summary":"둘은 **다루는 것에 끝이 있느냐 없느냐로 갈리는 두 처리 방식**이다.","aliases":["batch vs stream processing","일괄 처리와 흐름 처리","batch","stream processing"],"related":[{"term":"Windowing","note":"— 끝없는 쪽에서 \"여기까지를 한 판\" 이라고 자르는 그 일"},{"term":"Watermark","note":"— 잘라 둔 판을 언제 닫아도 되는지 정하는 선"},{"term":"Event Time vs Processing Time","note":"— 흐름 쪽에서 무엇으로 셀지 고르는 두 시계"},{"term":"Apache Kafka","note":"— 흐르는 쪽의 입력을 담아 두고 되감게 해 주는 자리"},{"term":"Apache Spark","note":"— 같은 엔진으로 두 박자를 모두 돌리는 대표적인 예"}]},{"id":"db--bloom-filter","term":"Bloom Filter","reading":"블룸 필터","category":"데이터베이스","summary":"Bloom Filter 는 **없는 것을 값싸게 걸러 내는 확률적 검사표**다.","aliases":["bloom filter","블룸 필터"],"related":[{"term":"LSM Tree","note":"— 파일마다 이 표를 붙여 헛걸음을 줄이는 대표적인 자리"},{"term":"Index","note":"— 있는 것을 찾아가는 쪽. 이 표는 없는 것을 쳐내는 쪽이다"},{"term":"Redis","note":"— 이 구조를 명령으로 직접 제공하는 저장소"},{"term":"Key-Value Store","note":"— 열쇠로 묻고 답하는 구조라 이 걸러내기가 잘 맞는다"}]},{"id":"db--cap-theorem","term":"CAP Theorem","reading":"CAP 정리","category":"데이터베이스","summary":"CAP Theorem은 **네트워크가 갈라지면 일관성과 가용성 중 하나를 내주게 된다는 정리**다.","aliases":["cap theorem","cap 정리"],"related":[{"term":"ACID","note":"— 한 대에서 지키는 보장. CAP 의 C 는 이 C 와 다른 말이다"},{"term":"NoSQL","note":"— 여러 대로 흩어지면서 가용성 쪽을 자주 택하는 계열"},{"term":"Sharding","note":"— 데이터를 여러 대에 나눠 두는 방식. 노드가 여럿이라야 분할이 문제가 된다"},{"term":"Availability Zone","note":"— 분할이 실제로 일어나는 물리적 경계"}]},{"id":"db--cte","term":"CTE","reading":"공통 테이블 식","category":"데이터베이스","summary":"CTE는 **질의 하나 안에서만 사는 이름 붙인 중간 표**다.","aliases":["cte","공통 테이블 식"],"related":[{"term":"Query","note":"— CTE 가 얹히는 질의 그 자체"},{"term":"View & Materialized View","note":"— 문장 밖에서도 사는 이름. CTE 는 문장 안에서만 산다"},{"term":"Query Plan","note":"— 접어 넣었는지 따로 계산했는지가 여기 찍힌다"},{"term":"SQL","note":"— `WITH` 절이 속한 언어"},{"term":"ETL","note":"— 단을 나눠 쌓는 일을 질의 하나 안에서 하는 방법"}]},{"id":"db--cardinality","term":"Cardinality","reading":"카디널리티","category":"데이터베이스","summary":"Cardinality는 **한 칸에 서로 다른 값이 몇 가지 있는가**다.","aliases":["cardinality","카디널리티"],"related":[{"term":"Index","note":"— 갈래가 많은 칸에서 값어치가 나는 장치"},{"term":"Query Plan","note":"— 어림한 줄 수가 계획으로 굳는 자리"},{"term":"JOIN","note":"— 짝의 수를 잘못 보면 줄이 불어나는 연산"},{"term":"B-Tree","note":"— 갈래가 많은 칸에서 힘을 내는 목차 구조"},{"term":"Star Schema","note":"— \"일\" 쪽과 \"다\" 쪽으로 표의 역할이 갈리는 짜임"}]},{"id":"db--change-data-capture","term":"Change Data Capture","reading":"변경 데이터 포착","category":"데이터베이스","summary":"CDC 는 **표에서 바뀐 줄만 골라 흐름으로 흘려보내는 일**이다.","aliases":["change data capture","변경 데이터 포착"],"related":[{"term":"WAL","note":"— CDC 가 읽어 내는 바로 그 기록. 원래는 고장 대비용으로 적히던 것이다"},{"term":"Transaction","note":"— 변경 줄에 붙는 확정 번호가 묶어 주는 단위"},{"term":"Apache Kafka","note":"— 뽑아낸 변경 흐름을 흘려보내는 가장 흔한 다음 자리"},{"term":"Replication","note":"— 같은 로그를 읽어 사본을 맞추는 쪽. CDC 와 뿌리가 같다"},{"term":"ETL","note":"— 표 전체를 다시 붓던 자리를 바뀐 줄만으로 바꾸는 대상"}]},{"id":"db--columnar-storage","term":"Columnar Storage","reading":"열 기반 저장","category":"데이터베이스","summary":"Columnar Storage는 **같은 칸의 값끼리 이어 붙여 두는 저장 방식**이다.","aliases":["columnar storage","열 기반 저장"],"related":[{"term":"Apache Parquet","note":"— 이 방식을 파일 형식으로 굳혀 놓은 대표 사례"},{"term":"OLTP vs OLAP","note":"— 줄 저장과 칸 저장이 갈리는 바로 그 두 갈래"},{"term":"Index","note":"— 줄 저장에서 찾아 들어가려고 따로 만드는 것. 여기서는 세그먼트 통계가 그 일을 한다"},{"term":"Data Warehouse","note":"— 이 저장 방식이 기본값처럼 쓰이는 자리"},{"term":"Partitioning","note":"— 읽을 덩어리를 미리 갈라 두는 다른 축. 칸으로 나누는 이것과 같이 쓴다"}]},{"id":"db--connection-pool","term":"Connection Pool","reading":"커넥션 풀","category":"데이터베이스","summary":"커넥션 풀은 **연결을 열어 두고 돌려쓰는 통**이다.","aliases":["connection pool","커넥션 풀"],"related":[{"term":"DB","note":"— 풀이 붙들고 있는 상대"},{"term":"Socket","note":"— 풀에 담기는 연결의 실체"},{"term":"ORM","note":"— 대개 자기 안에 이 풀을 끼고 도는 계층"},{"term":"Latency","note":"— 연결을 새로 맺지 않아 줄어드는 시간"}]},{"id":"db--db","term":"DB","reading":"Database, 데이터베이스","category":"데이터베이스","summary":"DB는 **데이터를 구조에 맞춰 맡아두고 지키는 시스템**이다.","aliases":["db","database, 데이터베이스"],"related":[{"term":"SQL","note":"— 관계형 DB에 무엇을 원하는지 적어 보내는 언어"},{"term":"ORM","note":"— DB의 행을 프로그램의 객체로 바꿔주는 계층"},{"term":"Index","note":"— 찾는 속도를 위해 따로 만들어두는 정렬 목록"},{"term":"Transaction","note":"— 여러 작업을 전부 되거나 전부 안 되게 묶는 단위"},{"term":"NoSQL","note":"— 표 모양을 미리 정하지 않는 쪽의 DB"}]},{"id":"db--data-catalog","term":"Data Catalog","reading":"데이터 카탈로그","category":"데이터베이스","summary":"Data Catalog는 **어디에 무엇이 어떤 모양으로 있는지 적어 둔 목록**이다.","aliases":["data catalog","데이터 카탈로그"],"related":[{"term":"Data Lake","note":"— 파일 더미로 쌓아 두는 자리. 목록이 없으면 늪이 된다"},{"term":"Data Warehouse","note":"— 정돈해 쌓는 자리. 목록은 이쪽과 저쪽을 함께 적는다"},{"term":"ETL","note":"— 목록에 적힌 표를 읽어 다른 표로 옮기는 일"},{"term":"Data Lineage","note":"— 그 표가 어디서 왔는지까지 목록에 붙는 칸"},{"term":"Data Quality","note":"— 믿어도 되는지를 점수로 붙여 두는 칸"}]},{"id":"db--data-contract","term":"Data Contract","reading":"데이터 계약","category":"데이터베이스","summary":"Data Contract는 **주는 쪽과 받는 쪽이 미리 적어 두는 약속**이다.","aliases":["data contract","데이터 계약"],"related":[{"term":"Schema Registry","note":"— 계약 중 모양 부분만 떼어 기계에 맡긴 자리"},{"term":"Schema Evolution","note":"— 계약을 깨지 않고 바꿔 나갈 때 지키는 규칙"},{"term":"SLA SLO SLI","note":"— 계약에 적는 \"언제까지·얼마나\" 를 재는 눈금"},{"term":"Data Warehouse","note":"— 계약이 걸리는 표가 실제로 사는 곳"},{"term":"ETL","note":"— 계약을 어겼는지 검사가 도는 자리. 만드는 그 길목이다"}]},{"id":"db--data-lake","term":"Data Lake","reading":"데이터 레이크","category":"데이터베이스","summary":"데이터 레이크는 **정리하지 않은 원본을 그대로 쌓아 두는 저장소**다.","aliases":["data lake","데이터 레이크"],"related":[{"term":"Data Warehouse","note":"— 담을 때 먼저 정리하는 반대쪽 선택"},{"term":"ETL","note":"— 담기 전에 변환하는 방식. 레이크는 이 순서를 뒤집는다"},{"term":"S3","note":"— 레이크의 저장 층으로 흔히 쓰이는 클라우드 저장소"},{"term":"JSON","note":"— 레이크가 원본 그대로 받는 반구조화 형식의 예"},{"term":"구조화 데이터","note":"— 웨어하우스가 요구하고 레이크는 요구하지 않는 형태"}]},{"id":"db--data-lineage","term":"Data Lineage","reading":"데이터 계보","category":"데이터베이스","summary":"Data Lineage는 **자료가 어디서 나와 무엇을 거쳐 여기 왔는지의 지도**다.","aliases":["data lineage","데이터 계보"],"related":[{"term":"Data Catalog","note":"— 계보가 붙는 목록. 표 설명 옆 칸이 계보다"},{"term":"ETL","note":"— 계보의 화살표 하나하나가 이 작업이다"},{"term":"Data Quality","note":"— 규칙이 깨진 곳에서 원인으로 거슬러 오를 때 타는 길"},{"term":"Pipeline","note":"— 계보가 그리는 그 길 자체"},{"term":"Observability","note":"— 밖에서 물어 안을 알아내는 같은 생각. 이쪽은 대상이 자료다"}]},{"id":"db--data-quality","term":"Data Quality","reading":"데이터 품질","category":"데이터베이스","summary":"Data Quality는 **쌓인 자료가 제 쓸모를 하는 정도**다.","aliases":["data quality","데이터 품질"],"related":[{"term":"Data Catalog","note":"— 규칙 묶음이 매달리는 표 목록"},{"term":"Data Lineage","note":"— 규칙이 걸린 자리에서 원인으로 거슬러 오르는 길"},{"term":"ETL","note":"— 흐르는 중에 규칙을 거는 자리"},{"term":"Data Warehouse","note":"— 규칙이 지켜 주는 최종 저장 자리"},{"term":"Observability","note":"— 밖에서 물어 안을 알아내는 같은 생각. 이쪽은 대상이 자료다"}]},{"id":"db--data-warehouse","term":"Data Warehouse","reading":"데이터 웨어하우스","category":"데이터베이스","summary":"데이터 웨어하우스는 **여러 시스템의 데이터를 분석용으로 모아 정리해 둔 저장소**다.","aliases":["data warehouse","데이터 웨어하우스"],"related":[{"term":"ETL","note":"— 소스에서 웨어하우스로 옮기며 형식을 맞추는 과정"},{"term":"Data Lake","note":"— 정리를 미루고 원본부터 쌓는 반대쪽 선택"},{"term":"Snowflake","note":"— 이 개념을 클라우드 제품으로 만든 예"},{"term":"DB","note":"— 웨어하우스와 갈라지는 운영용 쪽의 큰 갈래"},{"term":"SQL","note":"— 웨어하우스에 묻는 언어"}]},{"id":"db--denormalization","term":"Denormalization","reading":"역정규화","category":"데이터베이스","summary":"Denormalization 은 **읽기를 위해 중복을 일부러 되살리는** 설계다.","aliases":["denormalization","역정규화"],"related":[{"term":"Normalization","note":"— 역정규화가 되돌리는 대상. 이걸 먼저 하고 나서 고른다"},{"term":"NoSQL","note":"— 접근 패턴에 맞춰 표 수를 줄이는 쪽이라 역정규화가 기본에 가깝다"},{"term":"Eventual Consistency","note":"— 베껴 둔 값이 원본을 잠시 못 따라가는 상태를 다루는 짝"},{"term":"Index","note":"— 표를 안 건드리고 읽기를 빠르게 하는 다른 방법"},{"term":"Cache","note":"— 읽기를 사려고 중복을 허용한다는 점에서 같은 종류의 거래"}]},{"id":"db--distributed-sql-database","term":"Distributed SQL Database","reading":"흩어 놓은 관계형 데이터베이스","category":"데이터베이스","summary":"분산 SQL DB 는 **여러 대에 흩어 놓고도 한 대처럼 쓰는 관계형 DB**다.","aliases":["distributed sql database","흩어 놓은 관계형 데이터베이스"],"related":[{"term":"CAP Theorem","note":"— 여러 대로 흩어지면 무엇까지 동시에 가질 수 있는지를 다루는 자리"},{"term":"Partitioning","note":"— 표를 조각내는 일. 여기서는 사람이 아니라 DB 가 한다"},{"term":"Replication","note":"— 조각마다 사본을 두는 일. 과반 합의가 얹히는 바탕"},{"term":"NoSQL","note":"— 같은 벽 앞에서 SQL 과 트랜잭션을 내주고 확장을 택한 쪽"},{"term":"Sharding","note":"— 앱이 손으로 하던 그 일. 분산 SQL DB 는 그걸 DB 안으로 들여놓은 것이다"}]},{"id":"db--document-database","term":"Document Database","reading":"문서 데이터베이스","category":"데이터베이스","summary":"Document Database는 **한 덩어리 문서를 그대로 저장하는** 저장소다.","aliases":["document database","문서 데이터베이스"],"related":[{"term":"NoSQL","note":"— 문서 저장소가 속한 큰 갈래"},{"term":"Key-Value Store","note":"— 값 안을 들여다보지 않는, 한 칸 더 단순한 이웃"},{"term":"JSON","note":"— 문서가 밖에서 오갈 때 쓰는 표기법"},{"term":"Denormalization","note":"— 쪼개지 않고 통째로 담는 일이 곧 이것이다"},{"term":"WAL","note":"— 저널이라 부른 그 장치. 먼저 적고 나중에 내려 앉힌다"}]},{"id":"db--elt","term":"ELT","reading":"추출 적재 변환","category":"데이터베이스","summary":"ELT 는 **원본을 먼저 담고 담은 자리에서 바꾸는 순서**다.","aliases":["elt","추출 적재 변환"],"related":[{"term":"ETL","note":"— 바꾸기가 담기보다 앞에 오는 쪽. 세 글자 중 둘의 자리만 다르다"},{"term":"Data Lake","note":"— 손대지 않은 원본을 담아 두는 그 자리"},{"term":"Data Warehouse","note":"— 담긴 원본을 질의로 바꿔 표를 만드는 목적지"},{"term":"Apache Spark","note":"— 층과 층 사이의 변환을 실제로 돌리는 엔진 중 하나"},{"term":"Change Data Capture","note":"— 원본 층에 바뀐 줄만 흘려 넣는 앞자리"}]},{"id":"db--etl","term":"ETL","reading":"Extract Transform Load","category":"데이터베이스","summary":"ETL 은 **뽑고 바꾸고 담는 순서로 데이터를 옮기는 일**이다.","aliases":["etl","extract transform load"],"related":[{"term":"Data Warehouse","note":"— ETL 이 데이터를 담는 대표적인 목적지"},{"term":"Data Lake","note":"— 원본을 먼저 담는 곳. ELT 로 순서가 바뀔 때의 앞자리"},{"term":"Pipeline","note":"— ETL 이 그 위에서 도는 틀"},{"term":"SQL","note":"— ELT 에서 변환을 적는 언어"},{"term":"구조화 데이터","note":"— 바꾸기 단계가 맞춰 내는 모양"}]},{"id":"db--event-time-vs-processing-time","term":"Event Time vs Processing Time","reading":"발생 시각과 처리 시각","category":"데이터베이스","summary":"발생 시각과 처리 시각은 **한 사건에 달린 서로 다른 두 시계**다.","aliases":["event time vs processing time","발생 시각과 처리 시각","event time","processing time"],"related":[{"term":"Watermark","note":"— 발생 시각으로 세기로 하면 반드시 따라오는 장치"},{"term":"Windowing","note":"— 두 시계 중 어느 것으로 칸을 자를지 정하는 자리"},{"term":"Exactly-Once Semantics","note":"— 다시 돌려도 같은 값이 나와야 한다는 요구가 만나는 곳"},{"term":"ETL","note":"— 배치로 모아 옮길 때 이 시차가 그대로 지연이 되는 쪽"}]},{"id":"db--eventual-consistency","term":"Eventual Consistency","reading":"최종 일관성","category":"데이터베이스","summary":"Eventual Consistency 는 **쓴 직후 읽으면 옛 값이 올 수 있는** 규칙이다.","aliases":["eventual consistency","최종 일관성"],"related":[{"term":"Transaction","note":"— 한 곳에서 즉시 일관성을 지키는 반대편 장치"},{"term":"NoSQL","note":"— 최종 일관성을 기본 읽기 모델로 두는 저장소 계열"},{"term":"Denormalization","note":"— 베껴 둔 값이 원본을 잠시 못 따라가는 대표적인 자리"},{"term":"Cache","note":"— 원본보다 낡은 값을 잠깐 보여준다는 점에서 같은 종류의 타협"},{"term":"Latency","note":"— 최신 보장을 늦추는 대가로 줄이는 값"}]},{"id":"db--exactly-once-semantics","term":"Exactly-Once Semantics","reading":"정확히 한 번","category":"데이터베이스","summary":"Exactly-Once Semantics 는 **같은 사건이 결과에 딱 한 번만 남는 보장**이다.","aliases":["exactly-once semantics","정확히 한 번"],"related":[{"term":"Idempotency","note":"— 여러 번 해도 결과가 같아지는 성질. 이 보장을 떠받치는 밑재료다"},{"term":"Idempotency Key","note":"— 두 번째를 알아보게 해 주는 그 번호표"},{"term":"Transaction","note":"— 여러 곳에 한꺼번에 확정하거나 통째로 무르는 묶음"},{"term":"Retry & Exponential Backoff","note":"— 중복을 만들어 내는 바로 그 동작"},{"term":"Message Queue","note":"— 이 보장을 가장 먼저 따져 보게 되는 자리"}]},{"id":"db--graph-database","term":"Graph Database","reading":"그래프 데이터베이스","category":"데이터베이스","summary":"Graph Database는 **관계 자체를 하나의 자료로 저장하는** 저장소다.","aliases":["graph database","그래프 데이터베이스"],"related":[{"term":"NoSQL","note":"— 그래프 저장소가 속한 큰 갈래"},{"term":"JOIN","note":"— 표 쪽에서 같은 일을 하는 방법. 이쪽은 물을 때마다 만든다"},{"term":"인덱스","note":"— 걷기 시작할 점을 좁혀 주는 자리"},{"term":"Vector DB","note":"— \"닮은 것\" 으로 잇는 이웃. 그래프는 \"이어진 것\" 으로 잇는다"},{"term":"Graph","note":"— 점과 선이라는 자료구조 그 자체. 이쪽은 그것을 저장하고 묻는 창고다"}]},{"id":"db--isolation-level","term":"Isolation Level","reading":"격리 수준","category":"데이터베이스","summary":"Isolation Level은 **동시에 도는 트랜잭션을 서로에게서 얼마나 가릴지 정하는 단계**다.","aliases":["isolation level","격리 수준"],"related":[{"term":"Transaction","note":"— 격리 수준은 이 묶음 하나하나에 걸리는 설정이다"},{"term":"ACID","note":"— 네 글자 중 I 를 몇 단계로 지킬지 고르는 자리"},{"term":"Concurrency","note":"— 이 수준이 다루려는 문제의 배경"},{"term":"DB","note":"— 기본 단계를 제품이 정해서 내놓는 쪽"}]},{"id":"db--join","term":"JOIN","reading":"조인","category":"데이터베이스","summary":"JOIN 은 **조건에 맞는 행끼리 짝지어** 여러 표를 한 결과로 내는 일이다.","aliases":["join","조인"],"related":[{"term":"Primary Key & Foreign Key","note":"— 조인이 따라가는 짝의 근거가 되는 값"},{"term":"Index","note":"— 조인 조건 컬럼에 없으면 상대 표를 통째로 훑게 된다"},{"term":"SQL","note":"— 조인을 적는 언어"},{"term":"DB","note":"— 표를 나눠 담아 조인이 필요해지는 곳"},{"term":"NoSQL","note":"— 나누지 않고 한 문서에 묶어 담아 조인을 피하는 다른 선택"}]},{"id":"db--key-value-store","term":"Key-Value Store","reading":"키-값 저장소","category":"데이터베이스","summary":"Key-Value Store는 **열쇠 하나로 값 하나를 꺼내는 저장소**다.","aliases":["key-value store","키-값 저장소"],"related":[{"term":"NoSQL","note":"— 표 구조를 내려놓은 갈래. 그 안의 한 종류다"},{"term":"Redis","note":"— 열쇠-값 저장소를 메모리에 두고 쓰는 대표 제품"},{"term":"Hash","note":"— 열쇠를 자리로 바꿔 한 번에 닿게 하는 방법"},{"term":"Query","note":"— 열쇠 대신 조건으로 묻는 쪽. 이 저장소가 내려놓은 것"},{"term":"Index","note":"— 값으로 찾아야 할 때 따로 세워야 하는 장치"}]},{"id":"db--lsm-tree","term":"LSM Tree","reading":"엘에스엠 트리","category":"데이터베이스","summary":"LSM Tree 는 **쓰기를 모아 두었다가 통째로 내려쓰는 저장 구조**다.","aliases":["lsm tree","엘에스엠 트리"],"related":[{"term":"B-Tree","note":"— 제자리를 지키는 반대편 저장 구조"},{"term":"Bloom Filter","note":"— 파일마다 붙어 \"여기 없다\" 를 싸게 답해 주는 표"},{"term":"WAL","note":"— 메모리 표가 날아가도 되살리게 해 주는 먼저 적기"},{"term":"Key-Value Store","note":"— 이 구조를 주로 쓰는 저장소 갈래"},{"term":"VACUUM","note":"— 낡은 판을 뒤에서 걷어낸다는 점에서 합치기와 같은 일을 하는 쪽"}]},{"id":"db--mvcc","term":"MVCC","reading":"다중 버전 동시성 제어","category":"데이터베이스","summary":"MVCC 는 **고치는 대신 새 판을 덧붙이는 동시성 처리 방식**이다.","aliases":["mvcc","다중 버전 동시성 제어"],"related":[{"term":"Transaction","note":"— 판을 고를 때 기준이 되는 묶음 그 자체"},{"term":"Isolation Level","note":"— 어느 시각의 판까지 보여줄지 정하는 눈금"},{"term":"VACUUM","note":"— 아무도 안 보게 된 옛 판을 걷어내는 쪽"},{"term":"Optimistic vs Pessimistic Lock","note":"— 쓰기끼리의 다툼은 여전히 남아서 이 둘 중 하나로 다룬다"},{"term":"WAL","note":"— 새 판을 안전하게 못 박는 기록 방식"}]},{"id":"db--migration","term":"Migration","reading":"스키마 마이그레이션","category":"데이터베이스","summary":"마이그레이션은 **스키마 변경을 코드로 적어 이력으로 쌓는** 일이다.","aliases":["migration","스키마 마이그레이션"],"related":[{"term":"DB","note":"— 마이그레이션이 실제로 고치는 대상"},{"term":"SQL","note":"— 마이그레이션 파일이 걸릴 때 번역되어 나가는 말"},{"term":"ORM","note":"— 모델과 스키마의 차이를 떠서 마이그레이션 파일을 뽑아 주는 계층"},{"term":"Git","note":"— 마이그레이션 파일이 다른 소스와 함께 쌓이는 곳"},{"term":"CI_CD","note":"— 배포할 때 마이그레이션을 언제 걸지 정하는 자리"}]},{"id":"db--n-1-problem","term":"N+1 Problem","reading":"N+1 문제","category":"데이터베이스","summary":"N+1 문제는 **목록 하나를 얻고 항목마다 또 묻는** 낭비다.","aliases":["n+1 problem","n+1 문제"],"related":[{"term":"ORM","note":"— 이 문제가 대개 생기는 자리. 질의를 감춰 주면서 질의 수도 함께 감춘다"},{"term":"GraphQL","note":"— 중첩 필드를 파고들 때 같은 꼴로 걸리는 다른 무대"},{"term":"Index","note":"— 질의 한 개를 빠르게 하는 장치. 질의 수는 줄이지 못한다"},{"term":"Latency","note":"— 왕복이 늘어날 때 실제로 커지는 값"},{"term":"Caching","note":"— 같은 질의가 되풀이될 때 왕복 자체를 없애는 다른 길"}]},{"id":"db--nosql","term":"NoSQL","reading":"","category":"데이터베이스","summary":"NoSQL은 **표 모양을 고집하지 않는 데이터베이스**다.","aliases":["nosql"],"related":[{"term":"SQL","note":"— 관계형 DB에 묻는 언어. NoSQL이 내려놓은 쪽"},{"term":"DB","note":"— NoSQL이 속한 큰 갈래"},{"term":"Redis","note":"— Key-Value 저장소의 대표"},{"term":"Vector DB","note":"— 값이 아니라 의미의 가까움으로 찾는 또 다른 갈래"},{"term":"Sharding","note":"— 여러 서버에 나눠 담아 늘리는 방법"}]},{"id":"db--normalization","term":"Normalization","reading":"정규화","category":"데이터베이스","summary":"Normalization 은 **같은 사실을 한 곳에만 두도록** 표를 쪼개는 일이다.","aliases":["normalization","정규화"],"related":[{"term":"Denormalization","note":"— 정규화한 뒤 읽기 성능을 위해 일부러 되돌리는 선택"},{"term":"DB","note":"— 정규화가 손보는 표와 관계가 사는 곳"},{"term":"SQL","note":"— 쪼갠 표를 조인으로 다시 붙여 읽는 언어"},{"term":"Transaction","note":"— 여러 표를 한꺼번에 고칠 때 중간 상태가 안 보이게 묶는 단위"},{"term":"Index","note":"— 쪼갠 표를 열쇠로 빨리 찾게 해 주는 장치"}]},{"id":"db--oltp-vs-olap","term":"OLTP vs OLAP","reading":"","category":"데이터베이스","summary":"OLTP 와 OLAP 는 **한 건을 다루는 쪽과 모아 보는 쪽**이다.","aliases":["oltp vs olap","oltp","olap"],"related":[{"term":"DB","note":"— 두 방식이 갈라지기 전의 같은 바탕"},{"term":"Transaction","note":"— OLTP 쪽이 붙들고 OLAP 쪽은 쓰지 않는 장치"},{"term":"Snowflake","note":"— OLAP 쪽을 맡는 대표적인 클라우드 데이터 웨어하우스"},{"term":"Index","note":"— 한 건을 빨리 찾는 장치. 집계를 겨눈 열 저장과는 노리는 데가 다르다"},{"term":"구조화 데이터","note":"— 두 쪽이 모두 다루는, 미리 정해진 틀에 담긴 데이터"}]},{"id":"db--orm","term":"ORM","reading":"Object-Relational Mapping","category":"데이터베이스","summary":"ORM은 **DB 테이블을 프로그램의 객체처럼 다루게 해주는 계층**이다.","aliases":["orm","object-relational mapping"],"related":[{"term":"SQL","note":"— ORM이 대신 써주는 것. 결국 DB로 가는 건 이것이다"},{"term":"DB","note":"— ORM이 객체로 감싸는 대상"},{"term":"Transaction","note":"— ORM 이 함께 감싸주는 또 하나의 DB 개념"},{"term":"Index","note":"— ORM이 만든 쿼리가 느릴 때 먼저 보는 곳"}]},{"id":"db--optimistic-vs-pessimistic-lock","term":"Optimistic vs Pessimistic Lock","reading":"낙관적 잠금과 비관적 잠금","category":"데이터베이스","summary":"낙관적·비관적 잠금은 **충돌을 나중에 잡을지 미리 막을지 가르는 두 방식**이다.","aliases":["optimistic vs pessimistic lock","낙관적 잠금과 비관적 잠금","optimistic","pessimistic lock"],"related":[{"term":"MVCC","note":"— 읽기와 쓰기의 다툼은 없애 주지만 쓰기끼리의 다툼은 여기로 넘긴다"},{"term":"Isolation Level","note":"— 무엇까지 자동으로 막아줄지 정하는 눈금"},{"term":"Deadlock","note":"— 비관적으로 잠글 때 순서가 엇갈리면 빠지는 함정"},{"term":"Distributed Lock","note":"— 한 저장소 안이 아니라 여러 대에 걸쳐 잠글 때 쓰는 쪽"},{"term":"Transaction","note":"— 잠금이 언제 풀리는지를 정하는 경계"}]},{"id":"db--oracle-exadata","term":"Oracle Exadata","reading":"엑사데이타","category":"데이터베이스","summary":"Oracle Exadata는 **오라클 DB 만 돌리려고 만든 전용 장비**다.","aliases":["oracle exadata","엑사데이타"],"related":[{"term":"DB","note":"— Exadata 가 돌리려고 만들어진 대상"},{"term":"SQL","note":"— 저장 쪽에서 미리 거는 조건이 여기서 나온다"},{"term":"Index","note":"— 훑는 양을 줄이는 다른 방법. 잘 걸리면 전용 장비가 덜 필요하다"},{"term":"Bare Metal","note":"— 가상화 없이 물리 장비를 그대로 쓰는 방식"}]},{"id":"db--partitioning","term":"Partitioning","reading":"파티셔닝","category":"데이터베이스","summary":"Partitioning은 **한 테이블을 여러 조각으로 쪼개 두고 하나처럼 쓰는 것**이다.","aliases":["partitioning","파티셔닝"],"related":[{"term":"Sharding","note":"— 서버를 넘어 나누는 쪽. 파티셔닝은 한 데이터베이스 안에서 나눈다"},{"term":"Index","note":"— 파티셔닝이 인덱스의 위층을 대신해 주는 관계"},{"term":"DB","note":"— 한 테이블의 파티션이 모두 함께 있어야 하는 단위"},{"term":"SQL","note":"— 파티션 경계와 조회 조건을 적는 언어"}]},{"id":"db--point-in-time-recovery","term":"Point-in-Time Recovery","reading":"시점 복구","category":"데이터베이스","summary":"Point-in-Time Recovery 는 **원하는 시각의 상태로 되돌리는 복구 방식**이다.","aliases":["point-in-time recovery","시점 복구"],"related":[{"term":"WAL","note":"— 되감을 때 다시 실행되는 그 기록"},{"term":"Replication","note":"— 기계 고장은 막지만 잘못된 명령은 그대로 따라 하는 쪽"},{"term":"Disaster Recovery","note":"— 어디까지 잃어도 되는지를 정하는 더 넓은 계획"},{"term":"Transaction","note":"— 재생을 어디서 멈춰도 일관된 상태가 되는 근거"}]},{"id":"db--primary-key-foreign-key","term":"Primary Key & Foreign Key","reading":"기본키와 외래키","category":"데이터베이스","summary":"기본키는 행의 신분증이고, 외래키는 그 신분증을 **가리키는 손가락**이다.","aliases":["primary key & foreign key","기본키와 외래키","primary key","foreign key"],"related":[{"term":"DB","note":"— 이 두 키가 붙는 표들이 사는 곳"},{"term":"SQL","note":"— 키를 선언하고 어기는 값을 거절하게 만드는 언어"},{"term":"Index","note":"— 기본키를 만들면 자동으로 함께 생기는 것"},{"term":"JOIN","note":"— 외래키가 가리키는 방향을 따라 표를 다시 붙이는 일"},{"term":"Transaction","note":"— 부모와 자식을 함께 고치는 일을 한 덩어리로 묶는 단위"}]},{"id":"db--provisioned-vs-on-demand-capacity","term":"Provisioned vs On-Demand Capacity","reading":"미리 잡는 용량과 쓴 만큼","category":"데이터베이스","summary":"용량 방식은 **처리량을 미리 사 둘지 쓴 만큼 낼지 가르는 두 갈래**다.","aliases":["provisioned vs on-demand capacity","미리 잡는 용량과 쓴 만큼","provisioned","on-demand capacity"],"related":[{"term":"Serverless","note":"— 용량을 안 적는 쪽을 부르는 더 넓은 이름"},{"term":"Reserved Instance","note":"— 미리 약속하고 더 싸게 사는, 같은 결의 다른 자리"},{"term":"FinOps","note":"— 이 선택을 한 번이 아니라 주기적으로 다시 재는 활동"},{"term":"Auto Scaling","note":"— 미리 잡는 쪽에서 그 값을 사람 대신 움직여 주는 장치"},{"term":"Distributed SQL Database","note":"— 용량 고르기 자체를 없앤 쪽의 관리형 DB"}]},{"id":"db--query","term":"Query","reading":"쿼리","category":"데이터베이스","summary":"Query는 **저장된 데이터에서 원하는 것을 꺼내오라는 명령**이다.","aliases":["query","쿼리"],"related":[{"term":"SQL","note":"— 쿼리를 적는 가장 널리 쓰이는 말. 쿼리와 같은 말은 아니다"},{"term":"URL","note":"— 물음표 뒤가 쿼리 스트링으로 불리는 자리"},{"term":"Key-Value Store","note":"— 쿼리 대신 열쇠 하나로 꺼내는 쪽"},{"term":"Index","note":"— 같은 쿼리를 훨씬 덜 읽고 답하게 하는 장치"},{"term":"DB","note":"— 쿼리를 받아 답하는 상대"}]},{"id":"db--query-plan","term":"Query Plan","reading":"쿼리 실행 계획","category":"데이터베이스","summary":"Query Plan 은 **DB 가 이 질문을 어떻게 풀지 미리 고른 순서**다.","aliases":["query plan","쿼리 실행 계획"],"related":[{"term":"Index","note":"— 계획이 쓸지 말지 고르는 후보"},{"term":"B-Tree","note":"— 그 인덱스가 실제로 취하는 모양"},{"term":"SQL","note":"— 무엇을 원하는지만 적고 어떻게는 안 적는 언어"},{"term":"DB","note":"— 계획을 세우고 그대로 실행하는 쪽"}]},{"id":"db--redis","term":"Redis","reading":"","category":"데이터베이스","summary":"Redis는 **데이터를 디스크가 아니라 메모리에 두는 저장소**다.","aliases":["redis"],"related":[{"term":"Cache","note":"— Redis 가 가장 많이 놓이는 자리"},{"term":"Session","note":"— 여러 서버가 같이 봐야 하는 대표적인 값"},{"term":"TTL","note":"— 열쇠가 얼마나 살아 있을지 정하는 값"},{"term":"DB","note":"— 원본이 있는 곳. Redis 는 그 앞에 선다"},{"term":"NoSQL","note":"— 표와 질의문 없이 값을 다루는 계열"}]},{"id":"db--replication","term":"Replication","reading":"복제","category":"데이터베이스","summary":"Replication은 **같은 데이터를 여러 서버에 복사해 두는 것**이다.","aliases":["replication","복제"],"related":[{"term":"Sharding","note":"— 데이터를 나눠 담는 쪽. 복제는 같은 것을 여러 벌 두는 반대 방향이다"},{"term":"DB","note":"— 복제가 여러 대로 늘리는 대상"},{"term":"Load Balancing","note":"— 읽기 요청을 복제본 여러 대에 나눠 보내는 장치"},{"term":"Transaction","note":"— 동기 복제가 커밋 순간에 붙들어 두는 단위"}]},{"id":"db--sql","term":"SQL","reading":"Structured Query Language","category":"데이터베이스","summary":"SQL은 **표에 담긴 데이터를 다루는 질의 언어**다.","aliases":["sql","structured query language"],"related":[{"term":"DB","note":"— SQL로 말을 거는 대상"},{"term":"Index","note":"— 데이터베이스가 찾는 방법을 정할 때 쓰는 장치"},{"term":"SQL Injection","note":"— 사용자 입력이 질의의 일부가 될 때 생기는 공격"},{"term":"Transaction","note":"— 여러 문장을 한 덩어리로 묶어 함께 되돌리는 단위"},{"term":"NoSQL","note":"— 표와 SQL을 쓰지 않는 쪽"}]},{"id":"db--schema-evolution","term":"Schema Evolution","reading":"스키마 진화","category":"데이터베이스","summary":"Schema Evolution은 **옛 기록을 그대로 둔 채 모양을 바꾸는 일**이다.","aliases":["schema evolution","스키마 진화"],"related":[{"term":"Schema Registry","note":"— 이 규칙을 사람 대신 등록 때 검사해 주는 곳"},{"term":"Data Contract","note":"— 어디까지 바꿔도 되는지를 미리 문서로 못 박아 두는 쪽"},{"term":"Apache Iceberg","note":"— 파일을 하나도 안 건드리고 이 변경을 해내는 표 규격"},{"term":"Protocol Buffers","note":"— 이름이 아니라 번호로 짝을 짓는 쪽의 대표 규격"},{"term":"Migration","note":"— 쌓인 것을 실제로 다시 쓰는 쪽. 진화는 그 일을 피하려는 쪽이다"}]},{"id":"db--schema-registry","term":"Schema Registry","reading":"스키마 등록소","category":"데이터베이스","summary":"Schema Registry는 **모양을 등록해 두고 번호로 부르게 하는 곳**이다.","aliases":["schema registry","스키마 등록소"],"related":[{"term":"Schema Evolution","note":"— 등록할 때 검사하는 그 규칙 자체"},{"term":"Message Queue","note":"— 번호 붙은 기록이 실제로 흘러가는 자리"},{"term":"Serialization","note":"— 값을 바이트로 바꾸는 그 지점에 등록소가 끼어든다"},{"term":"Protocol Buffers","note":"— 등록소가 받아 주는 대표 모양 규격 중 하나"},{"term":"Data Contract","note":"— 모양 너머의 약속(품질·기한·책임)까지 적어 두는 쪽"}]},{"id":"db--snowflake","term":"Snowflake","reading":"","category":"데이터베이스","summary":"Snowflake는 **저장과 계산을 떼어놓은 클라우드 데이터 웨어하우스**다.","aliases":["snowflake"],"related":[{"term":"DB","note":"— Snowflake가 속한 큰 갈래"},{"term":"SQL","note":"— Snowflake에 묻는 언어"},{"term":"S3","note":"— 저장소 층이 실제로 쓰는 클라우드 저장소의 예"},{"term":"Cloud","note":"— 저장과 계산을 떼어놓는 것이 가능해진 배경"},{"term":"Auto Scaling","note":"— 웨어하우스를 자동으로 늘렸다 줄이는 것과 같은 발상"}]},{"id":"db--star-schema","term":"Star Schema","reading":"별 모양 스키마","category":"데이터베이스","summary":"Star Schema는 **사건 표 하나에 설명 표들을 둘러 붙인 짜임**이다.","aliases":["star schema","별 모양 스키마"],"related":[{"term":"Data Warehouse","note":"— 이 짜임이 주로 서는 자리"},{"term":"Denormalization","note":"— 차원 표를 일부러 펴 두는 그 판단"},{"term":"Normalization","note":"— 사실 표가 따르는 원칙. 차원 표에서까지 끝까지 밀면 별이 눈꽃이 된다"},{"term":"OLTP vs OLAP","note":"— 넣기 위주와 갈라 보기 위주의 갈림"},{"term":"JOIN","note":"— 가운데와 둘레를 이어 붙이는 연산"}]},{"id":"db--stored-procedure","term":"Stored Procedure","reading":"저장 프로시저","category":"데이터베이스","summary":"Stored Procedure는 **SQL 여러 줄을 DB 안에 이름 붙여 저장한 것**이다.","aliases":["stored procedure","저장 프로시저"],"related":[{"term":"SQL","note":"— 프로시저 안에 담기는 문장 그 자체"},{"term":"DB","note":"— 프로시저 정의가 저장되는 곳"},{"term":"Transaction","note":"— 프로시저가 실행 중에 커밋·롤백할 수 있는 단위"},{"term":"ORM","note":"— 같은 SQL 을 앱 쪽에 두는 반대 방향의 선택"}]},{"id":"db--time-series-database","term":"Time Series Database","reading":"시계열 데이터베이스","category":"데이터베이스","summary":"Time Series Database는 **시각이 찍힌 값을 시각 순으로 쌓는** 저장소다.","aliases":["time series database","시계열 데이터베이스"],"related":[{"term":"Prometheus","note":"— 이 창고를 품고 지표를 긁어 모으는 대표 도구"},{"term":"Metric","note":"— 여기에 쌓이는 값의 정체"},{"term":"WAL","note":"— 덩이로 굽기 전에 먼저 적어 두는 그 기록"},{"term":"Partitioning","note":"— 시각으로 잘라 두는 일이 여기서는 기본값이다"},{"term":"OLTP vs OLAP","note":"— 낱건을 고치는 쪽과 모아 보는 쪽. 이 창고는 뒤쪽에 가깝다"}]},{"id":"db--transaction","term":"Transaction","reading":"트랜잭션","category":"데이터베이스","summary":"Transaction은 **다 되거나 아예 안 되게 묶는 작업 단위**다.","aliases":["transaction","트랜잭션"],"related":[{"term":"SQL","note":"— 트랜잭션을 여닫는 명령이 속한 언어"},{"term":"DB","note":"— 트랜잭션이 지켜주는 대상"},{"term":"Concurrency","note":"— 여러 트랜잭션이 겹칠 때 생기는 문제의 배경"},{"term":"NoSQL","note":"— 트랜잭션 보장을 일부 내주고 확장을 택한 쪽"}]},{"id":"db--transparent-data-encryption","term":"Transparent Data Encryption","reading":"저장할 때 통째로 잠그기","category":"데이터베이스","summary":"TDE 는 **앱을 안 고치고 저장된 파일을 통째로 잠그는 기능**이다.","aliases":["transparent data encryption","저장할 때 통째로 잠그기"],"related":[{"term":"Encryption","note":"— 잠그는 일 자체. TDE 는 그걸 저장 자리에만 자동으로 건 것"},{"term":"Secret Management","note":"— 보호자 열쇠를 어디에 두고 누가 돌릴지 정하는 자리"},{"term":"PII","note":"— 이 잠금을 요구하게 만드는 대표적인 내용물"},{"term":"Shared Responsibility Model","note":"— 열쇠를 클라우드가 쥘지 내가 쥘지 가르는 경계"},{"term":"Point-in-Time Recovery","note":"— 백업과 로그가 함께 잠기므로 같이 봐야 하는 자리"}]},{"id":"db--vacuum","term":"VACUUM","reading":"배큠","category":"데이터베이스","summary":"VACUUM 은 **죽은 줄을 걷어 자리를 되쓰게 하는 청소 작업**이다.","aliases":["vacuum","배큠"],"related":[{"term":"MVCC","note":"— 죽은 줄이 생기는 이유. 이 청소는 그 구조의 뒷면이다"},{"term":"Transaction","note":"— 오래 열려 있으면 청소를 막아 세우는 쪽"},{"term":"Index","note":"— 죽은 줄이 남으면 함께 부풀고 함께 느려진다"},{"term":"LSM Tree","note":"— 낡은 판을 뒤에서 걷어낸다는 점에서 합치기가 같은 일을 한다"},{"term":"Query Plan","note":"— 청소와 함께 갱신되는 통계가 이것을 좌우한다"}]},{"id":"db--view-materialized-view","term":"View & Materialized View","reading":"뷰와 구체화 뷰","category":"데이터베이스","summary":"뷰는 **저장된 질문**이고, 구체화 뷰는 그 질문의 저장된 답이다.","aliases":["view & materialized view","뷰와 구체화 뷰","view","materialized view"],"related":[{"term":"SQL","note":"— 뷰의 정체인 질의를 적는 언어"},{"term":"JOIN","note":"— 뷰로 감싸 이름을 붙이게 되는 복잡한 조회의 대부분"},{"term":"Cache","note":"— 답을 저장하고 낡음을 감당하는, 구체화 뷰와 같은 거래"},{"term":"Index","note":"— SQL Server 에서 뷰를 구체화시키는 수단이고, 안전한 갱신의 조건"},{"term":"DB","note":"— 뷰와 구체화 뷰가 얹히는 원본 표들이 있는 곳"}]},{"id":"db--wal","term":"WAL","reading":"Write-Ahead Log","category":"데이터베이스","summary":"WAL 은 **고칠 내용을 먼저 적어두는 기록 방식**이다.","aliases":["wal","write-ahead log"],"related":[{"term":"Transaction","note":"— 커밋과 롤백이 이 기록 위에서 확정된다"},{"term":"DB","note":"— WAL 이 장애에서 지켜주는 저장소"},{"term":"Index","note":"— 표와 함께 나중에 따라 고쳐지는 데이터 파일 쪽"},{"term":"Logging","note":"— 사람이 읽는 기록과 복구용 기록은 목적이 다르다"}]},{"id":"db--watermark","term":"Watermark","reading":"워터마크","category":"데이터베이스","summary":"워터마크는 **여기까지는 다 들어왔다고 선언하는 시각 표시**다.","aliases":["watermark","워터마크"],"related":[{"term":"Windowing","note":"— 이 선이 닫아 주는 칸 그 자체"},{"term":"Event Time vs Processing Time","note":"— 이 선이 재는 것은 앞쪽 시계다"},{"term":"Exactly-Once Semantics","note":"— 다시 돌려도 같은 답이 나오게 하는 짝"},{"term":"Eventual Consistency","note":"— 늦게 와도 결국 맞춰진다는 쪽과 견줘 볼 자리"}]},{"id":"db--window-function","term":"Window Function","reading":"윈도 함수","category":"데이터베이스","summary":"Window Function은 **줄을 남겨 둔 채로 이웃 줄까지 보고 계산하는 함수**다.","aliases":["window function","윈도 함수"],"related":[{"term":"SQL","note":"— 창 계산을 적는 언어. `OVER` 절이 이 문법의 일부다"},{"term":"Query Plan","note":"— 창 계산이 거르기 뒤에 도는 것이 계획에 단계로 찍힌다"},{"term":"JOIN","note":"— 이웃 줄을 보려고 같은 표를 한 번 더 붙이던 옛 방법"},{"term":"Denormalization","note":"— 이웃을 볼 필요가 없게 미리 계산해 칸에 넣어 두는 다른 해법"}]},{"id":"db--windowing","term":"Windowing","reading":"윈도잉","category":"데이터베이스","summary":"윈도잉은 **끝없이 흐르는 것을 시간 칸으로 잘라 세는 일**이다.","aliases":["windowing","윈도잉"],"related":[{"term":"Watermark","note":"— 이 칸을 언제 닫아도 되는지 알려 주는 선"},{"term":"Event Time vs Processing Time","note":"— 어느 시계로 칸을 자를지 고르는 자리"},{"term":"Partitioning","note":"— 저장 쪽에서 같은 일을 하는 사촌. 시간으로 잘라 둔다"},{"term":"ETL","note":"— 배치는 하루치를 한 칸으로 자른 것과 같다"},{"term":"Window Function","note":"— 이름은 닮았지만 다른 것. 저쪽은 이미 쌓인 표에서 이웃 줄을 내다보는 계산이다"}]},{"id":"db--term-357e8f82","term":"구조화 데이터","reading":"Structured Data","category":"데이터베이스","summary":"구조화 데이터는 **모양을 미리 정해두고 담은 데이터**다.","aliases":["구조화 데이터","structured data"],"related":[{"term":"DB","note":"— 구조화 데이터를 담아두고 관리하는 곳"},{"term":"SQL","note":"— 구조화 데이터에 조건을 걸어 묻는 언어"},{"term":"JSON","note":"— 이름표는 있고 형식은 느슨한 반구조화의 대표"},{"term":"NoSQL","note":"— 표 모양을 강제하지 않는 쪽을 택한 저장소"},{"term":"Index","note":"— 열이 정해져 있어서 붙일 수 있는 검색 보조 장치"}]},{"id":"db--term-c10fd790","term":"인덱스","reading":"Database Index","category":"데이터베이스","summary":"인덱스는 **찾을 값을 미리 정렬해 따로 만들어둔 목록**이다.","aliases":["인덱스","database index","index"],"related":[{"term":"DB","note":"— 인덱스가 놓이는 자리"},{"term":"SQL","note":"— 인덱스를 만들고 쓰게 되는 질의 언어"},{"term":"Big O 표기법","note":"— 훑기와 인덱스 탐색의 차이를 재는 방식"},{"term":"자료구조","note":"— 인덱스가 쓰는 트리도 여기 속한다"},{"term":"Cache","note":"— 같은 결과를 다시 안 만드는 다른 방향의 해법"}]}]},{"id":"arch","name":"아키텍처 패턴","blurb":"규모가 커질 때 쓰는 구조","terms":[{"id":"arch--api","term":"API","reading":"Application Programming Interface","category":"아키텍처 패턴","summary":"API는 **다른 프로그램의 기능을 빌려 쓰는 창구**다.","aliases":["api","application programming interface"],"related":[{"term":"REST","note":"— 주소를 자원 이름으로 쓰는 대표적인 API 설계 방식"},{"term":"HTTP","note":"— 웹 API의 요청과 응답을 실어 나르는 규약"},{"term":"JSON","note":"— API가 주고받는 값을 담는 형식"},{"term":"GraphQL","note":"— 필요한 필드만 골라 받는 다른 방식의 API"},{"term":"API Gateway","note":"— 여러 API 앞에 서서 인증과 제한을 대신 맡는 자리"}]},{"id":"arch--api-gateway","term":"API Gateway","reading":"API 게이트웨이","category":"아키텍처 패턴","summary":"API Gateway는 **여러 서버로 가는 요청을 한 문에서 받는 서버**다.","aliases":["api gateway","api 게이트웨이"],"related":[{"term":"Load Balancer","note":"— 같은 서버 여럿에 나누는 쪽. 게이트웨이는 다른 서비스로 보낸다"},{"term":"Reverse Proxy","note":"— 앞에서 대신 받는다는 점이 같다. 게이트웨이는 거기에 정책이 붙은 것"},{"term":"Rate Limiting","note":"— 게이트웨이가 주로 맡는 대표적인 일"},{"term":"Monolith vs Microservices","note":"— 게이트웨이가 필요해지는 구조"}]},{"id":"arch--api-2","term":"API 외부 공개","reading":"로컬 API 를 남이 쓰게 하기","category":"아키텍처 패턴","summary":"API 외부 공개는 **내 컴퓨터에만 있던 API 를 인터넷에서 부를 수 있게 하는 일**이다.","aliases":["api 외부 공개","로컬 api 를 남이 쓰게 하기"],"related":[{"term":"HTTPS","note":"— 공개한 API 가 오가는 내용을 가리는 층"},{"term":"API Gateway","note":"— 공개 지점 앞에서 인증과 호출 제한을 맡는다"},{"term":"DNS","note":"— IP 대신 도메인으로 찾아오게 해주는 것"},{"term":"Rate Limiting","note":"— 공개한 뒤 한 사람이 얼마나 부를지 정하는 장치"},{"term":"Load Balancer","note":"— 뒤에 서버를 여러 대 두고 나눠 받을 때"}]},{"id":"arch--aws-bedrock","term":"AWS Bedrock","reading":"","category":"아키텍처 패턴","summary":"Bedrock은 **여러 회사의 AI 모델을 한 API로 부르는 AWS 서비스**다.","aliases":["aws bedrock","bedrock"],"related":[{"term":"LLM","note":"— Bedrock이 불러주는 모델들이 여기에 해당한다"},{"term":"AWS","note":"— Bedrock이 올라가 있는 플랫폼"},{"term":"API","note":"— 모델을 부르는 창구의 형태"},{"term":"VPC","note":"— 통신을 인터넷 밖으로 내보내지 않게 가두는 망"}]},{"id":"arch--active-active-vs-active-passive","term":"Active-Active vs Active-Passive","reading":"둘 다 일하기와 하나는 대기","category":"아키텍처 패턴","summary":"둘은 **여벌을 같이 굴리느냐 세워 두느냐의 갈림**이다.","aliases":["active-active vs active-passive","둘 다 일하기와 하나는 대기","active-active","active-passive"],"related":[{"term":"High Availability","note":"— 이 갈림이 사려는 목표 그 자체"},{"term":"Disaster Recovery","note":"— 지역이 통째로 죽었을 때를 다루는 상위 계획"},{"term":"Multi-Region","note":"— 여벌을 어느 지역에 둘지를 정하는 자리"},{"term":"Load Balancer","note":"— 어느 쪽으로 보낼지를 실제로 실행하는 앞단"},{"term":"Health Check","note":"— 살아 있는 쪽을 가려내 전환을 당기는 신호"}]},{"id":"arch--auto-scaling","term":"Auto Scaling","reading":"오토 스케일링","category":"아키텍처 패턴","summary":"Auto Scaling은 **부하에 맞춰 서버 대수를 자동으로 조절하는 기능**이다.","aliases":["auto scaling","오토 스케일링"],"related":[{"term":"Load Balancing","note":"— 늘어난 서버에 요청을 나눠주는 짝. 없으면 늘려도 안 쓰인다"},{"term":"EC2","note":"— 늘리고 줄이는 대상이 되는 서버 그 자체"},{"term":"Kubernetes","note":"— 같은 일을 컨테이너 단위로 한다"},{"term":"Latency","note":"— CPU 말고 응답 시간을 기준으로 삼을 때 보는 값"}]},{"id":"arch--bff","term":"BFF","reading":"Backend for Frontend","category":"아키텍처 패턴","summary":"BFF는 **화면 종류마다 따로 두는 전용 백엔드**다.","aliases":["bff","backend for frontend"],"related":[{"term":"API Gateway","note":"— 앞에 서서 공통 일을 맡는 관문. 전용 뒤쪽은 그 뒤에서 화면별 일만 한다"},{"term":"Backend","note":"— 나누기 전의 그 공용 뒤쪽"},{"term":"GraphQL","note":"— 화면이 필요한 것만 골라 묻게 해서 이 층을 대신하기도 한다"},{"term":"Monolith vs Microservices","note":"— 뒤쪽이 여러 서비스로 갈라지면서 이 층이 필요해졌다"},{"term":"Rate Limiting","note":"— 전용 뒤쪽에 넣지 말고 관문에 두라고 하는 대표적인 공통 기능"}]},{"id":"arch--back-pressure","term":"Back Pressure","reading":"배압","category":"아키텍처 패턴","summary":"Back Pressure는 **받는 쪽이 느리면 보내는 쪽을 늦추는 신호**다.","aliases":["back pressure","배압"],"related":[{"term":"Message Queue","note":"— 넘치는 양을 줄로 받아 두는 자리. 배압은 그 줄이 자라기만 할 때 필요하다"},{"term":"Rate Limiting","note":"— 들어오는 양을 앞에서 자른다. 배압은 뒤가 느리다는 사실을 앞으로 전한다"},{"term":"Circuit Breaker","note":"— 상대가 죽었을 때 끊는다. 배압은 상대가 느릴 때 늦춘다"},{"term":"Latency","note":"— 배압이 걸리면 처리량 대신 이쪽이 늘어난다"},{"term":"Auto Scaling","note":"— 느린 쪽을 늘려 배압을 푸는 다른 길"}]},{"id":"arch--bulkhead","term":"Bulkhead","reading":"격벽 패턴","category":"아키텍처 패턴","summary":"Bulkhead는 **자원을 칸칸이 나눠 고장을 한 칸에 가두는 설계**다.","aliases":["bulkhead","격벽 패턴"],"related":[{"term":"Circuit Breaker","note":"— 죽은 곳을 그만 부르는 장치. 격벽은 부르다 물린 자원을 미리 갈라 둔다"},{"term":"Rate Limiting","note":"— 한 칸이 쓸 수 있는 양의 상한을 실제로 매기는 장치"},{"term":"Sharding","note":"— 자료를 조각내는 일. 셀은 그 조각에 처리까지 통째로 딸려 나눈 것이다"},{"term":"Auto Scaling","note":"— 칸마다 따로 늘릴 수 있어 칸별로 규모를 맞춘다"},{"term":"Monolith vs Microservices","note":"— 서비스를 나눠도 자원을 같이 쓰면 그건 벽이 아니다"}]},{"id":"arch--cqrs","term":"CQRS","reading":"Command Query Responsibility Segregation","category":"아키텍처 패턴","summary":"CQRS는 **읽기와 쓰기를 서로 다른 모델로 가르는 설계**다.","aliases":["cqrs","command query responsibility segregation"],"related":[{"term":"Event Sourcing","note":"— 쓰기 쪽 원본을 사건 기록으로 두는 짝 패턴. 자주 같이 쓰지만 별개의 선택이다"},{"term":"Eventual Consistency","note":"— 저장소를 가른 대가로 받아들이는 성질"},{"term":"Materialized View","note":"— 읽기 모델이 미리 만들어 두는 조회용 표"},{"term":"Message Queue","note":"— 쓰기 쪽 소식을 읽기 쪽으로 나르는 길"}]},{"id":"arch--cache-aside-vs-write-through","term":"Cache Aside vs Write Through","reading":"캐시 쓰기 전략","category":"아키텍처 패턴","summary":"둘은 **캐시를 읽다가 채우느냐 쓰면서 채우느냐의 갈림**이다.","aliases":["cache aside vs write through","캐시 쓰기 전략","cache aside","write through"],"related":[{"term":"Caching","note":"— 이 두 전략이 고르는 대상 그 자체"},{"term":"Cache","note":"— 가까이 둔 사본. 여기에 무엇을 언제 넣을지가 이 갈림이다"},{"term":"Redis","note":"— 그 사본을 실제로 담아 두는 가장 흔한 자리"},{"term":"HTTP Caching","note":"— 같은 판단을 브라우저와 중간 서버에서 하는 쪽"},{"term":"Latency","note":"— 캐시를 붙이는 이유가 이걸 줄이는 것이다"}]},{"id":"arch--caching","term":"Caching","reading":"캐싱","category":"아키텍처 패턴","summary":"Caching은 **한 번 가져온 것을 가까이 두고 다시 쓰는 일**이다.","aliases":["caching","캐싱"],"related":[{"term":"Redis","note":"— 분산 캐시로 가장 많이 쓰이는 저장소"},{"term":"CDN","note":"— 같은 원리를 파일과 위치에 적용한 것"},{"term":"TTL","note":"— 캐시가 값을 얼마나 들고 있을지 정하는 값"},{"term":"Latency","note":"— 캐싱으로 줄이려는 대상이 바로 이 값이다"}]},{"id":"arch--circuit-breaker","term":"Circuit Breaker","reading":"서킷 브레이커","category":"아키텍처 패턴","summary":"Circuit Breaker는 **고장 난 서비스 호출을 잠시 끊어버리는 장치**다.","aliases":["circuit breaker","서킷 브레이커"],"related":[{"term":"Rate Limiting","note":"— 들어오는 쪽을 막는다. 차단기는 나가는 쪽을 막는다"},{"term":"Latency","note":"— 응답이 늦어지는 정도. 차단기가 실패로 셀지 정하는 기준"},{"term":"Monolith vs Microservices","note":"— 서비스를 나누면서 이 장치가 필요해졌다"},{"term":"Fallback","note":"— 차단기가 열렸을 때 대신 돌려줄 것"}]},{"id":"arch--clean-architecture","term":"Clean Architecture","reading":"클린 아키텍처","category":"아키텍처 패턴","summary":"클린 아키텍처는 **업무 규칙이 바깥 기술에 기대지 않게 뒤집은 구조**다.","aliases":["clean architecture","클린 아키텍처"],"related":[{"term":"DDD","note":"— 한가운데에 둘 업무 모델을 어디서 찾는가"},{"term":"Dependency","note":"— 방향을 뒤집는 대상이 바로 이것이다"},{"term":"MVC","note":"— 같은 관심사 분리를 화면 쪽에서 하는 다른 패턴"},{"term":"모놀리스 vs 마이크로서비스","note":"— 한 덩어리 안에서도 이 구조는 값을 한다"}]},{"id":"arch--consistent-hashing","term":"Consistent Hashing","reading":"일관된 해싱","category":"아키텍처 패턴","summary":"Consistent Hashing은 **서버가 바뀌어도 대부분의 키가 제자리에 남는 분배 방식**이다.","aliases":["consistent hashing","일관된 해싱"],"related":[{"term":"Sharding","note":"— 데이터를 여러 노드에 나눠 담는 일. 그 배치 규칙으로 쓰인다"},{"term":"Hash","note":"— 키와 서버를 원 위의 점으로 바꾸는 데 쓰는 계산"},{"term":"Cache","note":"— 서버를 늘릴 때 적중률을 지키려고 이 방식을 쓴다"},{"term":"Load Balancing","note":"— 요청을 나누는 일. 여기서는 데이터를 나눈다"},{"term":"Redis","note":"— 여러 대로 나눠 쓸 때 키 배치에 쓰이는 저장소"}]},{"id":"arch--ddd","term":"DDD","reading":"Domain-Driven Design","category":"아키텍처 패턴","summary":"DDD는 **업무 영역을 모델로 삼아 시스템 경계를 긋는 설계법**이다.","aliases":["ddd","domain-driven design"],"related":[{"term":"모놀리스 vs 마이크로서비스","note":"— 이 설계가 그어 주는 경계가 곧 서비스 경계다"},{"term":"Clean Architecture","note":"— 여기서 찾은 업무 모델을 코드 한가운데에 두는 구조"},{"term":"API","note":"— 경계 컨텍스트끼리 만나는 창구"},{"term":"이벤트 기반 아키텍처","note":"— 경계를 넘는 소식을 주고받는 방식"}]},{"id":"arch--dead-letter-queue","term":"Dead Letter Queue","reading":"실패 편지함","category":"아키텍처 패턴","summary":"Dead Letter Queue 는 **처리에 끝내 실패한 메시지를 옮겨 담는 줄**이다.","aliases":["dead letter queue","실패 편지함"],"related":[{"term":"Message Queue","note":"— 이 줄이 딸려 붙는 본체"},{"term":"Retry & Exponential Backoff","note":"— 실패 줄로 넘어가기 전까지 몇 번 더 해 보는 쪽"},{"term":"Idempotency","note":"— 같은 것을 여러 번 건네도 안전하게 만드는 성질"},{"term":"Back Pressure","note":"— 못 먹는 일감이 쌓일 때 앞을 늦추는 다른 대응"},{"term":"Alerting","note":"— 실패 줄이 늘어나는 것을 사람에게 알리는 자리"}]},{"id":"arch--distributed-lock","term":"Distributed Lock","reading":"분산 락","category":"아키텍처 패턴","summary":"분산 락은 서로 다른 기계의 작업을 **한 번에 하나만 들여보내는 자물쇠**다.","aliases":["distributed lock","분산 락"],"related":[{"term":"Leader Election","note":"— 이 자물쇠를 한 번 잡아 계속 쥐고 있는 쓰임"},{"term":"Race Condition","note":"— 자물쇠가 없을 때 벌어지는 일 그 자체"},{"term":"Idempotency Key","note":"— 막는 대신 \"두 번 해도 같다\" 로 푸는 다른 길"},{"term":"Redis","note":"— 이 패턴을 문서로 규정해 둔 저장소"},{"term":"Deadlock","note":"— 잠금이 안 풀린 채 굳는 반대편 사고"}]},{"id":"arch--error-budget","term":"Error Budget","reading":"에러 예산","category":"아키텍처 패턴","summary":"에러 예산은 **100% 에서 SLO 를 뺀 만큼 허락된 실패량**이다.","aliases":["error budget","에러 예산"],"related":[{"term":"SLA SLO SLI","note":"— 이 잔액을 계산해 내는 앞 단계"},{"term":"CI/CD","note":"— 잔액이 바닥났을 때 실제로 멈춰 세우는 자리"},{"term":"Logging","note":"— 잔액을 계산할 원자료가 쌓이는 곳"},{"term":"Circuit Breaker","note":"— 잔액이 한꺼번에 깎이는 것을 막아 주는 장치"}]},{"id":"arch--event-sourcing","term":"Event Sourcing","reading":"이벤트 소싱","category":"아키텍처 패턴","summary":"Event Sourcing은 **지금 값 대신 일어난 일을 쌓아 두는 저장 방식**이다.","aliases":["event sourcing","이벤트 소싱"],"related":[{"term":"CQRS","note":"— 읽기와 쓰기를 가르는 짝 패턴. 사건 기록이 쓰기 쪽 원본이 된다"},{"term":"WAL","note":"— 값을 고치기 전에 일어난 일을 먼저 적어 둔다는 생각이 같다"},{"term":"Audit Log","note":"— 따로 붙이던 기록이 저장 방식 자체가 된 셈이다"},{"term":"Saga","note":"— 여러 서비스에 걸친 일을 사건으로 이을 때 함께 쓴다"},{"term":"Eventual Consistency","note":"— 조회용 표가 늦게 따라오는 그 성질"}]},{"id":"arch--fault-tolerance","term":"Fault Tolerance","reading":"장애 허용성","category":"아키텍처 패턴","summary":"Fault Tolerance는 **부품이 고장 나도 전체는 계속 도는 성질**이다.","aliases":["fault tolerance","장애 허용성"],"related":[{"term":"Circuit Breaker","note":"— 번지는 길을 끊는 대표 장치"},{"term":"High Availability","note":"— 견딘 결과를 시간 비율로 재는 목표"},{"term":"Rate Limiting","note":"— 한 칸이 남의 몫까지 먹지 못하게 미리 눌러 두는 쪽"},{"term":"Fallback","note":"— 칸이 막혔을 때 대신 내놓을 것"},{"term":"Replication","note":"— 같은 것을 두 벌로 두는 가장 흔한 방법"}]},{"id":"arch--high-availability","term":"High Availability","reading":"고가용성","category":"아키텍처 패턴","summary":"High Availability는 **멈춘 시간을 약속한 한도 안으로 묶는 설계**다.","aliases":["high availability","고가용성"],"related":[{"term":"Availability Zone","note":"— 두 벌을 어디에 나눠 둘지의 기본 단위"},{"term":"Load Balancing","note":"— 여러 대 중 살아 있는 쪽으로만 보내 주는 앞단"},{"term":"Fault Tolerance","note":"— 고장이 사용자에게 안 보이게 하는 쪽. 가용성은 그 결과를 시간 비율로 잰다"},{"term":"Replication","note":"— 데이터 쪽의 두 벌. 앞단만 늘려도 이게 없으면 넘길 곳이 없다"},{"term":"Latency","note":"— 살아는 있는데 느린 상태. 이걸 정지로 셀지 목표에 적어 두어야 한다"}]},{"id":"arch--idempotency","term":"Idempotency","reading":"멱등성","category":"아키텍처 패턴","summary":"Idempotency는 **여러 번 해도 한 번 한 것과 결과가 같은 성질**이다.","aliases":["idempotency","멱등성"],"related":[{"term":"Idempotency Key","note":"— 멱등이 아닌 요청을 멱등하게 만들어 붙이는 표"},{"term":"HTTP","note":"— 어떤 메서드가 멱등인지 규격으로 정해 둔 자리"},{"term":"Message Queue","note":"— 같은 메시지가 두 번 오는 대표적인 자리. 받는 쪽이 멱등해야 한다"},{"term":"Circuit Breaker","note":"— 재시도와 짝을 이루는 장치. 그 재시도의 전제가 이 성질이다"},{"term":"Transaction","note":"— 두 번 일어나는 것과 반만 일어나는 것은 서로 다른 사고다"}]},{"id":"arch--langgraph","term":"LangGraph","reading":"","category":"아키텍처 패턴","summary":"LangGraph는 **LLM 앱의 흐름을 그래프로 적어 실행하는 도구**다.","aliases":["langgraph"],"related":[{"term":"AI Agent","note":"— 되돌아가는 흐름이 필요한 대표적인 사용처"},{"term":"RAG","note":"— 검색 노드와 생성 노드를 잇는 형태로 자주 짠다"},{"term":"LLM","note":"— 노드 안에서 실제로 답을 만드는 쪽"},{"term":"Pipeline","note":"— 단계를 이어 붙인다는 점은 같고, 되돌아가는 길이 있다는 점이 다르다"}]},{"id":"arch--latency","term":"Latency","reading":"지연 시간","category":"아키텍처 패턴","summary":"Latency는 **요청을 보내고 응답이 올 때까지 걸리는 시간**이다.","aliases":["latency","지연 시간"],"related":[{"term":"CDN","note":"— 거리 때문에 생기는 지연을 줄이는 쪽"},{"term":"Caching","note":"— 같은 조회를 반복하며 쌓이는 지연을 없애는 쪽"},{"term":"Index","note":"— 데이터베이스 조회에서 늘어지는 시간을 줄이는 수단"},{"term":"Load Balancer","note":"— 지연이 아니라 처리량 쪽을 늘리는 장치"}]},{"id":"arch--leader-election","term":"Leader Election","reading":"리더 선출","category":"아키텍처 패턴","summary":"리더 선출은 같은 일을 하는 여러 대 중 **조율할 한 대만 정하는 방법**이다.","aliases":["leader election","리더 선출"],"related":[{"term":"Distributed Lock","note":"— 대표 자리를 잡는 데 쓰는 바로 그 도구"},{"term":"Kubernetes","note":"— 제어 평면 이중화에 이 방식을 쓰는 대표적인 예"},{"term":"Message Queue","note":"— 대표를 안 뽑고도 일이 한 번만 처리되게 하는 다른 길"},{"term":"Auto Scaling","note":"— 규모를 줄이다가 대표를 내려버릴 수 있는 자리"}]},{"id":"arch--load-balancing","term":"Load Balancing","reading":"로드 밸런싱","category":"아키텍처 패턴","summary":"Load Balancing은 **들어오는 요청을 여러 서버에 나눠 보내는 일**이다.","aliases":["load balancing","로드 밸런싱"],"related":[{"term":"Load Balancer","note":"— 그 일을 실제로 맡는 장치"},{"term":"Auto Scaling","note":"— 부하에 따라 뒤쪽 서버 대수를 자동으로 조절한다"},{"term":"Reverse Proxy","note":"— 앞에 서서 요청을 받는다는 점이 같다"},{"term":"Nginx","note":"— 밸런서로 자주 쓰이는 소프트웨어"},{"term":"Circuit Breaker","note":"— 나가는 호출을 끊는 쪽. 밸런서는 들어오는 쪽을 나눈다"}]},{"id":"arch--mvc","term":"MVC","reading":"Model View Controller","category":"아키텍처 패턴","summary":"MVC는 **앱을 모델·뷰·컨트롤러 셋으로 가르는 짜임새**다.","aliases":["mvc","model view controller"],"related":[{"term":"Clean Architecture","note":"— 셋으로 가른 다음에 층을 한 번 더 가르는 구조"},{"term":"Component","note":"— 화면을 더 잘게 나누는 요즘 방식"},{"term":"REST","note":"— 같은 컨트롤러가 화면 대신 응답을 내는 자리"},{"term":"Frontend","note":"— 뷰가 브라우저 쪽으로 통째로 옮겨간 형태"}]},{"id":"arch--message-queue","term":"Message Queue","reading":"메시지 큐","category":"아키텍처 패턴","summary":"Message Queue는 **할 일을 줄에 넣어두고 나중에 처리하게 하는 장치**다.","aliases":["message queue","메시지 큐"],"related":[{"term":"Pub-Sub","note":"— 한 메시지를 여러 곳이 받는 방식. 큐는 보통 한 곳이 받는다"},{"term":"Redis","note":"— 가벼운 큐로도 자주 쓰이는 저장소"},{"term":"Circuit Breaker","note":"— 큐가 완충한다면 차단기는 끊어낸다"},{"term":"Queue","note":"— 같은 개념을 프로그램 안의 자료구조로 쓴 것"}]},{"id":"arch--multi-tier-architecture","term":"Multi-Tier Architecture","reading":"여러 층 구조","category":"아키텍처 패턴","summary":"Multi-Tier Architecture 는 **앱을 화면·처리·저장 층으로 갈라 두는 짜임**이다.","aliases":["multi-tier architecture","여러 층 구조"],"related":[{"term":"Monolith vs Microservices","note":"— 층으로 가르는 것과 기능으로 쪼개는 것의 차이"},{"term":"Load Balancing","note":"— 층 앞에 서서 그 층만 여러 대로 늘려 주는 자리"},{"term":"MVC","note":"— 코드 안에서 같은 갈래를 짓는 더 작은 짜임"},{"term":"Clean Architecture","note":"— 의존 방향을 안쪽으로 못 박은 다른 층 규칙"},{"term":"Subnet","note":"— 층 경계를 망 위의 경계로 실제로 그리는 자리"}]},{"id":"arch--pipeline","term":"Pipeline","reading":"파이프라인","category":"아키텍처 패턴","summary":"Pipeline은 **작업을 단계로 나눠 차례로 흘려보내는 구조**다.","aliases":["pipeline","파이프라인"],"related":[{"term":"CI_CD","note":"— 빌드와 테스트, 배포를 파이프라인으로 묶은 것"},{"term":"Message Queue","note":"— 단계 사이에 일을 쌓아두고 넘길 때 쓴다"},{"term":"Cron Job","note":"— 데이터 파이프라인을 정해진 시각에 시작시킨다"},{"term":"Orchestrator","note":"— 여러 단계의 순서와 재실행을 맡는 쪽"}]},{"id":"arch--pub-sub","term":"Pub/Sub","reading":"발행-구독","category":"아키텍처 패턴","summary":"Pub/Sub은 **한 번 발행한 소식을 관심 있는 쪽이 각자 받아가는 방식**이다.","aliases":["pub/sub","발행-구독","pub-sub","pub","sub"],"related":[{"term":"Message Queue","note":"— 한 메시지를 한 곳이 가져가는 방식"},{"term":"Event-Driven Architecture","note":"— 이 방식을 바탕으로 삼는 설계"},{"term":"Webhook","note":"— 소식을 HTTP로 밀어주는 더 단순한 방식"},{"term":"Monolith vs Microservices","note":"— 서비스가 늘어날수록 이 방식이 필요해진다"}]},{"id":"arch--rate-limiting","term":"Rate Limiting","reading":"요청량 제한","category":"아키텍처 패턴","summary":"Rate Limiting은 **정해진 시간 안에 부를 수 있는 횟수를 막는 것**이다.","aliases":["rate limiting","요청량 제한"],"related":[{"term":"API Gateway","note":"— 요청량 제한이 주로 놓이는 자리"},{"term":"Circuit Breaker","note":"— 나가는 호출을 막는 쪽. 제한은 들어오는 쪽을 막는다"},{"term":"Redis","note":"— 여러 서버가 횟수를 함께 세는 데 쓰인다"},{"term":"Firewall","note":"— 그 앞단에서 아예 연결을 끊는 쪽"}]},{"id":"arch--retry-exponential-backoff","term":"Retry & Exponential Backoff","reading":"재시도와 지수 백오프","category":"아키텍처 패턴","summary":"이 짝은 **실패한 호출을 점점 길게 기다렸다 다시 거는 규칙**이다.","aliases":["retry & exponential backoff","재시도와 지수 백오프","retry","exponential backoff"],"related":[{"term":"Circuit Breaker","note":"— 다시 걸어도 안 되는 상대를 아예 그만 부르는 장치. 재시도와 짝으로 쓴다"},{"term":"Idempotency Key","note":"— 두 번 걸려도 한 번만 처리되게 만드는 열쇠"},{"term":"Rate Limiting","note":"— 상대가 요청량을 자를 때 돌아오는 그 거절이 재시도의 대표적인 신호다"},{"term":"Back Pressure","note":"— 상대가 느릴 때는 다시 거는 대신 보내는 속도를 늦춘다"},{"term":"Latency","note":"— 기다림을 늘리면 성공률은 오르고 이쪽은 길어진다"}]},{"id":"arch--sla-slo-sli","term":"SLA SLO SLI","reading":"서비스 수준 목표","category":"아키텍처 패턴","summary":"SLI·SLO·SLA 는 서비스 수준을 **재고 걸고 물어주는** 세 단계다.","aliases":["sla slo sli","서비스 수준 목표","sla","slo","sli"],"related":[{"term":"Error Budget","note":"— 목표에서 남는 여유분을 잔액으로 바꿔 쓰는 짝"},{"term":"Latency","note":"— SLI 로 자주 세우는 지표 하나"},{"term":"Availability Zone","note":"— 목표치를 올릴 때 쓰는 이중화 수단"},{"term":"Logging","note":"— 지표를 뽑아내는 원자료가 쌓이는 곳"},{"term":"Circuit Breaker","note":"— 목표를 못 지킬 때 피해 범위를 가두는 장치"}]},{"id":"arch--saga","term":"Saga","reading":"사가 패턴","category":"아키텍처 패턴","summary":"Saga는 **단계마다 되돌릴 방법을 짝지어 둔 분산 거래**다.","aliases":["saga","사가 패턴"],"related":[{"term":"Two-Phase Commit","note":"— 같은 문제를 보상 대신 잠금으로 푸는 반대편 답"},{"term":"Event-Driven Architecture","note":"— 단계를 사건으로 잇는 바탕"},{"term":"Transaction","note":"— 한 저장소 안에서는 그냥 받던 그 묶음"},{"term":"Eventual Consistency","note":"— 사가가 도는 동안 값이 어긋나 있는 성질"},{"term":"Message Queue","note":"— 단계 사이 소식을 나르는 길"}]},{"id":"arch--scalability","term":"Scalability","reading":"확장성","category":"아키텍처 패턴","summary":"Scalability는 **자원을 더하거나 빼서 일의 양에 맞추는 성질**이다.","aliases":["scalability","확장성"],"related":[{"term":"Auto Scaling","note":"— 이 성질을 규칙으로 자동화한 장치"},{"term":"Load Balancing","note":"— 늘린 대수에 일을 나눠 주는 앞단"},{"term":"Sharding","note":"— 저장소 쪽을 수평으로 늘리는 방법"},{"term":"Rate Limiting","note":"— 확장이 따라붙기 전까지 들어오는 양을 눌러 두는 쪽"},{"term":"High Availability","note":"— 늘린 대수가 장애까지 나눠 받게 되는 이웃 목표"}]},{"id":"arch--service-discovery","term":"Service Discovery","reading":"서비스 디스커버리","category":"아키텍처 패턴","summary":"Service Discovery는 **서비스가 지금 어디 있는지 찾아주는 장치**다.","aliases":["service discovery","서비스 디스커버리"],"related":[{"term":"Load Balancing","note":"— 찾아낸 주소가 여럿일 때 어디로 보낼지 고르는 쪽"},{"term":"API Gateway","note":"— 바깥 요청을 받아 안쪽 서비스를 찾아 넘기는 문"},{"term":"Monolith vs Microservices","note":"— 서비스를 잘게 나누면서 이 장치가 필요해졌다"},{"term":"Kubernetes","note":"— 컨테이너를 띄우며 등록과 해지를 대신해주는 쪽"}]},{"id":"arch--service-mesh","term":"Service Mesh","reading":"서비스 메시","category":"아키텍처 패턴","summary":"Service Mesh는 **서비스끼리의 통신을 앱 밖으로 꺼내 맡는 인프라 층**이다.","aliases":["service mesh","서비스 메시"],"related":[{"term":"Sidecar","note":"— 메시의 프록시가 실제로 서 있는 자리"},{"term":"mTLS","note":"— 메시가 코드 수정 없이 켜 주는 대표 기능"},{"term":"Kubernetes","note":"— 메시가 주로 얹히는 바닥"},{"term":"Circuit Breaker","note":"— 앱 대신 프록시가 걸어 주는 실패 관리 장치"},{"term":"API Gateway","note":"— 밖에서 들어오는 길목을 맡는 쪽. 메시는 안쪽 통신을 맡는다"}]},{"id":"arch--sharding","term":"Sharding","reading":"샤딩","category":"아키텍처 패턴","summary":"Sharding은 **하나의 데이터베이스를 여러 대로 쪼개 나눠 담는 것**이다.","aliases":["sharding","샤딩"],"related":[{"term":"Index","note":"— 샤딩 전에 먼저 시도해야 할 것"},{"term":"DB","note":"— 샤딩으로 나누는 대상"},{"term":"Hash","note":"— 데이터를 고르게 흩는 데 쓰이는 계산"},{"term":"NoSQL","note":"— 샤딩을 내장해 자동으로 처리해주는 경우가 많다"}]},{"id":"arch--sidecar","term":"Sidecar","reading":"사이드카","category":"아키텍처 패턴","summary":"Sidecar는 **본체 옆에 따로 띄워 수명을 같이하는 보조 부품**이다.","aliases":["sidecar","사이드카"],"related":[{"term":"Service Mesh","note":"— 서비스마다 이 옆칸을 붙여 만든 대표적인 결과물"},{"term":"Container","note":"— 옆칸을 담는 가장 흔한 그릇"},{"term":"Kubernetes","note":"— 본체와 옆칸을 한 파드에 함께 띄우는 대표 플랫폼"},{"term":"Logging","note":"— 옆칸이 가장 자주 넘겨받는 일"}]},{"id":"arch--stateless-workload","term":"Stateless Workload","reading":"상태를 안 쥔 일감","category":"아키텍처 패턴","summary":"Stateless Workload 는 **처리에 필요한 기억을 제 안에 두지 않는 일감**이다.","aliases":["stateless workload","상태를 안 쥔 일감"],"related":[{"term":"Twelve-Factor App","note":"— 이 원칙을 열두 항목 중 하나로 못 박은 원전"},{"term":"StatefulSet","note":"— 이름과 디스크를 붙들어야 하는 반대쪽 갈래"},{"term":"Auto Scaling","note":"— 무상태라서 비로소 성립하는 늘리고 줄이기"},{"term":"Rolling Update","note":"— 대를 하나씩 갈아 끼우는 배포. 무상태가 전제다"},{"term":"Load Balancer","note":"— \"아무 대나 된다\" 를 실제로 써먹는 앞단"}]},{"id":"arch--strangler-fig","term":"Strangler Fig","reading":"교살자 무화과","category":"아키텍처 패턴","summary":"Strangler Fig는 **옛 시스템을 한 조각씩 새 것으로 갈아 끼우는 이주 방식**이다.","aliases":["strangler fig","교살자 무화과"],"related":[{"term":"Monolith vs Microservices","note":"— 한 덩어리를 이 방식으로 조각내 옮긴다"},{"term":"API Gateway","note":"— 앞에 세우는 창구를 실제로 맡는 물건"},{"term":"Migration","note":"— 스키마를 한 걸음씩 바꿔 이력으로 쌓는 일. 테이블을 새 쪽으로 옮기는 단계가 그렇게 쌓인다"},{"term":"Feature Flag","note":"— 어느 요청을 새 쪽으로 보낼지 스위치로 정하는 다른 방법"}]},{"id":"arch--twelve-factor-app","term":"Twelve-Factor App","reading":"12요소 앱","category":"아키텍처 패턴","summary":"12요소 앱은 **어디에 올려도 똑같이 도는 앱을 만드는 열두 규칙**이다.","aliases":["twelve-factor app","12요소 앱"],"related":[{"term":"환경 변수","note":"— 셋째 항목이 설정을 두라고 한 바로 그 자리"},{"term":"CI/CD","note":"— 빌드·릴리스·실행을 갈라 두는 일을 실제로 하는 도구"},{"term":"Container","note":"— 의존성과 실행 환경을 통째로 굳혀 어디서나 같게 만드는 방법"},{"term":"Logging","note":"— 열한째 항목이 다루는 자리"}]},{"id":"arch--two-phase-commit","term":"Two-Phase Commit","reading":"2단계 커밋","category":"아키텍처 패턴","summary":"Two-Phase Commit은 **먼저 전원에게 묻고 그다음 확정하는 약속**이다.","aliases":["two-phase commit","2단계 커밋"],"related":[{"term":"Saga","note":"— 같은 문제를 잠금 대신 보상으로 푸는 반대편 답"},{"term":"Transaction","note":"— 한 저장소 안에서는 그냥 받던 그 보장"},{"term":"ACID","note":"— 두 단계 커밋이 여러 저장소로 넓히려는 그 네 글자"},{"term":"Isolation Level","note":"— 준비 상태가 쥐고 있는 잠금이 걸리는 자리"}]},{"id":"arch--trpc","term":"tRPC","reading":"","category":"아키텍처 패턴","summary":"tRPC는 **서버 함수의 타입을 클라이언트에 그대로 물려주는 도구**다.","aliases":["trpc"],"related":[{"term":"API","note":"— tRPC가 대신 서는 자리"},{"term":"GraphQL","note":"— 스키마를 따로 두고 타입을 맞추는 다른 방법"},{"term":"REST","note":"— 규약으로 주고받되 타입은 양쪽이 각자 적는 쪽"},{"term":"gRPC","note":"— 스키마 파일로 양쪽 코드를 만들어내는 RPC 방식"}]},{"id":"arch--vs","term":"모놀리스 vs 마이크로서비스","reading":"","category":"아키텍처 패턴","summary":"모놀리스와 마이크로서비스는 **기능을 한 덩어리로 둘지 쪼갤지**의 차이다.","aliases":["모놀리스 vs 마이크로서비스","monolith vs microservices","모놀리스","마이크로서비스"],"related":[{"term":"API Gateway","note":"— 나뉜 서비스들 앞에서 요청을 받아 나눠 보내는 자리"},{"term":"Circuit Breaker","note":"— 나눠도 장애가 번지지 않게 하려면 따로 붙여야 하는 장치"},{"term":"Docker","note":"— 서비스마다 다른 환경을 담아 옮기는 단위"},{"term":"Kubernetes","note":"— 서비스가 여러 개가 되면 배치와 확장을 맡는 자리"},{"term":"CI_CD","note":"— 서비스별로 따로 배포하려면 먼저 갖춰야 하는 것"}]},{"id":"arch--term-f4ea9317","term":"이벤트 기반 아키텍처","reading":"Event-Driven Architecture","category":"아키텍처 패턴","summary":"이벤트 기반 아키텍처는 **일어난 일을 알리기만 하고 넘어가는 구조**다.","aliases":["이벤트 기반 아키텍처","event-driven architecture"],"related":[{"term":"Message Queue","note":"— 사건을 받아 쌓아두는 자리. 이 구조의 가운데에 있다"},{"term":"Pub-Sub","note":"— 하나가 발행하고 여럿이 구독하는 기본 형태"},{"term":"Monolith vs Microservices","note":"— 서비스를 나누면서 이 구조가 필요해졌다"},{"term":"Webhook","note":"— 사건을 서비스 밖으로 알릴 때 쓰는 방식"},{"term":"Circuit Breaker","note":"— 직접 호출이 남은 구간에서 장애가 번지는 것을 막는다"}]}]},{"id":"sec","name":"보안 · 인증","blurb":"누구인지 확인하고 지키는 법","terms":[{"id":"sec--api-key","term":"API Key","reading":"API 키","category":"보안 · 인증","summary":"API Key는 **API를 부르는 쪽이 누구인지 알리는 문자열**이다.","aliases":["api key","api 키"],"related":[{"term":"Rate Limiting","note":"— Key 단위로 호출 횟수를 세서 거는 제한"},{"term":"JWT","note":"— 정보를 담아 스스로 검증되는 다른 방식의 인증 토큰"},{"term":"OAuth","note":"— 사용자를 대신해 제3자 앱에 권한을 주는 방식"},{"term":"API Gateway","note":"— Key 검사와 한도 확인을 한곳에 모아 두는 자리"},{"term":"HTTPS","note":"— Key가 오가는 통로를 가려주는 쪽"}]},{"id":"sec--api-token","term":"API Token","reading":"API 토큰","category":"보안 · 인증","summary":"API Token은 **비밀번호 대신 API 를 부를 때 쓰는 문자열**이다.","aliases":["api token","api 토큰"],"related":[{"term":"API Key","note":"— 거의 같은 역할. 권한 범위와 만료를 붙였는지가 갈림길이다"},{"term":"JWT","note":"— 토큰 안에 정보를 담아 서버가 조회 없이 검증하는 방식"},{"term":"OAuth","note":"— 사용자를 대신할 토큰을 안전하게 받아오는 절차"},{"term":"Refresh Token","note":"— 짧게 만료되는 토큰을 다시 발급받는 데 쓰는 짝"}]},{"id":"sec--access-review","term":"Access Review","reading":"권한 재점검","category":"보안 · 인증","summary":"Access Review는 **이미 준 권한을 주기마다 다시 묻는 절차**다.","aliases":["access review","권한 재점검"],"related":[{"term":"Least Privilege","note":"— 처음에 좁게 주는 원칙. 재점검은 그 뒤에 남은 것을 걷는다"},{"term":"IAM","note":"— 재점검이 들여다보는 사용자와 권한의 원장"},{"term":"RBAC","note":"— 역할 단위로 점검하면 볼 줄 수가 사람 수만큼 줄어든다"},{"term":"Audit Log","note":"— 누가 무엇을 승인했는지 남기는 자리"},{"term":"Break-Glass Account","note":"— 평소엔 잠가 두고 쓴 흔적만 점검하는 예외 계정"}]},{"id":"sec--anonymous-public-access","term":"Anonymous Public Access","reading":"누구나 열리는 공개 접근","category":"보안 · 인증","summary":"Anonymous Public Access는 **누가 왔는지 묻지 않고 내주는 설정**이다.","aliases":["anonymous public access","누구나 열리는 공개 접근"],"related":[{"term":"Least Privilege","note":"— 이 설정 하나로 가장 크게 깨지는 원칙"},{"term":"Organization Policy Guardrail","note":"— 계정 단위로 공개를 아예 못 켜게 막는 물건"},{"term":"Object Storage","note":"— 이 설정이 붙는 저장 방식 그 자체"},{"term":"Audit Log","note":"— 누가 가져갔는지가 여기에도 안 남는다는 것을 확인하는 자리"},{"term":"Zero Trust","note":"— \"어디서 왔든 매번 묻는다\" 는 원칙. 이 설정은 그 정반대다"}]},{"id":"sec--attribute-based-access-control","term":"Attribute-Based Access Control","reading":"속성으로 정하는 권한","category":"보안 · 인증","summary":"Attribute-Based Access Control은 **꼬리표끼리 맞는지 보고 허락하는 방식**이다.","aliases":["attribute-based access control","속성으로 정하는 권한"],"related":[{"term":"RBAC","note":"— 역할로 주는 밑바탕. 대체가 아니라 그 위에 얹힌다"},{"term":"Resource Tag","note":"— 자원 쪽 꼬리표를 실제로 다는 물건"},{"term":"IAM","note":"— 두 꼬리표를 견주는 판정이 벌어지는 자리"},{"term":"Least Privilege","note":"— 꼬리표로 좁혀서 다다르려는 목표"},{"term":"Conditional Access","note":"— 같은 조건 판정을 로그인 관문 쪽에서 하는 사촌"}]},{"id":"sec--audit-log","term":"Audit Log","reading":"감사 로그","category":"보안 · 인증","summary":"Audit Log는 **누가 무엇을 했는지 남기는 기록**이다.","aliases":["audit log","감사 로그"],"related":[{"term":"RBAC","note":"— 누가 무엇을 할 수 있는지 정하는 쪽. 감사 로그는 실제로 무엇을 했는지 남긴다"},{"term":"PII","note":"— 접근 기록을 반드시 남겨야 하는 정보"},{"term":"Logging","note":"— 일반 로그. 감사 로그는 그중 책임 추적을 목적으로 하는 갈래다"},{"term":"Guardrail","note":"— 위험한 동작을 막는 쪽. 막힌 시도도 감사 로그에 남는다"},{"term":"Escalation","note":"— 로그에서 이상을 찾은 다음 사람에게 넘기는 단계"}]},{"id":"sec--bastion-host","term":"Bastion Host","reading":"배스천 호스트","category":"보안 · 인증","summary":"Bastion Host는 **내부 서버로 들어가는 유일한 진입점 서버**다.","aliases":["bastion host","배스천 호스트"],"related":[{"term":"DMZ","note":"— 외부와 내부 사이에 두는 완충 구역. 배스천이 놓이는 자리"},{"term":"SSH","note":"— 배스천을 오가는 데 쓰는 접속 방식"},{"term":"Subnet","note":"— 내부 서버를 외부에서 안 보이게 가르는 단위"},{"term":"Audit Log","note":"— 배스천이 남기는 접속 기록"},{"term":"Zero Trust","note":"— 문 하나를 믿는 대신 매번 검증하자는 반대 방향의 접근"}]},{"id":"sec--break-glass-account","term":"Break-Glass Account","reading":"비상 시 깨는 유리 계정","category":"보안 · 인증","summary":"Break-Glass Account는 **평소엔 아무도 안 쓰는 비상용 관리자 계정**이다.","aliases":["break-glass account","비상 시 깨는 유리 계정"],"related":[{"term":"MFA","note":"— 이 계정에 거는 강한 로그인 수단. 평소 계정과 다른 것을 고른다"},{"term":"Least Privilege","note":"— 이 계정 하나만 예외가 되는 원칙"},{"term":"Audit Log","note":"— 깨진 유리 소리가 실제로 남는 자리"},{"term":"Conditional Access","note":"— 이 계정을 일부러 빼 두는 그 정책"},{"term":"Disaster Recovery","note":"— 같은 물음을 인프라 쪽에서 다루는 짝"}]},{"id":"sec--ca","term":"CA","reading":"Certificate Authority, 인증 기관","category":"보안 · 인증","summary":"CA는 **인증서에 서명해 서버 신원을 보증하는 기관**이다.","aliases":["ca","certificate authority, 인증 기관"],"related":[{"term":"Certificate","note":"— CA 가 서명해 내주는 그 파일"},{"term":"CSR","note":"— 발급을 신청할 때 내는 요청서"},{"term":"SSL_TLS","note":"— 이 인증서를 주고받으며 연결을 맺는 규약"},{"term":"HTTPS","note":"— 검증이 통과해야 자물쇠가 뜨는 자리"}]},{"id":"sec--csp","term":"CSP","reading":"Content Security Policy","category":"보안 · 인증","summary":"CSP는 **이 페이지가 무엇을 실어도 되는지 미리 정해 보내는 헤더**다.","aliases":["csp","content security policy"],"related":[{"term":"XSS","note":"— 이 정책이 피해를 줄이려는 바로 그 공격"},{"term":"Same-Origin Policy","note":"— 브라우저가 원래 갖고 있는 경계. 정책은 그 위에 더 조인다"},{"term":"HTTP","note":"— 정책이 실려 오는 응답 헤더의 자리"},{"term":"HSTS","note":"— 헤더 한 줄로 브라우저를 움직이는 같은 방식의 다른 예"}]},{"id":"sec--csrf","term":"CSRF","reading":"Cross-Site Request Forgery","category":"보안 · 인증","summary":"CSRF는 **로그인한 사용자의 브라우저로 몰래 요청을 보내는 공격**이다.","aliases":["csrf","cross-site request forgery"],"related":[{"term":"Cookie","note":"— 브라우저가 자동으로 붙여주는 성질이 이 공격의 출발점이다"},{"term":"Session","note":"— CSRF가 빌려 쓰는 로그인 상태"},{"term":"XSS","note":"— 스크립트를 심는 공격. 이게 뚫리면 CSRF 방어도 같이 무너진다"},{"term":"JWT","note":"— 쿠키 대신 헤더로 보내면 자동 첨부가 없어 표면이 줄어든다"}]},{"id":"sec--cve","term":"CVE","reading":"Common Vulnerabilities and Exposures","category":"보안 · 인증","summary":"CVE 는 **알려진 보안 구멍 하나에 붙는 세계 공통 번호**다.","aliases":["cve","common vulnerabilities and exposures"],"related":[{"term":"Zero-Day","note":"— 아직 이 번호가 없거나, 번호는 있어도 고칠 것이 없는 상태"},{"term":"OWASP Top 10","note":"— 이 번호 17만여 건을 세어 부류별 위험도를 매긴 목록"},{"term":"Supply Chain Attack","note":"— 이 번호로는 잘 안 잡히는 부분이 많은 공격"},{"term":"Dependency","note":"— 검사 도구가 이 번호와 맞춰 보는 대상"},{"term":"SQL Injection","note":"— 한 약점 유형 아래 이 번호가 여러 개 달리는 대표 예"}]},{"id":"sec--certificate","term":"Certificate","reading":"인증서","category":"보안 · 인증","summary":"인증서는 **이 서버가 그 도메인의 주인이 맞다고 제3자가 보증한 파일**이다.","aliases":["certificate","인증서"],"related":[{"term":"HTTPS","note":"— 인증서 확인이 끝나고 나서 시작되는 통신"},{"term":"SSL_TLS","note":"— 인증서를 확인하고 열쇠를 주고받는 규칙"},{"term":"CA","note":"— 인증서에 서명해주는 발급 기관"},{"term":"암호화","note":"— 인증서에 실린 공개키로 열쇠를 주고받는 방식"},{"term":"DNS","note":"— 인증서에 적힌 도메인을 IP 로 바꾸는 쪽"}]},{"id":"sec--compliance-framework","term":"Compliance Framework","reading":"규정 준수 틀","category":"보안 · 인증","summary":"Compliance Framework는 **지켜야 할 것을 항목으로 쪼개 놓은 목록**이다.","aliases":["compliance framework","규정 준수 틀"],"related":[{"term":"Audit Log","note":"— 항목이 지켜졌음을 증명하는 재료"},{"term":"Shared Responsibility Model","note":"— 항목마다 담당이 갈리는 까닭"},{"term":"Cloud Security Posture Management","note":"— 이 항목들을 계속 재는 도구 쪽 이름"},{"term":"Access Review","note":"— 틀이 주기마다 요구하는 점검을 실제로 하는 자리"},{"term":"Least Privilege","note":"— 거의 모든 틀이 항목으로 담고 있는 원칙"}]},{"id":"sec--conditional-access","term":"Conditional Access","reading":"조건을 보고 들이기","category":"보안 · 인증","summary":"Conditional Access는 **누구인지 확인한 뒤 상황을 한 번 더 보는 관문**이다.","aliases":["conditional access","조건을 보고 들이기"],"related":[{"term":"MFA","note":"— 조건이 걸렸을 때 가장 흔히 더 요구하는 그 한 가지"},{"term":"Step-up Auth","note":"— 민감한 작업 앞에서만 조건을 세게 거는 방식"},{"term":"Zero Trust","note":"— 매번 다시 본다는 원칙. 이 관문이 그 원칙의 집행 장치다"},{"term":"Attribute-Based Access Control","note":"— 같은 조건 판정을 자원 쪽 꼬리표까지 넓힌 사촌"},{"term":"Break-Glass Account","note":"— 이 정책에서 일부러 빼 두는 예외"}]},{"id":"sec--cookie","term":"Cookie","reading":"쿠키","category":"보안 · 인증","summary":"쿠키는 **서버가 브라우저에 맡겨두고 매 요청마다 돌려받는 쪽지**다.","aliases":["cookie","쿠키"],"related":[{"term":"Session","note":"— 쿠키에 담긴 값으로 서버 쪽에서 찾아내는 상태"},{"term":"JWT","note":"— 서버에 상태를 두지 않는 방식. 쿠키에 담기도 한다"},{"term":"XSS","note":"— 스크립트로 쿠키를 훔쳐가는 공격. HttpOnly 가 막는다"},{"term":"CSRF","note":"— 쿠키가 자동으로 붙는 성질을 노린 공격. SameSite 가 막는다"},{"term":"HTTP","note":"— 요청 사이를 기억하지 않아서 쿠키가 생겼다"}]},{"id":"sec--customer-managed-key","term":"Customer-Managed Key","reading":"내가 쥐는 열쇠","category":"보안 · 인증","summary":"Customer-Managed Key는 **잠그는 열쇠를 내가 만들어 쥐는 방식**이다.","aliases":["customer-managed key","내가 쥐는 열쇠"],"related":[{"term":"Encryption","note":"— 잠그는 일 그 자체. 이 단어는 그 열쇠의 주인만 정한다"},{"term":"Secret Management","note":"— 열쇠와 비밀을 코드 밖에서 다루는 자리"},{"term":"Compliance Framework","note":"— 열쇠를 누가 쥐는지를 항목으로 묻는 쪽"},{"term":"Envelope Encryption","note":"— 내 열쇠가 감싸는 그 안쪽 구조. 이 단어는 그 바깥 주인만 정한다"},{"term":"Shared Responsibility Model","note":"— 어디까지가 내 몫인지가 이 선택에서 갈린다"}]},{"id":"sec--dac","term":"DAC","reading":"Data Access Control","category":"보안 · 인증","summary":"DAC는 **데이터 접근을 가운데서 통제하고 기록하는 계층**이다.","aliases":["dac","data access control"],"related":[{"term":"RBAC","note":"— 누구에게 무엇을 허용할지 역할로 정하는 방식"},{"term":"Audit Log","note":"— DAC 가 남기는 기록 그 자체"},{"term":"IAM","note":"— 계정과 권한을 관리하는 상위 체계"},{"term":"Bastion Host","note":"— 접근 통로를 한 곳으로 모은다는 점에서 같은 발상"}]},{"id":"sec--ddos-mitigation","term":"DDoS Mitigation","reading":"떼로 몰려오는 공격 막기","category":"보안 · 인증","summary":"DDoS Mitigation은 **몰려온 가짜 물량을 걸러 내 진짜 손님을 계속 받는 일**이다.","aliases":["ddos mitigation","떼로 몰려오는 공격 막기"],"related":[{"term":"Web Application Firewall","note":"— 정상처럼 생긴 7계층 홍수를 규칙으로 거르는 쪽"},{"term":"Rate Limiting","note":"— 한 곳에서 오는 양을 초당 몇 건으로 묶는 방법"},{"term":"CDN","note":"— 가장자리에서 물량을 나눠 받는 그 그물"},{"term":"Load Balancer","note":"— 걸러지고 남은 몫을 여러 대에 나누는 자리"},{"term":"Auto Scaling","note":"— 남은 몫을 흡수하려고 대수를 늘리는 쪽"}]},{"id":"sec--dmz","term":"DMZ","reading":"Demilitarized Zone, 비무장 지대","category":"보안 · 인증","summary":"DMZ는 **외부에 열어야 할 서버만 따로 모아두는 중간 구역**이다.","aliases":["dmz","demilitarized zone, 비무장 지대"],"related":[{"term":"Firewall","note":"— DMZ를 만드는 도구. 두 겹으로 세워 구역을 가른다"},{"term":"Bastion Host","note":"— 관리자가 내부로 들어갈 때 거치는 진입점. DMZ에 놓인다"},{"term":"Subnet","note":"— 클라우드에서 DMZ와 내부망을 나눌 때 쓰는 단위"},{"term":"인바운드 아웃바운드","note":"— 방향마다 다른 규칙을 거는 그 방향의 이름"},{"term":"VPC","note":"— 클라우드에서 이 구조 전체를 담는 가상 네트워크"}]},{"id":"sec--data-classification","term":"Data Classification","reading":"데이터 등급 나누기","category":"보안 · 인증","summary":"Data Classification은 **자료마다 새어 나갔을 때의 크기를 매겨 등급을 붙이는 일**이다.","aliases":["data classification","데이터 등급 나누기"],"related":[{"term":"PII","note":"— 등급이 가장 높게 붙는 대표적인 자료"},{"term":"Data Masking and Tokenization","note":"— 등급이 높은 칸을 실제로 가리거나 바꾸는 손"},{"term":"Data Residency","note":"— 등급이 높은 자료에 자주 함께 걸리는 요건"},{"term":"Data Catalog","note":"— 무엇이 어디 있는지 세어 두는 목록"},{"term":"Least Privilege","note":"— 등급별로 누가 볼지 좁히는 원칙"}]},{"id":"sec--data-masking-and-tokenization","term":"Data Masking and Tokenization","reading":"가리기와 대체 표 바꾸기","category":"보안 · 인증","summary":"Data Masking and Tokenization은 **원본을 덮거나 표로 바꿔 내보내는 방법**이다.","aliases":["data masking and tokenization","가리기와 대체 표 바꾸기"],"related":[{"term":"PII","note":"— 가리거나 바꿔야 할 값이 무엇인지 정하는 쪽"},{"term":"암호화","note":"— 되돌릴 수 있게 잠그는 방법. 표로 바꾸기의 속 재료다"},{"term":"Hash","note":"— 같은 값을 늘 같은 결과로 바꾸고 되돌리지는 못하는 쪽"},{"term":"Data Classification","note":"— 어느 칸을 가릴지 정하는 앞 단계"},{"term":"RBAC","note":"— 누가 가림을 풀 수 있는지 가르는 자리"}]},{"id":"sec--data-perimeter","term":"Data Perimeter","reading":"데이터가 넘지 못할 울타리","category":"보안 · 인증","summary":"Data Perimeter는 **자료가 우리 울타리 밖으로 못 나가게 치는 상시 방벽**이다.","aliases":["data perimeter","데이터가 넘지 못할 울타리"],"related":[{"term":"Least Privilege","note":"— 무엇을 해도 되나를 정하는 쪽. 울타리는 그 뒤에서 한 번 더 묻는다"},{"term":"Organization Policy Guardrail","note":"— 조직 단위로 상한을 깎아 울타리의 한 겹이 되는 물건"},{"term":"VPC","note":"— 예상한 망이라는 말의 실체"},{"term":"Zero Trust","note":"— 망 안에 있다는 이유만으로 믿지 않는다는 원칙"},{"term":"Audit Log","note":"— 무엇이 막혔고 누가 넘으려 했는지 남는 자리"}]},{"id":"sec--data-residency","term":"Data Residency","reading":"데이터가 머무는 나라","category":"보안 · 인증","summary":"Data Residency는 **자료를 어느 나라 땅에 둘지 정해 지키는 일**이다.","aliases":["data residency","데이터가 머무는 나라"],"related":[{"term":"Region","note":"— 자료를 어느 땅에 둘지 고르는 단위"},{"term":"Multi-Region","note":"— 지역을 넓히는 설계. 이 요건과 정면으로 부딪히는 자리"},{"term":"Data Classification","note":"— 어느 자료에 이 요건이 걸리는지 가르는 앞 단계"},{"term":"PII","note":"— 이 요건이 가장 자주 걸리는 자료"},{"term":"Secret Management","note":"— 열쇠를 누가 어디서 쥐느냐를 다루는 쪽"}]},{"id":"sec--defense-in-depth","term":"Defense in Depth","reading":"심층 방어","category":"보안 · 인증","summary":"Defense in Depth는 **한 겹이 뚫려도 다음 겹이 막게 겹쳐 두는 설계**다.","aliases":["defense in depth","심층 방어"],"related":[{"term":"Zero Trust","note":"— 겹마다 다시 확인하게 만드는 원칙"},{"term":"Least Privilege","note":"— 뚫린 뒤에 번지는 범위를 줄이는 겹"},{"term":"Password Hashing","note":"— 저장소가 새어도 버티게 하는 마지막 겹"},{"term":"XSS","note":"— 거르기와 브라우저 제한을 겹으로 막는 대표적인 공격"},{"term":"MFA","note":"— 비밀번호 뒤에 세우는 두 번째 겹"}]},{"id":"sec--digital-forensics","term":"Digital Forensics","reading":"흔적 되짚기","category":"보안 · 인증","summary":"Digital Forensics는 **흔적을 훼손 없이 모아 무슨 일이었는지 밝히는 일**이다.","aliases":["digital forensics","흔적 되짚기"],"related":[{"term":"Audit Log","note":"— 누가 언제 무엇을 했는지 남는, 되짚기의 첫 재료"},{"term":"Threat Detection","note":"— 되짚기를 시작하게 만드는 신호"},{"term":"Postmortem","note":"— 밝힌 것을 다시 안 나게 정리하는 다음 걸음"},{"term":"Data Residency","note":"— 증거를 어느 지역에 둘지에 함께 걸리는 요건"},{"term":"Object Storage","note":"— 못 고치게 굳혀 두는 자리"}]},{"id":"sec--directory-service","term":"Directory Service","reading":"사람과 기기 명부","category":"보안 · 인증","summary":"Directory Service는 **사람과 기기와 그 권한을 한곳에 모아 둔 명부**다.","aliases":["directory service","사람과 기기 명부"],"related":[{"term":"IAM","note":"— 명부에 적힌 신원에 무엇을 허락할지 정하는 쪽"},{"term":"SSO","note":"— 이 명부 하나로 여러 앱을 한 번에 여는 방식"},{"term":"User Provisioning","note":"— 명부에 항목을 넣고 빼는 일을 자동으로 돌리는 쪽"},{"term":"External Identity","note":"— 우리 명부에 없는 사람을 들이는 다른 길"},{"term":"RBAC","note":"— 명부의 묶음(그룹)에 권한을 거는 방식"}]},{"id":"sec--encryption","term":"Encryption","reading":"암호화","category":"보안 · 인증","summary":"Encryption은 **키가 있어야 되돌릴 수 있게 바꿔두는 일**이다.","aliases":["encryption","암호화"],"related":[{"term":"Hash","note":"— 되돌릴 수 없는 쪽. 비밀번호와 무결성 확인에 쓴다"},{"term":"HTTPS","note":"— 오가는 길을 암호화로 감싼 통신"},{"term":"SSL_TLS","note":"— HTTPS 가 쓰는 암호화 프로토콜"},{"term":"PII","note":"— 암호화로 지켜야 할 대표적인 데이터"}]},{"id":"sec--envelope-encryption","term":"Envelope Encryption","reading":"열쇠를 열쇠로 감싸기","category":"보안 · 인증","summary":"Envelope Encryption은 **자료를 잠근 열쇠를 다른 열쇠로 또 잠그는 방식**이다.","aliases":["envelope encryption","열쇠를 열쇠로 감싸기"],"related":[{"term":"Encryption","note":"— 잠그는 일 그 자체. 봉투 방식은 그것을 두 층으로 나눈 것이다"},{"term":"Hardware Security Module","note":"— 감싸는 열쇠가 실제로 사는 금고 장치"},{"term":"Secret Management","note":"— 열쇠 말고 다른 비밀을 어디에 둘지 다루는 쪽"},{"term":"IAM","note":"— 감싸는 열쇠를 부를 수 있는 사람을 정하는 자리"}]},{"id":"sec--external-identity","term":"External Identity","reading":"바깥에서 온 신원","category":"보안 · 인증","summary":"External Identity는 **밖에서 확인된 신원을 그대로 받아 들여보내는 방식**이다.","aliases":["external identity","바깥에서 온 신원"],"related":[{"term":"SAML","note":"— 밖의 발급자가 서명해 보내는 대표 형식"},{"term":"OpenID Connect","note":"— 같은 일을 하는 다른 형식"},{"term":"Workload Identity Federation","note":"— 사람이 아니라 기계 쪽의 같은 얼개"},{"term":"SSO","note":"— 한 번 로그인해 여러 곳을 여는 쪽"},{"term":"Short-Lived Credential","note":"— 밖의 신원을 바꿔 받는 그 짧은 출입증"}]},{"id":"sec--hsts","term":"HSTS","reading":"HTTP Strict Transport Security","category":"보안 · 인증","summary":"HSTS는 **앞으로 이 사이트는 자물쇠 건 길로만 열라고 새기는 헤더**다.","aliases":["hsts","http strict transport security"],"related":[{"term":"HTTPS","note":"— 이 헤더가 강제하려는 바로 그 연결"},{"term":"SSL/TLS","note":"— 인증서 오류가 나면 연결을 끊게 만드는 계층"},{"term":"Certificate","note":"— 오류가 났을 때 넘어갈 수 없게 되는 대상"},{"term":"CSP","note":"— 헤더 한 줄로 브라우저를 움직이는 같은 방식의 다른 예"}]},{"id":"sec--hardware-security-module","term":"Hardware Security Module","reading":"열쇠 전용 금고 장치","category":"보안 · 인증","summary":"Hardware Security Module은 **열쇠를 밖으로 안 내보내는 전용 금고 장치**다.","aliases":["hardware security module","열쇠 전용 금고 장치"],"related":[{"term":"Envelope Encryption","note":"— 이 장치가 맡는 것은 대개 감싸는 쪽 열쇠다"},{"term":"Encryption","note":"— 장치가 안에서 실제로 하는 일"},{"term":"CA","note":"— 뿌리 열쇠를 이 장치에 두는 대표적인 곳"},{"term":"Certificate","note":"— 그 열쇠로 서명해 만들어 내는 물건"},{"term":"Secret Management","note":"— 열쇠 말고 다른 비밀을 두는 자리"}]},{"id":"sec--iam","term":"IAM","reading":"Identity and Access Management","category":"보안 · 인증","summary":"IAM은 **누가 어떤 자원에 무엇을 할 수 있는지 정해두는 체계**다.","aliases":["iam","identity and access management"],"related":[{"term":"RBAC","note":"— 역할 단위로 권한을 묶는 방식. IAM 안에서도 쓰인다"},{"term":"MFA","note":"— 접근 조건에 하나 더 얹을 수 있는 인증 수단"},{"term":"API Key","note":"— 오래 사는 자격 증명. 역할이 주는 임시 자격과 대비된다"},{"term":"Audit Log","note":"— 누가 무엇에 접근했는지 남기는 기록"},{"term":"Zero Trust","note":"— 안쪽이라고 믿지 않고 매번 확인하는 사고방식"}]},{"id":"sec--ipsec-vpn","term":"IPSec VPN","reading":"Internet Protocol Security VPN","category":"보안 · 인증","summary":"IPSec VPN은 **인터넷 위에 암호화된 통로를 만드는 방식**이다.","aliases":["ipsec vpn","internet protocol security vpn"],"related":[{"term":"VPN","note":"— IPSec은 VPN을 만드는 방식 가운데 하나다"},{"term":"Tunnel","note":"— 원래 패킷을 다른 패킷 안에 감싸 보내는 그 기법"},{"term":"암호화","note":"— 터널 안의 내용을 읽지 못하게 만드는 부분"},{"term":"인증서","note":"— 연결 전에 서로가 맞는지 확인할 때 쓰는 수단"},{"term":"SSL_TLS","note":"— 응용 계층에서 같은 일을 하는 다른 방식"}]},{"id":"sec--identity-impersonation","term":"Identity Impersonation","reading":"남의 신원 빌려 쓰기","category":"보안 · 인증","summary":"Identity Impersonation은 **내 자격으로 다른 신원의 권한을 잠깐 받아 쓰는 것**이다.","aliases":["identity impersonation","남의 신원 빌려 쓰기"],"related":[{"term":"Service Account","note":"— 대개 빌려 쓰는 대상이 되는 신원"},{"term":"Short-Lived Credential","note":"— 빌리면 손에 들어오는 그 짧은 출입증"},{"term":"Permission Boundary","note":"— 빌린 뒤에도 넘지 못하게 미리 깎아 둔 상한"},{"term":"Audit Log","note":"— 누가 무엇을 빌렸는지가 남는 자리"},{"term":"Least Privilege","note":"— 상시로 주지 않고 빌려 쓰게 만드는 이유"}]},{"id":"sec--identity-based-ssh-access","term":"Identity-Based SSH Access","reading":"신원으로 여는 원격 접속","category":"보안 · 인증","summary":"Identity-Based SSH Access는 **열쇠 파일 대신 신원으로 여는 원격 접속**이다.","aliases":["identity-based ssh access","신원으로 여는 원격 접속"],"related":[{"term":"SSH","note":"— 이 방식이 그대로 쓰는 바탕 약속"},{"term":"Bastion Host","note":"— 접속 길목을 한 대로 모으는 다른 방법"},{"term":"IAM","note":"— 누가 어느 기계에 들어가도 되는지를 적어 두는 자리"},{"term":"Short-Lived Credential","note":"— 접속할 때 그 자리에서 내주는 짧은 증명"},{"term":"Audit Log","note":"— 누가 언제 들어갔는지가 남는 자리"}]},{"id":"sec--incident-response","term":"Incident Response","reading":"사고 대응","category":"보안 · 인증","summary":"Incident Response는 **보안 사고를 준비해 두고 수습해 배우는 절차**다.","aliases":["incident response","사고 대응"],"related":[{"term":"Postmortem","note":"— 마지막 칸에서 배운 것을 글로 남기는 자리"},{"term":"On-call","note":"— 경보를 받아 첫 칸을 여는 당번"},{"term":"Runbook","note":"— 미리 적어 두는 대응 절차. 준비 칸의 알맹이다"},{"term":"Threat Detection","note":"— 두 번째 칸을 열어 주는 쪽"},{"term":"SIEM","note":"— 무슨 일이 있었는지 이어 붙여 보여 주는 도구"}]},{"id":"sec--jwt","term":"JWT","reading":"JSON Web Token","category":"보안 · 인증","summary":"JWT는 **내용과 서명을 함께 담아 위조를 막은 토큰**이다.","aliases":["jwt","json web token"],"related":[{"term":"Session","note":"— 서버가 기억하는 방식. JWT와 반대편"},{"term":"OAuth","note":"— 발급되는 토큰의 형식으로 JWT를 쓰는 경우가 많다"},{"term":"SSO","note":"— 여러 서비스가 같은 토큰을 신뢰하는 구조"},{"term":"Cookie","note":"— 토큰을 어디에 저장할지의 선택지 중 하나"}]},{"id":"sec--just-in-time-access","term":"Just-in-Time Access","reading":"필요할 때만 잠깐 주는 권한","category":"보안 · 인증","summary":"Just-in-Time Access는 **필요할 때만 켰다가 스스로 꺼지는 권한**이다.","aliases":["just-in-time access","필요할 때만 잠깐 주는 권한"],"related":[{"term":"Least Privilege","note":"— 최소한만 주자는 원칙. 이 방식은 그 최소를 시간으로도 자른다"},{"term":"Short-Lived Credential","note":"— 같은 생각을 자격 증명의 수명으로 푸는 쪽"},{"term":"Access Review","note":"— 자격을 가진 사람이 아직 그래도 되는지 되묻는 자리"},{"term":"Permission Boundary","note":"— 켰을 때의 최대치를 미리 깎아 두는 다른 장치"},{"term":"Audit Log","note":"— 누가 왜 켰는지가 남는 곳"}]},{"id":"sec--least-privilege","term":"Least Privilege","reading":"최소 권한","category":"보안 · 인증","summary":"Least Privilege는 **맡은 일에 필요한 만큼만 권한을 주는 원칙**이다.","aliases":["least privilege","최소 권한"],"related":[{"term":"RBAC","note":"— 최소 권한을 실제로 나눠 주는 가장 흔한 방식"},{"term":"IAM","note":"— 누구에게 무엇을 허용할지 적어 두는 자리"},{"term":"Zero Trust","note":"— 매번 다시 확인하는 원칙. 최소 권한과 짝으로 쓴다"},{"term":"Defense in Depth","note":"— 같은 자리에 겹을 더 세우는 다른 원칙"},{"term":"Audit Log","note":"— 실제로 쓴 권한을 남겨 목록을 좁히는 근거"}]},{"id":"sec--mfa","term":"MFA","reading":"Multi-Factor Authentication","category":"보안 · 인증","summary":"MFA는 **종류가 다른 증거를 둘 이상 요구하는 인증**이다.","aliases":["mfa","multi-factor authentication"],"related":[{"term":"Step-up Auth","note":"— 위험한 동작 앞에서만 한 번 더 요구하는 방식"},{"term":"IAM","note":"— 접근 조건에 MFA 통과 여부를 넣을 수 있다"},{"term":"SSO","note":"— 한 번의 인증으로 여러 서비스를 여는 방식. MFA와 같이 쓴다"},{"term":"Zero Trust","note":"— 안쪽이라고 믿지 않는 사고방식. MFA가 그 수단 중 하나다"}]},{"id":"sec--oauth-2-0","term":"OAuth 2.0","reading":"","category":"보안 · 인증","summary":"OAuth는 **비밀번호를 넘기지 않고 권한만 빌려주는 규약**이다.","aliases":["oauth 2.0","oauth"],"related":[{"term":"JWT","note":"— 발급되는 토큰의 형식으로 자주 쓰인다"},{"term":"SSO","note":"— 한 번 로그인으로 여러 서비스를 쓰는 구조"},{"term":"Refresh Token","note":"— 만료된 액세스 토큰을 다시 받는 장치"},{"term":"API Key","note":"— 권한 범위나 회수 개념이 없는 더 단순한 방식"}]},{"id":"sec--owasp-top-10","term":"OWASP Top 10","reading":"Open Worldwide Application Security Project Top 10","category":"보안 · 인증","summary":"OWASP Top 10 은 **웹 앱에서 가장 흔한 보안 결함 열 부류**다.","aliases":["owasp top 10","open worldwide application security project top 10"],"related":[{"term":"Supply Chain Attack","note":"— 2025년판에서 3위로 올라온 부류가 겨누는 공격"},{"term":"CVE","note":"— 부류마다 얼마나 위험한지를 계산할 때 세는 번호"},{"term":"SQL Injection","note":"— 5위 주입 부류에 들어가는 대표 사례"},{"term":"XSS","note":"— 같은 주입 부류의 다른 한쪽"}]},{"id":"sec--openid-connect","term":"OpenID Connect","reading":"열린 신원 확인","category":"보안 · 인증","summary":"OpenID Connect는 **누가 로그인했는지를 표 한 장으로 알려주는 규약**이다.","aliases":["openid connect","열린 신원 확인"],"related":[{"term":"OAuth","note":"— 이 규약이 올라타 있는 권한 위임 틀"},{"term":"JWT","note":"— ID 토큰이 실제로 실려 오는 형식"},{"term":"SSO","note":"— 한 번 확인한 결과를 여러 앱이 나눠 쓰는 그림"},{"term":"SAML","note":"— 같은 일을 앞선 세대가 하던 방식"},{"term":"IAM","note":"— 확인이 끝난 뒤 무엇을 해도 되는지 정하는 쪽"}]},{"id":"sec--organization-policy-guardrail","term":"Organization Policy Guardrail","reading":"조직이 그은 상한선","category":"보안 · 인증","summary":"Organization Policy Guardrail은 **위에서 그어 두는 권한의 상한선**이다.","aliases":["organization policy guardrail","조직이 그은 상한선"],"related":[{"term":"IAM","note":"— 상한선과 짝을 이루는, 실제로 권한을 주는 쪽"},{"term":"Least Privilege","note":"— 상한선이 기계로 강제하려는 원칙"},{"term":"Permission Boundary","note":"— 같은 \"깎기\" 를 사람·역할 한 명 단위로 거는 물건"},{"term":"Audit Log","note":"— 어디서 막혔고 무엇이 안 쓰이는지 확인하는 자리"},{"term":"Multi-tenancy","note":"— 계정을 여러 개로 나눠 쓰는 구조. 상한선이 필요해지는 배경"}]},{"id":"sec--pii","term":"PII","reading":"Personally Identifiable Information","category":"보안 · 인증","summary":"PII는 **특정 개인을 알아낼 수 있는 정보**다.","aliases":["pii","personally identifiable information"],"related":[{"term":"암호화","note":"— 되돌릴 수 있게 가리는 방법. 원본이 다시 필요한 값에 쓴다"},{"term":"Hash","note":"— 되돌릴 수 없게 바꾸는 쪽. 익명화에 쓴다"},{"term":"RBAC","note":"— 역할에 따라 원본을 볼지 마스킹을 볼지 가르는 장치"},{"term":"Audit Log","note":"— 누가 언제 PII를 열어봤는지 남기는 기록"},{"term":"Guardrail","note":"— 챗봇 입출력에서 PII를 걸러내는 장치"}]},{"id":"sec--password-hashing","term":"Password Hashing","reading":"비밀번호 해싱","category":"보안 · 인증","summary":"Password Hashing은 **비밀번호를 되돌릴 수 없는 값으로 바꿔 저장하는 것**이다.","aliases":["password hashing","비밀번호 해싱"],"related":[{"term":"Hash","note":"— 되돌릴 수 없게 뭉개는 계산 그 자체"},{"term":"Encryption","note":"— 열쇠로 되돌릴 수 있는 쪽. 비밀번호에는 쓰지 않는다"},{"term":"Defense in Depth","note":"— 저장소가 새어도 버티게 하는 겹의 하나"},{"term":"Session","note":"— 한 번 통과한 뒤 매번 비밀번호를 안 묻게 해 주는 자리"},{"term":"MFA","note":"— 비밀번호가 뚫려도 남는 다른 문"}]},{"id":"sec--penetration-testing","term":"Penetration Testing","reading":"모의 침투 시험","category":"보안 · 인증","summary":"Penetration Testing은 **허락을 받고 실제로 뚫어 보는 시험**이다.","aliases":["penetration testing","모의 침투 시험"],"related":[{"term":"OWASP Top 10","note":"— 무엇부터 시험할지 순서를 정할 때 보는 목록"},{"term":"CVE","note":"— 탐색 단계에서 찾아낸 알려진 구멍에 붙는 번호"},{"term":"Zero-Day","note":"— 목록에 아직 없는 구멍. 시험으로도 잘 안 나온다"},{"term":"Phishing","note":"— 사람 쪽을 겨눈 시험에서 실제로 쓰는 수법"},{"term":"Defense in Depth","note":"— 한 겹을 넘어도 다음 겹에서 막히게 두는 사고방식"}]},{"id":"sec--permission-boundary","term":"Permission Boundary","reading":"권한 천장","category":"보안 · 인증","summary":"Permission Boundary는 **권한 문서가 줄 수 있는 최대치를 미리 걸어 두는 것**이다.","aliases":["permission boundary","권한 천장"],"related":[{"term":"IAM","note":"— 천장이 얹히는 바탕. 허락을 실제로 주는 쪽"},{"term":"Least Privilege","note":"— 천장이 기계로 강제하려는 원칙"},{"term":"Organization Policy Guardrail","note":"— 같은 깎기를 계정·조직 단위로 거는 물건"},{"term":"Resource-Based Policy","note":"— 천장의 암묵적 거부가 안 닿는 예외가 있는 자리"},{"term":"RBAC","note":"— 권한을 역할로 묶는 방식. 천장은 그 역할 위에 걸린다"}]},{"id":"sec--phishing","term":"Phishing","reading":"피싱","category":"보안 · 인증","summary":"피싱은 **믿을 만한 곳인 척해 비밀을 직접 받아내는 속임수**다.","aliases":["phishing","피싱"],"related":[{"term":"MFA","note":"— 비밀번호 하나가 넘어가도 그것만으로는 안 열리게 하는 다음 겹"},{"term":"Step-up Auth","note":"— 위험한 동작 앞에서 한 번 더 확인을 요구하는 자리"},{"term":"Zero Trust","note":"— 아는 사람인지 매번 다시 확인하자는 쪽의 설계 원칙"},{"term":"Audit Log","note":"— 넘어간 뒤에 무슨 일이 있었는지 되짚는 기록"},{"term":"SQL Injection","note":"— 코드 한 줄을 바로잡으면 사라지는 쪽. 피싱은 그 반대다"}]},{"id":"sec--post-quantum-cryptography","term":"Post-Quantum Cryptography","reading":"양자내성암호","category":"보안 · 인증","summary":"양자내성암호는 **양자컴퓨터로도 못 푸는 공개키 암호**다.","aliases":["post-quantum cryptography","양자내성암호"],"related":[{"term":"SSL/TLS","note":"— 이 키 교환이 실제로 일어나는 자리"},{"term":"HTTPS","note":"— 바뀐 알고리즘이 그대로 적용되는 가장 흔한 통신"},{"term":"Encryption","note":"— 나눠 가진 비밀로 그다음에 하는 일"},{"term":"Certificate","note":"— 서명 쪽 전환이 걸려 있는 자리"}]},{"id":"sec--presigned-url","term":"Presigned URL","reading":"미리 서명한 임시 주소","category":"보안 · 인증","summary":"Presigned URL은 **미리 서명해 둔, 기한이 붙은 파일 주소**다.","aliases":["presigned url","미리 서명한 임시 주소"],"related":[{"term":"Object Storage","note":"— 이 주소가 가리키는 저장 방식"},{"term":"Short-Lived Credential","note":"— 주소의 실제 수명을 정하는 쪽"},{"term":"Least Privilege","note":"— 읽기만 되는 주소를 주라는 근거"},{"term":"HTTPS","note":"— 주소가 중간에서 새지 않게 하는 최소 조건"},{"term":"Resource-Based Policy","note":"— 통 쪽에 허락을 적어 여는 다른 방법"}]},{"id":"sec--querypie","term":"QueryPie","reading":"","category":"보안 · 인증","summary":"QueryPie는 **데이터베이스 접근을 한곳에서 통제하는 플랫폼**이다.","aliases":["querypie"],"related":[{"term":"Audit Log","note":"— QueryPie가 쿼리마다 남기는 기록"},{"term":"RBAC","note":"— 사람이 아니라 역할에 권한을 붙이는 방식"},{"term":"PII","note":"— 마스킹의 대상이 되는 개인정보"},{"term":"Bastion Host","note":"— 서버 접속에서 같은 구조를 만드는 진입점"}]},{"id":"sec--rbac","term":"RBAC","reading":"Role-Based Access Control","category":"보안 · 인증","summary":"RBAC은 **권한을 사람이 아니라 역할에 붙이는 방식**이다.","aliases":["rbac","role-based access control"],"related":[{"term":"IAM","note":"— 사용자와 역할, 권한을 묶어 관리하는 상위 체계"},{"term":"DAC","note":"— 자원 주인이 직접 권한을 주는 방식. 역할을 거치지 않는다"},{"term":"JWT","note":"— 확인된 역할을 담아 요청마다 들고 다니는 토큰"},{"term":"Audit Log","note":"— 누가 어떤 권한으로 무엇을 했는지 남기는 기록"}]},{"id":"sec--refresh-token","term":"Refresh Token","reading":"리프레시 토큰","category":"보안 · 인증","summary":"Refresh Token은 **만료된 액세스 토큰을 다시 받아오는 열쇠**다.","aliases":["refresh token","리프레시 토큰"],"related":[{"term":"Token 인증","note":"— 로그인 상태를 토큰으로 들고 다니는 방식 전체"},{"term":"JWT","note":"— 두 토큰을 담는 데 흔히 쓰는 형식"},{"term":"OAuth","note":"— 이 두 토큰 구조를 표준으로 정해둔 규약"},{"term":"Session","note":"— 서버가 상태를 들고 있는 방식. 토큰 방식과 갈리는 지점"},{"term":"XSS","note":"— `localStorage` 에 둔 토큰을 그대로 읽어가는 공격"}]},{"id":"sec--resource-based-policy","term":"Resource-Based Policy","reading":"자원 쪽에 붙는 권한","category":"보안 · 인증","summary":"Resource-Based Policy는 **자원에 붙어서 누가 들어올 수 있는지 적는 문서**다.","aliases":["resource-based policy","자원 쪽에 붙는 권한"],"related":[{"term":"IAM","note":"— 이 두 문서가 함께 사는 집"},{"term":"Least Privilege","note":"— 명단을 좁게 적으라는 근거"},{"term":"Permission Boundary","note":"— 허락을 주는 대신 최대치를 깎는 쪽"},{"term":"Organization Policy Guardrail","note":"— 계정 전체에 걸어 두는 더 위쪽 상한"},{"term":"Presigned URL","note":"— 문서를 안 고치고 파일 하나만 잠깐 여는 다른 방법"}]},{"id":"sec--saml","term":"SAML","reading":"Security Assertion Markup Language","category":"보안 · 인증","summary":"SAML은 **한 곳에서 확인한 신원을 여러 서비스가 믿게 하는 규약**이다.","aliases":["saml","security assertion markup language"],"related":[{"term":"SSO","note":"— SAML이 구현하려는 목표 그 자체"},{"term":"OAuth","note":"— 인증이 아니라 권한 위임을 다루는 이웃 규약"},{"term":"IAM","note":"— 누가 무엇을 할 수 있는지 관리하는 큰 틀"},{"term":"Certificate","note":"— 보증서 서명을 검증할 때 쓰는 IdP의 공개 인증서"},{"term":"Session","note":"— 검증이 끝난 뒤 SP가 만들어 유지하는 것"}]},{"id":"sec--siem","term":"SIEM","reading":"기록을 한데 모아 보는 눈","category":"보안 · 인증","summary":"SIEM은 **흩어진 보안 기록을 한곳에 모아 이상을 찾아내는 도구**다.","aliases":["siem","기록을 한데 모아 보는 눈"],"related":[{"term":"Audit Log","note":"— 여기로 흘러드는 대표적인 기록 한 갈래"},{"term":"Logging","note":"— 모을 재료를 만드는 쪽"},{"term":"Threat Detection","note":"— 모아 둔 기록 위에서 규칙이 하는 일"},{"term":"Incident Response","note":"— 묶인 사건을 사람이 받아 수습하는 다음 단계"},{"term":"Observability","note":"— 같은 재료로 장애를 좁히는 쪽. 목적이 보안이 아니라 운영이다"}]},{"id":"sec--sql-injection","term":"SQL Injection","reading":"SQL 삽입","category":"보안 · 인증","summary":"SQL Injection은 **입력값이 데이터가 아니라 명령으로 실행되는 공격**이다.","aliases":["sql injection","sql 삽입"],"related":[{"term":"XSS","note":"— 같은 뿌리의 문제. 이쪽은 브라우저에서 실행된다"},{"term":"Index","note":"— 질의문을 다루는 다른 주제"},{"term":"Audit Log","note":"— 뚫렸을 때 무엇이 나갔는지 아는 수단"},{"term":"암호화","note":"— 뚫려도 내용을 못 읽게 하는 다음 겹"}]},{"id":"sec--ssh","term":"SSH","reading":"Secure Shell","category":"보안 · 인증","summary":"SSH는 **멀리 있는 컴퓨터에 암호화된 통로로 접속하는 규약**이다.","aliases":["ssh","secure shell"],"related":[{"term":"TCP","note":"— SSH 연결이 올라타는 아래층"},{"term":"암호화","note":"— SSH 통로 안을 가려주는 원리"},{"term":"Port Forwarding","note":"— SSH 통로 안으로 다른 포트를 끌어오는 기능"},{"term":"Bastion Host","note":"— 내부망에 들어갈 때 SSH로 먼저 거치는 서버"},{"term":"VPN","note":"— 통로를 만드는 다른 방법. 적용 범위가 더 넓다"}]},{"id":"sec--ssl-tls","term":"SSL/TLS","reading":"","category":"보안 · 인증","summary":"TLS는 **오가는 데이터를 가리고 상대가 맞는지 확인하는 규약**이다.","aliases":["ssl/tls","ssl_tls","ssl","tls"],"related":[{"term":"HTTPS","note":"— HTTP 를 TLS 위에 올린 것"},{"term":"인증서","note":"— 서버가 그 도메인의 주인임을 보이는 문서"},{"term":"CA","note":"— 그 인증서에 서명해주는 기관"},{"term":"암호화","note":"— TLS 가 내용을 가릴 때 쓰는 계산"},{"term":"TCP","note":"— TLS 가 그 위에 얹히는 아래층 규약"}]},{"id":"sec--sso","term":"SSO","reading":"Single Sign-On","category":"보안 · 인증","summary":"SSO는 **한 번 로그인하면 여러 서비스를 그대로 쓰는 방식**이다.","aliases":["sso","single sign-on"],"related":[{"term":"OAuth","note":"— 권한을 빌려주는 규약. SSO의 재료로 쓰인다"},{"term":"JWT","note":"— 증표를 담는 형식으로 자주 쓰인다"},{"term":"SAML","note":"— 기업 환경에서 오래 쓰인 증표 교환 방식"},{"term":"Zero Trust","note":"— 한 번 통과했다고 계속 믿지 않는 반대 방향의 원칙"}]},{"id":"sec--secret-management","term":"Secret Management","reading":"시크릿 관리","category":"보안 · 인증","summary":"Secret Management는 **열쇠 노릇을 하는 값을 코드 밖에서 다루는 일**이다.","aliases":["secret management","시크릿 관리"],"related":[{"term":"API Key","note":"— 시크릿 중 가장 흔한 것"},{"term":"환경 변수","note":"— 코드 밖으로 값을 빼내는 가장 기본적인 자리"},{"term":"Least Privilege","note":"— 누가 어떤 시크릿을 꺼낼 수 있는지 좁히는 원칙"},{"term":"Audit Log","note":"— 누가 언제 꺼냈는지 남기는 자리"},{"term":"Kubernetes","note":"— 시크릿을 파드 밖에 따로 두는 대표적인 실행 환경"}]},{"id":"sec--security-hardening","term":"Security Hardening","reading":"굳히기","category":"보안 · 인증","summary":"Security Hardening은 **공격받을 자리를 미리 줄여 두는 일**이다.","aliases":["security hardening","굳히기"],"related":[{"term":"Least Privilege","note":"— 남겨 둔 문을 누가 지나갈지 좁히는 쪽"},{"term":"Defense in Depth","note":"— 한 겹이 뚫려도 다음 겹이 남게 하는 쪽. 굳히기는 겹마다 적용된다"},{"term":"CVE","note":"— 붙일 패치가 어느 구멍을 막는지 부르는 공용 번호"},{"term":"Threat Detection","note":"— 줄이고 남은 자리에서 벌어지는 일을 지켜보는 쪽"},{"term":"Zero Trust","note":"— 굳혀 둔 안쪽도 믿지 말고 매번 다시 확인하자는 쪽"}]},{"id":"sec--self-service-password-reset","term":"Self-Service Password Reset","reading":"스스로 푸는 비밀번호","category":"보안 · 인증","summary":"Self-Service Password Reset은 **잊은 비밀번호를 본인이 직접 되돌리는 길**이다.","aliases":["self-service password reset","스스로 푸는 비밀번호"],"related":[{"term":"MFA","note":"— 스스로 풀 때 본인을 증명하는 수단이 곧 이것이다"},{"term":"Password Hashing","note":"— 새로 정한 비밀번호가 저장되는 방식"},{"term":"User Provisioning","note":"— 계정을 만들고 지우는 쪽. 되돌리기는 그 계정 일생의 한 대목이다"},{"term":"SSO","note":"— 한 번 들어가면 여러 곳이 열리는 쪽. 그 하나가 막히면 전부 막힌다"},{"term":"IAM","note":"— 이 길을 누구에게 열어 줄지 정하는 자리"}]},{"id":"sec--separation-of-duties","term":"Separation of Duties","reading":"한 사람이 다 못 하게 나누기","category":"보안 · 인증","summary":"Separation of Duties는 **혼자서는 못 끝내게 일을 쪼개는 원칙**이다.","aliases":["separation of duties","한 사람이 다 못 하게 나누기"],"related":[{"term":"Least Privilege","note":"— 권한의 크기를 줄이는 쪽. 이쪽은 권한의 조합을 흩는다"},{"term":"RBAC","note":"— 갈라 놓을 단위를 역할로 만들어 두는 자리"},{"term":"Audit Log","note":"— 갈라 놓은 것이 실제로 지켜졌는지 나중에 확인하는 자리"},{"term":"Service Account","note":"— 사람이 아닌 것에도 같은 원칙을 적용해야 하는 대상"},{"term":"IAM","note":"— 누구에게 무엇을 허용하고 어디서 상한을 깎을지 정하는 자리"}]},{"id":"sec--service-account","term":"Service Account","reading":"사람이 아닌 것의 신원","category":"보안 · 인증","summary":"Service Account는 **사람이 아니라 프로그램에게 주는 계정**이다.","aliases":["service account","사람이 아닌 것의 신원"],"related":[{"term":"Short-Lived Credential","note":"— 이 계정이 열쇠 대신 받아 쓰는 짧은 출입증"},{"term":"IAM","note":"— 이 계정에 무엇을 허용할지 정하는 자리"},{"term":"Secret Management","note":"— 그래도 남는 열쇠 파일을 어디에 둘지 다루는 쪽"},{"term":"Least Privilege","note":"— 이 계정에 줄 권한의 크기를 정하는 원칙"},{"term":"Audit Log","note":"— 사람이 아닌 것이 무엇을 했는지 남는 자리"}]},{"id":"sec--short-lived-credential","term":"Short-Lived Credential","reading":"금방 만료되는 출입증","category":"보안 · 인증","summary":"Short-Lived Credential은 **몇 시간 뒤 저절로 죽는 출입증**이다.","aliases":["short-lived credential","금방 만료되는 출입증"],"related":[{"term":"Service Account","note":"— 짧은 출입증을 받아 가는 쪽의 신원"},{"term":"API Key","note":"— 스스로 만료되지 않는 대표적인 장기 비밀"},{"term":"Refresh Token","note":"— 만료된 뒤 새로 받는 다른 방식. 짧은 자격에는 없는 경우가 있다"},{"term":"Secret Management","note":"— 그래도 남는 장기 비밀을 어디에 둘지 다루는 쪽"},{"term":"Zero Trust","note":"— 매번 다시 확인하자는 쪽. 수명이 짧으면 자연히 다시 묻게 된다"}]},{"id":"sec--step-up-auth","term":"Step-up Auth","reading":"추가 인증","category":"보안 · 인증","summary":"Step-up Auth는 **민감한 작업 앞에서 한 번 더 본인을 확인하는 절차**다.","aliases":["step-up auth","추가 인증"],"related":[{"term":"Token 인증","note":"— 지금 인증 수준이 얼마인지를 담아 나르는 수단"},{"term":"MFA","note":"— 로그인 시점에 수단을 둘 이상 요구하는 쪽"},{"term":"Session","note":"— 승격된 상태를 어디에 들고 있을지의 문제"},{"term":"Audit Log","note":"— 추가 인증 시도를 남겨두는 기록"}]},{"id":"sec--supply-chain-attack","term":"Supply Chain Attack","reading":"공급망 공격","category":"보안 · 인증","summary":"공급망 공격은 **내가 가져다 쓰는 것을 먼저 뚫는 공격**이다.","aliases":["supply chain attack","공급망 공격"],"related":[{"term":"OWASP Top 10","note":"— 2025년판에서 이 공격을 3위 부류로 올린 목록"},{"term":"Dependency","note":"— 공격이 들어오는 가장 흔한 통로"},{"term":"Package Manager","note":"— 그 통로로 코드를 실제로 내려받아 실행하는 도구"},{"term":"Lock File","note":"— 어떤 버전이 들어왔는지 적혀 있는 자리"},{"term":"CVE","note":"— 가져온 부품에 알려진 구멍이 있는지 맞춰 볼 때 보는 번호"}]},{"id":"sec--threat-detection","term":"Threat Detection","reading":"위협 탐지","category":"보안 · 인증","summary":"Threat Detection은 **공격이 벌어지고 있는지 계속 찾아내는 일**이다.","aliases":["threat detection","위협 탐지"],"related":[{"term":"Audit Log","note":"— 탐지가 읽는 재료. 이게 안 남으면 볼 것이 없다"},{"term":"Security Hardening","note":"— 들어올 자리를 줄이는 쪽. 탐지는 그 뒤를 본다"},{"term":"Zero-Day","note":"— 알려진 목록에 없는 공격. 평소와 다른 행동으로 잡아야 하는 쪽"},{"term":"Observability","note":"— 밖에서 물어 안을 아는 성질. 탐지는 그 재료를 보안 쪽으로 쓴다"},{"term":"Phishing","note":"— 낌새가 사람 쪽에서 시작되는 대표적인 길"}]},{"id":"sec--token","term":"Token 인증","reading":"Token Authentication","category":"보안 · 인증","summary":"Token 인증은 **로그인 때 받은 출입증으로 신원을 증명하는 방식**이다.","aliases":["token 인증","token authentication"],"related":[{"term":"JWT","note":"— 토큰 인증에서 가장 많이 쓰는 토큰 형식"},{"term":"Session","note":"— 서버가 기억하는 쪽. 즉시 끊기가 쉽다"},{"term":"Refresh Token","note":"— 짧은 Access Token을 다시 받아오는 긴 수명의 토큰"},{"term":"OAuth","note":"— 다른 서비스의 계정으로 토큰을 받아오는 절차"},{"term":"HTTPS","note":"— 토큰이 중간에서 읽히지 않게 감싸는 것"}]},{"id":"sec--user-provisioning","term":"User Provisioning","reading":"계정 만들고 지우기","category":"보안 · 인증","summary":"User Provisioning은 **사람이 오고 갈 때 계정을 자동으로 맞추는 일**이다.","aliases":["user provisioning","계정 만들고 지우기"],"related":[{"term":"SSO","note":"— 문을 여는 쪽. 이쪽은 그 문 안에 자리를 만들어 둔다"},{"term":"SAML","note":"— 로그인 정보를 넘겨 주는 규격. 프로비저닝과 짝으로 쓰인다"},{"term":"IAM","note":"— 만들어 둔 계정에 무엇을 허용할지 정하는 자리"},{"term":"Audit Log","note":"— 누가 언제 만들어지고 지워졌는지 남는 자리"},{"term":"Least Privilege","note":"— 만들 때 얼마만큼 줄지 정하는 원칙"}]},{"id":"sec--vulnerability-scanning","term":"Vulnerability Scanning","reading":"구멍 훑기","category":"보안 · 인증","summary":"Vulnerability Scanning은 **남이 적어 둔 구멍 목록으로 내 것을 훑는 점검**이다.","aliases":["vulnerability scanning","구멍 훑기"],"related":[{"term":"CVE","note":"— 훑기가 대조하는 그 목록의 낱개 번호"},{"term":"Zero-Day","note":"— 목록에 아직 없어서 훑어도 안 나오는 구멍"},{"term":"OWASP Top 10","note":"— 웹 쪽 훑기가 주로 겨누는 유형 묶음"},{"term":"Web Application Firewall","note":"— 못 고친 구멍 앞을 임시로 가려 시간을 버는 쪽"},{"term":"Supply Chain Attack","note":"— 가져다 쓴 것을 통해 구멍이 들어오는 경로"}]},{"id":"sec--web-application-firewall","term":"Web Application Firewall","reading":"웹 앞단 방화벽","category":"보안 · 인증","summary":"Web Application Firewall은 **오가는 웹 요청을 규칙에 비춰 걸러내는 앞단**이다.","aliases":["web application firewall","웹 앞단 방화벽"],"related":[{"term":"Firewall","note":"— 포트를 여닫는 쪽. 같은 이름을 쓰지만 보는 층이 다르다"},{"term":"OWASP Top 10","note":"— 앞단의 기본 규칙 묶음이 겨누는 그 목록"},{"term":"SQL Injection","note":"— 앞단이 가장 먼저 알아보는 요청 형태 중 하나"},{"term":"XSS","note":"— 같은 규칙 묶음이 함께 겨누는 다른 형태"},{"term":"Rate Limiting","note":"— 내용이 아니라 횟수로 거는 같은 앞단의 다른 갈래"}]},{"id":"sec--workload-identity-federation","term":"Workload Identity Federation","reading":"일감에 신원을 빌려주기","category":"보안 · 인증","summary":"Workload Identity Federation은 **밖에서 받은 증표를 짧은 자격으로 바꿔 주는 신뢰**다.","aliases":["workload identity federation","일감에 신원을 빌려주기"],"related":[{"term":"IAM","note":"— 들어온 뒤 무엇을 만질 수 있는지를 정하는 쪽"},{"term":"Secret Management","note":"— 오래 사는 열쇠를 그래도 둬야 할 때 숨겨 두는 쪽"},{"term":"OAuth","note":"— 증표를 자격으로 바꾸는 이 교환의 바탕이 되는 약속"},{"term":"JWT","note":"— 밖에서 받아 오는 그 증표가 대개 이 모양이다"},{"term":"Least Privilege","note":"— 받아 온 자격이 열 수 있는 범위를 좁히는 원칙"}]},{"id":"sec--xss","term":"XSS","reading":"Cross-Site Scripting","category":"보안 · 인증","summary":"XSS는 **남의 브라우저에서 내 스크립트를 실행시키는 공격**이다.","aliases":["xss","cross-site scripting"],"related":[{"term":"SQL Injection","note":"— 같은 뿌리의 문제. 이쪽은 DB에서 실행된다"},{"term":"Cookie","note":"— 탈취 대상이자 방어 설정을 거는 곳"},{"term":"CORS","note":"— 다른 출처의 요청을 다루는 별도의 규칙"},{"term":"CSRF","note":"— 같은 브라우저를 노리지만 방향이 반대인 공격"}]},{"id":"sec--zero-trust","term":"Zero Trust","reading":"제로 트러스트","category":"보안 · 인증","summary":"Zero Trust는 **어디서 왔든 매번 다시 확인하는 보안 원칙**이다.","aliases":["zero trust","제로 트러스트"],"related":[{"term":"SSO","note":"— 신원 확인을 한 곳에 모으는 장치. 제로 트러스트의 재료"},{"term":"VPN","note":"— 위치로 신뢰를 주던 옛 방식의 대표"},{"term":"Audit Log","note":"— 확인했다는 사실을 남기는 수단"},{"term":"Step-up Auth","note":"— 위험해 보일 때만 추가 인증을 요구하는 방법"}]},{"id":"sec--zero-day","term":"Zero-Day","reading":"제로데이","category":"보안 · 인증","summary":"제로데이는 **아직 고칠 패치가 없는 보안 구멍**이다.","aliases":["zero-day","제로데이"],"related":[{"term":"CVE","note":"— 이 구멍이 공개되면 붙는 번호. 붙어도 패치가 없으면 여전히 제로데이다"},{"term":"OWASP Top 10","note":"— Log4Shell 을 제로데이 사례로 적어 둔 목록"},{"term":"Supply Chain Attack","note":"— 이 구멍이 남의 부품을 타고 내 앱에 들어오는 경로"},{"term":"Zero Trust","note":"— 막을 것이 없는 때가 있다는 전제에서 안쪽까지 검사하는 쪽"}]},{"id":"sec--term-101f686a","term":"방화벽 규칙","reading":"Firewall Rules","category":"보안 · 인증","summary":"방화벽 규칙은 **어떤 통신을 통과시키고 무엇을 막을지 적어둔 목록**이다.","aliases":["방화벽 규칙","firewall rules"],"related":[{"term":"Firewall","note":"— 이 규칙들을 들고 실제로 판정하는 장치"},{"term":"인바운드 아웃바운드","note":"— 규칙에 적는 두 방향"},{"term":"Port","note":"— 규칙이 가리키는 문의 번호"},{"term":"Zero Trust","note":"— 기본을 차단으로 두는 생각을 전체로 넓힌 것"},{"term":"Bastion Host","note":"— 관리자 접속을 한 곳에 모아 규칙을 단순하게 만드는 방법"}]},{"id":"sec--term-37ee660f","term":"세션","reading":"Session","category":"보안 · 인증","summary":"세션은 **서버가 접속한 사람을 기억해두는 방식**이다.","aliases":["세션","session"],"related":[{"term":"Cookie","note":"— 세션 번호를 브라우저와 서버 사이에 실어 나르는 수단"},{"term":"JWT","note":"— 서버에 저장하지 않고 토큰 안에 정보를 담는 다른 방식"},{"term":"Redis","note":"— 서버 여러 대가 같은 세션을 보게 할 때 쓰는 저장소"},{"term":"CSRF","note":"— 로그인된 세션을 본인 모르게 쓰게 만드는 공격"},{"term":"Token 인증","note":"— 번호 대신 토큰으로 신분을 확인하는 쪽"}]},{"id":"sec--term-7dd2a53a","term":"암호화","reading":"Encryption","category":"보안 · 인증","summary":"암호화는 **열쇠를 가진 사람만 읽을 수 있게 바꾸는 일**이다.","aliases":["암호화","encryption"],"related":[{"term":"Hash","note":"— 되돌릴 길이 없는 쪽. 비밀번호는 이쪽으로 간다"},{"term":"SSL_TLS","note":"— 오가는 통신을 암호화하는 규약"},{"term":"인증서","note":"— 상대의 공개키가 진짜인지 보증하는 문서"},{"term":"HTTPS","note":"— 웹에서 이 암호화가 적용된 결과"}]},{"id":"sec--term-b117da1b","term":"인바운드 / 아웃바운드 트래픽","reading":"Inbound / Outbound","category":"보안 · 인증","summary":"인바운드와 아웃바운드는 **트래픽이 서버로 들어오는지 나가는지의 방향**이다.","aliases":["인바운드 / 아웃바운드 트래픽","inbound / outbound","인바운드 아웃바운드","인바운드","아웃바운드 트래픽","inbound","outbound"],"related":[{"term":"Firewall","note":"— 인바운드와 아웃바운드 규칙이 걸리는 장치"},{"term":"방화벽 규칙","note":"— 방향, 상대, 포트, 허용 여부로 이루어진 한 줄"},{"term":"Port","note":"— 규칙이 가리키는 번호"},{"term":"Subnet","note":"— 규칙에서 상대를 IP 범위로 지정할 때 쓰는 단위"},{"term":"Bastion Host","note":"— SSH 인바운드를 한 곳으로 모아 좁히는 방법"}]},{"id":"sec--term-23d55d60","term":"인증서","reading":"SSL/TLS Certificate","category":"보안 · 인증","summary":"인증서는 **이 사이트가 맞다고 제3자가 보증한 문서**다.","aliases":["인증서","ssl/tls certificate","tls certificate"],"related":[{"term":"HTTPS","note":"— 인증서가 붙어야 성립하는 프로토콜"},{"term":"SSL_TLS","note":"— 인증서를 주고받고 열쇠를 정하는 절차"},{"term":"CA","note":"— 인증서에 서명해주는 발급 기관"},{"term":"암호화","note":"— 인증서가 확인을 마친 뒤 실제로 내용을 가리는 일"},{"term":"Domain","note":"— 인증서에 적힌 이름과 맞춰봐야 하는 대상"}]}]},{"id":"cloud","name":"클라우드","blurb":"남의 컴퓨터를 빌려 쓰는 법","terms":[{"id":"cloud--7r-migration-strategy","term":"7R Migration Strategy","reading":"일곱 갈래 이전 전략","category":"클라우드","summary":"7R Migration Strategy는 **응용마다 어떻게 옮길지 고르는 일곱 갈래**다.","aliases":["7r migration strategy","일곱 갈래 이전 전략"],"related":[{"term":"Cloud Migration","note":"— 이 일곱 갈래가 쓰이는 그 일 자체"},{"term":"Application Dependency Mapping","note":"— 갈래를 붙이기 전에 무엇이 무엇에 붙어 있는지 먼저 그리는 일"},{"term":"Strangler Fig","note":"— 다시 짜기를 한 번에 하지 않고 조금씩 갈아 끼우는 방법"},{"term":"Managed Service","note":"— 바탕 갈아 끼우기가 향하는 대표적인 목적지"},{"term":"CapEx vs OpEx","note":"— 갈래를 고를 때 값을 어느 쪽 장부로 세는지가 갈린다"}]},{"id":"cloud--aws","term":"AWS","reading":"Amazon Web Services","category":"클라우드","summary":"AWS는 **서버와 저장소를 빌려 쓰는 클라우드 묶음**이다.","aliases":["aws","amazon web services"],"related":[{"term":"Cloud","note":"— AWS가 속한 큰 개념. 빌려 쓰는 방식 전체를 가리킨다"},{"term":"EC2","note":"— AWS가 빌려주는 가상 서버"},{"term":"S3","note":"— 파일을 담아두는 저장소"},{"term":"Lambda","note":"— 서버를 띄우지 않고 함수만 돌리는 쪽"},{"term":"Azure","note":"— Microsoft가 같은 자리에서 내놓는 것"}]},{"id":"cloud--application-dependency-mapping","term":"Application Dependency Mapping","reading":"응용 의존 관계 지도","category":"클라우드","summary":"Application Dependency Mapping은 **서로 붙어 있는 것을 찾아 그리는 일**이다.","aliases":["application dependency mapping","응용 의존 관계 지도"],"related":[{"term":"Cloud Migration","note":"— 이 지도를 그리는 목적이 되는 일"},{"term":"7R Migration Strategy","note":"— 지도를 그린 다음에 응용마다 갈래를 붙인다"},{"term":"Service Discovery","note":"— 돌아가는 중에 서로를 찾는 쪽. 이건 옮기기 전에 미리 그리는 쪽이다"},{"term":"Distributed Tracing","note":"— 같은 관계를 옮긴 뒤 운영 중에 계속 보는 방법"},{"term":"Disaster Recovery","note":"— 무엇이 함께 죽는지를 아는 데도 같은 지도가 쓰인다"}]},{"id":"cloud--availability-zone","term":"Availability Zone","reading":"가용 영역","category":"클라우드","summary":"가용 영역은 **한 리전 안에서 전원과 망이 따로 도는 데이터센터 묶음**이다.","aliases":["availability zone","가용 영역"],"related":[{"term":"Region","note":"— 가용 영역을 여러 개 묶는 더 큰 단위"},{"term":"Load Balancer","note":"— 죽은 영역을 빼고 남은 곳으로 요청을 보내는 쪽"},{"term":"VPC","note":"— 여러 가용 영역에 걸쳐 놓는 사설 망"},{"term":"Auto Scaling","note":"— 잃은 만큼 살아 있는 영역에 새로 띄워주는 것"}]},{"id":"cloud--azure","term":"Azure","reading":"Microsoft Azure","category":"클라우드","summary":"Azure는 **Microsoft가 빌려주는 클라우드 플랫폼**이다.","aliases":["azure","microsoft azure"],"related":[{"term":"AWS","note":"— 같은 자리에서 겨루는 Amazon 쪽 플랫폼"},{"term":"Cloud","note":"— Azure가 속한 큰 개념"},{"term":"Kubernetes","note":"— AKS 가 관리형으로 내주는 기반 기술"},{"term":"Serverless","note":"— Azure Functions 가 속한 방식"}]},{"id":"cloud--block-storage","term":"Block Storage","reading":"블록 스토리지","category":"클라우드","summary":"Block Storage 는 서버에 붙여 **디스크처럼 쓰는** 저장소다.","aliases":["block storage","블록 스토리지"],"related":[{"term":"Object Storage","note":"— 같은 자리를 두고 겨루는 다른 저장 방식. 통째로 넣고 꺼낸다"},{"term":"EC2","note":"— 이 볼륨을 붙여 쓰는 쪽"},{"term":"Availability Zone","note":"— 볼륨과 서버가 같이 있어야 하는 범위"},{"term":"File System","note":"— 조각 위에 서버가 얹는 층"},{"term":"VM","note":"— 임시 디스크가 딸려 오는 그 가상 서버"}]},{"id":"cloud--budget-alert","term":"Budget Alert","reading":"예산 경보","category":"클라우드","summary":"Budget Alert는 **쓴 돈이 정한 선에 닿으면 알려 주는 장치**다.","aliases":["budget alert","예산 경보"],"related":[{"term":"FinOps","note":"— 알리고·고르고·바꾸는 세 걸음 중 \"알리기\" 를 맡는 대표 장치"},{"term":"Egress Cost","note":"— 청구서에서 가장 늦게 발견되는 항목. 경보가 없으면 특히 늦다"},{"term":"Alerting","note":"— 같은 구조를 장애 쪽에 쓰는 형제. 문턱을 정해 두고 넘으면 부른다"},{"term":"Auto Scaling","note":"— 자동으로 늘어난 만큼 값도 자동으로 는다"},{"term":"Well-Architected","note":"— 비용 기둥이 이 장치를 기본으로 깔아 두라고 적는다"}]},{"id":"cloud--capex-vs-opex","term":"CapEx vs OpEx","reading":"사서 쓰기와 빌려 쓰기","category":"클라우드","summary":"CapEx vs OpEx는 **장비를 사서 쓰느냐 빌려 쓰느냐의 갈림**이다.","aliases":["capex vs opex","사서 쓰기와 빌려 쓰기","capex","opex"],"related":[{"term":"Reserved Instance","note":"— 미래 사용량을 지금 값에 묶는 대표 장치"},{"term":"Spot Instance","note":"— 끊겨도 되는 일감을 남는 자리에 싸게 태우는 쪽"},{"term":"FinOps","note":"— 매일 결정하는 일이 된 값을 계속 되돌아보는 방식"},{"term":"On-Premises","note":"— 사서 쓰기 쪽의 원래 자리"},{"term":"Budget Alert","note":"— 매달 바뀌는 값을 그 주 안에 알아채는 장치"}]},{"id":"cloud--cloud","term":"Cloud","reading":"클라우드","category":"클라우드","summary":"Cloud는 **컴퓨터 자원을 필요한 만큼 빌려 쓰는 방식**이다.","aliases":["cloud","클라우드"],"related":[{"term":"IaaS_PaaS_SaaS","note":"— 어디까지 맡길지를 나눈 세 가지 층"},{"term":"AWS","note":"— 대표적인 클라우드 제공자"},{"term":"Serverless","note":"— 서버 자체를 의식하지 않는 더 위쪽 방식"},{"term":"EC2","note":"— 빌려 쓰는 가상 서버"},{"term":"S3","note":"— 빌려 쓰는 저장소"}]},{"id":"cloud--cloud-migration","term":"Cloud Migration","reading":"클라우드 마이그레이션","category":"클라우드","summary":"클라우드 마이그레이션은 **쓰던 것을 클라우드로 옮겨 가는 일**이다.","aliases":["cloud migration","클라우드 마이그레이션"],"related":[{"term":"Cloud","note":"— 옮겨 갈 목적지"},{"term":"On-Premises","note":"— 옮기기 전에 살던 곳"},{"term":"Managed Service","note":"— 리플랫폼으로 갈아타는 대표 목적지"},{"term":"Well-Architected","note":"— 최적화 단계에서 드는 잣대"},{"term":"VM","note":"— 재호스팅이 통째로 옮기는 단위"}]},{"id":"cloud--cloud-security-posture-management","term":"Cloud Security Posture Management","reading":"클라우드 보안 자세 관리","category":"클라우드","summary":"Cloud Security Posture Management는 **잘못 잠긴 곳을 계속 찾아내는 일**이다.","aliases":["cloud security posture management","클라우드 보안 자세 관리"],"related":[{"term":"Shared Responsibility Model","note":"— 설정은 쓰는 쪽 몫이라는 선이 이 일이 필요한 이유다"},{"term":"Least Privilege","note":"— 권고 목록에서 가장 많이 걸리는 항목이 권한 과다다"},{"term":"Security Group","note":"— 아무 데서나 들어오게 열린 자리를 세는 대표 대상"},{"term":"Audit Log","note":"— 누가 언제 그 설정을 켰는지는 이쪽이 답한다"},{"term":"Zero Trust","note":"— 자세를 계속 의심하고 다시 재는 사고방식의 큰 틀"}]},{"id":"cloud--cold-start","term":"Cold Start","reading":"콜드 스타트","category":"클라우드","summary":"Cold Start는 **실행 환경을 새로 만드느라 첫 호출이 늦어지는 것**이다.","aliases":["cold start","콜드 스타트"],"related":[{"term":"Serverless","note":"— 쓸 때만 자리를 만드는 방식이라 이 지연이 생긴다"},{"term":"Lambda","note":"— 이 지연이 가장 자주 이야기되는 자리"},{"term":"Auto Scaling","note":"— 자리를 늘리는 순간마다 같은 지연이 새로 생긴다"},{"term":"Latency","note":"— 이 지연이 얹히는 전체 시간"}]},{"id":"cloud--confidential-computing","term":"Confidential Computing","reading":"쓰는 중에도 가리는 계산","category":"클라우드","summary":"Confidential Computing은 **쓰고 있는 중에도 안이 안 보이게 하는 계산**이다.","aliases":["confidential computing","쓰는 중에도 가리는 계산"],"related":[{"term":"Encryption","note":"— 쉴 때와 오갈 때를 맡는 쪽. 이건 남은 한 순간을 맡는다"},{"term":"SSL_TLS","note":"— 오가는 중을 가리는 대표 장치"},{"term":"Tenant","note":"— 같은 기계를 나눠 쓰는 구조가 이 걱정의 출발점이다"},{"term":"Shared Responsibility Model","note":"— 빌려준 쪽을 어디까지 믿느냐의 선을 다시 긋는다"},{"term":"Secret Management","note":"— 열쇠를 어디에 두느냐라는 같은 물음의 다른 자리"}]},{"id":"cloud--container-registry","term":"Container Registry","reading":"컨테이너 레지스트리","category":"클라우드","summary":"Container Registry 는 컨테이너 이미지를 **모아 두고 나눠 주는 곳**이다.","aliases":["container registry","컨테이너 레지스트리"],"related":[{"term":"Docker Image","note":"— 이 창고에 꽂히는 판 그 자체"},{"term":"Container","note":"— 그 판을 띄워 실제로 도는 것"},{"term":"Managed Kubernetes","note":"— 이 창고에서 판을 받아 띄우는 대표적인 쪽"},{"term":"CI/CD","note":"— 판을 만들어 올리는 자동 흐름"},{"term":"IAM","note":"— 누가 올리고 누가 받을 수 있는지 정한다"}]},{"id":"cloud--control-plane-vs-data-plane","term":"Control Plane vs Data Plane","reading":"지시하는 층과 나르는 층","category":"클라우드","summary":"Control Plane vs Data Plane은 **만들고 바꾸는 길과 실제로 일하는 길의 갈림**이다.","aliases":["control plane vs data plane","지시하는 층과 나르는 층","control plane","data plane"],"related":[{"term":"High Availability","note":"— 나르는 층에 기대는 설계가 이 값을 실제로 올린다"},{"term":"Disaster Recovery","note":"— 복구 절차를 어느 층으로 짜느냐가 성패를 가른다"},{"term":"Kubernetes","note":"— 이 갈림을 이름으로 그대로 쓰는 대표 사례"},{"term":"Auto Scaling","note":"— 늘리는 일이 바꾸는 층에 있다는 점이 장애 때 발목을 잡는다"},{"term":"Availability Zone","note":"— 한 구역을 비우는 판단을 어느 층으로 하느냐가 이 이야기의 무대다"}]},{"id":"cloud--cost-allocation-tag","term":"Cost Allocation Tag","reading":"비용 배분 꼬리표","category":"클라우드","summary":"Cost Allocation Tag 는 자원마다 붙여 **청구서를 나눠 보는 이름표**다.","aliases":["cost allocation tag","비용 배분 꼬리표"],"related":[{"term":"FinOps","note":"— 이 꼬리표로 갈린 숫자를 실제 결정으로 바꾸는 일"},{"term":"Egress Cost","note":"— 갈라 봐야 비로소 정체가 드러나는 대표적인 요금"},{"term":"Reserved Instance","note":"— 어디에 얼마가 꾸준히 드는지 안 뒤에 고르는 다음 수"},{"term":"Infrastructure as Code","note":"— 꼬리표를 손이 아니라 코드로 강제하는 자리"},{"term":"Resource Tag","note":"— 꼬리표를 붙이는 규칙 자체. 이 편은 그것이 청구서로 넘어가는 뒷단이다"}]},{"id":"cloud--deletion-protection","term":"Deletion Protection","reading":"삭제 보호","category":"클라우드","summary":"Deletion Protection 은 지우는 명령 자체를 **막아 두는 걸쇠**다.","aliases":["deletion protection","삭제 보호"],"related":[{"term":"IAM","note":"— 사람 쪽에 거는 문. 이 걸쇠는 자원 쪽에 건다"},{"term":"Least Privilege","note":"— 권한을 좁히는 방향. 좁혀도 남는 사고를 이 걸쇠가 맡는다"},{"term":"Disaster Recovery","note":"— 사고가 난 뒤 되돌리는 쪽. 이 걸쇠는 나기 전을 맡는다"},{"term":"Disk Snapshot","note":"— 되돌릴 지점을 미리 떠 두는 짝 장치"},{"term":"Infrastructure as Code","note":"— 이 걸쇠를 손이 아니라 코드로 늘 켜 두는 자리"}]},{"id":"cloud--disk-snapshot","term":"Disk Snapshot","reading":"디스크 순간 사본","category":"클라우드","summary":"Disk Snapshot 은 디스크를 **그 순간 모습 그대로 떠 둔 사본**이다.","aliases":["disk snapshot","디스크 순간 사본"],"related":[{"term":"Block Storage","note":"— 이 사본이 뜨는 대상. 한 대가 자기 판처럼 쓰는 저장소"},{"term":"Point-in-Time Recovery","note":"— 데이터베이스 쪽에서 같은 일을 더 촘촘히 하는 방법"},{"term":"Disaster Recovery","note":"— 이 사본을 어디까지 어떻게 쓸지 정하는 큰 그림"},{"term":"Availability Zone","note":"— 사본이 어디까지 복제되는지를 재는 단위"},{"term":"Deletion Protection","note":"— 사고 자체를 막는 짝 장치. 이쪽은 난 뒤를 맡는다"}]},{"id":"cloud--ec2","term":"EC2","reading":"Elastic Compute Cloud","category":"클라우드","summary":"EC2는 **AWS 에서 시간 단위로 빌려 쓰는 가상 서버**다.","aliases":["ec2","elastic compute cloud"],"related":[{"term":"AWS","note":"— EC2 를 제공하는 쪽"},{"term":"VM","note":"— EC2 인스턴스가 실제로는 이것이다"},{"term":"VPC","note":"— 인스턴스를 놓을 네트워크 공간"},{"term":"Subnet","note":"— 그 VPC 안에서 인스턴스가 실제로 자리 잡는 구획"},{"term":"Auto Scaling","note":"— 인스턴스 대수를 자동으로 조절하려면 따로 붙인다"}]},{"id":"cloud--edge-computing","term":"Edge Computing","reading":"가장자리 계산","category":"클라우드","summary":"Edge Computing 은 계산을 **쓰는 쪽 가까이로 내려 보내는 방식**이다.","aliases":["edge computing","가장자리 계산"],"related":[{"term":"CDN","note":"— 가장자리에 자료를 미리 갖다 두는 쪽. 계산까지 내려보내면 이 단어가 된다"},{"term":"Latency","note":"— 이 방식이 줄이려는 바로 그 값"},{"term":"Region","note":"— 가운데의 큰 자리. 가장자리는 여기서 뻗어 나간 것이다"},{"term":"On-Premises","note":"— 제 건물에 두는 쪽. 가장자리 장비는 여기에 놓이는 일이 많다"},{"term":"Hybrid Cloud","note":"— 가운데와 가장자리를 하나처럼 묶어 쓰는 큰 그림"}]},{"id":"cloud--egress-cost","term":"Egress Cost","reading":"아웃바운드 요금","category":"클라우드","summary":"Egress Cost는 **밖으로 나가는 데이터에 붙는 요금**이다.","aliases":["egress cost","아웃바운드 요금"],"related":[{"term":"CDN","note":"— 나가는 양을 가장자리로 옮겨 원본에서 나가는 몫을 줄인다"},{"term":"S3","note":"— 이 요금이 가장 자주 눈에 띄는 저장소"},{"term":"Region","note":"— 리전을 벗어나는 순간 이 요금이 붙는다"},{"term":"FinOps","note":"— 청구서에서 이 항목을 찾아내는 일하는 방식"},{"term":"Cache","note":"— 같은 것을 두 번 안 내보내게 하는 장치"}]},{"id":"cloud--elastic-ip","term":"Elastic IP","reading":"탄력적 IP","category":"클라우드","summary":"Elastic IP는 **계정이 쥐고 옮겨 붙이는 고정 공인 주소**다.","aliases":["elastic ip","탄력적 ip"],"related":[{"term":"IP Address","note":"— 이 주소가 무엇인지의 바탕"},{"term":"Public IP vs Private IP","note":"— 탄력적 IP 가 다루는 쪽은 공인 주소다"},{"term":"NAT","note":"— 밖으로 나가기만 하면 될 때 주소를 아끼는 방법"},{"term":"Load Balancer","note":"— 고정된 끝점 뒤에 여러 대를 두는 다른 방법"}]},{"id":"cloud--fault-domain-and-update-domain","term":"Fault Domain and Update Domain","reading":"고장 묶음과 갱신 묶음","category":"클라우드","summary":"둘 다 **한꺼번에 같이 내려가는 묶음**인데, 하나는 고장이고 하나는 갱신이다.","aliases":["fault domain and update domain","고장 묶음과 갱신 묶음"],"related":[{"term":"Availability Zone","note":"— 묶음보다 한 단계 큰 나눔. 건물이 통째로 흔들릴 때를 맡는다"},{"term":"High Availability","note":"— 이 나눔이 떠받치는 목표 그 자체"},{"term":"Placement Group","note":"— 같은 고장 축을 AWS·Google 쪽 이름과 숫자로 다루는 편"},{"term":"Rolling Update","note":"— 갱신 묶음과 같은 생각을 내 배포에 적용한 것"},{"term":"Multi-Region","note":"— 지역이 통째로 흔들릴 때를 맡는 더 큰 나눔"}]},{"id":"cloud--file-storage","term":"File Storage","reading":"파일 저장소","category":"클라우드","summary":"File Storage 는 여러 대가 **같은 폴더를 함께 여는** 저장소다.","aliases":["file storage","파일 저장소"],"related":[{"term":"Block Storage","note":"— 한 대가 자기 판처럼 쓰는 쪽. 여럿이 같이 붙이면 깨진다"},{"term":"Object Storage","note":"— 통째로 넣고 꺼내는 쪽. 폴더도 잠금도 없다"},{"term":"NFS","note":"— 이 저장소를 여는 대표 규약"},{"term":"StatefulSet","note":"— 상태를 들고 있어야 하는 컨테이너가 이 저장소를 붙이는 자리"},{"term":"Cloud Migration","note":"— 옛 앱을 코드 안 고치고 옮길 때 이 저장소가 다리가 된다"}]},{"id":"cloud--finops","term":"FinOps","reading":"핀옵스","category":"클라우드","summary":"FinOps는 **클라우드에 쓴 돈을 보이게 하고 계속 다듬는 방식**이다.","aliases":["finops","핀옵스"],"related":[{"term":"Reserved Instance","note":"— 같은 양을 싸게 사는 쪽의 대표 수단"},{"term":"Spot Instance","note":"— 남는 자리를 싸게 빌려 쓰는 다른 수단"},{"term":"Egress Cost","note":"— 청구서에서 늦게 발견되는 대표 항목"},{"term":"Cloud","note":"— 쓴 만큼 낸다는 구조 때문에 이 일이 필요해졌다"},{"term":"Auto Scaling","note":"— 덜 쓰는 쪽을 자동으로 맞추는 장치"}]},{"id":"cloud--hybrid-cloud","term":"Hybrid Cloud","reading":"섞어 쓰는 클라우드","category":"클라우드","summary":"Hybrid Cloud 는 따로인 두 곳을 **하나처럼 묶어 쓰는 방식**이다.","aliases":["hybrid cloud","섞어 쓰는 클라우드"],"related":[{"term":"Cloud","note":"— 섞는 두 쪽 중 빌리는 쪽"},{"term":"On-Premises","note":"— 섞는 두 쪽 중 제 것인 쪽"},{"term":"Cloud Migration","note":"— 한 번에 다 못 옮길 때 이 방식이 다리가 된다"},{"term":"Egress Cost","note":"— 두 곳 사이를 오가는 자료에 붙는 값"},{"term":"Edge Computing","note":"— 가장자리로 뻗는 쪽. 섞어 쓰기의 한 갈래로 자주 겹친다"}]},{"id":"cloud--iaas-paas-saas","term":"IaaS / PaaS / SaaS","reading":"","category":"클라우드","summary":"IaaS, PaaS, SaaS는 **클라우드가 어디까지 맡느냐**로 나뉜 세 단계다.","aliases":["iaas / paas / saas","iaas_paas_saas","iaas","paas","saas"],"related":[{"term":"Cloud","note":"— 이 세 가지를 묶어 부르는 상위 개념"},{"term":"On-Premises","note":"— 아무것도 맡기지 않고 전부 직접 하는 쪽"},{"term":"VM","note":"— IaaS에서 빌리는 서버의 실체"},{"term":"Serverless","note":"— 실행 환경조차 의식하지 않는, PaaS보다 더 넘긴 형태"},{"term":"Container","note":"— 애플리케이션을 통째로 묶어 어느 층에서든 같게 돌리는 방법"}]},{"id":"cloud--immutable-storage","term":"Immutable Storage","reading":"고칠 수 없는 저장소","category":"클라우드","summary":"Immutable Storage 는 정해 둔 기간 동안 **아무도 못 지우는** 저장소다.","aliases":["immutable storage","고칠 수 없는 저장소"],"related":[{"term":"Object Versioning","note":"— AWS 는 판 보관을 켠 통에서만 이 잠금을 걸 수 있다"},{"term":"Object Storage","note":"— 이 잠금이 걸리는 저장소"},{"term":"Object Lifecycle Policy","note":"— 자동으로 지우는 규칙. 잠긴 개체에는 안 먹는다"},{"term":"Immutable Infrastructure","note":"— 같은 \"고치지 않는다\" 생각을 서버 쪽에 적용한 것"},{"term":"Disaster Recovery","note":"— 마지막 한 벌을 지키려는 목적이 여기서 만난다"}]},{"id":"cloud--instance-metadata-service","term":"Instance Metadata Service","reading":"인스턴스 신원 조회 창구","category":"클라우드","summary":"Instance Metadata Service 는 그 서버가 **자기 정보를 물어보는** 고정 주소다.","aliases":["instance metadata service","인스턴스 신원 조회 창구"],"related":[{"term":"EC2","note":"— AWS 에서 이 창구가 붙어 있는 그 한 대"},{"term":"IAM","note":"— 창구가 내주는 임시 열쇠에 어떤 권한이 실릴지 정하는 쪽"},{"term":"Secret Management","note":"— 열쇠를 심어야 할 때 쓰는 다른 길. 창구는 심을 필요를 없앤다"},{"term":"Instance Template","note":"— 이 창구로 읽히는 시작 스크립트가 들어 있는 틀"},{"term":"Least Privilege","note":"— 임시 열쇠라도 권한이 넓으면 새었을 때 똑같이 위험하다"}]},{"id":"cloud--instance-template","term":"Instance Template","reading":"인스턴스 붕어빵 틀","category":"클라우드","summary":"Instance Template 은 같은 서버를 몇 대든 똑같이 찍어 내는 **틀**이다.","aliases":["instance template","인스턴스 붕어빵 틀"],"related":[{"term":"Auto Scaling","note":"— 이 틀을 들여다보고 대를 늘리고 줄이는 쪽"},{"term":"EC2","note":"— AWS 에서 이 틀로 찍혀 나오는 그 한 대"},{"term":"Immutable Infrastructure","note":"— 고치지 않고 새로 찍어 바꾼다는 같은 생각"},{"term":"Rolling Update","note":"— 새 틀로 도는 대를 한 대씩 갈아 끼우는 방법"},{"term":"Infrastructure as Code","note":"— 이 틀 자체를 글로 적어 두고 형상 관리하는 쪽"}]},{"id":"cloud--lambda","term":"Lambda","reading":"AWS Lambda","category":"클라우드","summary":"Lambda는 **함수만 올려두고 부를 때만 실행하는 서비스**다.","aliases":["lambda","aws lambda"],"related":[{"term":"Serverless","note":"— Lambda가 속한 큰 갈래"},{"term":"API Gateway","note":"— HTTP 요청을 Lambda로 넘겨주는 앞단"},{"term":"S3","note":"— 파일이 올라온 사건으로 Lambda를 깨우는 곳"},{"term":"EC2","note":"— 켜두고 쓰는 쪽. 비용 계산이 반대로 간다"},{"term":"Container","note":"— Lambda가 함수를 담아 띄우는 단위"}]},{"id":"cloud--landing-zone","term":"Landing Zone","reading":"첫 착륙장","category":"클라우드","summary":"Landing Zone 은 일을 올리기 전에 **미리 깔아 두는** 클라우드 바닥이다.","aliases":["landing zone","첫 착륙장"],"related":[{"term":"Well-Architected","note":"— 착륙장이 지키려는 설계 원칙을 정리해 둔 쪽"},{"term":"IAM","note":"— 누가 어느 칸에 들어올 수 있는지를 정하는 부분"},{"term":"VPC","note":"— 착륙장이 미리 깔아 두는 망 그 자체"},{"term":"Infrastructure as Code","note":"— 착륙장을 손이 아니라 글로 깔게 만드는 도구"},{"term":"Audit Log","note":"— 모든 칸의 기록을 한 계정에 모으는 것이 착륙장의 기본 항목이다"}]},{"id":"cloud--managed-kubernetes","term":"Managed Kubernetes","reading":"관리형 쿠버네티스","category":"클라우드","summary":"Managed Kubernetes 는 **컨트롤 플레인을 클라우드가 맡는** 쿠버네티스다.","aliases":["managed kubernetes","관리형 쿠버네티스"],"related":[{"term":"Kubernetes","note":"— 관리형이 대신 맡아 주는 그 물건 자체"},{"term":"Container Registry","note":"— 클러스터가 띄울 판을 받아 오는 창고"},{"term":"Container","note":"— 노드 위에서 실제로 도는 것"},{"term":"Auto Scaling","note":"— 노드를 늘리고 줄이는 장치"},{"term":"VM","note":"— 노드로 쓰이는 가상 머신"}]},{"id":"cloud--managed-service","term":"Managed Service","reading":"관리형 서비스","category":"클라우드","summary":"관리형 서비스는 **운영 일감을 제공자가 대신 맡는 서비스**다.","aliases":["managed service","관리형 서비스"],"related":[{"term":"Shared Responsibility Model","note":"— 관리형은 그 선을 제공자 쪽으로 밀어 올린 것"},{"term":"IaaS_PaaS_SaaS","note":"— 얼마나 관리해 주느냐로 클라우드를 세 칸으로 나눈 구분"},{"term":"Serverless","note":"— 관리형을 끝까지 밀어 실행 자리까지 감춘 형태"},{"term":"EC2","note":"— 운영을 내가 맡는 쪽의 대표"},{"term":"Cloud Migration","note":"— 관리형으로 갈아타는 것이 이전 방식 중 하나다"}]},{"id":"cloud--multi-region","term":"Multi-Region","reading":"멀티 리전","category":"클라우드","summary":"멀티 리전은 **지역 하나가 통째로 멈춰도 다른 지역이 받게 하는 구성**이다.","aliases":["multi-region","멀티 리전"],"related":[{"term":"Region","note":"— 나누는 단위 그 자체"},{"term":"Availability Zone","note":"— 한 리전 안에서 나누는 더 작은 단위"},{"term":"Replication","note":"— 다른 리전에 자료를 따라가게 하는 방법"},{"term":"DNS","note":"— 사용자를 어느 리전으로 보낼지 정하는 자리"}]},{"id":"cloud--object-lifecycle-policy","term":"Object Lifecycle Policy","reading":"객체 수명 규칙","category":"클라우드","summary":"Object Lifecycle Policy 는 오래된 파일을 **저절로 내리거나 지우는** 규칙이다.","aliases":["object lifecycle policy","객체 수명 규칙"],"related":[{"term":"Object Storage","note":"— 이 규칙이 걸리는 저장소"},{"term":"Object Versioning","note":"— 옛 판을 남기는 쪽. 이 규칙과 짝을 지어야 값이 안 샌다"},{"term":"Immutable Storage","note":"— 잠긴 개체에는 이 규칙의 삭제가 통하지 않는다"},{"term":"FinOps","note":"— 이 규칙이 실제로 줄이는 것이 무엇인지 세는 쪽"},{"term":"Storage Class","note":"— 이 규칙이 파일을 옮겨 넣는 칸들. 값과 꺼내는 시간이 여기서 갈린다"}]},{"id":"cloud--object-storage","term":"Object Storage","reading":"오브젝트 스토리지","category":"클라우드","summary":"Object Storage 는 파일을 **통째로 넣고 통째로 꺼내는** 저장소다.","aliases":["object storage","오브젝트 스토리지"],"related":[{"term":"S3","note":"— AWS 가 이 개념을 파는 이름"},{"term":"Block Storage","note":"— 같은 자리를 두고 겨루는 다른 저장 방식. 조각 단위로 고칠 수 있다"},{"term":"CDN","note":"— 오브젝트를 사용자 가까운 곳에 복사해 두는 앞단"},{"term":"File System","note":"— 폴더 나무로 파일을 다루는 방식. 오브젝트에는 그 나무가 없다"},{"term":"IAM","note":"— 어떤 계정이 통에 무엇을 할 수 있는지 정한다"}]},{"id":"cloud--object-versioning","term":"Object Versioning","reading":"객체 판 보관","category":"클라우드","summary":"Object Versioning 은 덮어쓰거나 지운 옛 파일을 **그대로 남겨 두는** 설정이다.","aliases":["object versioning","객체 판 보관"],"related":[{"term":"Object Storage","note":"— 판이 쌓이는 그 저장소"},{"term":"Object Lifecycle Policy","note":"— 쌓인 옛 판을 정리하는 짝. 없으면 값이 계속 는다"},{"term":"Immutable Storage","note":"— 잠금이 걸리는 단위가 바로 이 판이다"},{"term":"Point-in-Time Recovery","note":"— 데이터베이스 쪽에서 같은 일을 하는 방법"},{"term":"Disaster Recovery","note":"— 사람의 실수를 견디는 층으로 이 설정이 들어간다"}]},{"id":"cloud--offline-bulk-data-transfer","term":"Offline Bulk Data Transfer","reading":"장비로 실어 나르는 대량 전송","category":"클라우드","summary":"Offline Bulk Data Transfer 는 큰 자료를 **선 대신 차로** 옮기는 방법이다.","aliases":["offline bulk data transfer","장비로 실어 나르는 대량 전송"],"related":[{"term":"Cloud Migration","note":"— 이 방법이 쓰이는 가장 흔한 자리"},{"term":"Object Storage","note":"— 실어 나른 자료가 결국 도착하는 통"},{"term":"Egress Cost","note":"— 반대 방향으로 내려받을 때 선을 쓰면 붙는 값"},{"term":"Disaster Recovery","note":"— 클라우드에 있는 것을 사내로 되가져올 때 같은 장비를 쓴다"},{"term":"Data Lake","note":"— 옮겨 놓은 대량 자료가 자리 잡는 곳"}]},{"id":"cloud--placement-group","term":"Placement Group","reading":"배치 묶음","category":"클라우드","summary":"Placement Group 은 **여러 대를 어디에 놓을지 거는 조건**이다.","aliases":["placement group","배치 묶음"],"related":[{"term":"Availability Zone","note":"— 떼어 놓기의 가장 굵은 눈금. 붙여 놓기는 이 선을 못 넘는다"},{"term":"High Availability","note":"— 배치 조건이 결국 무엇을 사려는 것인지"},{"term":"EC2","note":"— 이 조건을 거는 대상이 되는 기계"},{"term":"Auto Scaling","note":"— 늘었다 줄었다 하는 무리에 붙여 놓기가 잘 안 맞는 이유"},{"term":"Latency","note":"— 붙여 놓기로 사려는 값 그 자체"}]},{"id":"cloud--private-endpoint","term":"Private Endpoint","reading":"사설 접점","category":"클라우드","summary":"Private Endpoint 는 **바깥 서비스를 내 망 안 주소로 끌어들이는 입구**다.","aliases":["private endpoint","사설 접점"],"related":[{"term":"VPC","note":"— 사설 주소를 꽂아 넣을 내 망 그 자체"},{"term":"Subnet","note":"— 접점의 랜카드가 실제로 앉는 칸"},{"term":"DNS","note":"— 같은 이름을 안팎에서 다르게 풀어 주는 장치"},{"term":"Security Group","note":"— 접점에 닿을 수 있는 쪽을 다시 한 번 좁히는 자리"},{"term":"Egress Cost","note":"— 인터넷으로 안 나가면서 함께 줄어드는 값"}]},{"id":"cloud--region","term":"Region","reading":"리전","category":"클라우드","summary":"Region은 **클라우드 업체가 한 지역에 세운 독립된 데이터센터 묶음**이다.","aliases":["region","리전"],"related":[{"term":"Availability Zone","note":"— 리전 안에서 다시 나뉘는 단위. 견디는 사고의 크기가 다르다"},{"term":"DNS","note":"— 요청을 어느 리전으로 보낼지 정해주는 자리"},{"term":"Latency","note":"— 리전을 어디에 둘지 정할 때 재는 값"},{"term":"CDN","note":"— 리전보다 촘촘한 지점에 복사본을 두어 거리를 더 줄이는 쪽"},{"term":"VPC","note":"— 리전 안에 만드는 가상 네트워크. 리전을 넘어가지 않는다"}]},{"id":"cloud--reserved-instance","term":"Reserved Instance","reading":"예약 인스턴스","category":"클라우드","summary":"Reserved Instance는 **오래 쓰겠다고 약속하고 요금을 깎는 계약**이다.","aliases":["reserved instance","예약 인스턴스"],"related":[{"term":"Spot Instance","note":"— 반대쪽 선택. 약속 없이 싸게 쓰고 끊김을 받는다"},{"term":"EC2","note":"— 이 할인이 가장 먼저 붙는 자리"},{"term":"Region","note":"— 할인이 붙는 조건에 리전이 들어간다"},{"term":"FinOps","note":"— 이 계약을 언제 살지 정하는 일하는 방식"},{"term":"Cloud","note":"— 쓴 만큼 낸다는 기본 규칙 위에 얹힌 예외"}]},{"id":"cloud--resource-hierarchy","term":"Resource Hierarchy","reading":"자원 계층","category":"클라우드","summary":"Resource Hierarchy 는 **규칙이 위에서 아래로 흐르는 나무**다.","aliases":["resource hierarchy","자원 계층"],"related":[{"term":"IAM","note":"— 위에서 아래로 흐르는 것이 무엇인지, 그 권한의 이름"},{"term":"Least Privilege","note":"— 층마다 천장을 낮춰 가는 원칙 그 자체"},{"term":"Resource Tag","note":"— 계층이 못 가르는 축을 가로질러 붙이는 이름표"},{"term":"FinOps","note":"— 그릇 단위로 갈린 값을 실제로 읽고 쓰는 쪽"},{"term":"Tenant","note":"— 이 나무 한 그루가 통째로 한 손님이라는 관점"}]},{"id":"cloud--resource-tag","term":"Resource Tag","reading":"자원 꼬리표","category":"클라우드","summary":"Resource Tag 는 **자원에 붙여 두는 낱말 한 쌍**이다.","aliases":["resource tag","자원 꼬리표"],"related":[{"term":"Resource Hierarchy","note":"— 그릇으로 갈리는 축. 꼬리표는 그 축을 가로지른다"},{"term":"Cost Allocation Tag","note":"— 이 쪽지로 값을 가르는 쪽만 따로 떼어 본 편"},{"term":"IAM","note":"— 꼬리표 값을 조건으로 권한을 거는 자리"},{"term":"Infrastructure as Code","note":"— 사람 손이 아니라 코드로 꼬리표를 붙게 만드는 방법"},{"term":"Rightsizing","note":"— 어느 것을 줄일지 고를 때 먼저 거르는 기준"}]},{"id":"cloud--rightsizing","term":"Rightsizing","reading":"크기 맞추기","category":"클라우드","summary":"Rightsizing 은 **쓰는 만큼으로 크기를 다시 맞추는 일**이다.","aliases":["rightsizing","크기 맞추기"],"related":[{"term":"FinOps","note":"— 이 일을 누가 언제 하는지 정하는 살림 방식"},{"term":"Auto Scaling","note":"— 크기 대신 대수로 맞추는 다른 길"},{"term":"Reserved Instance","note":"— 미리 사 둔 할인. 크기를 바꾸기 전에 확인할 것"},{"term":"Metric","note":"— 크기 맞추기가 근거로 삼는 잰 값 그 자체"},{"term":"Resource Requests and Limits","note":"— 같은 일을 쿠버네티스 안에서 하는 자리"}]},{"id":"cloud--s3","term":"S3","reading":"Simple Storage Service","category":"클라우드","summary":"S3는 **AWS가 파일을 맡아 보관해주는 저장소**다.","aliases":["s3","simple storage service"],"related":[{"term":"AWS","note":"— S3를 제공하는 쪽"},{"term":"CDN","note":"— S3 앞에 두어 파일을 가까운 곳에서 주게 한다"},{"term":"Lambda","note":"— 파일이 올라온 것을 신호로 받아 뒤처리를 돌린다"},{"term":"EC2","note":"— 파일을 들고 있지 않게 되는 쪽. 서버는 주소만 안다"},{"term":"IAM","note":"— 어떤 계정이 버킷에 무엇을 할 수 있는지 정한다"}]},{"id":"cloud--security-group","term":"Security Group","reading":"보안 그룹","category":"클라우드","summary":"보안 그룹은 **자원 하나하나에 붙는 허용 규칙 묶음**이다.","aliases":["security group","보안 그룹"],"related":[{"term":"VPC","note":"— 보안 그룹이 사는 사설망. 그룹은 이 안의 자원에 붙는다"},{"term":"방화벽 규칙","note":"— 무엇을 열고 막을지 적는 규칙 일반"},{"term":"인바운드 / 아웃바운드 트래픽","note":"— 규칙을 나누는 두 방향"},{"term":"VPC Peering","note":"— 상대 망의 그룹을 출발지로 참조할 수 있게 하는 연결"}]},{"id":"cloud--serverless","term":"Serverless","reading":"서버리스","category":"클라우드","summary":"Serverless는 **서버를 직접 띄우지 않고 함수만 올려 실행하는 방식**이다.","aliases":["serverless","서버리스"],"related":[{"term":"Lambda","note":"— 서버리스 함수의 대표적인 구현"},{"term":"Container","note":"— 서버리스 실행 환경의 바탕이 되는 기술"},{"term":"IaaS_PaaS_SaaS","note":"— 클라우드 서비스 구분에서 서버리스의 자리"},{"term":"Latency","note":"— 첫 호출이 느려지는 현상을 재는 잣대"}]},{"id":"cloud--service-quota","term":"Service Quota","reading":"서비스 상한","category":"클라우드","summary":"Service Quota 는 **한 계정이 얼마까지 쓸 수 있는지의 상한**이다.","aliases":["service quota","서비스 상한"],"related":[{"term":"Rate Limiting","note":"— 초당 몇 번까지를 재는 쪽. 상한의 한 갈래다"},{"term":"Auto Scaling","note":"— 자동으로 늘다가 이 벽에 먼저 부딪히는 장치"},{"term":"Disaster Recovery","note":"— 복구 지역의 상한이 복구 시간을 늘리는 자리"},{"term":"Multi-Region","note":"— 지역마다 따로 세어진다는 사실이 바로 걸리는 설계"},{"term":"Reserved Instance","note":"— 상한과 달리 자리까지 잡아 두는 물건"}]},{"id":"cloud--shared-responsibility-model","term":"Shared Responsibility Model","reading":"책임 공유 모델","category":"클라우드","summary":"책임 공유 모델은 **클라우드의 안전을 제공자와 내가 나눠 맡는 약속**이다.","aliases":["shared responsibility model","책임 공유 모델"],"related":[{"term":"IaaS_PaaS_SaaS","note":"— 이 선이 어느 높이에 그어지는지를 정하는 구분"},{"term":"Managed Service","note":"— 선을 제공자 쪽으로 밀어 올린 서비스"},{"term":"Well-Architected","note":"— 선의 내 쪽 칸을 무엇으로 채울지 묻는 목록"},{"term":"IAM","note":"— 어느 형태에서도 내 몫으로 남는 계정과 권한"},{"term":"Zero Trust","note":"— 내 칸 안에서 무엇을 믿을지 정하는 원칙"}]},{"id":"cloud--spot-instance","term":"Spot Instance","reading":"스팟 인스턴스","category":"클라우드","summary":"Spot Instance는 **남는 자리를 싸게 쓰되 언제든 회수당하는 서버**다.","aliases":["spot instance","스팟 인스턴스"],"related":[{"term":"Reserved Instance","note":"— 반대쪽 선택. 약속을 걸고 값을 깎는다"},{"term":"EC2","note":"— 이 자리를 파는 대표 서비스"},{"term":"Auto Scaling","note":"— 회수된 자리를 다시 채워 주는 장치"},{"term":"Availability Zone","note":"— 남는 용량이 존마다 따로 있어 값도 존마다 다르다"},{"term":"FinOps","note":"— 이 선택을 언제 할지 정하는 일하는 방식"}]},{"id":"cloud--startup-script","term":"Startup Script","reading":"시동 스크립트","category":"클라우드","summary":"Startup Script 는 **기계가 켜질 때 저절로 도는 명령 묶음**이다.","aliases":["startup script","시동 스크립트"],"related":[{"term":"Auto Scaling","note":"— 사람이 못 붙는 시각에 대가 늘어나는, 이 물건이 필요한 자리"},{"term":"Immutable Infrastructure","note":"— 켜질 때 고치지 말고 미리 구워 두라는 반대편 주장"},{"term":"Ansible","note":"— 같은 일을 켜진 뒤에 밖에서 밀어 넣는 방식"},{"term":"Secret Management","note":"— 여기 적으면 안 되는 것을 대신 맡아 두는 자리"},{"term":"Environment Variable","note":"— 기계마다 다른 값을 넘기는 더 작은 그릇"}]},{"id":"cloud--storage-class","term":"Storage Class","reading":"저장 등급","category":"클라우드","summary":"Storage Class 는 **얼마나 자주 꺼낼지**로 나눈 저장 요금제다.","aliases":["storage class","저장 등급"],"related":[{"term":"Object Storage","note":"— 등급이 붙는 대상. 오브젝트 하나하나가 제 등급을 갖는다"},{"term":"S3","note":"— AWS 가 이 등급들을 파는 이름"},{"term":"Storage Redundancy","note":"— 같은 저장소를 값이 아니라 여벌의 위치로 나눈 다른 축"},{"term":"Egress Cost","note":"— 밖으로 내보낼 때 붙는 또 다른 값. 등급의 꺼내기 요금과 따로 센다"},{"term":"FinOps","note":"— 등급 고르기를 한 번이 아니라 매달의 일로 만드는 자리"}]},{"id":"cloud--storage-redundancy","term":"Storage Redundancy","reading":"저장 이중화","category":"클라우드","summary":"Storage Redundancy 는 같은 파일을 **몇 군데에 몇 벌** 둘지 고르는 설정이다.","aliases":["storage redundancy","저장 이중화"],"related":[{"term":"Availability Zone","note":"— 한 지역 안에서 여벌을 흩어 두는 단위"},{"term":"Region","note":"— 여벌을 여기까지 보낼지가 값과 견딤을 가르는 경계"},{"term":"Multi-Region","note":"— 여벌뿐 아니라 서비스까지 여러 지역에 두는 다음 단계"},{"term":"Storage Class","note":"— 같은 저장소를 값의 축으로 나눈 짝. 등급에 따라 못 쓰는 이중화가 있다"},{"term":"Disaster Recovery","note":"— 여벌이 실제로 쓰이는 순간의 절차"}]},{"id":"cloud--subnet","term":"Subnet","reading":"서브넷","category":"클라우드","summary":"Subnet은 **큰 네트워크를 쪼개놓은 작은 구획**이다.","aliases":["subnet","서브넷"],"related":[{"term":"VPC","note":"— 서브넷이 속하는 상위 네트워크"},{"term":"Availability Zone","note":"— 서브넷 하나가 묶이는 물리적 단위"},{"term":"IP Address","note":"— 서브넷이 나누는 대상"},{"term":"NAT","note":"— 비공개 구획이 바깥으로 나갈 때 거치는 장치"},{"term":"방화벽 규칙","note":"— 구획 안팎의 실제 허용을 정하는 자리"}]},{"id":"cloud--tenant","term":"Tenant","reading":"테넌트","category":"클라우드","summary":"테넌트는 **같은 시스템을 나눠 쓰면서 서로 격리된 고객 단위**다.","aliases":["tenant","테넌트"],"related":[{"term":"Multi-tenancy","note":"— 테넌트를 여럿 받는 구조 자체를 가리키는 말"},{"term":"IaaS_PaaS_SaaS","note":"— 테넌트 개념이 실제로 쓰이는 서비스 모델"},{"term":"RBAC","note":"— 테넌트 안에서 누가 무엇을 볼지 다시 나누는 장치"},{"term":"VPC","note":"— 자원까지 갈라놓고 싶을 때 쓰는 네트워크 단위"},{"term":"DB","note":"— 격리 방식을 고르는 자리"}]},{"id":"cloud--total-cost-of-ownership","term":"Total Cost of Ownership","reading":"총 보유 비용","category":"클라우드","summary":"Total Cost of Ownership 은 사는 값이 아니라 **끝까지 드는 값 전부**다.","aliases":["total cost of ownership","총 보유 비용"],"related":[{"term":"FinOps","note":"— 이 계산을 한 번이 아니라 매달 돌리는 일로 만든 것"},{"term":"Cloud Migration","note":"— 총 보유 비용 계산이 가장 자주 쓰이는 결정"},{"term":"Reserved Instance","note":"— 미래 사용을 약속해 총합을 낮추는 대표 수단"},{"term":"Egress Cost","note":"— 옮기고 나서야 보이는, 견적서에서 가장 자주 빠지는 줄"},{"term":"Well-Architected","note":"— 비용 최적화를 설계의 한 기둥으로 세운 틀"}]},{"id":"cloud--vpc","term":"VPC","reading":"Virtual Private Cloud","category":"클라우드","summary":"VPC는 **클라우드 안에 내 것만 있는 사설 네트워크**다.","aliases":["vpc","virtual private cloud"],"related":[{"term":"Subnet","note":"— VPC를 다시 나눈 구간"},{"term":"방화벽 규칙","note":"— 무엇을 열고 막을지 적는 규칙"},{"term":"Zero Trust","note":"— 경계 안쪽도 믿지 않는 반대 방향의 원칙"},{"term":"VPN","note":"— 사내망과 VPC를 잇는 방법 중 하나"}]},{"id":"cloud--vpc-peering","term":"VPC Peering","reading":"VPC 피어링","category":"클라우드","summary":"VPC 피어링은 **두 사설망을 사설 주소로 잇는 1대1 연결**이다.","aliases":["vpc peering","vpc 피어링"],"related":[{"term":"VPC","note":"— 피어링이 잇는 두 대상. 이 경계를 유지한 채 이어 준다"},{"term":"Security Group","note":"— 연결한 뒤에도 이쪽을 열어야 트래픽이 통한다"},{"term":"Subnet","note":"— 대역이 겹치는지 따질 때 실제로 견주는 단위"},{"term":"IPSec VPN","note":"— 망 밖의 상대와 이을 때 쓰는 다른 방법"}]},{"id":"cloud--well-architected","term":"Well-Architected","reading":"잘 설계된 프레임워크","category":"클라우드","summary":"Well-Architected는 **설계가 좋은지 기둥별로 캐묻는 질문 목록**이다.","aliases":["well-architected","잘 설계된 프레임워크"],"related":[{"term":"Shared Responsibility Model","note":"— 기둥별로 채울 칸이 어디까지 내 몫인지 그은 선"},{"term":"Availability Zone","note":"— 안정성 기둥이 가장 먼저 묻는 자리"},{"term":"Auto Scaling","note":"— 성능 효율과 비용 최적화가 함께 걸리는 장치"},{"term":"Managed Service","note":"— 운영 우수성 기둥의 일감을 제공자에게 넘기는 방법"},{"term":"Cloud Migration","note":"— 옮긴 뒤 최적화 단계에서 이 목록을 잣대로 쓴다"}]}]},{"id":"infra","name":"인프라 · 운영","blurb":"띄우고, 굴리고, 지켜본다","terms":[{"id":"infra--alerting","term":"Alerting","reading":"알림","category":"인프라 · 운영","summary":"Alerting은 **정해 둔 조건에 걸리면 사람을 부르는 일**이다.","aliases":["alerting","알림"],"related":[{"term":"Prometheus","note":"— 조건을 따져 알림을 만드는 쪽"},{"term":"Grafana","note":"— 화면에서 규칙을 걸고 받을 곳을 정하는 쪽"},{"term":"Health Check","note":"— 사람을 부르기 전에 기계가 먼저 빼고 넣는 자동 대응"},{"term":"Escalation","note":"— 부른 사람이 못 풀 때 위로 넘기는 다음 단계"},{"term":"Logging","note":"— 알림을 받고 나서 원인을 찾으러 가는 자리"}]},{"id":"infra--ansible","term":"Ansible","reading":"앤서블","category":"인프라 · 운영","summary":"Ansible 은 **떨어져 있는 기계들을 적어 둔 상태로 맞추는 도구**다.","aliases":["ansible","앤서블"],"related":[{"term":"Infrastructure as Code","note":"— Ansible 이 속한 방식"},{"term":"Terraform","note":"— 기계를 세우는 쪽. Ansible 은 세워진 뒤 그 안을 채운다"},{"term":"YAML","note":"— 플레이북을 적는 형식"},{"term":"GitOps","note":"— 이 지시서를 저장소에 두고 자동으로 맞추는 방식"},{"term":"Linux","note":"— 관리 노드가 되는 대표적인 운영체제"}]},{"id":"infra--apache","term":"Apache","reading":"아파치 웹 서버","category":"인프라 · 운영","summary":"Apache는 **HTTP 요청을 받아 웹 페이지를 돌려주는 오픈소스 서버**다.","aliases":["apache","아파치 웹 서버"],"related":[{"term":"Nginx","note":"— 같은 자리를 맡는 다른 웹 서버. 비교 대상으로 자주 붙는다"},{"term":"HTTP","note":"— Apache가 주고받는 규약"},{"term":"Reverse Proxy","note":"— 웹 서버 앞에 서서 요청을 뒤로 넘기는 자리"},{"term":"Linux","note":"— Apache를 서비스로 올려두는 바탕"}]},{"id":"infra--backup-retention-policy","term":"Backup Retention Policy","reading":"백업 보관 규칙","category":"인프라 · 운영","summary":"Backup Retention Policy는 **백업을 언제까지 두고 언제 지울지 정한 규칙**이다.","aliases":["backup retention policy","백업 보관 규칙"],"related":[{"term":"Disaster Recovery","note":"— 남겨 둔 사본으로 무엇을 어디까지 되살릴지 짜 두는 계획"},{"term":"RPO and RTO","note":"— 보관 규칙이 지켜야 할 두 숫자"},{"term":"Object Lifecycle Policy","note":"— 같은 생각을 저장소 안의 파일 하나하나에 적용한 것"},{"term":"Immutable Storage","note":"— 기한이 끝나기 전 삭제를 아예 막는 저장 방식"},{"term":"Disk Snapshot","note":"— 이 규칙이 관리하는 사본의 가장 흔한 형태"}]},{"id":"infra--bare-metal","term":"Bare Metal","reading":"베어 메탈","category":"인프라 · 운영","summary":"Bare Metal은 **가상화 없이 물리 서버를 통째로 쓰는 방식**이다.","aliases":["bare metal","베어 메탈"],"related":[{"term":"VM","note":"— 하드웨어 위에 가상 서버를 여러 대 올리는 쪽. 베어 메탈이 뺀 계층이 여기다"},{"term":"Container","note":"— 운영체제는 하나로 두고 프로세스만 나눈다. 중간 무게다"},{"term":"Hypervisor","note":"— 가상 서버를 만들고 관리하는 소프트웨어"},{"term":"On-Premises","note":"— 장비를 직접 두고 쓰는 것. 베어 메탈은 그 위에서 어떻게 쓸지의 문제다"}]},{"id":"infra--blue-green-deployment","term":"Blue-Green Deployment","reading":"블루 그린 배포","category":"인프라 · 운영","summary":"Blue-Green Deployment 은 **똑같은 환경 두 벌 사이에서 트래픽을 옮기는 배포**다.","aliases":["blue-green deployment","블루 그린 배포"],"related":[{"term":"Canary Release","note":"— 한 번에 다 넘기지 않고 몫을 조금씩 넘기는 다른 방식"},{"term":"Rollback","note":"— 이 방식이 전환 한 번으로 값싸게 만들어 주는 바로 그 동작"},{"term":"Load Balancer","note":"— 어느 환경으로 보낼지 실제로 가리키는 앞단"},{"term":"CI/CD","note":"— 초록 환경을 세우고 검증까지 자동으로 돌리는 자리"},{"term":"Migration","note":"— 두 환경이 같이 보기 때문에 되돌리기가 안 되는 쪽"}]},{"id":"infra--ci-cd","term":"CI/CD","reading":"지속적 통합과 배포","category":"인프라 · 운영","summary":"CI/CD는 **코드를 올리면 검사와 배포가 자동으로 도는 파이프라인**이다.","aliases":["ci/cd","지속적 통합과 배포","ci_cd","ci","cd"],"related":[{"term":"Docker","note":"— 파이프라인이 만들어내는 산출물이자 실행 환경"},{"term":"Kubernetes","note":"— 만들어진 이미지를 받아 배포하는 다음 단계"},{"term":"Git","note":"— 파이프라인을 촉발하는 지점"},{"term":"Build","note":"— 파이프라인의 첫 단계"}]},{"id":"infra--canary-release","term":"Canary Release","reading":"카나리 배포","category":"인프라 · 운영","summary":"Canary Release 는 **새 버전을 일부에게만 먼저 내보내 지켜보는 배포**다.","aliases":["canary release","카나리 배포"],"related":[{"term":"Blue-Green Deployment","note":"— 몫을 나누지 않고 한 번에 통째로 옮기는 다른 방식"},{"term":"Rollback","note":"— 카나리가 나쁘다고 판정됐을 때 실제로 하는 일"},{"term":"Feature Flag","note":"— 배포를 건드리지 않고 기능만 일부에게 켜 주는 방법"},{"term":"Load Balancer","note":"— 어느 몫을 새 쪽으로 보낼지 실제로 가르는 자리"},{"term":"A/B Testing","note":"— 같은 분할을 안전이 아니라 효과 측정에 쓰는 쪽"}]},{"id":"infra--capacity-planning","term":"Capacity Planning","reading":"용량 미리 재기","category":"인프라 · 운영","summary":"Capacity Planning은 **앞으로 필요한 자원의 양을 미리 재어 두는 일**이다.","aliases":["capacity planning","용량 미리 재기"],"related":[{"term":"Load Test","note":"— 재어 둔 값이 실제로 견디는지 미리 걸어 보는 시험"},{"term":"Service Quota","note":"— 대수보다 먼저 걸리는 계정 단위 한도"},{"term":"Rightsizing","note":"— 이미 잡아 둔 자원이 남는지 되재는 쪽"},{"term":"Horizontal Pod Autoscaler","note":"— 재어 둔 범위 안에서 자동으로 늘리고 줄이는 장치"},{"term":"Metric","note":"— 예측의 재료가 되는 지난 숫자"}]},{"id":"infra--chaos-engineering","term":"Chaos Engineering","reading":"카오스 엔지니어링","category":"인프라 · 운영","summary":"Chaos Engineering은 **고장을 일부러 넣어 견디는지 보는 실험**이다.","aliases":["chaos engineering","카오스 엔지니어링"],"related":[{"term":"Circuit Breaker","note":"— 고장이 번지지 않게 끊는 장치. 그게 실제로 도는지 확인하는 것이 이 실험이다"},{"term":"Availability Zone","note":"— 통째로 꺼 놓고 견디는지 보는 대표 대상"},{"term":"Load Test","note":"— 고장 대신 사용량을 걸어 보는 이웃 시험"},{"term":"Disaster Recovery","note":"— 견디지 못했을 때를 대비해 미리 짜 두는 복구 계획"}]},{"id":"infra--configmap-vs-secret","term":"ConfigMap vs Secret","reading":"컨피그맵과 시크릿","category":"인프라 · 운영","summary":"ConfigMap 과 Secret 은 **설정을 이미지 밖으로 빼 두는 두 그릇**이다.","aliases":["configmap vs secret","컨피그맵과 시크릿","configmap","secret"],"related":[{"term":"Environment Variable","note":"— 두 그릇의 값을 파드에 넣는 가장 흔한 통로"},{"term":"Secret Management","note":"— 클러스터 밖 금고에 맡기는 더 강한 방법"},{"term":"etcd","note":"— Secret 이 실제로 적혀 있는 자리"},{"term":"Base64","note":"— Secret 값이 적히는 그 꼴. 암호가 아니다"},{"term":"Pod","note":"— 값을 받아 실제로 쓰는 쪽"}]},{"id":"infra--configuration-drift","term":"Configuration Drift","reading":"설정 표류","category":"인프라 · 운영","summary":"Configuration Drift는 **적어 둔 설정과 실제 기계가 조용히 어긋나는 일**이다.","aliases":["configuration drift","설정 표류"],"related":[{"term":"Infrastructure as Code","note":"— 어긋남을 잴 기준이 되는 \"적어 둔 것\""},{"term":"Immutable Infrastructure","note":"— 손댈 자리를 아예 없애 표류를 막는 쪽"},{"term":"Terraform","note":"— plan -refresh-only 로 이 어긋남을 보여주는 도구"},{"term":"GitOps","note":"— 저장소를 유일한 기준으로 두고 어긋나면 되맞추는 방식"},{"term":"Runbook","note":"— 급한 밤의 손 조작을 글로 남겨 표류를 줄이는 자리"}]},{"id":"infra--container-runtime-interface","term":"Container Runtime Interface","reading":"컨테이너 런타임 인터페이스","category":"인프라 · 운영","summary":"kubelet 이 어떤 런타임과도 말할 수 있게 정한 **하나의 규약**이다.","aliases":["container runtime interface","컨테이너 런타임 인터페이스"],"related":[{"term":"Kubernetes","note":"— 이 약속의 손님 쪽인 kubelet 이 사는 곳"},{"term":"Container","note":"— 이 약속 너머에서 실제로 만들어지는 것"},{"term":"OCI","note":"— 그 너머의 이미지와 실행 방식을 정한 다른 규격"},{"term":"Docker","note":"— 규약이 생기기 전 본체 안에 박혀 있던 쪽"},{"term":"Pod","note":"— 이 약속이 만들고 없애는 단위"}]},{"id":"infra--continuous-profiling","term":"Continuous Profiling","reading":"돌아가는 중에 재는 속내","category":"인프라 · 운영","summary":"Continuous Profiling은 **돌아가는 중에 어느 코드가 자원을 쓰는지 계속 재는 일**이다.","aliases":["continuous profiling","돌아가는 중에 재는 속내"],"related":[{"term":"Observability","note":"— 밖에서 물어 안을 알아내는 성질. 이 값도 그 재료 중 하나다"},{"term":"Distributed Tracing","note":"— 어느 구간에서 오래 걸렸는지를 맡는 이웃 신호"},{"term":"Metric","note":"— 얼마나 느린지까지만 말하는 숫자"},{"term":"Load Test","note":"— 재기 좋은 상황을 일부러 만들어 주는 쪽"},{"term":"Latency","note":"— 이 값이 결국 줄이려는 대상"}]},{"id":"infra--cron-job","term":"Cron Job","reading":"크론 잡","category":"인프라 · 운영","summary":"Cron Job은 **정해진 시각마다 명령을 자동 실행하는 예약 작업**이다.","aliases":["cron job","크론 잡"],"related":[{"term":"Logging","note":"— cron이 남긴 실행 결과를 확인하는 자리"},{"term":"Cache","note":"— 캐시를 주기적으로 갱신할 때 흔히 cron을 쓴다"},{"term":"Kubernetes","note":"— 여러 대에 흩어진 예약 작업을 한곳에서 관리하는 쪽"},{"term":"CI_CD","note":"— 정해진 시각마다 빌드를 돌릴 때도 같은 방식이 쓰인다"}]},{"id":"infra--daemonset","term":"DaemonSet","reading":"데몬셋","category":"인프라 · 운영","summary":"DaemonSet은 **노드마다 파드를 한 개씩 깔아 두는 것**이다.","aliases":["daemonset","데몬셋"],"related":[{"term":"Pod","note":"— 노드마다 하나씩 깔리는 그 단위"},{"term":"Deployment (Kubernetes)","note":"— 개수로 정하는 쪽. 어디에 뜨는지는 안 정한다"},{"term":"Taint and Toleration","note":"— 아픈 노드에도 남게 해 주는 그 장치"},{"term":"Logging","note":"— 노드마다 하나씩 두는 가장 흔한 쓰임"},{"term":"Metric","note":"— 노드 상태를 재서 내보내는 다른 쓰임"}]},{"id":"infra--deployment","term":"Deployment","reading":"Kubernetes) (디플로이먼트","category":"인프라 · 운영","summary":"Deployment는 **적어 둔 대로 파드 개수와 판을 맞춰 주는 것**이다.","aliases":["deployment","kubernetes) (디플로이먼트","deployment (kubernetes)"],"related":[{"term":"Pod","note":"— Deployment 가 개수를 맞추는 대상"},{"term":"Rolling Update","note":"— 겹쳐 가며 갈아 끼우는 그 방식"},{"term":"Rollback","note":"— 옛 묶음을 도로 키워 되돌리는 일"},{"term":"StatefulSet","note":"— 파드마다 이름과 디스크가 필요할 때 쓰는 다른 쪽"},{"term":"Horizontal Pod Autoscaler","note":"— `replicas` 숫자를 자동으로 올리고 내리는 쪽"}]},{"id":"infra--devops","term":"DevOps","reading":"","category":"인프라 · 운영","summary":"DevOps는 **개발과 운영을 한 팀이 함께 맡는 방식**이다.","aliases":["devops"],"related":[{"term":"CI_CD","note":"— DevOps에서 자동화가 실제로 돌아가는 줄기"},{"term":"Docker","note":"— 개발과 운영 환경을 같게 만드는 데 쓴다"},{"term":"Kubernetes","note":"— 컨테이너를 배포하고 굴리는 자리"},{"term":"Git","note":"— 파이프라인의 방아쇠인 커밋이 여기서 일어난다"},{"term":"Container","note":"— 환경을 통째로 묶어 옮기는 단위"}]},{"id":"infra--disaster-recovery","term":"Disaster Recovery","reading":"재해 복구","category":"인프라 · 운영","summary":"Disaster Recovery는 **재해에 대비하고 그 뒤에 되살아나는 일**이다.","aliases":["disaster recovery","재해 복구"],"related":[{"term":"Replication","note":"— 다른 지역으로 데이터를 계속 넘겨 두는 수단"},{"term":"Region","note":"— 예비 자리를 어디에 둘지 고르는 단위"},{"term":"Availability Zone","note":"— 지역 안의 고장을 나눠 받는 단위. 지역 전체가 나가면 그 밖의 대비가 필요하다"},{"term":"Chaos Engineering","note":"— 계획이 실제로 되는지 미리 확인하는 방법"}]},{"id":"infra--distributed-tracing","term":"Distributed Tracing","reading":"분산 추적","category":"인프라 · 운영","summary":"Distributed Tracing은 **요청 하나가 지나간 길을 여러 대에 걸쳐 잇는 것**이다.","aliases":["distributed tracing","분산 추적"],"related":[{"term":"Observability","note":"— 세 신호 중 \"어느 구간\" 을 맡는 쪽이 이것이다"},{"term":"Metric","note":"— \"얼마나\" 를 맡는 짝. 이상을 먼저 알리는 쪽이다"},{"term":"Logging","note":"— 같은 번호로 이어 붙여 그 순간의 문장까지 내려간다"},{"term":"OpenTelemetry","note":"— 이 자취를 만들고 실어 나르는 공통 규격"},{"term":"Latency","note":"— 추적이 구간별로 쪼개서 보여주는 그 시간"}]},{"id":"infra--elastic-search","term":"Elastic Search","reading":"엘라스틱서치","category":"인프라 · 운영","summary":"Elastic Search 는 **글을 단어로 쪼개 미리 색인해두는 검색 엔진**이다.","aliases":["elastic search","엘라스틱서치"],"related":[{"term":"Index","note":"— 미리 만들어두는 단어 목록. 속도의 이유"},{"term":"NoSQL","note":"— 문서를 그대로 담아 두고 뒤진다는 점이 닮았다"},{"term":"Semantic Search","note":"— 단어가 아니라 뜻이 가까운지로 찾는 쪽"},{"term":"Logging","note":"— 쌓인 로그를 뒤질 때 자주 함께 쓰인다"}]},{"id":"infra--failover-and-failback","term":"Failover and Failback","reading":"넘어가기와 되돌아오기","category":"인프라 · 운영","summary":"Failover and Failback은 **예비 쪽으로 넘겼다가 원래 자리로 되돌아오는 한 쌍**이다.","aliases":["failover and failback","넘어가기와 되돌아오기"],"related":[{"term":"Disaster Recovery","note":"— 이 한 쌍을 언제 어떻게 쓸지 적어 둔 계획"},{"term":"RPO and RTO","note":"— 어느 시점으로 얼마 만에 넘길지를 재는 두 숫자"},{"term":"Pilot Light and Warm Standby","note":"— 예비 쪽을 얼마나 켜 둘지 고르는 방식"},{"term":"Health Check","note":"— 자동 전환을 켤 때 방아쇠가 되는 확인"},{"term":"Replication","note":"— 넘어갈 수 있게 자료를 미리 보내 두는 일"}]},{"id":"infra--file-descriptor-limit","term":"File Descriptor Limit","reading":"파일 서술자 한도","category":"인프라 · 운영","summary":"File Descriptor Limit 은 **한 프로세스가 동시에 열어 둘 수 있는 개수의 상한**이다.","aliases":["file descriptor limit","파일 서술자 한도"],"related":[{"term":"Socket","note":"— 접속 하나가 번호표 한 장인 대표적인 예"},{"term":"Process","note":"— 이 한도가 걸리는 단위"},{"term":"Connection Pool","note":"— 번호표를 빌려 쓰고 돌려주게 만드는 장치"},{"term":"File System","note":"— 번호표가 가리키는 것들이 사는 곳"},{"term":"systemd","note":"— 데몬으로 뜨는 프로세스의 한도를 정해 주는 쪽"}]},{"id":"infra--gitops","term":"GitOps","reading":"깃옵스","category":"인프라 · 운영","summary":"GitOps 는 **저장소에 적힌 상태로 실제 환경을 계속 맞추는 방식**이다.","aliases":["gitops","깃옵스"],"related":[{"term":"Infrastructure as Code","note":"— 선언으로 적어 두는 부분을 GitOps 가 그대로 쓴다"},{"term":"Git","note":"— 그 선언이 사는 자리이자 변경 이력이 쌓이는 곳"},{"term":"Kubernetes","note":"— 이 방식이 가장 먼저 자리 잡은 실행 환경"},{"term":"CI/CD","note":"— 만들어 내는 쪽. GitOps 는 반영하는 쪽을 맡는다"},{"term":"Terraform","note":"— 인프라 쪽 선언을 같은 결로 다루는 도구"}]},{"id":"infra--golden-image","term":"Golden Image","reading":"기준이 되는 원본 이미지","category":"인프라 · 운영","summary":"Golden Image는 **똑같은 기계를 찍어 내는 기준 원본 한 장**이다.","aliases":["golden image","기준이 되는 원본 이미지"],"related":[{"term":"Immutable Infrastructure","note":"— 고쳐 쓰지 않고 다시 굽는다는 생각의 큰 갈래"},{"term":"Configuration Drift","note":"— 판을 안 쓸 때 대끼리 벌어지는 바로 그 차이"},{"term":"Patch Management","note":"— 판을 언제 다시 구울지 정하는 쪽"},{"term":"Instance Template","note":"— 구운 판으로 어떻게 띄울지 적어 두는 틀"},{"term":"Docker Image","note":"— 같은 생각을 컨테이너에 적용한 형태"}]},{"id":"infra--graceful-shutdown","term":"Graceful Shutdown","reading":"우아한 종료","category":"인프라 · 운영","summary":"Graceful Shutdown 은 **새 일은 그만 받고 하던 일을 끝낸 뒤 내려가는 것**이다.","aliases":["graceful shutdown","우아한 종료"],"related":[{"term":"Kubernetes","note":"— 파드를 내릴 때 이 절차를 실제로 밟는 쪽"},{"term":"Load Balancer","note":"— 내려가는 대상에는 새 요청을 안 보내는 앞단"},{"term":"Rollback","note":"— 되돌릴 때도 옛 판을 내리면서 같은 절차를 밟는다"},{"term":"Nginx","note":"— 신호마다 빠른 종료와 우아한 종료를 갈라 둔 예"},{"term":"Process","note":"— 신호를 받고 끝나는 그 단위"}]},{"id":"infra--grafana","term":"Grafana","reading":"그라파나","category":"인프라 · 운영","summary":"Grafana는 **값이 사는 곳에 물어서 화면에 그려 주는 도구**다.","aliases":["grafana","그라파나"],"related":[{"term":"Prometheus","note":"— 이 화면이 가장 흔히 물어보는 저장소"},{"term":"Alerting","note":"— 화면이 비는 시간을 메우는 짝"},{"term":"Logging","note":"— 지표 옆에 겹쳐 보는 또 하나의 데이터 소스"},{"term":"Elastic Search","note":"— 로그 쪽 데이터 소스로 자주 붙는 저장소"},{"term":"DevOps","note":"— 이 화면을 벽에 걸어두는 일하는 방식"}]},{"id":"infra--health-check","term":"Health Check","reading":"헬스 체크","category":"인프라 · 운영","summary":"Health Check는 **멀쩡한지 주기마다 물어 걸러 내는 짧은 확인**이다.","aliases":["health check","헬스 체크"],"related":[{"term":"Load Balancer","note":"— 이 확인 결과로 보낼 대상을 고르는 쪽"},{"term":"Kubernetes","note":"— 세 가지 확인을 나눠 쓰는 대표적인 자리"},{"term":"Auto Scaling","note":"— 새로 늘린 대상도 이 확인을 통과해야 목록에 든다"},{"term":"Alerting","note":"— 기계가 스스로 못 고칠 때 사람을 부르는 다음 단계"},{"term":"Prometheus","note":"— 확인이 몇 번 실패했는지를 숫자로 쌓아 두는 쪽"}]},{"id":"infra--helm","term":"Helm","reading":"헬름","category":"인프라 · 운영","summary":"Helm은 **쿠버네티스 앱을 꾸러미로 묶어 설치하고 되돌리는 도구**다.","aliases":["helm","헬름"],"related":[{"term":"Kubernetes","note":"— 헬름이 자원을 올려 놓는 곳"},{"term":"Pod","note":"— 차트가 만들어 내는 자원의 끝에 서는 것"},{"term":"Ingress","note":"— 그 컨트롤러를 차트로 설치하는 것이 흔한 예다"},{"term":"Dependency","note":"— 차트가 다른 차트에 기대는 관계도 같은 말이다"},{"term":"Docker Image","note":"— 차트가 값으로 골라 넣는 재료"}]},{"id":"infra--horizontal-pod-autoscaler","term":"Horizontal Pod Autoscaler","reading":"수평 파드 자동 확장기","category":"인프라 · 운영","summary":"쓰는 양에 맞춰 **파드 대수를 스스로 늘리고 줄이는** 장치다.","aliases":["horizontal pod autoscaler","수평 파드 자동 확장기"],"related":[{"term":"Pod","note":"— 이 장치가 세고 늘리는 단위"},{"term":"Resource Requests and Limits","note":"— 퍼센트를 계산할 밑변이 되는 값"},{"term":"Auto Scaling","note":"— 대수를 부하에 맞추는 생각 전체의 이름"},{"term":"Metric","note":"— 확장기가 15초마다 읽어 가는 숫자"},{"term":"Load Test","note":"— 목표치를 얼마로 잡을지 정하기 전에 재 보는 자리"}]},{"id":"infra--hypervisor","term":"Hypervisor","reading":"하이퍼바이저","category":"인프라 · 운영","summary":"Hypervisor는 **한 대의 컴퓨터를 여러 대처럼 나눠 쓰게 하는 소프트웨어**다.","aliases":["hypervisor","하이퍼바이저"],"related":[{"term":"VM","note":"— 하이퍼바이저가 만들고 관리하는 대상"},{"term":"Container","note":"— 하이퍼바이저 없이 OS 커널을 나눠 쓰는 다른 방식"},{"term":"VPS","note":"— 하이퍼바이저로 나눈 한 칸을 빌려주는 상품"},{"term":"Bare Metal","note":"— 나누지 않고 하드웨어를 통째로 쓰는 쪽"}]},{"id":"infra--iops-and-throughput","term":"IOPS and Throughput","reading":"초당 작업 수와 초당 양","category":"인프라 · 운영","summary":"IOPS and Throughput은 **저장 장치를 재는 초당 건수와 초당 양**이다.","aliases":["iops and throughput","초당 작업 수와 초당 양"],"related":[{"term":"Block Storage","note":"— 이 두 숫자로 성능을 파는 저장 방식"},{"term":"Latency","note":"— 한 건이 끝나기까지 걸리는 시간. 건수와 짝으로 본다"},{"term":"RAID","note":"— 여러 장을 묶어 이 두 숫자를 늘리는 오래된 방법"},{"term":"Cache","note":"— 요청이 장치까지 안 가게 해서 두 숫자를 아끼는 쪽"},{"term":"Load Test","note":"— 어느 상한에 먼저 닿는지 실제로 걸어 보는 시험"}]},{"id":"infra--immutable-infrastructure","term":"Immutable Infrastructure","reading":"불변 인프라","category":"인프라 · 운영","summary":"Immutable Infrastructure는 **고치지 않고 새로 세워 갈아 끼우는 방식**이다.","aliases":["immutable infrastructure","불변 인프라"],"related":[{"term":"Blue-Green Deployment","note":"— 새 무리로 넘어가는 두 방법 중 통째로 옮기는 쪽"},{"term":"Canary Release","note":"— 소수만 새 무리로 보내 지켜보는 다른 방법"},{"term":"Infrastructure as Code","note":"— 갈아 끼울 것을 무엇으로 정의하는지를 맡는 쪽"},{"term":"Configuration Drift","note":"— 이 방식이 애초에 막으려는 바로 그 현상"},{"term":"Rollback","note":"— 옛 무리를 다시 켜는 일 그 자체"}]},{"id":"infra--infrastructure-as-code","term":"Infrastructure as Code","reading":"코드형 인프라","category":"인프라 · 운영","summary":"Infrastructure as Code 는 **인프라를 손이 아니라 코드로 만드는 방식**이다.","aliases":["infrastructure as code","코드형 인프라"],"related":[{"term":"Terraform","note":"— 이 방식으로 인프라를 만드는 대표 도구"},{"term":"Ansible","note":"— 만들어 놓은 기계의 안을 적힌 상태로 맞추는 쪽"},{"term":"GitOps","note":"— 이 정의 파일을 어디에 두고 누가 적용할지까지 정한 방식"},{"term":"DevOps","note":"— IaC 가 속한 더 큰 실천"},{"term":"CI/CD","note":"— 이 파일을 사람 손 없이 적용하는 자리"}]},{"id":"infra--ingress","term":"Ingress","reading":"인그레스","category":"인프라 · 운영","summary":"Ingress는 **밖에서 온 웹 요청을 어느 서비스로 보낼지 적어 둔 규칙**이다.","aliases":["ingress","인그레스"],"related":[{"term":"Kubernetes","note":"— 인그레스가 자원으로 사는 곳"},{"term":"Pod","note":"— 규칙을 타고 들어온 요청이 결국 닿는 곳"},{"term":"Reverse Proxy","note":"— 인그레스 컨트롤러가 실제로 하는 일의 원래 이름"},{"term":"Load Balancer","note":"— 4계층에서 나누는 쪽. 인그레스는 그 위 7계층에서 가른다"},{"term":"HTTPS","note":"— 인그레스가 그 자리에서 끊어 주는 연결"}]},{"id":"infra--kubernetes","term":"Kubernetes","reading":"쿠버네티스","category":"인프라 · 운영","summary":"Kubernetes는 **컨테이너를 어디에 몇 개 띄울지 알아서 관리하는 시스템**이다.","aliases":["kubernetes","쿠버네티스"],"related":[{"term":"Container","note":"— 쿠버네티스가 관리하는 대상"},{"term":"Docker","note":"— 그 컨테이너 이미지를 만드는 도구"},{"term":"Load Balancer","note":"— 파드로 요청을 나누는 데 쓰인다"},{"term":"CI_CD","note":"— 새 이미지를 만들어 클러스터에 넘기는 앞 단계"}]},{"id":"infra--lvm","term":"LVM","reading":"논리 볼륨 관리자","category":"인프라 · 운영","summary":"LVM은 **여러 디스크를 한 덩어리로 묶어 다시 잘라 쓰는 중간 층**이다.","aliases":["lvm","논리 볼륨 관리자"],"related":[{"term":"File System","note":"— 이 층이 만든 칸 위에 얹혀 실제 파일을 다루는 층"},{"term":"RAID","note":"— 같은 원반들을 묶지만 목적이 다르다. 저쪽은 여벌을 만든다"},{"term":"Block Storage","note":"— 클라우드에서 이 층 밑에 깔리는 원반의 이름"},{"term":"Disaster Recovery","note":"— 스냅숏이 대신하지 못하는 자리를 맡는 쪽"},{"term":"Linux","note":"— 이 층이 커널의 device-mapper 로 구현되어 있는 바탕"}]},{"id":"infra--linux-namespace","term":"Linux Namespace","reading":"리눅스 이름공간","category":"인프라 · 운영","summary":"Linux Namespace 는 **프로세스마다 무엇이 보이는지를 나누는 커널 기능**이다.","aliases":["linux namespace","리눅스 이름공간"],"related":[{"term":"Container","note":"— 이 칸막이 위에 서 있는 것"},{"term":"cgroups","note":"— 같은 커널의 짝. 이쪽은 보이는 범위, 저쪽은 쓸 수 있는 양"},{"term":"Kernel","note":"— 이 칸막이를 실제로 만들어 주는 쪽"},{"term":"Pod","note":"— 여러 컨테이너가 일부 범위를 나눠 갖는 묶음"},{"term":"Docker","note":"— 이 기능들을 묶어 쓰기 쉽게 만든 도구"}]},{"id":"infra--liveness-probe-vs-readiness-probe","term":"Liveness Probe vs Readiness Probe","reading":"살아있음 검사와 준비됨 검사","category":"인프라 · 운영","summary":"컨테이너를 재시작할지 트래픽만 끊을지를 가르는 **두 검사**다.","aliases":["liveness probe vs readiness probe","살아있음 검사와 준비됨 검사","liveness probe","readiness probe"],"related":[{"term":"Health Check","note":"— 주기와 연속 횟수로 판정하는 확인의 일반 이름. 그 안에 무엇을 담을지는 이 편이 맡는다"},{"term":"Pod","note":"— 두 검사가 실제로 걸리는 자리"},{"term":"Graceful Shutdown","note":"— 목록에서 빠진 뒤 남은 것을 마저 처리하는 쪽"},{"term":"Rolling Update","note":"— 준비됨 검사가 통과해야 다음 파드로 넘어간다"},{"term":"Load Balancer","note":"— 목록에서 빠진 파드에 안 보내는 일을 맡는 앞단"}]},{"id":"infra--load-average","term":"Load Average","reading":"부하 평균","category":"인프라 · 운영","summary":"Load Average 는 **일하려고 줄 서 있는 프로세스 수의 최근 평균**이다.","aliases":["load average","부하 평균"],"related":[{"term":"CPU","note":"— 줄이 향하는 그 자원"},{"term":"Process","note":"— 줄에 서 있는 그 단위"},{"term":"Metric","note":"— 이 값을 재서 모아 두는 자리"},{"term":"Alerting","note":"— 이 값이 선을 넘으면 사람을 부르는 쪽"},{"term":"Latency","note":"— 줄이 길어졌을 때 사용자가 실제로 겪는 것"}]},{"id":"infra--load-shedding","term":"Load Shedding","reading":"부하 덜어내기","category":"인프라 · 운영","summary":"Load Shedding은 **넘치는 요청을 일부러 빨리 거절해 나머지를 살리는 일**이다.","aliases":["load shedding","부하 덜어내기"],"related":[{"term":"Rate Limiting","note":"— 미리 정한 몫으로 나누는 쪽. 이쪽은 넘친 뒤에 고른다"},{"term":"Circuit Breaker","note":"— 부르는 쪽에서 끊는 장치. 이쪽은 받는 쪽에서 끊는다"},{"term":"Back Pressure","note":"— 넘치는 양을 상류에 알려 속도를 늦추게 하는 방법"},{"term":"Retry & Exponential Backoff","note":"— 거절 뒤의 행동. 잘못 걸면 덜어낸 만큼 되돌아온다"},{"term":"Auto Scaling","note":"— 용량을 늘리는 쪽. 늘어나는 동안을 덜어내기가 버틴다"}]},{"id":"infra--load-test","term":"Load Test","reading":"부하 테스트","category":"인프라 · 운영","summary":"Load Test는 **예상한 만큼의 사용량을 미리 걸어 보는 시험**이다.","aliases":["load test","부하 테스트"],"related":[{"term":"Latency","note":"— 부하 테스트가 재는 대표 지표"},{"term":"Auto Scaling","note":"— 사용량이 늘 때 서버를 늘려 주는 쪽. 그 설정이 제때 도는지도 이 시험으로 본다"},{"term":"CI/CD","note":"— 부하 테스트를 배포 관문으로 걸어 두는 자리"},{"term":"Chaos Engineering","note":"— 사용량 대신 고장을 넣어 보는 이웃 시험"}]},{"id":"infra--log-routing","term":"Log Routing","reading":"기록 흘려보내기","category":"인프라 · 운영","summary":"Log Routing은 **어느 기록을 어디로 보낼지 미리 정해 두는 규칙**이다.","aliases":["log routing","기록 흘려보내기"],"related":[{"term":"Logging","note":"— 흘려보낼 그 한 줄을 만들어 내는 쪽"},{"term":"Observability","note":"— 흘려보내 모아 둔 기록이 있어야 성립하는 성질"},{"term":"OpenTelemetry","note":"— 받고 손보고 내보내는 길을 한 규격으로 정한 쪽"},{"term":"Elastic Search","note":"— 흘려보낸 줄이 도착해 실제로 뒤져지는 대표 목적지"},{"term":"Distributed Tracing","note":"— 같은 줄에 붙은 자취 번호로 다른 신호와 이어지는 자리"}]},{"id":"infra--logging","term":"Logging","reading":"로그, 로깅","category":"인프라 · 운영","summary":"Logging은 **프로그램이 한 일을 나중에 볼 수 있게 남기는 일**이다.","aliases":["logging","로그, 로깅"],"related":[{"term":"Audit Log","note":"— 누가 무엇을 했는지에 초점을 맞춘 기록"},{"term":"Elastic Search","note":"— 모아둔 로그를 검색하는 데 흔히 쓰는 저장소"},{"term":"JSON","note":"— 구조화 로그를 남길 때 쓰는 형식"},{"term":"Latency","note":"— 단계마다 남긴 시간을 모아 보는 값"}]},{"id":"infra--metric","term":"Metric","reading":"메트릭","category":"인프라 · 운영","summary":"Metric은 **일정 기간의 숫자를 합쳐 요약한 값**이다.","aliases":["metric","메트릭"],"related":[{"term":"Observability","note":"— 메트릭이 맡는 물음은 그 셋 중 \"얼마나\" 다"},{"term":"Distributed Tracing","note":"— 숫자가 이상하다고 말한 뒤 \"어디서\" 로 데려가는 짝"},{"term":"Logging","note":"— 버려진 낱낱의 사건이 남는 자리"},{"term":"OpenTelemetry","note":"— 메트릭을 재고 내보내는 공통 규격"},{"term":"Latency","note":"— 히스토그램으로 분포를 봐야 하는 대표 값"}]},{"id":"infra--nfs","term":"NFS","reading":"망 파일 시스템","category":"인프라 · 운영","summary":"NFS는 **남의 기계에 있는 폴더를 내 폴더처럼 쓰게 하는 약속**이다.","aliases":["nfs","망 파일 시스템"],"related":[{"term":"File System","note":"— 이 약속이 흉내 내는 대상. 로컬 파일 시스템처럼 보이게 한다"},{"term":"TCP","note":"— 파일 호출이 실제로 실려 가는 연결"},{"term":"Object Storage","note":"— \"여러 대가 같은 파일을\" 이라는 같은 문제를 다르게 푸는 쪽"},{"term":"Block Storage","note":"— 한 대만 붙이는 원반. 이쪽은 여러 대가 동시에 붙는다"}]},{"id":"infra--ntp","term":"NTP","reading":"망 시각 프로토콜","category":"인프라 · 운영","summary":"NTP는 **여러 기계의 시계를 같은 시각에 맞춰 두는 약속**이다.","aliases":["ntp","망 시각 프로토콜"],"related":[{"term":"TTL","note":"— 시각이 어긋나면 기한을 세는 값도 같이 어긋난다"},{"term":"Logging","note":"— 여러 대의 기록을 한 줄로 세우려면 시각이 먼저 맞아야 한다"},{"term":"Distributed Tracing","note":"— 구간의 앞뒤를 시각으로 이어 붙이는 쪽"},{"term":"Alerting","note":"— 시각 어긋남이 커지는 것을 재서 울리게 걸어 두는 자리"},{"term":"Metric","note":"— 어긋난 폭 자체를 숫자로 내보내는 신호"}]},{"id":"infra--namespace","term":"Namespace","reading":"Kubernetes) (쿠버네티스 이름공간","category":"인프라 · 운영","summary":"Namespace는 **한 클러스터 안을 이름이 안 겹치는 칸으로 나눈 것**이다.","aliases":["namespace","kubernetes) (쿠버네티스 이름공간","namespace (kubernetes)"],"related":[{"term":"Kubernetes","note":"— 이 칸을 두는 클러스터 쪽"},{"term":"Pod","note":"— 반드시 어느 한 칸에 속하는 대표적인 것"},{"term":"Service (Kubernetes)","note":"— 칸 이름이 그대로 DNS 이름에 들어가는 쪽"},{"term":"RBAC","note":"— 칸 하나만 열어 주는 권한을 거는 방법"},{"term":"Linux Namespace","note":"— 이름만 같고 층이 다른 리눅스 커널 쪽 개념"}]},{"id":"infra--node-pool","term":"Node Pool","reading":"같은 규격 기계 묶음","category":"인프라 · 운영","summary":"Node Pool은 **설정이 똑같은 기계들을 한 덩어리로 다루는 단위**다.","aliases":["node pool","같은 규격 기계 묶음"],"related":[{"term":"Kubernetes","note":"— 이 묶음들이 모여 이루는 판"},{"term":"Pod","note":"— 묶음 안의 기계 위에 실제로 올라가는 일감"},{"term":"Taint and Toleration","note":"— 어떤 일감만 그 묶음에 앉히도록 거르는 장치"},{"term":"Horizontal Pod Autoscaler","note":"— 일감 수를 늘리는 쪽. 묶음이 늘리는 것은 기계 수다"},{"term":"Resource Requests and Limits","note":"— 일감이 요구한 양이 어느 묶음에 들어갈 수 있는지를 정한다"}]},{"id":"infra--oci","term":"OCI","reading":"열린 컨테이너 규격","category":"인프라 · 운영","summary":"컨테이너의 이미지·실행·배포 방식을 정해 둔 **세 벌의 규격**이다.","aliases":["oci","열린 컨테이너 규격"],"related":[{"term":"Container Runtime Interface","note":"— 쿠버네티스가 이 규격을 지키는 실행기를 부르는 통로"},{"term":"Docker Image","note":"— 같은 이미지를 층·태그·다이제스트 쪽에서 들여다본 편"},{"term":"Container Registry","note":"— 세 규격 중 주고받는 법이 적용되는 자리"},{"term":"Container","note":"— 규격이 정의하려는 대상 그 자체"},{"term":"cgroups","note":"— 굴릴 때 실제 격리를 만드는 리눅스 쪽 장치"}]},{"id":"infra--oom-killer","term":"OOM Killer","reading":"메모리 부족 도살자","category":"인프라 · 운영","summary":"OOM Killer 는 **메모리가 바닥나면 커널이 하나를 골라 죽이는 장치**다.","aliases":["oom killer","메모리 부족 도살자"],"related":[{"term":"Memory","note":"— 이 일이 벌어지는 자원 그 자체"},{"term":"cgroups","note":"— 고르기를 기계 전체가 아니라 칸 안으로 가두는 울타리"},{"term":"Signal","note":"— 고른 쪽을 끊을 때 쓰는 그 수단"},{"term":"Pod","note":"— 죽고 나서 다시 뜨는 단위"},{"term":"Virtual Memory","note":"— 없는 메모리를 미리 약속해 줄 수 있는 까닭"}]},{"id":"infra--observability","term":"Observability","reading":"관측 가능성","category":"인프라 · 운영","summary":"Observability는 **밖에서 물어 안의 일을 알아내는 성질**이다.","aliases":["observability","관측 가능성"],"related":[{"term":"Metric","note":"— 밖에서 던지는 물음 중 \"얼마나\" 를 맡는 신호"},{"term":"Distributed Tracing","note":"— \"어느 구간에서\" 를 맡는 신호"},{"term":"Logging","note":"— \"그 순간 무슨 일이\" 를 맡는 신호"},{"term":"OpenTelemetry","note":"— 이 세 신호를 한 규격으로 재서 내보내는 쪽"},{"term":"Latency","note":"— 가장 먼저 보는 네 신호 중 하나"}]},{"id":"infra--on-premises","term":"On-Premises","reading":"온프레미스","category":"인프라 · 운영","summary":"On-Premises는 **서버를 직접 사서 자기 공간에 두고 운영하는 방식**이다.","aliases":["on-premises","온프레미스"],"related":[{"term":"Cloud","note":"— 남의 인프라를 빌려 쓰는 반대쪽 방식"},{"term":"Bare Metal","note":"— 가상화 없이 물리 장비를 그대로 쓰는 형태"},{"term":"Auto Scaling","note":"— 필요할 때 즉시 늘리는 클라우드 쪽 기능. 온프레미스에는 없다"},{"term":"VPN","note":"— 밖에서 자체 시설 안으로 들어올 때 쓰는 통로"},{"term":"IaaS_PaaS_SaaS","note":"— 어디까지 남에게 맡기느냐로 나눈 구분"}]},{"id":"infra--on-call","term":"On-call","reading":"온콜","category":"인프라 · 운영","summary":"On-call은 **차례가 되면 장애 호출을 받는 당번**이다.","aliases":["on-call","온콜"],"related":[{"term":"SRE","note":"— 온콜을 시간의 25% 안으로 묶어 둔 쪽"},{"term":"Runbook","note":"— 호출을 받은 사람이 새벽에 여는 글"},{"term":"Postmortem","note":"— 받은 사고를 끝낸 뒤 남기는 기록"},{"term":"Alerting","note":"— 무엇을 호출로 보낼지 가르는 앞자리"},{"term":"Logging","note":"— 아무도 볼 필요가 없는 것이 가는 자리"}]},{"id":"infra--opentelemetry","term":"OpenTelemetry","reading":"오픈텔레메트리","category":"인프라 · 운영","summary":"OpenTelemetry는 **재는 법만 정하고 저장은 안 맡는 공통 규격**이다.","aliases":["opentelemetry","오픈텔레메트리"],"related":[{"term":"Observability","note":"— 이 규격이 내보내는 자료가 그 성질의 재료다"},{"term":"Distributed Tracing","note":"— 이 규격이 표준으로 묶은 대표 신호"},{"term":"Metric","note":"— 세 신호 중 숫자를 맡는 쪽"},{"term":"Logging","note":"— 세 신호 중 문장을 맡는 쪽"}]},{"id":"infra--patch-management","term":"Patch Management","reading":"고침 패치 관리","category":"인프라 · 운영","summary":"Patch Management는 **고칠 조각을 찾아 고르고 깔고 확인하는 일**이다.","aliases":["patch management","고침 패치 관리"],"related":[{"term":"Rollback","note":"— 깐 조각이 탈을 냈을 때 되돌리는 쪽"},{"term":"Canary Release","note":"— 몇 대에만 먼저 깔아 보는 그 방식을 배포 쪽에서 부르는 이름"},{"term":"Immutable Infrastructure","note":"— 기계를 고치는 대신 새로 찍어 갈아 끼우는 다른 답"},{"term":"Configuration Drift","note":"— 어떤 기계만 안 깔려서 서로 달라지는 상태"},{"term":"Runbook","note":"— 비상일 때 무엇부터 할지 미리 적어 두는 문서"}]},{"id":"infra--pilot-light-and-warm-standby","term":"Pilot Light and Warm Standby","reading":"불씨만 켜 두기와 미리 데워 두기","category":"인프라 · 운영","summary":"둘은 **예비 터를 어디까지 켜 두느냐로 갈리는 두 방식**이다.","aliases":["pilot light and warm standby","불씨만 켜 두기와 미리 데워 두기"],"related":[{"term":"Disaster Recovery","note":"— 이 둘이 그 안에 놓인 두 단계다"},{"term":"RPO and RTO","note":"— 어느 단계를 고를지 정하는 두 숫자"},{"term":"Infrastructure as Code","note":"— 예비 터를 같은 모양으로 세워 두게 하는 방법"},{"term":"Health Check","note":"— 넘길 때가 됐는지 밖에서 두드려 보는 쪽"},{"term":"Blue-Green Deployment","note":"— 같은 것을 둘 두고 갈아 끼우는, 배포 자리의 닮은 방식"}]},{"id":"infra--pod","term":"Pod","reading":"파드","category":"인프라 · 운영","summary":"Pod는 **주소와 저장 공간을 함께 쓰는 컨테이너 묶음**이다.","aliases":["pod","파드"],"related":[{"term":"Kubernetes","note":"— 파드를 만들고 놓고 지우는 쪽"},{"term":"Container","note":"— 파드 안에서 실제로 도는 것"},{"term":"Docker Image","note":"— 그 컨테이너가 무엇으로 뜰지 정하는 재료"},{"term":"Ingress","note":"— 밖에서 온 웹 요청이 규칙을 타고 결국 닿는 곳"},{"term":"Helm","note":"— 파드를 만드는 정의를 꾸러미로 묶어 설치하는 도구"}]},{"id":"infra--policy-as-code","term":"Policy as Code","reading":"규칙을 코드로","category":"인프라 · 운영","summary":"Policy as Code는 **지켜야 할 규칙을 글이 아니라 판정하는 코드로 적는 것**이다.","aliases":["policy as code","규칙을 코드로"],"related":[{"term":"Infrastructure as Code","note":"— 터를 코드로 적는 쪽. 이 규칙이 재는 대상이 대개 그 코드다"},{"term":"GitOps","note":"— 그 코드가 어디에 있어야 하고 어떻게 반영되는지를 정하는 방식"},{"term":"Kubernetes","note":"— 자원이 접수되는 자리에서 이 규칙을 거는 대표적인 곳"},{"term":"Immutable Infrastructure","note":"— 규칙에 맞는 모양을 통째로 찍어내는 다른 방법"},{"term":"Configuration Drift","note":"— 규칙을 안 걸어 두면 조용히 벌어지는 어긋남"}]},{"id":"infra--postmortem","term":"Postmortem","reading":"사후 분석","category":"인프라 · 운영","summary":"Postmortem은 **장애를 기록해 다시 안 나게 하는 글**이다.","aliases":["postmortem","사후 분석"],"related":[{"term":"SRE","note":"— 이 절차를 규범으로 적어 둔 쪽"},{"term":"On-call","note":"— 이 글을 쓰게 만드는 사건을 처음 받는 자리"},{"term":"Runbook","note":"— 여기서 나온 조치가 절차로 굳는 자리"},{"term":"Logging","note":"— 시각별 기록을 복원하는 재료"},{"term":"Audit Log","note":"— 누가 무엇을 바꿨는지 되짚는 다른 기록"}]},{"id":"infra--prometheus","term":"Prometheus","reading":"프로메테우스","category":"인프라 · 운영","summary":"Prometheus는 **지표를 주기마다 긁어와 시각을 붙여 쌓는 감시 도구**다.","aliases":["prometheus","프로메테우스"],"related":[{"term":"Grafana","note":"— 여기 쌓인 값을 물어다 화면에 그려 주는 쪽"},{"term":"Alerting","note":"— 여기서 만든 알림을 묶고 보내는 다음 단계"},{"term":"Logging","note":"— 같은 사고를 숫자가 아니라 문장으로 남기는 쪽"},{"term":"Kubernetes","note":"— 이 도구가 가장 흔히 붙는 자리"},{"term":"Latency","note":"— 여기 쌓는 지표 중 가장 자주 보는 값"}]},{"id":"infra--raid","term":"RAID","reading":"레이드","category":"인프라 · 운영","summary":"RAID는 **여러 원반을 묶어 빠르게 또는 안 죽게 만드는 방식**이다.","aliases":["raid","레이드"],"related":[{"term":"LVM","note":"— 같은 원반들을 다루지만 저쪽은 칸을 나누는 일을 맡는다"},{"term":"Block Storage","note":"— 클라우드에서 이 배열의 재료가 되는 원반"},{"term":"High Availability","note":"— 원반 한 장의 고장을 견디는 일이 이 목표의 가장 아래층이다"},{"term":"Disaster Recovery","note":"— 이 묶음이 대신하지 못하는 자리를 맡는 쪽"},{"term":"File System","note":"— 배열 위에 얹혀 실제 파일을 다루는 층"}]},{"id":"infra--rpo-and-rto","term":"RPO and RTO","reading":"얼마까지 잃어도 되나와 얼마 만에 살아나나","category":"인프라 · 운영","summary":"RPO 와 RTO 는 **사고 때 어디까지 참을지 미리 정해 둔 두 숫자**다.","aliases":["rpo and rto","얼마까지 잃어도 되나와 얼마 만에 살아나나"],"related":[{"term":"Disaster Recovery","note":"— 이 두 숫자를 지키려고 짜 두는 계획 전체"},{"term":"Pilot Light and Warm Standby","note":"— 뒤 숫자를 얼마로 잡느냐에 따라 갈리는 두 방식"},{"term":"SRE","note":"— 목표를 숫자로 적고 지켜지는지 재는 같은 사고방식"},{"term":"Health Check","note":"— 사고가 났다고 판정하는 자리. 뒤 숫자는 여기서부터 센다"},{"term":"Rollback","note":"— 사고가 아니라 잘못 올린 판을 되돌릴 때 재는 다른 시간"}]},{"id":"infra--resource-requests-and-limits","term":"Resource Requests and Limits","reading":"요청량과 상한","category":"인프라 · 운영","summary":"Requests 는 **자리를 잡을 때 쓰는 값**이고, Limits 는 못 넘게 막는 선이다.","aliases":["resource requests and limits","요청량과 상한"],"related":[{"term":"Pod","note":"— 이 두 값을 적어 두는 자리"},{"term":"OOM Killer","note":"— 상한을 넘겼을 때 실제로 죽이는 쪽"},{"term":"cgroups","note":"— 상한이 리눅스에서 걸리는 그 장치"},{"term":"Horizontal Pod Autoscaler","note":"— 요청량을 기준 삼아 개수를 늘리고 줄이는 쪽"},{"term":"Memory","note":"— 못 압축되는 자원이라 넘으면 죽는 쪽"}]},{"id":"infra--rollback","term":"Rollback","reading":"롤백","category":"인프라 · 운영","summary":"Rollback 은 **직전에 잘 돌던 판으로 되돌리는 일**이다.","aliases":["rollback","롤백"],"related":[{"term":"Blue-Green Deployment","note":"— 되돌리기를 배포 한 번이 아니라 전환 한 번으로 줄여 주는 방식"},{"term":"Canary Release","note":"— 되돌릴 일이 생겼을 때 닿는 사람 수를 미리 줄여 두는 방식"},{"term":"Feature Flag","note":"— 배포를 되돌리지 않고 기능만 꺼서 같은 효과를 내는 더 빠른 길"},{"term":"CI/CD","note":"— 되돌아갈 판을 번호로 쌓아 두는 자리"},{"term":"Migration","note":"— 코드와 달리 되돌리기가 어려워 따로 다뤄야 하는 쪽"}]},{"id":"infra--rolling-update","term":"Rolling Update","reading":"굴러가는 갱신","category":"인프라 · 운영","summary":"옛 파드를 몇 개씩 새 파드로 **바꿔 끼우며** 넘어가는 방식이다.","aliases":["rolling update","굴러가는 갱신"],"related":[{"term":"Deployment (Kubernetes)","note":"— 이 방식을 기본값으로 굴리는 자리"},{"term":"Liveness Probe vs Readiness Probe","note":"— 다음 파드로 넘어가도 되는지 정하는 확인"},{"term":"Rollback","note":"— 옛 묶음이 남아 있어 가능한 되돌리기"},{"term":"Blue-Green Deployment","note":"— 두 벌을 통째로 세워 두고 한 번에 갈아타는 다른 방법"},{"term":"Canary Release","note":"— 새 판을 일부에게만 먼저 보여 확인하는 다른 방법"}]},{"id":"infra--runbook","term":"Runbook","reading":"런북","category":"인프라 · 운영","summary":"Runbook은 **정해진 결과에 이르는 절차를 적어 둔 글**이다.","aliases":["runbook","런북"],"related":[{"term":"On-call","note":"— 이 글을 새벽에 여는 사람"},{"term":"Postmortem","note":"— 여기서 나온 조치가 런북의 새 줄이 된다"},{"term":"SRE","note":"— 손으로 하던 일을 없애 가는 쪽"},{"term":"CI_CD","note":"— 런북이 자동화로 옮겨 가면 닿는 자리"},{"term":"Logging","note":"— 절차를 짚는 동안 무엇을 볼지 알려주는 재료"}]},{"id":"infra--sre","term":"SRE","reading":"사이트 신뢰성 엔지니어링","category":"인프라 · 운영","summary":"SRE는 **운영을 소프트웨어 공학으로 다루는 직무**다.","aliases":["sre","사이트 신뢰성 엔지니어링"],"related":[{"term":"DevOps","note":"— 이 방식이 그 원칙의 한 구현으로 읽히는 자리"},{"term":"Error Budget","note":"— 100%가 아닌 목표를 정하고 남는 몫을 쓰는 방법"},{"term":"On-call","note":"— SRE 시간의 25% 안으로 묶어 둔 당번"},{"term":"Postmortem","note":"— 장애를 재발 방지 목록으로 바꾸는 절차"},{"term":"Runbook","note":"— 사람이 손을 쓸 때 걸리는 시간을 줄이는 글"}]},{"id":"infra--service","term":"Service","reading":"Kubernetes) (쿠버네티스 서비스","category":"인프라 · 운영","summary":"Service는 **자꾸 갈리는 파드 앞에 세워 둔 안 바뀌는 주소**다.","aliases":["service","kubernetes) (쿠버네티스 서비스","service (kubernetes)"],"related":[{"term":"Pod","note":"— Service 뒤에 서서 실제로 받는 것"},{"term":"Ingress","note":"— 웹 요청 하나를 여러 Service 로 갈라 보내는 앞단"},{"term":"DNS","note":"— Service 이름이 IP 로 풀리는 그 방식"},{"term":"Load Balancer","note":"— `type: LoadBalancer` 가 클라우드에 만들어 달라고 하는 물건"},{"term":"StatefulSet","note":"— 머리 없는 Service 를 반드시 짝으로 두는 쪽"}]},{"id":"infra--signal","term":"Signal","reading":"시그널","category":"인프라 · 운영","summary":"Signal 은 **프로세스에게 번호 하나로 보내는 짧은 통지**다.","aliases":["signal","시그널"],"related":[{"term":"Process","note":"— 신호가 도착하는 그 단위"},{"term":"Graceful Shutdown","note":"— 종료 신호를 받고 나서 하는 일을 다룬 편"},{"term":"Kernel","note":"— 신호를 실제로 전해 주고 기본 동작을 실행하는 쪽"},{"term":"Nginx","note":"— 번호마다 자기 뜻을 붙여 쓰는 대표적인 예"},{"term":"systemd","note":"— 유닛을 멈출 때 이 신호를 보내는 쪽"}]},{"id":"infra--statefulset","term":"StatefulSet","reading":"스테이트풀셋","category":"인프라 · 운영","summary":"StatefulSet은 **파드마다 제 이름과 제 디스크를 붙여 두는 것**이다.","aliases":["statefulset","스테이트풀셋"],"related":[{"term":"Deployment (Kubernetes)","note":"— 서로 갈아 껴도 되는 파드를 다루는 쪽"},{"term":"Pod","note":"— 이름과 볼륨이 붙는 그 단위"},{"term":"Service (Kubernetes)","note":"— `serviceName` 에 적어 짝으로 두는 머리 없는 쪽"},{"term":"Replication","note":"— 상태를 여러 벌 두는 그 개념"},{"term":"Rolling Update","note":"— 큰 번호부터 하나씩 갈아 끼우는 방식"}]},{"id":"infra--synthetic-monitoring","term":"Synthetic Monitoring","reading":"가짜 손님으로 재기","category":"인프라 · 운영","summary":"Synthetic Monitoring은 **가짜 손님을 주기마다 보내 대신 겪게 하는 것**이다.","aliases":["synthetic monitoring","가짜 손님으로 재기"],"related":[{"term":"Health Check","note":"— 살아 있나만 한 번 두드려 보는 더 단순한 쪽"},{"term":"Observability","note":"— 밖에서 물어 안을 알아내는 성질. 이 방식은 그중 밖에서 두드리는 자리다"},{"term":"Alerting","note":"— 어긋났을 때 누구를 어떻게 부를지 정하는 쪽"},{"term":"Metric","note":"— 가짜 손님이 남기는 성공률과 걸린 시간이 여기로 쌓인다"},{"term":"Load Test","note":"— 일부러 많이 보내 보는, 다른 목적의 지어낸 손님"}]},{"id":"infra--ttl","term":"TTL","reading":"Time To Live","category":"인프라 · 운영","summary":"TTL은 **데이터가 유효한 시간을 미리 정해둔 값**이다.","aliases":["ttl","time to live"],"related":[{"term":"Cache","note":"— TTL이 가장 자주 붙는 곳"},{"term":"DNS","note":"— 레코드마다 TTL을 두어 얼마나 오래 캐시할지 정한다"},{"term":"CDN","note":"— 거점이 복사본을 들고 있는 기간을 TTL로 정한다"},{"term":"Redis","note":"— 키마다 TTL을 걸어 자동 만료시키는 저장소"},{"term":"Session","note":"— TTL로 유효 기간을 관리하는 대표적인 데이터"}]},{"id":"infra--taint-and-toleration","term":"Taint and Toleration","reading":"얼룩과 감내","category":"인프라 · 운영","summary":"노드가 파드를 밀어내는 표시와, 그걸 견디는 파드 쪽 **허락**이다.","aliases":["taint and toleration","얼룩과 감내"],"related":[{"term":"Pod","note":"— 견딤을 적어 두는 자리"},{"term":"Kubernetes","note":"— 이 거름망을 돌리는 스케줄러가 사는 곳"},{"term":"DaemonSet","note":"— 노드 상태 얼룩을 기본으로 견디게 만들어진 쪽"},{"term":"Resource Requests and Limits","note":"— 얼룩을 통과한 뒤 자리를 정하는 다른 조건"},{"term":"Spot Instance","note":"— 언제든 회수되는 노드라 얼룩으로 갈라 두는 대표 사례"}]},{"id":"infra--terraform","term":"Terraform","reading":"테라폼","category":"인프라 · 운영","summary":"Terraform 은 **원하는 인프라를 적어 두면 그대로 만들어 주는 도구**다.","aliases":["terraform","테라폼"],"related":[{"term":"Infrastructure as Code","note":"— Terraform 이 속한 방식 그 자체"},{"term":"Ansible","note":"— 만들어진 기계의 안을 채우는 짝. 자리가 다르다"},{"term":"GitOps","note":"— 이 설정 파일을 저장소에 두고 자동으로 맞추는 방식"},{"term":"AWS","note":"— 프로바이더로 붙는 대표적인 대상"},{"term":"Kubernetes","note":"— 클라우드가 아닌 것도 프로바이더로 붙는다는 보기"}]},{"id":"infra--vm","term":"VM","reading":"Virtual Machine, 가상 머신","category":"인프라 · 운영","summary":"VM은 **소프트웨어로 만들어진 컴퓨터 한 대**다.","aliases":["vm","virtual machine, 가상 머신"],"related":[{"term":"Hypervisor","note":"— VM 을 만들고 자원을 떼어 주는 층"},{"term":"Container","note":"— 운영체제를 얹지 않고 커널을 나눠 쓰는 가벼운 쪽"},{"term":"Bare Metal","note":"— 나누지 않고 물리 서버를 통째로 쓰는 쪽"},{"term":"VPS","note":"— VM 한 칸을 빌려주는 상품"},{"term":"On-Premises","note":"— 남의 데이터 센터가 아니라 우리 건물에 이걸 두는 방식"}]},{"id":"infra--vps","term":"VPS","reading":"Virtual Private Server","category":"인프라 · 운영","summary":"VPS는 **물리 서버 한 대를 쪼개 나눠 쓰는 가상 서버**다.","aliases":["vps","virtual private server"],"related":[{"term":"VM","note":"— VPS를 만들어내는 기반 기술"},{"term":"Hypervisor","note":"— 물리 서버를 나눠 각 VPS에 몫을 주는 층"},{"term":"SSH","note":"— VPS에 들어가 관리할 때 쓰는 접속 방법"},{"term":"Multi-tenancy","note":"— 한 기계를 여러 고객이 나눠 쓰는 구조"},{"term":"Bare Metal","note":"— 나누지 않고 기계를 통째로 쓰는 쪽"}]},{"id":"infra--cgroups","term":"cgroups","reading":"제어 그룹","category":"인프라 · 운영","summary":"cgroups 는 **프로세스를 묶어 자원 사용을 제한하는 커널 기능**이다.","aliases":["cgroups","제어 그룹"],"related":[{"term":"Container","note":"— 이 칸으로 자원이 나뉘는 대표적 대상"},{"term":"Linux Namespace","note":"— 같은 커널의 짝. 이쪽은 쓸 수 있는 양, 저쪽은 보이는 범위"},{"term":"systemd","note":"— 유닛마다 이 칸을 하나씩 만들어 붙이는 쪽"},{"term":"OOM Killer","note":"— 메모리 칸이 꽉 찼을 때 그 칸 안에서 불려 나오는 것"},{"term":"Kubernetes","note":"— 파드에 적은 한도를 이 칸으로 내려보내는 쪽"}]},{"id":"infra--etcd","term":"etcd","reading":"이티시디","category":"인프라 · 운영","summary":"클러스터의 모든 상태가 적혀 있는 **합의된 저장소**다.","aliases":["etcd","이티시디"],"related":[{"term":"Kubernetes","note":"— 상태를 전부 이 저장소 한 곳에 두는 대표 사용처"},{"term":"Key-Value Store","note":"— etcd 가 속한 저장소 갈래"},{"term":"Leader Election","note":"— etcd 안에서도 쓰이고, etcd 로 밖에서 구현하기도 하는 장치"},{"term":"Distributed Lock","note":"— 만료 붙은 열쇠로 세우는 대표 응용"},{"term":"Disaster Recovery","note":"— 스냅숏 한 파일이 복구 계획의 중심이 되는 이유"}]},{"id":"infra--systemd","term":"systemd","reading":"시스템디","category":"인프라 · 운영","summary":"systemd 는 **리눅스의 1번 프로세스이자 서비스 관리자**다.","aliases":["systemd","시스템디"],"related":[{"term":"Linux","note":"— systemd 가 1번 프로세스로 앉는 그 운영체제"},{"term":"Kernel","note":"— 1번 프로세스 하나만 띄우고 나머지를 넘기는 쪽"},{"term":"Process","note":"— systemd 가 띄우고 붙들고 되살리는 단위"},{"term":"cgroups","note":"— 띄운 프로세스를 유닛마다 묶어 두는 장치"},{"term":"Graceful Shutdown","note":"— 유닛을 멈출 때 보내는 신호와 기다리는 시간"}]}]},{"id":"tool","name":"개발 도구","blurb":"매일 손에 잡는 것들","terms":[{"id":"tool--breakpoint","term":"Breakpoint","reading":"중단점","category":"개발 도구","summary":"Breakpoint는 **실행이 이 줄에 닿으면 멈추라고 남기는 표시**다.","aliases":["breakpoint","중단점"],"related":[{"term":"Debugger","note":"— 이 표시를 읽고 실제로 멈춰 세우는 도구"},{"term":"IDE","note":"— 여백을 눌러 표시를 찍고 값을 보여주는 화면"},{"term":"Loop","note":"— 안에 중단점을 찍으면 수천 번 멈추는 그 구조"},{"term":"Logging","note":"— 세우면 안 되는 자리에서 추적점이 대신 하는 일"},{"term":"Variable","note":"— 멈춘 자리에서 값을 확인하는 대상"}]},{"id":"tool--cli","term":"CLI","reading":"Command Line Interface","category":"개발 도구","summary":"CLI는 **글자로 명령을 적어 컴퓨터를 시키는 방식**이다.","aliases":["cli","command line interface"],"related":[{"term":"Terminal","note":"— 글자를 띄우고 입력을 받는 창"},{"term":"SSH","note":"— 원격 서버에 CLI 로 붙는 통로"},{"term":"Linux","note":"— CLI 로 다루는 일이 가장 많은 운영체제"},{"term":"Git","note":"— CLI 로 쓰는 대표적인 도구"},{"term":"Docker","note":"— 컨테이너를 명령 한 줄로 띄우고 내린다"}]},{"id":"tool--cherry-pick","term":"Cherry-pick","reading":"체리픽","category":"개발 도구","summary":"Cherry-pick은 **커밋 하나만 골라 지금 가지에 옮겨 얹는 일**이다.","aliases":["cherry-pick","체리픽"],"related":[{"term":"Git","note":"— 이 명령이 속한 도구. 커밋과 가지가 있어야 성립한다"},{"term":"Git Stash","note":"— 작업 트리를 깨끗하게 만들어 체리픽을 시작할 수 있게 해준다"},{"term":"Trunk Based Development","note":"— 줄기에서 고친 것을 릴리스 가지로 내려보낼 때 이 명령을 쓴다"},{"term":"CI_CD","note":"— 옮겨 붙인 커밋도 그 가지에서 빌드와 테스트를 다시 통과해야 한다"}]},{"id":"tool--container","term":"Container","reading":"컨테이너","category":"개발 도구","summary":"Container는 **하나의 프로세스를 격리해서 돌리는 방식**이다.","aliases":["container","컨테이너"],"related":[{"term":"Docker","note":"— 컨테이너를 만들고 돌리는 대표적인 도구"},{"term":"Kubernetes","note":"— 컨테이너가 많아졌을 때 배치와 복구를 맡는다"},{"term":"VM","note":"— 운영체제를 통째로 띄우는 더 강한 격리"},{"term":"Hypervisor","note":"— 가상 머신을 만드는 계층"}]},{"id":"tool--debugger","term":"Debugger","reading":"디버거","category":"개발 도구","summary":"Debugger는 **실행을 멈춰 세우고 그 속을 들여다보는 도구**다.","aliases":["debugger","디버거"],"related":[{"term":"Breakpoint","note":"— 디버거에게 어디서 멈출지 알려주는 표시"},{"term":"Logging","note":"— 멈추지 않고 지나가며 기록만 남기는 반대쪽 방법"},{"term":"IDE","note":"— 디버깅 클라이언트를 화면에 붙여주는 편집기"},{"term":"Stack","note":"— 멈춘 자리에서 들여다보는 호출 스택이 쌓이는 그 구조"},{"term":"Process","note":"— 디버거가 붙는 대상. 붙은 쪽은 그 권한으로 코드를 돌릴 수 있다"}]},{"id":"tool--dependency","term":"Dependency","reading":"의존성","category":"개발 도구","summary":"의존성은 **내 코드가 돌아가려면 있어야 하는 남의 코드**다.","aliases":["dependency","의존성"],"related":[{"term":"Package Manager","note":"— 적어 둔 의존성을 실제로 받아다 놓는 도구"},{"term":"Lock File","note":"— 범위로 적힌 의존성이 실제로 어느 버전으로 깔렸는지 적어 두는 파일"},{"term":"Package","note":"— 의존성으로 걸리는 단위 하나"},{"term":"Build","note":"— 받아 온 의존성을 내 코드와 함께 묶는 다음 단계"}]},{"id":"tool--docker","term":"Docker","reading":"도커","category":"개발 도구","summary":"Docker는 **프로그램과 실행 환경을 한 덩어리로 묶는 도구**다.","aliases":["docker","도커"],"related":[{"term":"Container","note":"— Docker가 만들어 실행하는 대상"},{"term":"Kubernetes","note":"— 컨테이너가 많아졌을 때 관리를 맡는 도구"},{"term":"VM","note":"— 운영체제를 통째로 띄우는 더 무거운 격리 방식"},{"term":"CI_CD","note":"— 컨테이너를 실행 환경으로 삼는 대표적인 자리"}]},{"id":"tool--docker-compose","term":"Docker Compose","reading":"도커 컴포즈","category":"개발 도구","summary":"Docker Compose는 **여러 컨테이너를 한 파일로 정의해 함께 띄우는 도구**다.","aliases":["docker compose","도커 컴포즈"],"related":[{"term":"Docker","note":"— 컴포즈가 지휘하는 컨테이너를 실제로 만드는 도구"},{"term":"Container","note":"— 컴포즈가 한 파일로 여러 개 묶는 대상"},{"term":"Kubernetes","note":"— 호스트 한 대를 넘어설 때 넘어가는 쪽"},{"term":"YAML","note":"— `compose.yaml` 을 적는 형식"},{"term":"Environment Variable","note":"— 같은 파일을 환경마다 다르게 쓰게 하는 변수"}]},{"id":"tool--docker-image","term":"Docker Image","reading":"도커 이미지","category":"개발 도구","summary":"Docker Image는 **실행에 필요한 것을 다 담은 읽기 전용 꾸러미**다.","aliases":["docker image","도커 이미지"],"related":[{"term":"Container","note":"— 이미지를 실행해서 돌고 있는 상태"},{"term":"Dockerfile","note":"— 이 이미지를 무엇으로 어떻게 만들지 적은 파일"},{"term":"Docker","note":"— 이미지를 만들고 받고 실행하는 도구"},{"term":"Docker Volume","note":"— 이미지에 담을 수 없는 데이터를 밖에 두는 자리"},{"term":"Kubernetes","note":"— 어느 이미지를 몇 개 띄울지 정하는 층"}]},{"id":"tool--docker-volume","term":"Docker Volume","reading":"도커 볼륨","category":"개발 도구","summary":"Docker Volume은 **컨테이너가 지워져도 남는 데이터 저장 칸**이다.","aliases":["docker volume","도커 볼륨"],"related":[{"term":"Container","note":"— 지워지면 안에 쓴 파일이 같이 사라지는 그 대상"},{"term":"Docker Image","note":"— 읽기 전용이라 데이터를 담아둘 수 없는 쪽"},{"term":"Docker","note":"— 볼륨을 만들고 컨테이너에 붙여주는 도구"},{"term":"DB","note":"— 볼륨이 가장 먼저 필요해지는 자리"},{"term":"File System","note":"— 볼륨이 실제로 놓이는 호스트 쪽 저장 구조"}]},{"id":"tool--dockerfile","term":"Dockerfile","reading":"도커파일","category":"개발 도구","summary":"Dockerfile은 **이미지를 만드는 순서를 적은 텍스트 파일**이다.","aliases":["dockerfile","도커파일"],"related":[{"term":"Docker Image","note":"— Dockerfile 을 빌드해서 나오는 결과물"},{"term":"Docker","note":"— Dockerfile 을 읽어 이미지를 만드는 도구"},{"term":"Container","note":"— 그 이미지를 실제로 실행한 상태"},{"term":"Cache","note":"— 바뀌지 않은 층을 다시 만들지 않게 하는 그 원리"},{"term":"CI_CD","note":"— Dockerfile 빌드가 커밋마다 돌아가는 자리"}]},{"id":"tool--feature-flag","term":"Feature Flag","reading":"기능 플래그","category":"개발 도구","summary":"Feature Flag는 **다시 배포하지 않고 기능을 켜고 끄는 스위치**다.","aliases":["feature flag","기능 플래그"],"related":[{"term":"Trunk Based Development","note":"— 덜 끝난 코드를 줄기에 합치게 해 주는 짝. 규범 문서가 플래그를 그 장치로 든다"},{"term":"A B Testing","note":"— 플래그로 갈래를 나눠 두 안을 비교하는 대표적 활용"},{"term":"CI_CD","note":"— 플래그 조합마다 갈라 돌려야 하는 자동 검사 쪽"},{"term":"Environment Variable","note":"— 설정을 코드 밖으로 빼는 더 원시적인 방식. 바꾸려면 다시 띄워야 한다"}]},{"id":"tool--git","term":"Git","reading":"형상 관리 시스템","category":"개발 도구","summary":"Git은 **코드가 바뀐 이력을 시점마다 기록해두는 도구**다.","aliases":["git","형상 관리 시스템"],"related":[{"term":"CLI","note":"— git 명령을 실제로 입력하는 자리"},{"term":"Terminal","note":"— 그 명령을 치는 창"},{"term":"CI_CD","note":"— push를 방아쇠로 빌드와 배포가 이어진다"},{"term":"DevOps","note":"— 커밋에서 배포까지를 한 줄기로 잇는 방식. 그 출발점이 Git이다"}]},{"id":"tool--git-branch","term":"Git Branch","reading":"브랜치","category":"개발 도구","summary":"Git Branch 는 **커밋 하나를 가리키는 이름표**다.","aliases":["git branch","브랜치"],"related":[{"term":"Git","note":"— 브랜치라는 장치를 담고 있는 이력 관리 도구"},{"term":"Git Commit","note":"— 브랜치라는 이름표가 실제로 가리키는 대상"},{"term":"Merge vs Rebase","note":"— 갈라 놓은 가지를 다시 합치는 두 가지 방법"},{"term":"Hash","note":"— 이름표 안에 적히는 그 40자 값을 만드는 방식"},{"term":"CLI","note":"— `git branch` 와 `git switch` 를 실제로 치는 자리"}]},{"id":"tool--git-commit","term":"Git Commit","reading":"커밋","category":"개발 도구","summary":"Git Commit 은 **그 순간의 프로젝트 전체를 남긴 기록 하나**다.","aliases":["git commit","커밋"],"related":[{"term":"Git","note":"— 커밋을 쌓아 이력으로 만드는 도구"},{"term":"Git Branch","note":"— 커밋 하나를 가리키는 이름표. 커밋이 쌓이면 따라 옮겨 간다"},{"term":"Merge vs Rebase","note":"— 쌓인 커밋을 다른 가지에 합치거나 다시 얹는 두 방법"},{"term":"Hash","note":"— 커밋에 40자 이름을 붙일 때 쓰는 방식"},{"term":"CLI","note":"— `git add` 와 `git commit` 을 실제로 치는 자리"}]},{"id":"tool--git-flow","term":"Git Flow","reading":"깃 플로","category":"개발 도구","summary":"Git Flow는 **기능을 모아 두었다가 판으로 묶어 내보내는 분기 모델**이다.","aliases":["git flow","깃 플로"],"related":[{"term":"Trunk Based Development","note":"— 같은 물음에 정반대로 답한 모델. 규범 문서가 둘은 양립하지 않는다고 적는다"},{"term":"Git Branch","note":"— Git Flow 가 규칙을 얹는 그 장치. 가지를 내는 일 자체는 여기서 온다"},{"term":"Merge vs Rebase","note":"— 가지를 어떻게 붙일지의 물음. Git Flow 는 어떤 가지를 둘지를 정한다"},{"term":"Feature Flag","note":"— 줄기 하나로 갈 때 덜 된 기능을 가리는 장치. Git Flow 는 판 가지로 그 일을 대신한다"},{"term":"Semantic Versioning","note":"— 판 가지 이름에 붙는 그 번호를 매기는 규칙"}]},{"id":"tool--git-stash","term":"Git Stash","reading":"깃 스태시","category":"개발 도구","summary":"Git Stash는 **커밋하지 않은 변경을 잠깐 치워 두는 서랍**이다.","aliases":["git stash","깃 스태시"],"related":[{"term":"Git","note":"— 서랍이 딸려 있는 도구. 커밋과 가지가 있는 그 저장소 안에 있다"},{"term":"Cherry-pick","note":"— 작업 트리가 깨끗해야 시작되는 명령. 그 조건을 만들어 주는 것이 이것이다"},{"term":"Trunk Based Development","note":"— 가지를 자주 옮겨 다니게 만드는 방식. 서랍이 자주 필요해진다"},{"term":"CLI","note":"— `git stash` 를 실제로 치는 자리"}]},{"id":"tool--git-tag","term":"Git Tag","reading":"깃 태그","category":"개발 도구","summary":"Git Tag 는 **특정 커밋에 붙여 두는 움직이지 않는 이름표**다.","aliases":["git tag","깃 태그"],"related":[{"term":"Git","note":"— 태그를 담아 두는 버전 관리 도구"},{"term":"Git Branch","note":"— 커밋할 때마다 앞으로 옮겨지는 이름표. 태그는 그 반대다"},{"term":"Semantic Versioning","note":"— 태그에 적을 이름을 정하는 규칙"},{"term":"Build","note":"— 태그가 가리키는 그 상태로 결과물을 만든다"},{"term":"CI_CD","note":"— 어느 판을 내보낼지 태그 이름으로 골라 가는 자동화"}]},{"id":"tool--ide","term":"IDE","reading":"Integrated Development Environment","category":"개발 도구","summary":"IDE는 **개발에 쓰는 도구를 한 화면에 모아둔 프로그램**이다.","aliases":["ide","integrated development environment"],"related":[{"term":"CLI","note":"— IDE 밖에서 같은 일을 명령으로 하는 방법"},{"term":"Git","note":"— IDE 창 안에 붙어 있는 버전 관리 도구"},{"term":"Build","note":"— IDE 버튼 하나에 묶여 있는 과정"},{"term":"Terminal","note":"— IDE가 창 안에 넣어둔 명령 입력창"}]},{"id":"tool--linter-formatter","term":"Linter & Formatter","reading":"린터와 포매터","category":"개발 도구","summary":"린터는 **버그**를 찾고, 포매터는 모양을 맞추는 도구다.","aliases":["linter & formatter","린터와 포매터","linter","formatter"],"related":[{"term":"IDE","note":"— 저장할 때마다 이 둘을 돌려 주는 자리"},{"term":"CI_CD","note":"— 사람 눈 대신 기계가 이 검사를 강제하는 자리"},{"term":"Git","note":"— 모양을 안 맞춰 두면 diff 가 공백 변경으로 덮이는 자리"},{"term":"Package Manager","note":"— 린터와 포매터를 개발용 의존성으로 받아 두는 도구"}]},{"id":"tool--lock-file","term":"Lock File","reading":"잠금 파일","category":"개발 도구","summary":"잠금 파일은 **실제로 깔린 버전을 그대로 적어 둔 파일**이다.","aliases":["lock file","잠금 파일"],"related":[{"term":"Dependency","note":"— 잠금 파일이 버전을 못 박아 두는 대상"},{"term":"Package Manager","note":"— 이 파일을 만들고 읽는 도구"},{"term":"Git","note":"— 잠금 파일을 팀과 나눠 갖는 자리. 커밋해야 뜻이 생긴다"},{"term":"CI_CD","note":"— 잠금 파일 그대로 깔아야 하는 대표적인 자리"}]},{"id":"tool--merge-conflict","term":"Merge Conflict","reading":"병합 충돌","category":"개발 도구","summary":"병합 충돌은 **git 이 한쪽을 못 골라 사람에게 넘긴 상태**다.","aliases":["merge conflict","병합 충돌"],"related":[{"term":"Git","note":"— 충돌을 잡아내고 표시를 남기는 도구 그 자체"},{"term":"Pull Request","note":"— 충돌이 가장 자주 눈에 띄는 자리"},{"term":"CLI","note":"— 웹에서 못 고치는 충돌은 결국 여기서 고친다"},{"term":"CI_CD","note":"— 합친 결과가 실제로 도는지 확인하는 다음 단계"}]},{"id":"tool--merge-vs-rebase","term":"Merge vs Rebase","reading":"병합과 리베이스","category":"개발 도구","summary":"merge 와 rebase 는 가지를 합칠 때 **이력을 남길지 다시 쓸지**가 갈리는 두 방법이다.","aliases":["merge vs rebase","병합과 리베이스","merge","rebase"],"related":[{"term":"Git Branch","note":"— 이력을 갈라 놓는 쪽. merge 와 rebase 는 그것을 다시 합치는 쪽이다"},{"term":"Git Commit","note":"— merge 가 그대로 두고 rebase 가 새로 만드는 그 단위"},{"term":"Git","note":"— 이 두 명령이 들어 있는 도구"},{"term":"Hash","note":"— rebase 뒤에 값이 전부 달라지는 그 이름"}]},{"id":"tool--monorepo","term":"Monorepo","reading":"모노레포","category":"개발 도구","summary":"Monorepo 는 **여러 프로젝트를 저장소 하나에 함께 두는 방식**이다.","aliases":["monorepo","모노레포"],"related":[{"term":"Git","note":"— 모노레포도 결국 Git 저장소 하나다"},{"term":"Package Manager","note":"— 한 저장소 안의 패키지들을 서로 이어 붙이는 쪽"},{"term":"Package","note":"— 모노레포가 한 저장소에 여러 개 담는 그 단위"},{"term":"Monolith vs Microservices","note":"— 배포를 하나로 묶는 이야기. 저장소를 하나로 묶는 것과 다르다"},{"term":"CI_CD","note":"— 어느 폴더가 바뀌었을 때 무엇을 검사할지 정해야 하는 자리"}]},{"id":"tool--package-manager","term":"Package Manager","reading":"패키지 매니저","category":"개발 도구","summary":"패키지 매니저는 **남이 만든 코드를 받아다 놓아 주는** 도구다.","aliases":["package manager","패키지 매니저"],"related":[{"term":"Package","note":"— 패키지 매니저가 받아다 놓는 그 단위"},{"term":"Build","note":"— 받아 온 의존성을 묶어 실행할 것으로 만드는 다음 단계"},{"term":"SDK","note":"— 패키지 매니저로 받아 쓰는 대표적인 묶음"},{"term":"CLI","note":"— npm 이나 go 처럼 이 도구를 부리는 방식"}]},{"id":"tool--pull-request","term":"Pull Request","reading":"풀 리퀘스트","category":"개발 도구","summary":"풀 리퀘스트는 **변경을 합쳐 달라고 내는 제안**이다.","aliases":["pull request","풀 리퀘스트"],"related":[{"term":"Git","note":"— PR 이 얹혀 있는 아래층. 가지와 병합은 여기가 한다"},{"term":"Merge Conflict","note":"— 합치려는 순간 이 화면에 붙는 문제"},{"term":"CI_CD","note":"— PR 이 열릴 때마다 빌드와 시험을 자동으로 돌리는 짝"},{"term":"CLI","note":"— 웹에서 못 고치는 충돌을 여기서 고쳐 다시 올린다"}]},{"id":"tool--repl","term":"REPL","reading":"Read-Eval-Print Loop","category":"개발 도구","summary":"REPL은 **한 줄을 치면 그 자리에서 실행해 답을 보여주는 창**이다.","aliases":["repl","read-eval-print loop"],"related":[{"term":"Terminal","note":"— 이 창이 대개 떠 있는 자리"},{"term":"Shell","note":"— 명령을 한 줄씩 받아 도는 같은 모양의 바깥쪽 창"},{"term":"Compile vs Interpret","note":"— 한 줄씩 바로 실행되는 쪽이 이 창을 쉽게 만든다"},{"term":"Debugger","note":"— 멈춰 세운 자리에서 같은 방식으로 아무 식이나 물어보는 도구"}]},{"id":"tool--sdk","term":"SDK","reading":"Software Development Kit","category":"개발 도구","summary":"SDK는 **한 플랫폼에서 개발하는 데 필요한 것을 묶어 놓은 꾸러미**다.","aliases":["sdk","software development kit"],"related":[{"term":"IDE","note":"— SDK 를 얹어 작성과 디버깅을 한자리에서 하는 도구"},{"term":"Framework vs Library","note":"— SDK 와 자주 뒤섞이는 두 이름"},{"term":"Package","note":"— SDK 를 받아 설치할 때의 단위"},{"term":"Compile","note":"— SDK 에 딸려 오는 컴파일러가 하는 일"}]},{"id":"tool--semantic-versioning","term":"Semantic Versioning","reading":"유의적 버전","category":"개발 도구","summary":"Semantic Versioning 은 **세 자리 숫자로 호환을 약속하는 규칙**이다.","aliases":["semantic versioning","유의적 버전"],"related":[{"term":"Git Tag","note":"— 이 번호를 커밋에 이름표로 박아 두는 자리"},{"term":"Package Manager","note":"— 이 번호를 읽고 어떤 판을 받을지 정한다"},{"term":"Package","note":"— 이 번호가 붙는 단위"},{"term":"API","note":"— 깨졌는지 가리는 기준. 이 규칙은 공개 API 선언을 먼저 요구한다"}]},{"id":"tool--shell","term":"Shell","reading":"셸","category":"개발 도구","summary":"Shell은 **내가 친 명령을 알아듣고 실행하는 프로그램**이다.","aliases":["shell","셸"],"related":[{"term":"Terminal","note":"— 셸에 글자를 넘기고 결과를 그려주는 창"},{"term":"CLI","note":"— 셸에 명령을 적어 넣는 그 방식 자체"},{"term":"Environment Variable","note":"— 셸이 들고 있다가 띄우는 프로그램에 넘기는 값"},{"term":"Process","note":"— 셸이 명령마다 띄우는 실행 단위"},{"term":"Linux","note":"— 셸이 기본 조작 수단인 운영체제"}]},{"id":"tool--source-map","term":"Source Map","reading":"소스맵","category":"개발 도구","summary":"Source Map은 **빌드된 코드의 한 자리를 원본의 자리로 되돌리는 표**다.","aliases":["source map","소스맵"],"related":[{"term":"Stack Trace","note":"— 소스맵이 실제로 되돌려 주는 그 목록"},{"term":"Build","note":"— 자리를 어긋나게 만드는 단계. 지도는 여기서 결과물과 함께 나온다"},{"term":"TypeScript","note":"— 원본과 결과물이 갈리는 대표적인 자리"},{"term":"Debugger","note":"— 멈춰 세운 자리를 원본 줄로 보여줄 때 이 표를 쓴다"},{"term":"WebAssembly","note":"— 규격이 밝힌 대상 중 하나. 자바스크립트·CSS 와 함께 이 표로 되짚는다"}]},{"id":"tool--stack-trace","term":"Stack Trace","reading":"스택 추적","category":"개발 도구","summary":"Stack Trace는 **터진 자리까지 함수를 부른 순서를 적은 목록**이다.","aliases":["stack trace","스택 추적"],"related":[{"term":"Stack","note":"— 자취가 그대로 베껴 나오는 그 더미"},{"term":"Exception","note":"— 자취를 달고 올라오는 대표적인 사건"},{"term":"Debugger","note":"— 같은 더미를 죽은 뒤가 아니라 멈춘 채로 들여다보는 도구"},{"term":"Logging","note":"— 자취를 남겨 나중에 읽게 만드는 자리"}]},{"id":"tool--terminal","term":"Terminal","reading":"터미널","category":"개발 도구","summary":"Terminal은 **명령어를 치고 결과를 보는 창**이다.","aliases":["terminal","터미널"],"related":[{"term":"CLI","note":"— 글자로 명령을 주고받는 방식 그 자체"},{"term":"Environment Variable","note":"— PATH 처럼 Shell 설정 파일에 적어두는 값"},{"term":"SSH","note":"— 원격 서버의 Shell 을 내 터미널에 붙이는 방법"},{"term":"Git","note":"— 터미널에서 가장 많이 치게 되는 명령"}]},{"id":"tool--trunk-based-development","term":"Trunk Based Development","reading":"트렁크 기반 개발","category":"개발 도구","summary":"Trunk Based Development는 **모두가 한 줄기에 매일 합치는 방식**이다.","aliases":["trunk based development","트렁크 기반 개발"],"related":[{"term":"CI_CD","note":"— 규범 문서가 트렁크 기반 개발을 이것의 핵심 조건으로 든다"},{"term":"Git","note":"— 줄기와 가지를 실제로 만들고 합치는 도구"},{"term":"Cherry-pick","note":"— 줄기에서 고친 수정을 릴리스 가지로 내려보낼 때 쓰는 짝"},{"term":"Build","note":"— 가지를 줄기로 넣기 전에 통과해야 하는 자동 검사"},{"term":"DevOps","note":"— 커밋에서 배포까지를 한 줄기로 잇는 방식. 그 앞단의 분기 규칙이 이것이다"}]},{"id":"tool--term-e82c0160","term":"환경 변수","reading":"Environment Variable","category":"개발 도구","summary":"환경 변수는 **코드 밖에서 넣어주는 설정값**이다.","aliases":["환경 변수","environment variable"],"related":[{"term":"Docker","note":"— 컨테이너에 설정을 넘기는 방식이 환경 변수로 정리되어 있다"},{"term":"API Key","note":"— 코드에 두면 안 되는 대표적인 값"},{"term":"CI_CD","note":"— 배포 과정에서 환경별 값을 주입하는 자리"},{"term":"Git","note":"— `.env` 를 버전 관리에서 빼는 일이 여기서 벌어진다"}]}]},{"id":"ai","name":"AI · LLM","blurb":"요즘 제품에 들어가는 말들","terms":[{"id":"ai--a2a","term":"A2A","reading":"Agent2Agent Protocol","category":"AI · LLM","summary":"A2A는 **에이전트가 다른 에이전트에게 일을 맡기는 규약**이다.","aliases":["a2a","agent2agent protocol"],"related":[{"term":"MCP","note":"— 에이전트와 도구 사이를 정한 규약. 이쪽은 에이전트와 에이전트 사이다"},{"term":"AI Agent","note":"— 이 규약이 양쪽 끝에 세워 두는 것"},{"term":"Webhook","note":"— 스트림을 못 열 때 진행 상황을 대신 받는 방법"},{"term":"gRPC","note":"— 이 규약이 고를 수 있는 오가는 방식 하나"}]},{"id":"ai--ai-agent","term":"AI Agent","reading":"AI 에이전트","category":"AI · LLM","summary":"AI Agent는 **목표를 받아 스스로 도구를 써가며 일하는 AI**다.","aliases":["ai agent","ai 에이전트"],"related":[{"term":"LLM","note":"— 에이전트가 판단할 때 쓰는 자리"},{"term":"ReAct","note":"— 생각과 행동을 번갈아 하는 대표적인 동작 방식"},{"term":"MCP","note":"— 에이전트에 도구를 붙이는 규약"},{"term":"RAG","note":"— 에이전트가 외부 지식을 끌어오는 방법"},{"term":"Orchestrator","note":"— 에이전트 여럿을 묶어 순서를 정하는 쪽"}]},{"id":"ai--agent","term":"Agent","reading":"AI 에이전트","category":"AI · LLM","summary":"Agent는 **목표를 받아 스스로 도구를 쓰며 일을 끝내는 AI**다.","aliases":["agent","ai 에이전트"],"related":[{"term":"LLM","note":"— Agent가 다음 행동을 정할 때 쓰는 모델"},{"term":"ReAct","note":"— 생각과 행동을 번갈아 하는 대표적인 진행 방식"},{"term":"Prompt Engineering","note":"— 어떤 도구를 어떻게 쓸지 알려주는 지시문을 짜는 일"},{"term":"MCP","note":"— 도구를 Agent에 붙이는 규격"},{"term":"Fallback","note":"— 도구가 실패했을 때 대신 할 일"}]},{"id":"ai--agent-memory","term":"Agent Memory","reading":"에이전트 메모리","category":"AI · LLM","summary":"Agent Memory는 **대화가 끝나도 남도록 밖에 적어 두는 기록**이다.","aliases":["agent memory","에이전트 메모리"],"related":[{"term":"Context Window","note":"— 한 번에 보는 창. 이 기록은 그 창 밖에 산다"},{"term":"Agent","note":"— 이 기록을 읽고 쓰는 쪽"},{"term":"RAG","note":"— 밖에서 꺼내 온다는 점은 같고, 이쪽은 자기가 적은 것을 꺼낸다"},{"term":"Prompt Caching","note":"— 저쪽은 잠깐 남기고, 이쪽은 대화가 끝나도 남는다"},{"term":"Token","note":"— 폴더가 커질수록 읽어 오는 양이 늘어난다"}]},{"id":"ai--attention","term":"Attention","reading":"어텐션","category":"AI · LLM","summary":"Attention은 **각 낱말이 어느 낱말을 얼마나 볼지 정하는 장치**다.","aliases":["attention","어텐션"],"related":[{"term":"Transformer","note":"— 이 장치만 남기고 순환을 걷어낸 구조"},{"term":"Token","note":"— 어텐션이 서로 견주는 조각의 단위"},{"term":"Embedding","note":"— 낱말을 견줄 수 있는 숫자로 바꿔 두는 앞 단계"},{"term":"Context Window","note":"— 한 번에 서로 견줄 수 있는 낱말 수의 상한"},{"term":"LLM","note":"— 이 장치를 층층이 쌓아 만든 모델"}]},{"id":"ai--cnn","term":"CNN","reading":"Convolutional Neural Network","category":"AI · LLM","summary":"CNN은 **이미지에서 무늬를 찾아내도록 만든 신경망**이다.","aliases":["cnn","convolutional neural network"],"related":[{"term":"Transformer","note":"— 이웃 대신 전체의 관계를 보는 다른 신경망 구조"},{"term":"Fine-tuning","note":"— 이미 학습된 CNN을 내 데이터에 맞게 다시 다듬는 일"},{"term":"Embedding","note":"— CNN이 뽑아낸 특징도 결국 숫자 벡터로 남는다"},{"term":"LLM","note":"— 언어를 다루는 쪽. CNN이 이미지에서 하는 일에 대응한다"}]},{"id":"ai--chunking","term":"Chunking","reading":"청킹, 문서 분할","category":"AI · LLM","summary":"Chunking은 **긴 문서를 검색할 크기로 잘라두는 일**이다.","aliases":["chunking","청킹, 문서 분할"],"related":[{"term":"Embedding","note":"— 잘라낸 조각을 벡터로 바꾸는 단계"},{"term":"RAG","note":"— 청킹이 쓰이는 자리"},{"term":"Vector DB","note":"— 조각과 벡터가 저장되는 곳"},{"term":"Semantic Search","note":"— 저장된 조각을 뜻으로 찾아내는 일"}]},{"id":"ai--context-window","term":"Context Window","reading":"컨텍스트 윈도우","category":"AI · LLM","summary":"Context Window는 **모델이 한 번에 볼 수 있는 글의 길이**다.","aliases":["context window","컨텍스트 윈도우"],"related":[{"term":"Token","note":"— 창 크기를 세는 단위"},{"term":"LLM","note":"— 이 한도를 갖는 주체"},{"term":"RAG","note":"— 창에 넣을 조각을 골라 오는 방법"},{"term":"Chunking","note":"— 긴 문서를 창에 들어갈 크기로 자르는 일"}]},{"id":"ai--cosine-similarity","term":"Cosine Similarity","reading":"코사인 유사도","category":"AI · LLM","summary":"Cosine Similarity는 **두 벡터가 같은 쪽을 보는지 재는 값**이다.","aliases":["cosine similarity","코사인 유사도"],"related":[{"term":"Embedding","note":"— 각도를 재려면 먼저 글을 벡터로 바꿔야 한다"},{"term":"Vector DB","note":"— 많은 벡터와의 각도를 빠르게 재주는 저장소"},{"term":"Semantic Search","note":"— 이 값을 써서 뜻으로 찾는 검색"},{"term":"RAG","note":"— 모델에 넘길 조각을 이 값으로 고른다"},{"term":"Reranking","note":"— 각도로 추린 뒤 다시 순서를 매기는 단계"}]},{"id":"ai--distillation","term":"Distillation","reading":"지식 증류","category":"AI · LLM","summary":"Distillation은 **큰 모델의 답안지를 작은 모델에 베껴 넣는 학습**이다.","aliases":["distillation","지식 증류"],"related":[{"term":"Fine-tuning","note":"— 이미 학습된 모델에 예시를 더 먹이는 쪽. 증류는 목표 자체를 선생의 확률로 바꾼다"},{"term":"Quantization","note":"— 학습 없이 자릿수만 줄여 작게 만드는 다른 길"},{"term":"LoRA","note":"— 본체를 얼리고 얇은 조각만 학습하는 또 다른 길"},{"term":"LLM","note":"— 선생과 학생이 되는 모델"},{"term":"Token","note":"— 선생을 불러 답을 받아 내는 값을 세는 단위"}]},{"id":"ai--embedding","term":"Embedding","reading":"임베딩","category":"AI · LLM","summary":"Embedding은 **글이나 이미지를 뜻이 담긴 숫자 목록으로 바꾸는 것**이다.","aliases":["embedding","임베딩"],"related":[{"term":"Vector DB","note":"— 만들어진 벡터를 저장하고 가까운 것을 찾아주는 곳"},{"term":"RAG","note":"— 임베딩 검색을 답변 생성에 붙인 구조"},{"term":"Cosine Similarity","note":"— 두 벡터가 얼마나 가까운지 재는 방법"},{"term":"Semantic Search","note":"— 임베딩으로 하는 뜻 기반 검색"}]},{"id":"ai--escalation","term":"Escalation","reading":"에스컬레이션","category":"AI · LLM","summary":"Escalation은 **AI가 못 푸는 대화를 사람에게 넘기는 절차**다.","aliases":["escalation","에스컬레이션"],"related":[{"term":"AI Agent","note":"— 에스컬레이션을 판단하고 실행하는 주체"},{"term":"Fallback","note":"— 넘기기 전에 먼저 시도하는 대체 응답"},{"term":"Guardrail","note":"— 넘겨야 할 상황을 걸러내는 안전장치"},{"term":"Routing","note":"— 넘긴 건을 어느 담당자에게 보낼지 정하는 일"}]},{"id":"ai--eval","term":"Eval","reading":"평가","category":"AI · LLM","summary":"Eval은 **모델의 답을 미리 정한 기준으로 채점하는 시험**이다.","aliases":["eval","평가"],"related":[{"term":"Prompt Engineering","note":"— 고쳐 보는 쪽. 평가는 그 결과를 재는 짝이다"},{"term":"Hallucination","note":"— 평가로 잡아내려는 대표적인 실패"},{"term":"Guardrail","note":"— 막는 쪽. 평가는 배포 전에 재는 쪽이다"},{"term":"Cosine Similarity","note":"— 같은 질문에 답이 얼마나 비슷한지를 잴 때 쓰는 자"},{"term":"A/B Testing","note":"— 배포한 뒤 사람 반응으로 재는 쪽"}]},{"id":"ai--fallback","term":"Fallback","reading":"폴백","category":"AI · LLM","summary":"Fallback은 **첫 시도가 실패했을 때 대신 쓰는 두 번째 방법**이다.","aliases":["fallback","폴백"],"related":[{"term":"Escalation","note":"— 폴백이 다 끝난 뒤에 사람에게 넘기는 단계"},{"term":"Circuit Breaker","note":"— 죽은 곳을 아예 부르지 않게 막는 장치. 폴백과 짝으로 쓴다"},{"term":"Routing","note":"— 첫 번째로 어디에 물어볼지 고르는 쪽"},{"term":"RAG","note":"— 폴백 순서에 자주 들어가는 문서 검색 방식"}]},{"id":"ai--few-shot-zero-shot-learning","term":"Few-shot & Zero-shot Learning","reading":"","category":"AI · LLM","summary":"Zero-shot과 Few-shot은 **프롬프트에 예시를 몇 개 넣느냐**로 갈리는 지시 방식이다.","aliases":["few-shot & zero-shot learning","few-shot & zero-shot","few-shot","zero-shot learning"],"related":[{"term":"Prompt","note":"— 예시가 실제로 들어가 앉는 자리"},{"term":"LLM","note":"— 예시를 읽고 형식을 맞추는 쪽"},{"term":"Fine-tuning","note":"— 예시를 모델에 새겨 넣는 다른 길"},{"term":"Context Window","note":"— 예시를 몇 개까지 붙일 수 있는지를 정하는 한계"},{"term":"RAG","note":"— 예시 대신 문서를 붙여 넣는 방법. 같이 쓰기도 한다"}]},{"id":"ai--fine-tuning","term":"Fine-tuning","reading":"파인튜닝, 미세 조정","category":"AI · LLM","summary":"Fine-tuning은 **이미 학습된 모델에 예시를 더 먹여 다시 학습시키는 일**이다.","aliases":["fine-tuning","파인튜닝, 미세 조정"],"related":[{"term":"LLM","note":"— 파인튜닝의 대상이 되는 모델"},{"term":"RAG","note":"— 학습 대신 문서를 찾아 넣어주는 다른 접근"},{"term":"Prompt","note":"— 학습 없이 지시문만으로 조정하는 방법"},{"term":"Token","note":"— 학습 비용과 요청 비용을 세는 단위"},{"term":"Few-shot & Zero-shot","note":"— 예시를 요청 안에 몇 개만 넣어보는 중간 방법"}]},{"id":"ai--guardrail","term":"Guardrail","reading":"가드레일","category":"AI · LLM","summary":"Guardrail은 **AI가 하면 안 되는 일을 막는 검사 장치**다.","aliases":["guardrail","가드레일"],"related":[{"term":"PII","note":"— Guardrail이 입력과 출력 양쪽에서 찾아내는 정보"},{"term":"AI Agent","note":"— Guardrail이 감싸는 대상"},{"term":"Audit Log","note":"— 막힌 시도를 남겨두는 곳"},{"term":"RBAC","note":"— 행동 검사에서 권한을 볼 때 쓰는 기준"},{"term":"Escalation","note":"— 막은 다음 사람에게 넘겨야 할 때의 절차"}]},{"id":"ai--hallucination","term":"Hallucination","reading":"환각","category":"AI · LLM","summary":"Hallucination은 **모델이 사실이 아닌 것을 사실처럼 말하는 현상**이다.","aliases":["hallucination","환각"],"related":[{"term":"LLM","note":"— 환각이 나오는 구조 자체"},{"term":"RAG","note":"— 지어낼 필요를 줄이는 대표적인 대응"},{"term":"Prompt Engineering","note":"— 출처를 강제하는 지시를 짜는 일"},{"term":"Fine-tuning","note":"— 특정 분야에서 환각을 줄이는 다른 방법"}]},{"id":"ai--human-in-the-loop","term":"Human in the Loop","reading":"사람 개입","category":"AI · LLM","summary":"Human in the Loop은 **중요한 동작 앞에 사람 승인을 끼워 넣는 설계**다.","aliases":["human in the loop","사람 개입"],"related":[{"term":"Agent","note":"— 사람 칸을 끼워 넣는 그 고리"},{"term":"Guardrail","note":"— 기계가 자동으로 막는 쪽. 이쪽은 사람이 막는다"},{"term":"Prompt Injection","note":"— 승인 칸이 마지막 방어선이 되는 대표적인 공격"},{"term":"Escalation","note":"— 처리하던 것을 사람에게 넘기는 다른 형태"},{"term":"Fallback","note":"— 자동으로 못 하겠을 때 대신 가는 다른 길"}]},{"id":"ai--inference-vs-training","term":"Inference vs Training","reading":"추론과 학습","category":"AI · LLM","summary":"학습은 모델의 값을 고치는 때고, **추론은 그 값을 읽기만 하는 때**다.","aliases":["inference vs training","추론과 학습","inference","training"],"related":[{"term":"Fine-tuning","note":"— 이미 끝난 학습을 내 데이터로 조금 더 잇는 일"},{"term":"Parameter Count","note":"— 학습이 정하고 추론이 읽는 그 값들의 개수"},{"term":"Prompt","note":"— 추론 때 새 사실을 넣는 유일한 자리"},{"term":"Context Window","note":"— 추론 한 번에 넣을 수 있는 양의 한도"},{"term":"Hallucination","note":"— 굳은 값 안에 없는 것을 지어내는 일"}]},{"id":"ai--intent","term":"Intent 분류","reading":"Intent Classification","category":"AI · LLM","summary":"Intent 분류는 **사용자 말에서 무엇을 원하는지 골라내는 일**이다.","aliases":["intent 분류","intent classification"],"related":[{"term":"Routing","note":"— 분류 결과에 따라 어디로 보낼지 정하는 다음 단계"},{"term":"Orchestrator","note":"— 나뉜 갈래들을 묶어 전체 흐름을 이끄는 쪽"},{"term":"LLM","note":"— 맥락까지 보는 분류에 쓰이는 모델"},{"term":"AI Agent","note":"— 정해진 갈래를 실제로 처리하는 쪽"},{"term":"Few-shot & Zero-shot","note":"— 예시 몇 개로 분류 정확도를 올리는 방법"}]},{"id":"ai--jailbreak","term":"Jailbreak","reading":"탈옥","category":"AI · LLM","summary":"Jailbreak은 **거절하도록 배운 답을 말을 바꿔 꺼내는 시도**다.","aliases":["jailbreak","탈옥"],"related":[{"term":"Prompt Injection","note":"— 같은 뿌리의 공격. 이쪽은 남이 써 둔 글이 대신 명령한다"},{"term":"Guardrail","note":"— 모델 앞뒤에 세워 이 시도를 걸러내는 장치"},{"term":"Prompt","note":"— 탈옥이 손대는 그 글 자체"},{"term":"Fine-tuning","note":"— 거절하는 법을 가르치는 안전 학습이 이루어지는 자리"},{"term":"LLM","note":"— 그 학습이 걸려 있는 대상"}]},{"id":"ai--llm","term":"LLM","reading":"Large Language Model","category":"AI · LLM","summary":"LLM은 **다음에 올 단어를 확률로 고르는 모델**이다.","aliases":["llm","large language model"],"related":[{"term":"Token","note":"— 모델이 다루는 최소 단위이자 비용의 단위"},{"term":"Hallucination","note":"— 근거 없이 그럴듯한 말을 만드는 현상"},{"term":"RAG","note":"— 답의 근거를 밖에서 찾아 넣어주는 방법"},{"term":"Transformer","note":"— 지금 LLM 대부분이 쓰는 구조"}]},{"id":"ai--lora","term":"LoRA","reading":"Low-Rank Adaptation","category":"AI · LLM","summary":"LoRA는 **원래 가중치는 얼리고 얇은 표 두 장만 학습하는 방법**이다.","aliases":["lora","low-rank adaptation"],"related":[{"term":"Fine-tuning","note":"— 통째로 다시 학습하는 쪽. LoRA 는 그 자리를 두 장으로 좁힌 것이다"},{"term":"Quantization","note":"— 본체를 얼려 담는 자릿수. 4비트 위에 조각을 얹는 조합이 흔하다"},{"term":"Open Weight","note":"— 본체 파일이 손에 있어야 조각을 붙일 수 있다"},{"term":"Transformer","note":"— 조각을 붙이는 자리인 어텐션이 있는 구조"},{"term":"LLM","note":"— 얼려 두는 본체"}]},{"id":"ai--multimodal","term":"Multimodal","reading":"멀티모달","category":"AI · LLM","summary":"Multimodal은 **글과 함께 그림 같은 다른 입력도 받는 것**이다.","aliases":["multimodal","멀티모달"],"related":[{"term":"Token","note":"— 그림 조각도 이 단위로 세어진다"},{"term":"Context Window","note":"— 그림 토큰도 이 한도를 같이 나눠 쓴다"},{"term":"Prompt","note":"— 그림과 나란히 실어 보내는 글"},{"term":"LLM","note":"— 글만 받던 쪽. 여기에 그림 입구가 붙은 것이다"},{"term":"CNN","note":"— 그림을 다루던 다른 계열의 모델"}]},{"id":"ai--open-weight","term":"Open Weight","reading":"오픈 웨이트","category":"AI · LLM","summary":"Open Weight는 **학습된 숫자 파일을 누구나 받을 수 있게 푼 모델**이다.","aliases":["open weight","오픈 웨이트"],"related":[{"term":"Quantization","note":"— 받은 파일의 자릿수를 줄여 장비에 맞추는 일"},{"term":"LoRA","note":"— 받은 본체를 얼려 두고 조각만 학습하는 일"},{"term":"Distillation","note":"— 받은 모델을 선생 삼아 더 작은 모델을 만드는 일"},{"term":"LLM","note":"— 파일로 열리는 대상"},{"term":"Fine-tuning","note":"— 파일이 손에 있어야 마음대로 걸 수 있는 학습"}]},{"id":"ai--orchestrator","term":"Orchestrator","reading":"오케스트레이터","category":"AI · LLM","summary":"Orchestrator 는 **요청을 보고 어느 Agent 에게 맡길지 정하는 층**이다.","aliases":["orchestrator","오케스트레이터"],"related":[{"term":"AI Agent","note":"— Orchestrator 가 골라서 부르는 실행 단위"},{"term":"Intent 분류","note":"— 질문을 갈래로 나눈 결과"},{"term":"Fallback","note":"— 맡은 Agent 가 실패했을 때 넘어갈 곳"},{"term":"LLM","note":"— 갈래를 정하고 답을 합치는 데 쓰이는 모델"},{"term":"RAG","note":"— 문서 검색을 맡은 Agent 가 쓰는 방식"}]},{"id":"ai--parameter-count","term":"Parameter Count","reading":"파라미터 수","category":"AI · LLM","summary":"Parameter Count는 **모델이 학습으로 정한 숫자의 개수**다.","aliases":["parameter count","파라미터 수"],"related":[{"term":"LLM","note":"— 이 값을 수십억 개씩 가진 모델"},{"term":"Token","note":"— 파라미터 수와 같은 비율로 늘려야 하는 학습량의 단위"},{"term":"Fine-tuning","note":"— 이미 굳은 값들을 내 데이터로 조금 더 고치는 일"},{"term":"Inference vs Training","note":"— 값을 정하는 때와 정해진 값을 읽는 때"},{"term":"Transformer","note":"— 그 값들이 놓이는 구조"}]},{"id":"ai--prompt","term":"Prompt","reading":"프롬프트","category":"AI · LLM","summary":"Prompt는 **LLM 에게 무엇을 어떻게 해달라고 적어 보내는 글**이다.","aliases":["prompt","프롬프트"],"related":[{"term":"Prompt Engineering","note":"— 프롬프트를 다듬는 일을 따로 부르는 이름"},{"term":"Few-shot & Zero-shot","note":"— 예시를 몇 개 넣느냐로 갈리는 두 방식"},{"term":"Context Window","note":"— 프롬프트가 들어갈 수 있는 크기의 한계"},{"term":"Fine-tuning","note":"— 프롬프트가 아니라 모델 자체를 고치는 쪽"},{"term":"Hallucination","note":"— 프롬프트로 줄이려는 대표적인 문제"}]},{"id":"ai--prompt-caching","term":"Prompt Caching","reading":"프롬프트 캐싱","category":"AI · LLM","summary":"Prompt Caching은 **매번 같은 앞부분을 다시 계산하지 않고 재사용하는 것**이다.","aliases":["prompt caching","프롬프트 캐싱"],"related":[{"term":"Prompt","note":"— 캐시가 걸리는 대상 그 자체"},{"term":"Token","note":"— 새로 넣은 양과 꺼내 쓴 양을 세는 단위"},{"term":"Context Window","note":"— 앞부분을 길게 붙일수록 이 한도와 같이 봐야 한다"},{"term":"Cache","note":"— 같은 것을 두 번 계산하지 않는다는 원리의 원형"},{"term":"Agent Memory","note":"— 이쪽은 수명이 짧고, 저쪽은 대화가 끝나도 남는다"}]},{"id":"ai--prompt-engineering","term":"Prompt Engineering","reading":"프롬프트 엔지니어링","category":"AI · LLM","summary":"Prompt Engineering은 **원하는 답이 나오도록 질문을 설계하는 기술**이다.","aliases":["prompt engineering","프롬프트 엔지니어링"],"related":[{"term":"LLM","note":"— 프롬프트를 받아 답을 만드는 모델"},{"term":"Few-shot & Zero-shot","note":"— 예시를 몇 개 주느냐로 갈리는 두 가지 방식"},{"term":"RAG","note":"— 모델이 모르는 사실을 프롬프트에 실어 넣는 방법"},{"term":"Token","note":"— 프롬프트를 길게 쓸수록 늘어나는 단위"}]},{"id":"ai--prompt-injection","term":"Prompt Injection","reading":"프롬프트 주입","category":"AI · LLM","summary":"Prompt Injection은 **넣어 준 글이 원래 지시를 밀어내는 공격**이다.","aliases":["prompt injection","프롬프트 주입"],"related":[{"term":"Jailbreak","note":"— 같은 뿌리의 다른 공격. 이쪽은 사용자가 직접 자기 앞의 규칙을 푼다"},{"term":"Guardrail","note":"— 이 공격을 걸러내려고 모델 앞뒤에 세우는 검사 장치"},{"term":"Prompt","note":"— 밀려나는 그 원래 지시가 적힌 자리"},{"term":"Agent","note":"— 도구를 부를 수 있어서 뚫렸을 때 피해가 커지는 쪽"},{"term":"SQL Injection","note":"— 값이 놓일 자리에 명령이 들어간다는 점이 같은 옛 공격"}]},{"id":"ai--quantization","term":"Quantization","reading":"양자화","category":"AI · LLM","summary":"Quantization은 **모델의 숫자를 더 적은 자릿수로 줄여 담는 일**이다.","aliases":["quantization","양자화"],"related":[{"term":"LLM","note":"— 자릿수를 줄이는 대상"},{"term":"Open Weight","note":"— 파일을 받아야 자릿수에 손을 댈 수 있다"},{"term":"LoRA","note":"— 줄여 얼린 본체 위에 얇은 조각만 얹어 학습하는 짝"},{"term":"Distillation","note":"— 학습을 다시 시켜 작게 만드는 다른 길"},{"term":"Memory","note":"— 여기서 실제로 줄어드는 자리"}]},{"id":"ai--rag","term":"RAG","reading":"Retrieval-Augmented Generation","category":"AI · LLM","summary":"RAG는 **답하기 전에 관련 문서를 찾아 같이 넣어주는 방식**이다.","aliases":["rag","retrieval-augmented generation"],"related":[{"term":"Embedding","note":"— 문서와 질문을 벡터로 바꾸는 단계"},{"term":"Vector DB","note":"— 그 벡터를 저장하고 가까운 것을 찾아주는 곳"},{"term":"Hallucination","note":"— RAG가 줄이려는 대상"},{"term":"Chunking","note":"— 문서를 어떻게 자를지 정하는 일"}]},{"id":"ai--react","term":"ReAct","reading":"Reasoning + Acting","category":"AI · LLM","summary":"ReAct는 **생각과 행동을 번갈아 하는 AI 에이전트 방식**이다.","aliases":["react","reasoning + acting"],"related":[{"term":"AI Agent","note":"— ReAct는 에이전트를 굴리는 대표적인 방식이다"},{"term":"Prompt Engineering","note":"— 생각과 행동을 나눠 적게 하는 것이 이 방식의 프롬프트다"},{"term":"Hallucination","note":"— 도구로 확인하게 해서 줄이려는 대상"},{"term":"LangGraph","note":"— 이 반복을 흐름으로 짜서 돌리는 도구"},{"term":"RAG","note":"— 찾아온 자료로 답하게 한다는 점이 겹친다"}]},{"id":"ai--reranking","term":"Reranking","reading":"재순위화","category":"AI · LLM","summary":"Reranking은 **먼저 뽑아온 검색 결과의 순위를 다시 매기는 단계**다.","aliases":["reranking","재순위화"],"related":[{"term":"RAG","note":"— 리랭킹이 끼어드는 전체 흐름"},{"term":"Embedding","note":"— 1차 검색이 쓰는 벡터를 만드는 일"},{"term":"Vector DB","note":"— 그 벡터를 담아두고 빠르게 훑는 곳"},{"term":"Semantic Search","note":"— 리랭킹이 순서를 고쳐주는 1차 검색 방식"},{"term":"Cosine Similarity","note":"— 1차에서 벡터끼리 거리를 재는 방법"}]},{"id":"ai--routing","term":"Routing","reading":"라우팅","category":"AI · LLM","summary":"Routing은 **요청을 어느 처리자에게 넘길지 정하는 일**이다.","aliases":["routing","라우팅"],"related":[{"term":"Intent 분류","note":"— 라우팅이 판단 근거로 쓰는 앞 단계"},{"term":"Orchestrator","note":"— 여럿을 부르고 결과를 합치는 쪽. 라우터 다음 단계"},{"term":"AI Agent","note":"— 라우터가 골라서 넘기는 대상"},{"term":"Fallback","note":"— 어느 쪽도 확실하지 않을 때 가는 자리"}]},{"id":"ai--semantic-search","term":"Semantic Search","reading":"의미 검색","category":"AI · LLM","summary":"Semantic Search는 **낱말이 달라도 뜻이 비슷하면 찾아주는 검색**이다.","aliases":["semantic search","의미 검색"],"related":[{"term":"Embedding","note":"— 문장을 숫자 배열로 바꾸는 그 변환"},{"term":"Vector DB","note":"— 바꿔 놓은 배열을 담고 거리로 찾아주는 저장소"},{"term":"Cosine Similarity","note":"— 두 배열이 얼마나 가까운지 재는 방법"},{"term":"RAG","note":"— 이 검색을 앞에 두고 답을 만드는 구조"},{"term":"Reranking","note":"— 골라온 결과의 순서를 한 번 더 손보는 단계"}]},{"id":"ai--structured-output","term":"Structured Output","reading":"구조화 출력","category":"AI · LLM","summary":"Structured Output 은 **답의 모양을 미리 정해 두고 받는 방식**이다.","aliases":["structured output","구조화 출력"],"related":[{"term":"Tool Calling","note":"— 도구에 넘길 값도 같은 방식으로 모양을 강제한다"},{"term":"Hallucination","note":"— 모양은 막아도 지어내는 것은 못 막는다"},{"term":"Prompt Engineering","note":"— 부탁으로 하던 일을 규격으로 옮긴 것이다"},{"term":"Eval","note":"— 모양이 아니라 내용이 맞는지는 따로 재야 한다"}]},{"id":"ai--system-prompt","term":"System Prompt","reading":"시스템 프롬프트","category":"AI · LLM","summary":"System Prompt 는 **대화보다 먼저 서는 지시문**이다.","aliases":["system prompt","시스템 프롬프트"],"related":[{"term":"Prompt","note":"— 이 자리에 담기는 것도 결국 프롬프트다"},{"term":"Prompt Injection","note":"— 사람 쪽 말로 이 지시를 뒤집으려는 공격"},{"term":"Guardrail","note":"— 지시만으로 못 막는 것을 바깥에서 막는 장치"},{"term":"Context Window","note":"— 여기 적은 글자도 그 한도를 같이 먹는다"}]},{"id":"ai--temperature","term":"Temperature","reading":"온도","category":"AI · LLM","summary":"Temperature 는 **답을 고를 때의 모험을 정하는 값**이다.","aliases":["temperature","온도"],"related":[{"term":"Token","note":"— 이 값이 흔드는 것은 결국 다음 토큰 하나의 선택이다"},{"term":"Prompt","note":"— 값으로 못 잡는 흔들림은 시키는 말로 잡는다"},{"term":"Eval","note":"— 값을 바꾼 뒤 좋아졌는지는 재 봐야 안다"},{"term":"Hallucination","note":"— 높게 두면 지어내는 쪽으로 기울기 쉽다"}]},{"id":"ai--text-to-sql","term":"Text-to-SQL","reading":"","category":"AI · LLM","summary":"Text-to-SQL은 **말로 물으면 SQL을 만들어주는 기술**이다.","aliases":["text-to-sql"],"related":[{"term":"SQL","note":"— 최종적으로 만들어져 DB로 가는 것"},{"term":"LLM","note":"— 질문과 스키마를 보고 쿼리를 만드는 모델"},{"term":"Hallucination","note":"— 없는 표 이름을 지어내는 현상"},{"term":"QueryPie","note":"— 만들어진 쿼리를 실행 전에 거르는 보안 게이트"}]},{"id":"ai--token","term":"Token","reading":"토큰","category":"AI · LLM","summary":"Token은 **모델이 글을 다루는 최소 조각**이다.","aliases":["token","토큰"],"related":[{"term":"LLM","note":"— 토큰을 예측하는 것이 이 모델이 하는 일의 전부다"},{"term":"Context Window","note":"— 토큰으로 세는 한 번에 볼 수 있는 양"},{"term":"Embedding","note":"— 토큰을 벡터로 바꾸는 다음 단계"},{"term":"Prompt Engineering","note":"— 같은 지시를 적은 토큰으로 쓰는 일이 여기 포함된다"}]},{"id":"ai--tool-calling","term":"Tool Calling","reading":"도구 호출","category":"AI · LLM","summary":"Tool Calling 은 **모델이 시키고 앱이 실행하는 방식**이다.","aliases":["tool calling","도구 호출"],"related":[{"term":"AI Agent","note":"— 도구 호출을 여러 번 돌려 스스로 일을 끝내는 것"},{"term":"MCP","note":"— 도구를 매번 새로 붙이지 않도록 잇는 방식을 규격으로 정한 것"},{"term":"Prompt Injection","note":"— 실행 직전에 막지 않으면 이 통로로 들어온다"},{"term":"ReAct","note":"— 판단과 도구 실행을 번갈아 하는 방식"}]},{"id":"ai--transformer","term":"Transformer","reading":"트랜스포머","category":"AI · LLM","summary":"Transformer는 **문장을 한꺼번에 펼쳐 놓고 서로의 관계를 재는 구조**다.","aliases":["transformer","트랜스포머"],"related":[{"term":"LLM","note":"— 이 구조 위에 세워진 모델들"},{"term":"Token","note":"— Transformer 가 다루는 조각의 단위"},{"term":"Embedding","note":"— 그 조각을 숫자 배열로 바꾼 것"},{"term":"Context Window","note":"— 한 번에 펼쳐 놓을 수 있는 조각 수의 한계"},{"term":"Fine-tuning","note":"— 학습된 Transformer 를 특정 용도로 다시 손보는 일"}]},{"id":"ai--vector-db","term":"Vector DB","reading":"벡터 데이터베이스","category":"AI · LLM","summary":"Vector DB는 **벡터를 저장하고 가까운 것을 빠르게 찾아주는 저장소**다.","aliases":["vector db","벡터 데이터베이스"],"related":[{"term":"Embedding","note":"— 여기에 저장될 벡터를 만드는 단계"},{"term":"RAG","note":"— 벡터 DB를 답변 생성에 붙인 구조"},{"term":"Index","note":"— 빠른 검색을 위해 미리 만들어두는 구조"},{"term":"Semantic Search","note":"— 벡터 DB로 하는 뜻 기반 검색"}]},{"id":"ai--term-c69518b3","term":"경사 하강법","reading":"Gradient Descent","category":"AI · LLM","summary":"경사 하강법은 **틀림이 줄어드는 쪽으로 조금씩 옮기는 방법**이다.","aliases":["경사 하강법","gradient descent"],"related":[{"term":"신경망","note":"— 이 방법으로 층마다의 무게를 맞춘다"},{"term":"지도 학습","note":"— 틀림을 재려면 정답이 붙어 있어야 한다"},{"term":"과적합","note":"— 틀림이 0 에 닿았을 때 의심해야 하는 것"},{"term":"Fine-tuning","note":"— 이미 맞춰진 값에서 다시 걸음을 시작하는 일"}]},{"id":"ai--term-ffd91e00","term":"과적합","reading":"Overfitting","category":"AI · LLM","summary":"과적합은 **연습 문제를 외워 새 문제에서 틀리는 상태**다.","aliases":["과적합","overfitting"],"related":[{"term":"지도 학습","note":"— 이 함정이 나오는 자리"},{"term":"신경망","note":"— 크게 만들수록 더 쉽게 빠진다"},{"term":"Eval","note":"— 안 본 자료로 재는 일 그 자체"},{"term":"Fine-tuning","note":"— 적은 자료로 다듬을 때 특히 조심할 것"}]},{"id":"ai--term-7edc1a6b","term":"신경망","reading":"Neural Network","category":"AI · LLM","summary":"신경망은 **숫자를 여러 겹으로 거르며 답에 다가가는 구조**다.","aliases":["신경망","neural network"],"related":[{"term":"CNN","note":"— 사진을 다루려고 이 구조를 특별한 모양으로 만든 것"},{"term":"Transformer","note":"— 지금 언어 모델이 쓰는 신경망의 한 모양"},{"term":"경사 하강법","note":"— 층마다의 무게를 실제로 고치는 방법"},{"term":"과적합","note":"— 층을 깊게 쌓을수록 빠지기 쉬운 함정"},{"term":"Parameter Count","note":"— 그 무게가 모두 몇 개인지를 센 수"}]},{"id":"ai--term-ddd274d7","term":"지도 학습","reading":"Supervised Learning","category":"AI · LLM","summary":"지도 학습은 **정답이 붙은 예로 가르치는 학습 방식**이다.","aliases":["지도 학습","supervised learning"],"related":[{"term":"과적합","note":"— 정답표를 외워 버렸을 때 생기는 일"},{"term":"신경망","note":"— 이 방식으로 가르치는 대표적인 구조"},{"term":"Fine-tuning","note":"— 이미 배운 모델에 정답표를 더 먹여 다듬는 일"},{"term":"Eval","note":"— 배운 것이 쓸 만한지 정답표로 재는 일"}]}]},{"id":"pm","name":"제품 관리","blurb":"무엇을 왜 만드는지 정하는 말","terms":[{"id":"pm--a-b-testing","term":"A/B Testing","reading":"A/B 테스트","category":"제품 관리","summary":"A/B Testing은 **두 버전을 동시에 내보내 어느 쪽이 나은지 재는 실험**이다.","aliases":["a/b testing","a/b 테스트","a b testing"],"related":[{"term":"KPI","note":"— 실험에서 무엇을 이겼다고 볼지 정하는 지표"},{"term":"Funnel","note":"— 어느 단계의 전환율을 실험 대상으로 삼을지 알려준다"},{"term":"MVP","note":"— 실험할 것을 최소한으로 만들어 먼저 내보내는 방식"},{"term":"Persona","note":"— 누구를 놓고 가설을 세울지 정해준다"}]},{"id":"pm--agile","term":"Agile","reading":"애자일","category":"제품 관리","summary":"Agile은 **짧게 만들어 보여주고 고쳐 나가는 개발 방식**이다.","aliases":["agile","애자일"],"related":[{"term":"Scrum","note":"— 애자일을 2주 주기로 실천하는 대표적인 틀"},{"term":"Sprint","note":"— 그 한 바퀴에 해당하는 기간"},{"term":"Backlog","note":"— 다음 바퀴에 무엇을 넣을지 고르는 목록"},{"term":"MVP","note":"— 첫 바퀴에 어디까지만 만들지 정하는 기준"},{"term":"User Story","note":"— 한 바퀴에 담을 일을 적는 형식"}]},{"id":"pm--backlog","term":"Backlog","reading":"백로그","category":"제품 관리","summary":"Backlog는 **아직 안 한 일을 우선순위대로 세워둔 목록**이다.","aliases":["backlog","백로그"],"related":[{"term":"User Story","note":"— 백로그에 들어가는 항목을 적는 형식"},{"term":"Sprint","note":"— 백로그 위쪽을 꺼내 진행하는 한 주기"},{"term":"Agile","note":"— 백로그를 계속 다시 세우는 것을 전제로 하는 방식"},{"term":"Product Roadmap","note":"— 백로그보다 위에서 방향을 잡는 계획"},{"term":"MVP","note":"— 첫 출시에 넣을 항목을 고르는 기준"}]},{"id":"pm--cac-ltv","term":"CAC / LTV","reading":"고객 획득 비용과 생애 가치","category":"제품 관리","summary":"CAC 와 LTV 는 **고객 한 명에 드는 돈과 그 고객이 주는 돈**이다.","aliases":["cac / ltv","고객 획득 비용과 생애 가치","cac ltv","cac","ltv"],"related":[{"term":"North Star Metric","note":"— 이 숫자들 위에 놓는 하나의 대표 지표"},{"term":"Retention","note":"— 유지 기간을 늘려 LTV 를 키우는 쪽"},{"term":"Funnel","note":"— 전환율이 오르면 같은 비용으로 CAC 가 내려간다"},{"term":"OKR","note":"— 이 숫자들을 목표로 잡아 관리할 때 쓰는 틀"}]},{"id":"pm--crm","term":"CRM","reading":"Customer Relationship Management","category":"제품 관리","summary":"CRM은 **고객과 주고받은 일을 한곳에 모아두는 시스템**이다.","aliases":["crm","customer relationship management"],"related":[{"term":"Funnel","note":"— 고객이 단계를 밟아 내려가는 흐름. 파이프라인이 이걸 그린 것"},{"term":"KPI","note":"— 전환율이나 성사율처럼 CRM 기록에서 뽑아내는 숫자"},{"term":"CAC LTV","note":"— 한 고객을 데려오는 비용과 그 고객이 남기는 값. CRM 데이터로 계산한다"},{"term":"PII","note":"— CRM에 쌓이는 개인정보. 다루는 방식이 따로 정해져 있다"}]},{"id":"pm--churn-rate","term":"Churn Rate","reading":"이탈률","category":"제품 관리","summary":"Churn Rate는 **한 기간에 떠난 고객의 비율**이다.","aliases":["churn rate","이탈률"],"related":[{"term":"Retention","note":"— 같은 일의 반대쪽. 남은 몫을 보면 리텐션, 빠진 몫을 보면 이탈률이다"},{"term":"Cohort Analysis","note":"— 언제 들어온 무리가 언제 빠지는지를 갈라 보는 방법"},{"term":"CAC LTV","note":"— 이탈률이 생애 가치를 구할 때 나누는 수로 들어간다"},{"term":"DAU MAU","note":"— 명단에서 지워지기 전에 먼저 줄어드는 값"},{"term":"KPI","note":"— 이탈률을 그중 하나로 두는 회사가 많다"}]},{"id":"pm--cohort-analysis","term":"Cohort Analysis","reading":"코호트 분석","category":"제품 관리","summary":"Cohort Analysis는 **같은 때 시작한 사람들을 묶어 따라가는 분석**이다.","aliases":["cohort analysis","코호트 분석"],"related":[{"term":"Retention","note":"— 코호트 분석이 재려는 대표 값"},{"term":"Churn Rate","note":"— 무리에서 빠져나간 쪽을 비율로 적은 값"},{"term":"DAU MAU","note":"— 무리로 안 나눈 전체 활성 수. 여기서 안 보이는 것을 코호트가 본다"},{"term":"A B Testing","note":"— 사람을 시작 시점이 아니라 배정으로 가르는 방법"},{"term":"Funnel","note":"— 사람을 단계로 가른다면 코호트는 시작 시점으로 가른다"}]},{"id":"pm--conversion-rate","term":"Conversion Rate","reading":"전환율","category":"제품 관리","summary":"Conversion Rate는 **온 사람 중 목표 행동을 한 사람의 비율**이다.","aliases":["conversion rate","전환율"],"related":[{"term":"Funnel","note":"— 단계마다의 전환율을 이어 붙인 것"},{"term":"A B Testing","note":"— 두 화면의 전환율을 같은 기간에 견주는 방법"},{"term":"Churn Rate","note":"— 들어오는 쪽의 비율이 이것이면 나가는 쪽의 비율이 이탈률이다"},{"term":"CAC LTV","note":"— 전환율이 오르면 한 명을 데려오는 데 드는 값이 내려간다"},{"term":"KPI","note":"— 전환율을 목표 지표로 두는 자리"}]},{"id":"pm--dau-mau","term":"DAU / MAU","reading":"일간·월간 활성 사용자","category":"제품 관리","summary":"DAU 와 MAU 는 **하루와 한 달 동안 제품을 쓴 사람 수**다.","aliases":["dau / mau","일간·월간 활성 사용자","dau mau","dau","mau","일간","월간 활성 사용자"],"related":[{"term":"Retention","note":"— 활성 사용자가 다음 기간에도 남는지를 보는 값"},{"term":"Cohort Analysis","note":"— 활성 사용자를 언제 들어왔는지로 갈라 보는 방법"},{"term":"Churn Rate","note":"— 활성에서 빠져나간 쪽을 비율로 적은 값"},{"term":"North Star Metric","note":"— 이 값을 회사의 대표 숫자로 삼는 경우가 많다"},{"term":"KPI","note":"— 활성 사용자 수를 목표 지표로 두는 자리"}]},{"id":"pm--dora-metrics","term":"DORA Metrics","reading":"배포 능력 네 지표","category":"제품 관리","summary":"DORA Metrics는 **고친 것을 내보내는 속도와 안정성을 재는 네 숫자**다.","aliases":["dora metrics","배포 능력 네 지표"],"related":[{"term":"CI_CD","note":"— 잦기와 리드 타임이 실제로 결정되는 통로"},{"term":"Rollback","note":"— 복구 시간을 가장 크게 줄이는 장치"},{"term":"Trunk Based Development","note":"— 리드 타임을 줄이려고 고르는 대표적인 작업 방식"},{"term":"SLA SLO SLI","note":"— 사용자가 겪는 품질을 재는 다른 자. 이쪽은 내보내는 능력을 잰다"},{"term":"KPI","note":"— 조직이 쫓는 숫자 일반. 이 넷은 그중 전달 능력만 떼어 본 것이다"}]},{"id":"pm--definition-of-done","term":"Definition of Done","reading":"완료 정의","category":"제품 관리","summary":"Definition of Done은 **무엇을 갖추면 끝난 것으로 치는지 미리 적어 둔 기준**이다.","aliases":["definition of done","완료 정의"],"related":[{"term":"Scrum","note":"— 이 기준을 팀이 지켜야 할 약속으로 못 박아 둔 틀"},{"term":"Sprint","note":"— 이 기준을 통과한 것만 그 바퀴의 결과로 세어지는 한 바퀴"},{"term":"Kanban","note":"— 시작과 끝의 선을 정해야 흐름을 잴 수 있다고 적은 쪽"},{"term":"Story Point","note":"— 이 기준을 통과한 것만 더해야 뜻이 있는 숫자"},{"term":"Retrospective","note":"— 이 기준이 매번 안 지켜질 때 손보는 자리"}]},{"id":"pm--funnel","term":"Funnel","reading":"퍼널","category":"제품 관리","summary":"Funnel은 **사용자가 목표까지 가며 줄어드는 단계별 흐름**이다.","aliases":["funnel","퍼널"],"related":[{"term":"Retention","note":"— 퍼널의 아래쪽에서 다시 돌아오는지를 보는 지표"},{"term":"A B Testing","note":"— 병목으로 지목된 칸을 고칠 때 쓰는 방법"},{"term":"KPI","note":"— 각 칸의 통과율을 지표로 삼은 것"},{"term":"North Star Metric","note":"— 여러 칸의 개선이 결국 움직여야 할 하나의 숫자"}]},{"id":"pm--gtm","term":"GTM","reading":"Go-to-Market","category":"제품 관리","summary":"GTM은 **만든 것을 누구에게 어떻게 팔지 정하는 계획**이다.","aliases":["gtm","go-to-market"],"related":[{"term":"PMF","note":"— 팔릴 물건인지부터 확인하는 단계. GTM은 그다음이다"},{"term":"Persona","note":"— GTM이 좁힌 대상을 사람 모양으로 적어둔 것"},{"term":"Funnel","note":"— 정한 채널에서 고객이 실제로 어디서 빠지는지 보는 틀"},{"term":"MVP","note":"— 작게 내놓고 반응을 보는 방식. GTM의 첫 실행이 되기도 한다"},{"term":"CAC LTV","note":"— 고른 채널이 남는 장사인지 판정하는 숫자"}]},{"id":"pm--kpi","term":"KPI","reading":"Key Performance Indicator","category":"제품 관리","summary":"KPI는 **목표에 얼마나 다가갔는지 재는 숫자**다.","aliases":["kpi","key performance indicator"],"related":[{"term":"OKR","note":"— 목표를 세우는 틀. KPI는 그 목표를 재는 눈금이다"},{"term":"North Star Metric","note":"— 여러 KPI 위에 하나만 세우는 대표 지표"},{"term":"Retention","note":"— 사용자가 남는지를 보는 대표적인 제품 KPI"},{"term":"Funnel","note":"— 단계마다 KPI를 두어 어디서 새는지 찾는 방법"}]},{"id":"pm--kanban","term":"Kanban","reading":"칸반","category":"제품 관리","summary":"Kanban은 **일의 흐름을 보이게 하고 동시 진행 수를 통제하는 전략**이다.","aliases":["kanban","칸반"],"related":[{"term":"Scrum","note":"— 정해진 기간으로 일을 끊는 쪽. 칸반은 흐름으로 끊는다"},{"term":"Sprint","note":"— 스크럼이 쓰는 고정 기간. 칸반에는 이 단위가 없어도 된다"},{"term":"Backlog","note":"— 아직 시작 안 한 카드가 쌓여 있는 자리"},{"term":"Definition of Done","note":"— \"끝났다\" 의 선. 이 선이 있어야 처리량을 셀 수 있다"},{"term":"Agile","note":"— 칸반이 함께 놓이는 큰 흐름"}]},{"id":"pm--mvp","term":"MVP","reading":"Minimum Viable Product","category":"제품 관리","summary":"MVP는 **가설을 확인할 만큼만 만들어 내놓는 제품**이다.","aliases":["mvp","minimum viable product"],"related":[{"term":"Agile","note":"— 짧게 만들고 반응을 보는 이 방식을 담은 개발 방법론"},{"term":"Sprint","note":"— MVP를 한 조각씩 만들어 내는 짧은 작업 주기"},{"term":"User Story","note":"— 무엇이 최소인지 가릴 때 기능을 적는 단위"},{"term":"Product Roadmap","note":"— MVP로 확인한 다음에 무엇을 붙일지 그리는 계획"}]},{"id":"pm--north-star-metric","term":"North Star Metric","reading":"북극성 지표","category":"제품 관리","summary":"North Star Metric은 **제품의 가치를 대표하는 지표 하나**다.","aliases":["north star metric","북극성 지표"],"related":[{"term":"KPI","note":"— 여러 지표 중 맨 위에 두는 하나가 북극성 지표다"},{"term":"OKR","note":"— 목표를 세울 때 이 지표가 그 자리에 들어간다"},{"term":"PMF","note":"— 이 지표가 일정 수준을 넘으면 시장에 맞았다는 신호로 읽는다"},{"term":"Retention","note":"— 북극성 지표를 떠받치는 대표적인 입력 지표"},{"term":"Funnel","note":"— 지표를 올리려면 어느 단계에서 새는지 봐야 한다"}]},{"id":"pm--okr","term":"OKR","reading":"Objectives and Key Results","category":"제품 관리","summary":"OKR은 **목표 하나에 달성 여부를 잴 숫자를 붙이는 틀**이다.","aliases":["okr","objectives and key results"],"related":[{"term":"KPI","note":"— 지키려고 보는 숫자. OKR 은 밀어붙이려고 보는 숫자다"},{"term":"North Star Metric","note":"— 회사가 오래 보는 숫자 하나. OKR 은 분기마다 바뀐다"},{"term":"Product Roadmap","note":"— OKR 이 정한 방향을 일정으로 옮긴 것"},{"term":"Sprint","note":"— 분기 단위 OKR 을 주 단위 일감으로 쪼개는 자리"}]},{"id":"pm--pmf","term":"PMF","reading":"Product Market Fit","category":"제품 관리","summary":"PMF는 **제품이 시장의 필요와 맞아떨어진 상태**다.","aliases":["pmf","product market fit"],"related":[{"term":"MVP","note":"— PMF를 찾기 위해 최소한으로 만들어 보는 것"},{"term":"Retention","note":"— PMF를 재는 가장 직접적인 지표"},{"term":"North Star Metric","note":"— PMF 이후 성장을 이끌 하나의 숫자"},{"term":"Funnel","note":"— 가입에서 사용까지 어디서 새는지 보는 틀"},{"term":"KPI","note":"— PMF 지표를 조직의 목표로 옮긴 것"}]},{"id":"pm--persona","term":"Persona","reading":"페르소나","category":"제품 관리","summary":"Persona는 **조사한 사용자들을 한 사람으로 좁혀 적어둔 것**이다.","aliases":["persona","페르소나"],"related":[{"term":"User Story","note":"— 페르소나를 주어로 놓고 쓰는 작업 단위"},{"term":"MVP","note":"— 이 사람의 고충 하나만 먼저 풀어보는 방식"},{"term":"A B Testing","note":"— 페르소나에서 세운 가설을 숫자로 확인하는 쪽"},{"term":"PMF","note":"— 정한 사람들이 실제로 이걸 필요로 하는지를 묻는 단계"}]},{"id":"pm--product-roadmap","term":"Product Roadmap","reading":"제품 로드맵","category":"제품 관리","summary":"Product Roadmap 은 **무엇을 왜 먼저 하는지 적어 공유하는 문서**다.","aliases":["product roadmap","제품 로드맵"],"related":[{"term":"MVP","note":"— 로드맵의 첫 구간에 놓이는 최소 형태"},{"term":"OKR","note":"— 로드맵이 겨누는 목표를 숫자로 적은 것"},{"term":"Backlog","note":"— 로드맵 아래에 놓이는 상세 항목 목록"},{"term":"Sprint","note":"— 로드맵을 실제로 실행하는 단위"},{"term":"Agile","note":"— 로드맵을 자주 고쳐가며 실행하는 방식"}]},{"id":"pm--retention","term":"Retention","reading":"리텐션, 유지율","category":"제품 관리","summary":"Retention은 **가입한 사람 중 다시 돌아온 비율**이다.","aliases":["retention","리텐션, 유지율"],"related":[{"term":"PMF","note":"— 곡선이 평평해지는 것을 그 신호로 본다"},{"term":"Funnel","note":"— 가입까지 오는 과정. 리텐션은 그 뒤를 본다"},{"term":"CAC LTV","note":"— 데려오는 비용과 남아서 만드는 값. 리텐션이 뒷값을 정한다"},{"term":"North Star Metric","note":"— 리텐션과 이어지는 지표를 회사의 기준으로 삼는다"},{"term":"KPI","note":"— 리텐션을 그중 하나로 두는 경우가 많다"}]},{"id":"pm--retrospective","term":"Retrospective","reading":"회고","category":"제품 관리","summary":"Retrospective는 **지난 주기를 함께 돌아보고 다음에 고칠 것을 정하는 자리**다.","aliases":["retrospective","회고"],"related":[{"term":"Scrum","note":"— 이 자리를 주기의 마지막 행사로 못 박아 둔 틀"},{"term":"Sprint","note":"— 회고가 닫는 한 바퀴"},{"term":"Definition of Done","note":"— 회고에서 함께 들여다보라고 적힌 대상"},{"term":"Agile","note":"— 정기적으로 되돌아보고 방식을 조정하라고 원칙에 적어 둔 선언"},{"term":"Backlog","note":"— 회고에서 고른 개선이 실제로 들어가는 자리"}]},{"id":"pm--scrum","term":"Scrum","reading":"스크럼","category":"제품 관리","summary":"Scrum은 **짧은 주기를 반복해 제품을 만드는 방식**이다.","aliases":["scrum","스크럼"],"related":[{"term":"Agile","note":"— 스크럼이 따르는 생각. 스크럼은 그 실행 방식 중 하나다"},{"term":"Sprint","note":"— 범위를 고정하고 돌리는 한 주기"},{"term":"Backlog","note":"— 만들 것을 우선순위 순으로 쌓아둔 목록"},{"term":"User Story","note":"— 백로그 항목을 사용자 관점으로 쓰는 형식"}]},{"id":"pm--sprint","term":"Sprint","reading":"스프린트","category":"제품 관리","summary":"Sprint는 **정해둔 기간 안에 쓸 수 있는 결과를 내는 작업 주기**다.","aliases":["sprint","스프린트"],"related":[{"term":"Scrum","note":"— 스프린트를 축으로 삼는 진행 방식"},{"term":"Backlog","note":"— 스프린트에 담을 것을 꺼내오는 목록"},{"term":"Agile","note":"— 짧게 만들고 반응을 보는 큰 흐름"},{"term":"User Story","note":"— 스프린트에 담기는 일감의 단위"}]},{"id":"pm--story-point","term":"Story Point","reading":"스토리 포인트","category":"제품 관리","summary":"Story Point는 **일감의 크기를 다른 일감과 견줘 매기는 숫자**다.","aliases":["story point","스토리 포인트"],"related":[{"term":"Sprint","note":"— 이 합을 세는 단위가 되는 한 바퀴"},{"term":"Backlog","note":"— 점수가 붙는 항목들이 쌓여 있는 목록"},{"term":"User Story","note":"— 점수를 매기는 대상이 되는 일감의 형식"},{"term":"Definition of Done","note":"— 무엇을 더해도 되는지를 정하는 선"},{"term":"Kanban","note":"— 점수 대신 끝난 개수와 걸린 시간을 세는 쪽"}]},{"id":"pm--user-story","term":"User Story","reading":"사용자 스토리","category":"제품 관리","summary":"User Story는 **누가 무엇을 왜 원하는지 짧게 적은 요구사항**이다.","aliases":["user story","사용자 스토리"],"related":[{"term":"Agile","note":"— 스토리라는 형식이 나온 배경"},{"term":"Sprint","note":"— 스토리 하나가 들어가야 할 기간 단위"},{"term":"Backlog","note":"— 아직 손대지 않은 스토리가 쌓이는 곳"},{"term":"MVP","note":"— 먼저 만들 스토리만 골라낸 묶음"},{"term":"Persona","note":"— 스토리 첫 줄의 역할을 구체적으로 정해둔 것"}]},{"id":"pm--wireframe","term":"Wireframe","reading":"와이어프레임","category":"제품 관리","summary":"Wireframe은 **색과 꾸밈을 뺀 화면 설계도**다.","aliases":["wireframe","와이어프레임"],"related":[{"term":"User Story","note":"— 스토리에 적힌 것이 화면 어디에 놓이는지 맞춰보는 자리"},{"term":"MVP","note":"— 먼저 만들 화면만 골라낼 때 함께 본다"},{"term":"Persona","note":"— 이 화면을 볼 사람이 누구인지 정해둔 것"},{"term":"Agile","note":"— 짧게 그리고 자주 고치는 방식이 나온 배경"}]}]}];
